		},
		{
			id = "armor_void", name = "Void Carapace", price = 1000000,
			kind = "Armor", grants = "void",
			blurb = "It absorbs the tung.",
		},
		{
			id = "armor_eclipse", name = "Eclipse Aegis", price = 28000000,
			kind = "Armor", grants = "eclipse",
			blurb = "Sahur cannot reach you here.",
		},
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- invariant: THE GENERATOR SPEEDS THE DROPPERS AND THE BELT TOGETHER, at the
	-- same rate, and that pairing is the only way the feature works at all.
	--
	-- Income is dropValue/dropRate and does not depend on belt speed; what belt
	-- speed decides is how CROWDED the belt is. Drops in flight are
	-- peakRate x length / speed, so scaling rate alone is a straight multiplier on
	-- how many are on the belt at once — and the plot is already at 88% of
	-- MaxDropsPerPlot. A x1.4 generator on the droppers alone puts it over the cap,
	-- at which point spawnDrop starts silently eating the income you just paid for.
	-- Scaling both leaves the number in flight exactly where it was.
	--
	-- design:D-02 for the drop budget this is bounded by.
	-- ─────────────────────────────────────────────────────────────────────────────

	Config.Power = {
		MaxFactor = 2.00,   -- what the top rung must grant; asserted, not assumed
		StepMin = 1.10,     -- and each rung's step over the one below sits in this
		StepMax = 1.30,     -- band, so it is four even rungs rather than one big one
	}

	-- `factor` is CUMULATIVE — the multiplier owning this rung puts the plot at,
	-- not the step it adds. A track is a chain, so "the factor you are on" is the
	-- factor of the highest rung you own, which means the verifier asserts the
	-- headline x2 against a literal instead of against a product of four floats,
	-- and a save that somehow holds rung 3 without rung 2 lands on a defined value.
	Config.PowerButtons = {
		{
			id = "power1", name = "Diesel Generator", price = 14000,
			kind = "Power", factor = 1.19, variant = "golden",
			blurb = "The whole line runs 19% faster.",
		},
		{
			id = "power2", name = "Twin Turbine", price = 550000,
			kind = "Power", factor = 1.42, variant = "crimson",
			blurb = "The whole line runs 42% faster.",
		},
		{
			id = "power3", name = "Sahur Reactor", price = 3000000,
			kind = "Power", factor = 1.68, variant = "void",
			blurb = "The whole line runs 68% faster.",
		},
		{
			id = "power4", name = "Tung Fusion Core", price = 300000000,
			kind = "Power", factor = 2.00, variant = "infinity",
			blurb = "Double production. Droppers and belt alike.",
		},
	}

	--- The production multiplier a plot's `owned` set is running at.
	---
	--- Iterated in track order taking the LAST hit rather than multiplied, because
	--- `factor` is cumulative. Pure arithmetic and no Roblox types, so the server,
	--- the offline-earnings mirror and the verifier can all call the same one
	--- rather than keeping three copies of it in agreement.
	function Config.powerFactor(owns: (string) -> boolean): number
		local factor = 1
		for _, def in ipairs(Config.PowerButtons) do
			if owns(def.id) then
				factor = def.factor
			end
		end
		return factor
	end

	--- design:D-02, via #180 — the plot-wide multiplier a finished drop is worth:
	--- every owned upgrader, times the generator. The FULL stack, deliberately,
	--- whichever side's arches the drop physically crossed: after the mirrored
	--- line split a drop only passes its own path's three upgraders, and a
	--- per-side stack would halve the effective multiplier and break every
	--- price on the curve. The arch flash is theatre; this is the accounting.
	function Config.plotMultiplier(has: (string) -> boolean): number
		local upgradeMult = 1
		for id, def in pairs(Config.ButtonById) do
			if has(id) and def.kind == "Upgrader" then
				upgradeMult *= def.multiplier
			end
		end
		return upgradeMult * Config.powerFactor(has)
	end

	--- design:D-02, via #180 — what ONE collected tung pays, before the
	--- per-player terms: its dropper's value through the plot multiplier. The
	--- live plot's payer since #180; onCollect is its one caller in the game.
	function Config.dropPayout(dropValue: number, has: (string) -> boolean): number
		return dropValue * Config.plotMultiplier(has)
	end

	--- design:D-02 — THE income model, in the one file all readers reach.
	--- Tung/sec for a factory owning `has(id)`: dropper value over rate, summed,
	--- through the plot multiplier. Per-player terms (rebirth, session
	--- multipliers) belong to the callers — Tycoon:incomePerSecond adds the live
	--- multiplier stack, SessionService.incomePerSecondFor adds the rebirth term
	--- from a saved profile, and the verifier's progression simulation uses this
	--- number raw.
	---
	--- SINCE #180 THE LIVE PLOT PAYS THROUGH THE DROPS, and this rate is their
	--- long-run average — each owned dropper lands dropPayout(dropValue) every
	--- dropRate seconds — so the quote, the mirror and the simulation still read
	--- one model while the conveyor carries the actual money. Live pay is lumpy
	--- (one belt transit late) and LOSSY on purpose: a tung that never reaches
	--- the vault is income that never arrives.
	function Config.incomeRate(has: (string) -> boolean): number
		local total = 0
		for id, def in pairs(Config.ButtonById) do
			if has(id) and def.kind == "Dropper" then
				total += def.dropValue / def.dropRate
			end
		end
		return total * Config.plotMultiplier(has)
	end

	Config.Combat = {
		ComboWindow = 1.6,          -- seconds to chain a swing
		-- One more swing animation than there are combo stacks, because stack 0 is
		-- the first swing of a chain. Stacks 0,1,2,3 map to SwingAnim.SWINGS 1..4,
		-- so the chain plays diagonal / backhand / sweep / slam and then repeats.
		ComboMaxStacks = 3,
		SwingSteps = 4,             -- must equal #SwingAnim.SWINGS; both sides assert it
		ComboDamagePerStack = 0.18, -- +18% per stack
		HitboxSize = Vector3.new(7, 7, 1),
		RespawnCash = 0,            -- cash lost on death (0 = friendly)

		-- SWING TIMING, as fractions of the bat's cooldown. The hitbox used to be
		-- evaluated on the same frame the swing started, i.e. a whole animation
		-- BEFORE the bat visibly reached the target — which is most of why the old
		-- combat read as clicking rather than as hitting. Damage now lands on the
		-- strike frame.
		SwingWindUp = 0.26,         -- fraction spent winding up
		SwingStrikeAt = 0.40,       -- fraction at which the bat is at the end of its arc
		-- The strike is a moving arc, so one instantaneous box misses targets that
		-- are a few frames early or late. Sample twice, this far apart.
		SwingSampleGap = 0.07,
		HitStop = 0.07,             -- seconds the swing freezes on a landed hit

		CritMultiplier = 2,
		CritKnockback = 1.6,

		-- The last step of a combo is the overhead slam. It is slower to reach (it
		-- is the fourth click) so it pays out.
		FinisherDamage = 1.5,
		FinisherKnockback = 1.8,
		FinisherReach = 1.25,

		-- Roblox's default is 16. The plot grew by a third, and 22 keeps the walk
		-- from the gateway to the last dropper at about six seconds. Above ~32 a
		-- humanoid starts clipping through 4-stud walls.
		WalkSpeed = 22,
		JumpPower = 52,
	}

	-- design:D-04, via #94 — RAIDING. A safe amount is untouchable; only the
	-- overflow above it is ever at risk, and every number here is a KPI made
	-- config: a raid never costs more than a few minutes of the victim's income
	-- (recovered inside one sitting), an empty unit still pays the raider
	-- (minted — the defender loses nothing), and camping one target halves its
	-- spoils per repeat until it is worthless. The loot is CARRIED until the
	-- raider reaches their own plot, and killing the carrier returns it.
	Config.Raid = {
		-- The untouchable fraction of the storage cap. Overflow = cash above it,
		-- and overflow is the only Tung any raid mechanism can reach.
		SafeFraction = 0.5,
		-- What one storage-unit break takes, as a fraction of overflow. With the
		-- cap at 30 minutes of income, a full-worst-case raid costs
		-- 0.35 x 0.5 x 30 = 5.25 minutes — asserted under RecoveryMinutes.
		SpillFraction = 0.35,
		-- Breaking an EMPTY unit mints this fraction of the victim's cap for the
		-- raider; the defender loses nothing. Raiding always rewards the raider.
		EmptyBountyFraction = 0.05,
		-- A player kill takes this fraction of the victim's overflow, wherever
		-- combat is legal — the smaller vector, available everywhere.
		KillStealFraction = 0.1,
		-- Repeat spoils from the same victim halve per break inside the window.
		CampingHalving = 0.5,
		CampingWindowSeconds = 1800,
		-- The KPI ceiling the spill arithmetic is asserted under: a raid's worst
		-- case must be re-earnable inside one sitting.
		RecoveryMinutes = 8,
	}

	-- design:D-04, via #89 — THE OPEN WORLD. The plots hold the belt at the rim
	-- and danger concentrates inward: three fixed bands of roaming mobs between
	-- the belt and the centre, strongest in the middle, so difficulty is
	-- geography a player walks toward and a fresh player meets only what suits
	-- them near home. Fixed bands rather than levels scaled to the nearest
	-- player, so the world is learnable and every safety line is assertable.
	Config.Mobs = {
		Enabled = true,
		-- The bands, inmost first: annuli by flat distance from the world centre.
		-- `level` feeds the same growth curves as the central wave (BaseHealth x
		-- HealthGrowth^(level-1), damage capped at MaxDamage), and `count` is the
		-- band's standing population.
		Bands = {
			{ name = "core",      inner = 0,   outer = 140, level = 15, count = 8 },
			{ name = "mid",       inner = 140, outer = 300, level = 8,  count = 8 },
			{ name = "outskirts", inner = 300, outer = 420, level = 2,  count = 8 },
		},
		-- Home patches keep this clear of their band's edges, so a roamer's
		-- wander never straddles a boundary.
		HomeMargin = 20,
		-- The census: how often a short band is refilled, one body at a time.
		RespawnSeconds = 18,
		MaintainInterval = 3,
	}

	-- design:D-04, via #89 — THE PLOT WAVE. The server-wide climbing raid is
	-- gone; it is the stated problem (a fresh player joining a busy server walked
	-- into wave 40). Each plot now runs its own small cycle: raiders spawn in the
	-- grass outside YOUR gate at a level set by YOUR plot's progression, press
	-- the gate (#124's mobs, finally arrived), and stream in when it breaks. The
	-- central wave at the dais is the one shared event, and it may still climb —
	-- nobody stands in the core by accident.
	Config.PlotWave = {
		Enabled = true,
		-- Quiet time between one plot raid clearing and the next warning, plus a
		-- jitter so ten plots' sirens do not sound in chorus.
		RestSeconds = 240,
		RestJitter = 60,
		-- Wave size by plot level, capped WELL under MaxChasers — a plot wave is
		-- pressure to come home, never the wall a central wave is.
		BaseCount = 3,
		MaxCount = 6,
		-- How many raiders press the gate at once; the rest mill. This is the
		-- breach-floor arithmetic's input, so the verifier can promise how long
		-- the gate holds.
		GateSlots = 3,
		-- The whole siege despawns after this long, cleared or not.
		MaxSiegeSeconds = 150,
		-- At most this many plots under siege at once. The stagger is what keeps
		-- the world part budget bounded with ten plots occupied.
		MaxConcurrent = 3,
	}

	-- The whole world's NPC ceiling: the central wave's worst case, every band's
	-- standing population and every concurrent plot siege, all alive at once.
	-- The verifier sums the real worst case against this.
	-- Raised for the tower (#95): its platforms fight far above the world but
	-- their bodies still count. Central wave + bands + sieges + concurrent runs.
	Config.Mobs.MaxWorldNPCParts = 3600

	--- The plot wave's level: the plot's own progression, never the server's
	--- lifetime. Expansions are the plot's size and rebirths its age; the cap
	--- keeps a maxed veteran's raid inside the damage ceilings.
	function Config.plotWaveLevel(expansions: number, rebirths: number): number
		return math.min(1 + expansions + rebirths * 2, 12)
	end

	-- design:D-04, via #123 — HELPING PAYS. The counterweight to raiding: a
	-- server where everyone is prey loses its new players, so kindness earns a
	-- persistent reputation stat and a short income boost, weighted toward
	-- helping someone earlier in the game than you. The boost is minutes of a
	-- small multiplier — two accounts farming each other at this scale is
	-- acceptable, which is what removes the need for an abuse system.
	Config.Help = {
		-- The income multiplier a fresh act of help grants, and for how long.
		-- Deliberately small: the reward must never be the point of the game.
		BoostMultiplier = 1.2,
		BoostMinutes = 2,
		-- Repeated help extends the boost, to at most this far ahead.
		MaxBoostMinutes = 10,
		-- The progression-gap weighting: each rebirth the helper has over the
		-- helped adds this to the credit's weight, up to MaxWeight. A veteran
		-- pulling a new player up comes out ahead of two peers pairing.
		GapWeightPerRebirth = 0.5,
		MaxWeight = 3,
		-- One helper-helped pair earns credit at most this often. Longer than
		-- the boost it grants, so one tame pair cannot hold a boost forever.
		PairCooldownSeconds = 300,
	}

	-- design:D-03, via #106 — THE TIER IS PUBLIC. A player's overall progress is
	-- readable off their plot the way a Town Hall reads: the totem tag carries a
	-- rank name derived from rebirths, legible from reasonably close (the sign's
	-- existing "plot" draw distance) and deliberately NOT across the map — a
	-- world-legible tag lets raiders shop for targets from a distance they never
	-- have to travel, and reads as noise besides.
	Config.Tiers = {
		{ atLeast = 0, name = "TUNG", motto = "Everyone starts as a Tung." },
		{ atLeast = 1, name = "TUNG TUNG", motto = "The factory listens to you now." },
		{ atLeast = 2, name = "TUNG TUNG TUNG", motto = "The middle of the world is yours to farm." },
		{ atLeast = 3, name = "SAHUR", motto = "Raiders check your gate twice." },
		{ atLeast = 5, name = "GRAND SAHUR", motto = "The tower's top floor knows your name." },
	}

	--- The whole tier row a rebirth count sits in — #107's screen reads the
	--- motto off it.
	function Config.tierRow(rebirths: number)
		local row = Config.Tiers[1]
		for _, tier in ipairs(Config.Tiers) do
			if rebirths >= tier.atLeast then
				row = tier
			end
		end
		return row
	end

	--- The rank a rebirth count wears. Walks the ladder; the last row it clears
	--- is the answer.
	function Config.tierName(rebirths: number): string
		local name = Config.Tiers[1].name
		for _, tier in ipairs(Config.Tiers) do
			if rebirths >= tier.atLeast then
				name = tier.name
			end
		end
		return name
	end

	-- design:D-01, via #97 — DAILY OBJECTIVES AND THE HINT LINE. A short list of
	-- things to do today, paid in MINUTES OF YOUR OWN INCOME on completion (the
	-- tower's denomination — it scales with the player and structurally cannot
	-- out-earn the plot for long, and the verifier bounds the day's total).
	-- Objectives are per-account per-day: progress is a baseline snapshot taken
	-- at the day's first beat, measured against live profile stats, and the
	-- daily reset is the same day-number arithmetic the tower uses. The draw is
	-- the tower's seeded deal, so every server offers the same three that day.
	Config.Objectives = {
		PerDay = 3,
		-- What one day's objectives may pay IN TOTAL, in minutes of income. The
		-- streak and the offline grant are why players log in; this is a nudge.
		MaxDayMinutes = 12,
		Pool = {
			{ id = "kills5", name = "Knock down 5 Sahur", stat = "kills", count = 5, rewardMinutes = 3 },
			{ id = "kills12", name = "Knock down 12 Sahur", stat = "kills", count = 12, rewardMinutes = 4 },
			{ id = "buys3", name = "Buy 3 upgrades", stat = "buys", count = 3, rewardMinutes = 2 },
			{ id = "buys7", name = "Buy 7 upgrades", stat = "buys", count = 7, rewardMinutes = 4 },
			{ id = "kind1", name = "Do somebody a kindness", stat = "reputation", count = 1, rewardMinutes = 3 },
			{ id = "tower3", name = "Clear 3 tower floors", stat = "towerBest", count = 3, rewardMinutes = 4 },
		},
	}

	--- The day's draw: PerDay distinct pool rows, dealt by the same seeded LCG
	--- the tower uses, identical on every server that day.
	function Config.objectivesFor(daySeed: number)
		local pool = Config.Objectives.Pool
		local state = daySeed * 668265263 + 374761393
		local function nextRandom(n: number): number
			state = (state * 1103515245 + 12345) % 2147483648
			return (state % n) + 1
		end
		local indices = {}
		for i = 1, #pool do
			indices[i] = i
		end
		for i = #indices, 2, -1 do
			local swap = nextRandom(i)
			indices[i], indices[swap] = indices[swap], indices[i]
		end
		local drawn = {}
		for i = 1, math.min(Config.Objectives.PerDay, #pool) do
			drawn[i] = pool[indices[i]]
		end
		return drawn
	end

	-- The hint line: the first of these the player has not done yet, shown on
	-- the objectives card and spoken by the guide (#100). Non-purchase
	-- milestones only — the beacon and the NEXT card already own purchases.
	Config.Hints = {
		{ id = "firstKill", text = "Sahur roam the grass outside. Knock one down — kills pay.", stat = "kills", atLeast = 1 },
		{ id = "firstKindness", text = "Repair a stranger's wall, or down a thief. Kindness pays Rep and a boost.", stat = "reputation", atLeast = 1 },
		{ id = "firstRebirth", text = "The rebirth pad multiplies everything after it. The re-climb is fast.", stat = "rebirths", atLeast = 1 },
	}

	-- design:D-05, via #96 — PROGRESSIVE DISCLOSURE. The game starts small and
	-- grows its own interface: a surface takes up space only once the player can
	-- use it, every arrival is earned by something they just did, and nothing
	-- ever disappears once shown. The high-water lives in profile.disclosed, so
	-- a returning player sees what they earned and is never re-onboarded.
	--
	-- `after` is a Config.Buttons id; owning it (or the rebirth count, for the
	-- rebirths form) is the earn. A row with no `after` is on from the first
	-- second — that set IS the sixty-second screen, and the verifier prints it.
	-- `gate = true` rows gate GAMEPLAY as well as pixels: the plot siege waits
	-- for its row, because a raid siren in your first minute is the overload
	-- this whole system exists to prevent.
	Config.Disclosure = {
		{ id = "hud", name = "Your factory", help = "Buy droppers, follow the gold beacon. The vault banks what the machines earn." },
		{ id = "movement", name = "Sprint and dash", help = "Hold Shift to sprint, Q to dash. On touch: RUN and DASH, bottom left." },
		{ id = "terms", after = "dropper2", name = "Multipliers", help = "The line under your cash names every bonus you hold." },
		-- design:D-05, via #162 — THE SIDEBAR ARRIVES ONCE THE LINE RUNS, not
		-- while it is being laid: the session panel, the friends line and the
		-- daily objectives all landed inside the first three minutes and read as
		-- clutter over a plot that had not earned them yet. The gameplay-coupled
		-- rows keep their beats (the shop opens WITH its track at dropper3, the
		-- siege with the walls).
		{ id = "session", after = "dropper4", name = "Streaks and boosts", help = "The session panel: daily streak, playtime ladder, the boost button." },
		{ id = "social", after = "dropper5", name = "Friends pay", help = "Every friend in the server is +10% income. Invite from the status card." },
		{ id = "world", after = "dropper5", name = "The world outside", help = "Sahur roam the grass — weakest near the plots, strongest in the middle. Kills pay." },
		{ id = "siege", after = "walls", gate = true, name = "Raids on your plot", help = "Sahur press your gate now and then. The siren gives you time to run home; repair what breaks." },
		{ id = "party", after = "walls", name = "Parties", help = "Party up from the left card: no friendly fire, shared gates, +5% income each." },
		{ id = "recall", after = "walls", name = "Recall", help = "H (or HOME on touch) walks you home after six still seconds. Never with stolen Tung." },
		{ id = "objectives", after = "belt1", name = "Daily objectives", help = "Three things to do today, on the left card. Each pays minutes of your income." },
		{ id = "shop", after = "dropper3", name = "The shop", help = "Bats and armour live in the SHOP now — the rail button, or the merchant by the spawn." },
		{ id = "raiding", after = "gates", name = "Raiding", help = "Break a storage unit, carry the spill home. Half their cap is always safe; camping pays half each repeat." },
		{ id = "tower", after = "power1", name = "The tower", help = "The spire at the core's edge. A new deck of floors every day; each floor pays minutes of your income." },
	}

	--- Whether one disclosure row is earned. `has` answers ownership, the same
	--- shape incomeRate reads.
	function Config.disclosureEarned(row, has: (string) -> boolean): boolean
		if not row.after then
			return true
		end
		return has(row.after)
	end

	-- design:D-04, via #95 — THE TOWER. Combat with a shape: floors of waves,
	-- bosses, timed kills and survival, composed fresh each UTC day from the day
	-- seed so a run cannot be memorised, climbed by a party (#102) or alone.
	-- Rewards are paid PER FLOOR, on the spot, in MINUTES OF YOUR OWN INCOME —
	-- which makes "fighting beats waiting" a line of arithmetic the verifier
	-- holds at every progression stage, and makes a wipe keep what it cleared.
	Config.Tower = {
		Floors = 8,
		-- Enemy level by floor: BaseLevel + LevelPerFloor x floor, on the same
		-- growth curves every other Sahur uses.
		BaseLevel = 2,
		LevelPerFloor = 1.5,
		-- What one floor pays each member: minutes of their OWN income rate.
		FloorRewardMinutes = 2,
		-- The pacing estimate a floor is tuned around; the run-length and the
		-- fighting-beats-waiting assertions both read it.
		FloorNominalSeconds = 90,
		-- Archetype knobs.
		WaveCount = 6,          -- bodies in a wave floor, plus one per partymate
		TimedSeconds = 45,      -- kill the pack before this runs out
		SurvivalSeconds = 30,   -- stay alive this long
		-- Concurrency and the platform in the sky the floors fight on.
		MaxConcurrentRuns = 2,
		PlatformY = 500,
		PlatformSize = 90,
		-- Where the entrance spire stands: on the core's edge, opposite the
		-- spawn, in plain sight of anyone walking inward.
		EntranceRadius = 150,
	}

	-- The archetype deck. towerFloors deals it by day seed.
	Config.TowerArchetypes = { "wave", "timed", "survival", "boss" }

	--- The day's tower: a deterministic composition of Floors archetypes from
	--- the UTC day number, the same for every server and every party that day.
	--- Every archetype appears; a boss holds the top floor; the shuffle is a
	--- seeded LCG so the verifier can walk any seed it likes.
	function Config.towerFloors(daySeed: number): { string }
		local deck = {}
		local state = daySeed * 747796405 + 2891336453
		local function nextRandom(n: number): number
			state = (state * 1103515245 + 12345) % 2147483648
			return (state % n) + 1
		end
		for f = 1, Config.Tower.Floors - 1 do
			-- guarantee coverage: the first pass deals each archetype once, the
			-- rest draw freely
			local archetypes = Config.TowerArchetypes
			if f <= #archetypes then
				deck[f] = archetypes[f]
			else
				deck[f] = archetypes[nextRandom(#archetypes)]
			end
		end
		-- seeded shuffle of everything below the top
		for f = #deck, 2, -1 do
			local swap = nextRandom(f)
			deck[f], deck[swap] = deck[swap], deck[f]
		end
		-- the top floor is always the boss: a run ends on a fight worth talking
		-- about, whatever the deal dealt
		deck[Config.Tower.Floors] = "boss"
		return deck
	end

	-- design:D-04, via #146 — THE DAILY MODIFIER. One per day, dealt by the same
	-- seed as the deck, so "today's tower" is a sentence: the deck plus its
	-- twist. Scales are bounded by the verifier against the lines other systems
	-- stand on — a SWIFT raider must still lose to a sprinting player.
	Config.TowerModifiers = {
		{ id = "steady", name = "STEADY", blurb = "No twist today." },
		{ id = "swift", name = "SWIFT", blurb = "They move faster.", walkScale = 1.25 },
		{ id = "tough", name = "TOUGH", blurb = "They take more knocking down.", healthScale = 1.4 },
		{ id = "bountiful", name = "BOUNTIFUL", blurb = "Every floor pays a minute more.", bonusMinutes = 1 },
	}

	--- The day's modifier row, dealt beside the deck.
	function Config.towerModifier(daySeed: number)
		local state = daySeed * 22695477 + 1013904223
		state = (state * 1103515245 + 12345) % 2147483648
		return Config.TowerModifiers[(state % #Config.TowerModifiers) + 1]
	end

	--- Enemy level on one floor.
	function Config.towerLevel(floor: number): number
		return math.floor(Config.Tower.BaseLevel + Config.Tower.LevelPerFloor * floor)
	end

	-- design:D-04, via #103 — RECALL. The open world makes the trip home a
	-- recurring tax; recall pays it with TIME STANDING STILL instead of a walk.
	-- The stillness is the anti-escape: a caster is a free hit for anything
	-- already on them, moving or taking damage cancels the cast, and a raider's
	-- carry blocks it outright — stolen Tung walks home. One direction only:
	-- coming back. Going out is the walk (#101's sprint; mounts wait for later).
	Config.Recall = {
		CastSeconds = 6,
		CooldownSeconds = 45,
		-- Drifting further than this from where the cast began cancels it.
		CancelMoveStuds = 4,
	}

	-- design:D-04, via #101 — MOVEMENT. Sprint and dash ship now, as BASELINE
	-- capabilities everyone has: legibility first, and a movement axis nobody can
	-- buy is a movement axis nobody falls behind on. Mounts and waypoints wait
	-- for #89 — there is no world to cross yet.
	Config.Movement = {
		-- 32 is the wall-clip bound: above it a humanoid starts passing through
		-- 2-stud walls, and the PlayerUpgrades check has always held that line.
		-- Sprinting RAISES the defender's run home, so the siren guarantee
		-- (WarningTime x Combat.WalkSpeed >= MinPlotRadius) keeps its
		-- conservative walking form and sprint is pure margin.
		SprintSpeed = 32,
		-- The dash: a short burst that is also a dodge. Client-applied — the
		-- client owns its character's physics — with the cooldown enforced
		-- server-side so combat systems can trust the cadence.
		DashSpeed = 70,
		DashSeconds = 0.25,
		DashCooldown = 4,
	}

	Config.Waves = {
		Enabled = true,

		-- PACING. There used to be one number here, `Interval = 210`, and the loop
		-- was `while true do startWave(); task.wait(Interval) end` — no check that
		-- the last wave had been cleared, against a 420s straggler despawn, so two
		-- or three waves legally coexisted and the banner attributed leftovers from
		-- one to another. Waves now run one at a time, and the gap is measured from
		-- YOUR clear rather than from a wall clock.
		FirstWaveDelay = 30,
		-- Quiet time between a wave clearing and the next warning going up.
		--
		-- 18 + WarningTime 12 = THIRTY SECONDS from your clear to the next raid
		-- landing, which is the number this is set against. The verifier already
		-- defines dead air as RestTime + WarningTime, so the two agree on what is
		-- being measured. It was 20, for 32.
		RestTime = 18,
		-- A boss wave is the one you actually need to bank and heal after.
		RestTimeAfterBoss = 35,
		-- DO NOT SHORTEN WarningTime TO CLOSE THE GAP. It is load-bearing:
		-- 12 x Combat.WalkSpeed = 264 studs against a MinPlotRadius of 210, which
		-- is what lets a player standing on their own plot get back to the arena
		-- before the raiders land. Shorten RestTime instead; the verifier asserts
		-- this relationship.
		WarningTime = 12,
		-- Deadlock breaker, not a pacing tool. Raider pathfinding is still naive
		-- MoveTo, so one snagged on geometry must not stop the schedule forever.
		-- Note this WILL occasionally cut a legitimately hard solo wave short —
		-- 26 wave-20 raiders is about 340s of solo attention — and that is the
		-- intended trade. The banner says "TIMED OUT" rather than "CLEARED".
		MaxWaveTime = 300,
		-- Per-raider backstop, strictly after the wave deadline so it can only
		-- catch an entry whose wave record was somehow lost.
		StragglerGrace = 45,
		ClearBannerTime = 4,        -- how long CLEARED stays up; must be < RestTime
		SpawnGap = 0.12,            -- between raiders in the drip
		JoinGrace = 20,             -- grace before the first wave on a waking server
		BroadcastInterval = 0.5,    -- coalesce the per-death counter updates
		EmptyResetAfter = 180,      -- empty this long and the wave counter resets

		-- WAVE SIZE. Bigger, and it climbs faster: the first raid is six rather
		-- than four, and it grows by four a wave to a ceiling of forty.
		--
		-- THIS DOES NOT UNDO THE ANTI-SWARM WORK, and it is worth knowing that
		-- before the two changes look like they are fighting each other. MaxChasers
		-- is still 8, so no matter how many are alive only eight can engage any one
		-- player. A bigger wave is therefore more REINFORCEMENTS — bodies milling
		-- at their home patches and stepping in as slots free — not more people
		-- hitting you at once. The verifier asserts the two stay far enough apart
		-- for that to remain the shape of it.
		BaseCount = 6,
		CountPerWave = 4,
		MaxCount = 40,
		-- Parts in one raider, counted rather than guessed: 26 in the visible Tung
		-- (invisible core, 2 legs + 2 feet, 8-part bat body, face plate, 2 arms +
		-- 2 hands, and another 8-part bat in its hand) plus the 7-part invisible R6
		-- rig underneath it. Recount in TungModels.build/buildBatBody/buildNPC if
		-- you change the silhouette.
		--
		-- The verifier cannot see TungModels, so this is the only way the part
		-- budget is checkable at all — and a wave cap is exactly the number someone
		-- raises without thinking about what it costs on a full server.
		PartsPerRaider = 33,
		MaxRaiderParts = 1600,
		BaseHealth = 90,
		HealthGrowth = 1.20,        -- wave 20 raider ~2.9k HP: ~13s for one player
		BaseDamage = 9,
		DamageGrowth = 1.07,
		-- A player has 100 HP. These are ABSOLUTE ceilings: the boss multiplier used
		-- to be applied to the cap as well as to the damage, so a wave-20 boss hit
		-- for 61 and killed a full-health player in two swings — exactly what the
		-- cap was written to prevent.
		MaxDamage = 34,
		MaxBossDamage = 45,
		BossHealthMultiplier = 6,
		BossDamageMultiplier = 1.8,
		-- The rig's arm span in scale units: arms sit at +/-1.5 and are 1 wide, so
		-- the body is 2 * scale half-wide (see TungModels.buildNPC). It lives here
		-- because the verifier cannot see TungModels and the boss now spawns at a
		-- fixed point rather than out on the rim where nothing could be near it.
		BossBodyScale = 2.1,
		WalkSpeed = 13,
		RewardBase = 150,
		RewardGrowth = 2.3,         -- reward scales with wave number
		StealPerHit = 0.006,        -- fraction of a player's cash a raider steals on hit
		BossEvery = 5,

		-- RAIDER ATTACKS. Damage used to land on the same tick the raider decided
		-- to attack, with no wind-up and no animation, so being hit was pure
		-- proximity: you could not see it coming and you could not step out of it.
		-- Raiders now raise the bat, hold, and only then swing — and they stand
		-- still while they do it, which is the window you punish.
		AttackRange = 8,
		AttackWindUp = 0.45,        -- seconds of telegraph before the hit lands
		AttackRecover = 0.35,       -- seconds rooted after swinging
		AttackCooldown = 1.35,
		AttackKnockback = 28,
		BossWindUpScale = 1.35,     -- bosses telegraph LONGER; they hit much harder

		-- RAIDER AI. Every raider used to call nearestPlayer(position, 500) every
		-- 0.6 seconds — a radius bigger than the whole map — so all 26 of them
		-- beelined the same player from anywhere, forever, with no wander, no
		-- aggro range and no way to break contact. They now spawn on the rim, walk
		-- in to a home patch in the arena, mill around it, and only commit to a
		-- player who comes close enough.
		--
		-- The whole design rests on the raiders being SLOWER than the players
		-- (13-17 against 22). Without that gap, de-aggro is unreachable and the
		-- leash is the only thing that ever fires. The verifier asserts it.
		AggroRadius = 55,           -- a raider notices you across its own patch...
		DeAggroRadius = 85,         -- ...and needs a real run to lose you again
		-- Measured from the raider's HOME PATCH, not from where it spawned and not
		-- from the world origin. Home patches are scattered within HomeSpread of
		-- the arena centre, so the furthest a leashed raider can ever swing at
		-- something is HomeSpread + LeashRadius + AttackRange = 124 studs — against
		-- a nearest plot EDGE of 140 (MinPlotRadius 210 less half a plot depth).
		-- That 16-stud clearance is what makes plots provably safe, and it is
		-- asserted rather than commented.
		LeashRadius = 72,
		HomeSpread = 44,            -- home patches fill the arena, clear of the wall
		WanderRadius = 18,          -- 44 + 18 = 62 < ArenaRadius 70
		WanderDwellMin = 2.5,
		WanderDwellMax = 5.0,
		WanderSpeedScale = 0.55,    -- idling is visibly slower; that reads the flip
		ReturnSpeedScale = 1.2,     -- and going home is brisk, so the arena refills
		HomeArrive = 8,
		-- A returning raider must get most of the way back before it can bite
		-- again, or a player parked on the leash line yo-yos it forever.
		ReAggroFrac = 0.6,
		RepathChase = 0.35,         -- a 22 studs/s player covers 7.7 studs; at 0.6 it was 13
		RepathWander = 1.2,
		RepathReturn = 0.8,
		AggroCheck = 0.25,          -- how often an idling raider looks around
		SnapshotInterval = 0.1,     -- how often the shared player snapshot rebuilds

		-- ANTI-SWARM. An aggro radius alone does not fix the pile-up: raiders that
		-- spawn on one evenly-divided ring all cross the same threshold on the same
		-- tick and then converge on one point, so the wave arrives as a wall and
		-- fights as a single blob standing inside itself.
		SpawnGroupSize = 4,         -- clusters, not one synchronised ring
		SpawnGroupGap = 0.6,        -- pause between clusters
		GroupArc = 0.35,            -- radians of jitter within a cluster (~18 studs at r=52)
		AggroStagger = 1.8,         -- each raider holds you this long, at random, before committing
		-- Raiders MoveTo a point on a ring around you rather than to you. Under
		-- AttackRange, so a raider parked on its slot is already in swing range and
		-- the ring costs no damage output — it only stops 26 bodies occupying one
		-- stud.
		ApproachStandoff = 6.5,
		OrbitSpeed = 0.35,          -- rad/sec of drift, so the ring reads as a mob not a formation
		-- How many may engage one player at once. Not arbitrary: a 6.5-stud ring
		-- has a circumference of 40.8 and a raider is about 4.5 studs wide, so nine
		-- fit shoulder to shoulder. Eight leaves a slot of slack, and the ones over
		-- the cap keep milling and step in as slots free — which reads as
		-- reinforcements rather than as a queue.
		MaxChasers = 8,

		-- design:D-04 — the boss is the one thing in this game that couples two
		-- players' outcomes. Everything above this line describes a raid six people
		-- can play in six separate boxes.
		--
		-- SUB-LINEAR ON PURPOSE. Ten players do not deal ten players' damage to one
		-- target: MaxChasers is 8, the boss has one hitbox and one telegraph, and on
		-- a ten-plot server most of the ten are standing on their own plot watching
		-- their own number. Scaling health linearly with headcount would make a busy
		-- server a wall instead of an event.
		--
		-- AND DAMAGE DOES NOT SCALE AT ALL. MaxBossDamage owns the "a boss may never
		-- two-shot you" ceiling and the verifier asserts it with margin against an
		-- unarmoured player; making damage a function of headcount would put that
		-- assertion at the mercy of who happens to be online.
		BossSpawnRadius = 20,       -- on the dais, fixed bearing, NOT the rim
		BossHealthPerPlayer = 0.55,
		BossMaxHealthFactor = 4.0,
		-- The pot grows SLOWER than the health, so the boss stays a fight rather
		-- than a payday. The verifier holds the ratio above 0.6 from the other end,
		-- because a boss whose pot fell far behind its health would make joining a
		-- busy server a punishment.
		BossRewardPerPlayer = 0.45,
		BossMaxRewardFactor = 3.2,
		-- Tighter than LeashRadius. A shared objective that can be kited to the far
		-- side of the arena is one that eleven people spend the fight looking for.
		BossLeashRadius = 40,
		BossMinDamageFrac = 0.02,   -- of max health, to be paid at all
		-- Of the pot, split evenly among everyone eligible; the rest is split by
		-- damage. Everyone who showed up gets something, the person who did the work
		-- gets more, and at ONE eligible player the two terms sum to exactly the pot.
		BossFloorShare = 0.35,
	}

	--- BOSS SCALING, SAMPLED ONCE PER WAVE.
	---
	--- Pure arithmetic and no Roblox types, like Config.powerFactor: the server
	--- mints these into the wave record at beginWave and the verifier and the specs
	--- call the same ones, rather than three copies of the formula agreeing by
	--- inspection.
	---
	--- THE SOLO GUARANTEE. Both return exactly 1 at one player, and Config.bossShare
	--- is algebraically the identity at one eligible contributor — so a 1-player
	--- server gets byte-for-byte the boss it got before this existed, with no branch
	--- anywhere in the code. The verifier asserts that rather than trusting this
	--- paragraph.
	local function scaleFor(players: number, perPlayer: number, ceiling: number): number
		local n = math.max(1, math.floor(players or 1))
		return math.min(1 + perPlayer * (n - 1), ceiling)
	end

	function Config.bossHealthFactor(players: number): number
		return scaleFor(players, Config.Waves.BossHealthPerPlayer, Config.Waves.BossMaxHealthFactor)
	end

	function Config.bossRewardFactor(players: number): number
		return scaleFor(players, Config.Waves.BossRewardPerPlayer, Config.Waves.BossMaxRewardFactor)
	end

	--- One player's cut of a boss pot.
	---
	---   myDamage       applied damage this player dealt to the boss
	---   eligibleTotal  the same, summed over everyone eligible
	---   eligibleCount  how many players cleared BossMinDamageFrac
	---   pot            the whole reward, already scaled by bossRewardFactor
	---
	--- CONSERVES THE POT. Summed over the eligible it is exactly `pot`, at every
	--- count and every distribution — a floor share split evenly plus the remainder
	--- split by damage, and the two fractions add to one. Neither leaked nor minted,
	--- which is the property a verifier can hold and a comment cannot.
	function Config.bossShare(myDamage: number, eligibleTotal: number, eligibleCount: number, pot: number): number
		if eligibleCount <= 0 or pot <= 0 then
			return 0
		end
		local floorShare = Config.Waves.BossFloorShare
		local even = (pot * floorShare) / eligibleCount
		-- Falls back to an even split of the contribution half rather than dividing
		-- by zero. Unreachable while eligibility requires a positive damage floor,
		-- and it still sums to the pot if it ever is reached.
		if eligibleTotal <= 0 then
			return even + (pot * (1 - floorShare)) / eligibleCount
		end
		return even + pot * (1 - floorShare) * (myDamage / eligibleTotal)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- mechanism: BELT PATHS AND FLOORS. Shipped data — Tycoon.new consumes
	-- BeltPaths[1] unconditionally to build the ground floor's conveyor.
	--
	-- A path is just a list of corners, and every piece of belt geometry derives
	-- from leg(i), so the runtime does not care how many legs there are.
	-- ─────────────────────────────────────────────────────────────────────────────
	--
	-- Ground floor path is derived from the shipped Layout keys rather than
	-- duplicated, so the two cannot drift.
	--- `outboard` carries which SIDE of each leg the machines stand on, +1 or -1.
	--- It used to be inferred, by taking the perpendicular that points away from
	--- the plot origin — which works only while every leg hugs an outer edge. An
	--- upper floor's return leg runs back across the middle of its own deck, where
	--- the inferred side flips and puts the machines over the walkway and the buy
	--- buttons out in space. One entry per leg, so one fewer than `points`.
	-- TWO GROUND PATHS, mirrored (design:D-02, via #162). Both share the vault's
	-- collectorAt; each carries its own five droppers on leg 1 and three
	-- upgraders on leg 2, so the downstream rule holds per path. `west` first:
	-- the owner's right walking in the centred gate, and the side that fills
	-- first.
	Config.BeltPaths = {
		{
			id = "west",
			y = 0,
			points = {
				Vector3.new(-Config.Layout.BeltSideX, 0, Config.Layout.BeltFrontZ),
				Vector3.new(-Config.Layout.BeltSideX, 0, Config.Layout.BeltBackZ),
				Vector3.new(-Config.Layout.BeltInnerX, 0, Config.Layout.BeltBackZ),
			},
			outboard = { -1, -1 },
			collectorAt = Config.Layout.CollectorAt,
		},
		{
			id = "east",
			y = 0,
			points = {
				Vector3.new(Config.Layout.BeltSideX, 0, Config.Layout.BeltFrontZ),
				Vector3.new(Config.Layout.BeltSideX, 0, Config.Layout.BeltBackZ),
				Vector3.new(Config.Layout.BeltInnerX, 0, Config.Layout.BeltBackZ),
			},
			outboard = { 1, 1 },
			collectorAt = Config.Layout.CollectorAt,
		},
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- invariant: THE BUILDING SHELL — walls and gates, open to the sky.
	--
	-- ONE STRUCTURAL LINE. Config.Structure.WallHeight is the wall's top, and
	-- everything at that height derives from it.
	--
	-- SPANS ARE A LIST, NOT ARITHMETIC IN A LOOP. Config.wallSegments returns the
	-- solid runs and the openings of one wall of one storey, and the builder emits
	-- exactly what it is given. That is what makes "the wall accounts for its whole
	-- span" an assertion rather than a hope, and it is why the same function is read
	-- by tools/verify_config.lua and by a runtime spec.
	--
	-- SCALAR ARITHMETIC ONLY, like every derived position in this file: the
	-- verifier stubs Vector3 as a plain table with no operators.
	Config.Structure = {
		WallThickness = 2,

		-- The neon cap along a wall's top and the interior strip at the storey line
		-- are built from the same bar. `section` reproduces the 1-stud cap the old
		-- five-box wall carried and `proud` its 0.4 of overhang, so the trim that
		-- ships is the trim that shipped. They are keys rather than literals in the
		-- builder because Config.shellPartCount has to count them: it did not, and
		-- the budget was being asserted against a number 13% below what is built.
		Trim = { section = 1, proud = 0.4 },

		-- A solid run is built as three courses — sill, body, head — stacked to
		-- WallHeight. Three, so a broken wall can leave its sill standing as the
		-- repair stump while the courses above it fall (tycoon/Siege.lua). The
		-- numbers keep the old sill line and bay line, so the courses that ship
		-- are the courses that shipped.
		Course = {
			sill = 6,   -- floor to here
			body = 9,   -- sill to here + this; the head runs on to WallHeight
		},

		-- THE OPENINGS, as an inventory. Both keep height 13 — the old wall height —
		-- with a lintel course above, because a 20-stud gateway is not a door.
		Openings = {
			{
				id = "gateway", side = "front",
				centre = Config.Layout.GateCentre, width = Config.Layout.GateWidth,
				height = 13, leaves = 2,
				-- Which face the leaves hang on and slide along. INBOARD here: the
				-- front wall's inside is the open aisle, and a leaf out on the grass
				-- in front of the gateway would be the first thing you see.
				face = "inboard",
			},
			{
				id = "yardDoor", side = "back",
				-- The cut in the back wall onto the generator yard. Derived from the
				-- yard's own DoorFrom and the wall ring, so it cannot drift from the
				-- slab it opens onto: x = DoorFrom .. halfX.
				centre = (Config.Layout.Yard.DoorFrom + (Config.World.PlotSize.X / 2 - 1)) / 2,
				width = (Config.World.PlotSize.X / 2 - 1) - Config.Layout.Yard.DoorFrom,
				height = 13, leaves = 1,
				-- OUTBOARD, and this one is not a preference. The doorway is flush to
				-- the end of the back wall, so its single leaf can only slide inward
				-- along x — and the inside of the back wall IS the dropper row. Slot 1
				-- stands at x 38.5..43.5, z -66.5..-61.5, and an inboard leaf sliding
				-- x 33..46 passes 0.1 studs INTO it. Found by the verifier while the
				-- gate assertions were being falsified, on the shipped numbers.
				--
				-- Outboard it slides over the generator yard's own slab (x 32..60,
				-- z -97..-69), which is empty for its whole travel. The alternative
				-- was shaving `inset` to 0.1 for 0.2 studs of clearance against a
				-- machine, which is the kind of margin that becomes a bug the next
				-- time anything on that row moves.
				face = "outboard",
			},
		},

		-- GATES THAT OPEN ON APPROACH. Leaves slide along the inside face of the
		-- wall; travel is one leaf width, so the solid run beside an opening has to
		-- be at least that long (asserted).
		--
		-- Driven by a distance test on a fixed tick, NOT by Touched/TouchEnded. The
		-- teleport pads were deleted for exactly that: a character resting on a
		-- trigger bounces off its own physics jitter, which cost a cooldown, an
		-- arrival lock and a TouchEnded sweep to paper over.
		Gate = {
			thickness = 1.2,
			-- Clear air between the wall's FACE and the leaf's near face — not from
			-- the wall's centre plane. Which face is `opening.face`.
			inset = 0.4,
			triggerRadius = 20,      -- open when a humanoid is this close to the opening
			tickRate = 0.2,          -- seconds between distance tests, per claimed plot
			travelTime = 0.45,       -- tween seconds, each direction
		},

		-- design:D-02, via #162 — the castle silhouette: posts jutting off the
		-- wall's OUTER face at a wide, even pitch. One box per post, walked per
		-- solid run so none lands in an opening; `clearance` is the solid wall
		-- kept between a post and a run's edge.
		Buttress = {
			spacing = 35,   -- target pitch; the actual pitch divides the wall evenly
			width = 3,
			proud = 1.8,    -- how far the post stands off the wall's outer face
			-- OVER the wall's top, deliberately: the posts breaking the parapet
			-- line is what reads castle from a distance, at one part per post
			-- (design:D-02, via #162). Asserted taller than the wall and within
			-- `overshoot` of it, so "slightly" stays slight.
			height = 27,
			overshoot = 4,  -- ceiling on height - WallHeight
			clearance = 2,  -- solid wall kept between a post and an opening's jamb
		},

		-- design:D-02, via #162 — torches along the INNER face: a bracket and a
		-- neon flame carrying a PointLight, above the machine line so the plan
		-- clearances below stay the machines' own.
		Torch = {
			spacing = 45,
			height = 15,             -- bracket centre above the floor
			bracket = { 0.8, 0.8, 1.4 },   -- along the wall, tall, reach off the face
			flame = { 1, 1.6, 1 },
			-- Dim on purpose (#162 tophat): at 1.6 a ring of torches read as
			-- floodlights; a torch is warmth at the wall, and the world lights
			-- the plot.
			brightness = 0.6,
			-- Roblox CLAMPS a light's Range at 60 and says nothing about it, so a
			-- number above that reads as set and is not. Asserted.
			range = 26,
			clearance = 2,
		},

		-- invariant: A BUDGET. Config.shellPartCount() models the shell's part
		-- count from this spec and the verifier asserts the result at every land
		-- state. Whether it holds at full scale in a real server is open —
		-- design:D-03.
		PartBudget = 200,
	}

	-- design:D-02, via #162 — THE MASONRY, in tier order. The wall ships wooden;
	-- each purchase restyles every standing course, lintel and buttress in place
	-- — the glazing mechanism generalised: a material change on parts that
	-- already exist, zero new ones — and raises wall and gate health by one
	-- Health.WallPerTier/GatePerTier step. The gate leaves and the trim keep
	-- their timber: a castle's doors are wood, and a stone door reads as more
	-- wall.
	--
	-- `material` is an Enum.Material NAME, resolved at build time; whether each
	-- name is a real material only Studio can say, so the shipped four are on
	-- the Studio checklist.
	Config.Structure.Tiers = {
		{ structure = "cobble",     material = "Cobblestone", color = Color3.fromRGB(124, 120, 112) },
		{ structure = "stone",      material = "Limestone",   color = Color3.fromRGB(150, 146, 138) },
		{ structure = "slate",      material = "Slate",       color = Color3.fromRGB(102, 106, 114) },
		{ structure = "stonebrick", material = "Brick",       color = Color3.fromRGB(146, 140, 130) },
	}

	-- design:D-02, via #124 — the walls and gate are breakable, and their
	-- toughness arrives with the land (level = expansions owned + 1) and with the
	-- masonry (#162: each tier owned adds a PerTier step), so a grown, stone
	-- plot is a harder target. The state machine is tycoon/Siege.lua; players
	-- land damage through CombatService's structure observer, mobs will land
	-- theirs when #163 lets them reach a wall.
	Config.Structure.Health = {
		WallBase = 600,
		WallPerLevel = 150,
		WallPerTier = 300,
		-- The gate is the door a raider is MEANT to break (#94): cheaper than a
		-- wall, and the verifier holds it to "never one swing, never a siege" for
		-- every bat at every level and every tier. GatePerTier is bounded above by
		-- the maxed-break check: past ~96 the starter bat cannot open a fully
		-- grown stone keep inside 90 seconds.
		GateBase = 300,
		GatePerLevel = 75,
		GatePerTier = 90,
		-- Same shape as the storage unit's repair: quick, manual, owner-present,
		-- and it has to finish inside the raid's warning window (asserted).
		RepairSeconds = 3,
		PlayerDamageScale = 1,
		-- #89's mobs hit masonry at half a player's weight: the plot-wave breach
		-- floors (warning + time-to-breach covers the run home) are asserted
		-- against this, and at 1 a bare plot's storage fell before its owner
		-- could sprint back from the mid band.
		MobDamageScale = 0.5,
	}

	--- design:D-02, via #98 — what the storage unit can hold, in Tung: CapMinutes
	--- of the plot's income with the rebirth term, floored for a fresh plot, and
	--- collapsed to the broken floor while the unit is smashed. Pure arithmetic;
	--- the verifier walks the whole curve against it.
	function Config.storageCap(has: (string) -> boolean, rebirths: number?, intact: boolean?): number
		if intact == false then
			return Config.Storage.BrokenCapFloor
		end
		local rate = Config.incomeRate(has)
			* Config.Rebirth.MultiplierPerRebirth ^ math.max(0, rebirths or 0)
		return math.max(Config.Storage.CapFloor, rate * Config.Storage.CapMinutes * 60)
	end

	--- A wall's full health at `level` = expansions owned + 1 and `tiers` =
	--- masonry tiers owned (default 0, the wooden wall — so every caller that
	--- predates the masonry stays correct).
	function Config.wallMaxHealth(level: number, tiers: number?): number
		local H = Config.Structure.Health
		return H.WallBase + H.WallPerLevel * (level - 1) + H.WallPerTier * (tiers or 0)
	end

	--- A gate's full health at the same level and tier.
	function Config.gateMaxHealth(level: number, tiers: number?): number
		local H = Config.Structure.Health
		return H.GateBase + H.GatePerLevel * (level - 1) + H.GatePerTier * (tiers or 0)
	end

	-- The one structural line: floor top to the wall's top.
	-- design:D-02, via #162 — raised from the storey system's inherited 20.4 for
	-- the castle silhouette. Every reader is an inequality that relaxes upward
	-- (labels under it, machines under it, openings inside it), so the trim line
	-- moves and nothing else does.
	Config.Structure.WallHeight = 24

	--- One wall of the ring: the axis it runs along, its fixed coordinate on the
	--- other axis, and its extent — for a plot owning `left`/`right` expansions a
	--- side (both default 0, the bare centre).
	---
	--- Note the asymmetry, which is how the shell has always been built: the side
	--- walls run the FULL plot depth and the front and back walls sit between them.
	--- Changing that changes four corners at once. Land grows the ring along X
	--- only: the front and back walls lengthen, the side walls MOVE outward, and
	--- depth never changes — which is what keeps the leash, gate-trap and
	--- warning-walk arithmetic still about the same distances.
	function Config.wallExtent(side: string, left: number?, right: number?)
		local extents = Config.landExtents(left or 0, right or 0)
		local minX, maxX = extents.minX + 1, extents.maxX - 1
		local halfZ = Config.World.PlotSize.Z / 2 - 1
		if side == "back" then
			return { axis = "X", fixed = -halfZ, from = minX, to = maxX, outward = -1 }
		elseif side == "front" then
			return { axis = "X", fixed = halfZ, from = minX, to = maxX, outward = 1 }
		elseif side == "left" then
			return { axis = "Z", fixed = minX, from = -Config.World.PlotSize.Z / 2,
				to = Config.World.PlotSize.Z / 2, outward = -1 }
		elseif side == "right" then
			return { axis = "Z", fixed = maxX, from = -Config.World.PlotSize.Z / 2,
				to = Config.World.PlotSize.Z / 2, outward = 1 }
		end
		return nil
	end

	Config.Structure.Sides = { "back", "front", "left", "right" }

	--- Every opening in one wall, in order along the wall.
	function Config.openingsIn(side: string)
		local found = {}
		for _, opening in ipairs(Config.Structure.Openings) do
			if opening.side == side then
				table.insert(found, opening)
			end
		end
		table.sort(found, function(a, b)
			return a.centre < b.centre
		end)
		return found
	end

	--- THE WALL, AS A LIST OF SPANS. Solid runs and openings, in order, covering
	--- the whole extent with no gap and no overlap.
	---
	--- This is the function the builder emits from, the verifier sums, and a runtime
	--- spec exercises. A wall that does not account for its own span is now a failed
	--- check rather than a seven-stud band of daylight nobody measured.
	---
	--- ON A GROWN PLOT the front and back walls also split their solid runs at
	--- every land boundary, so each expansion's frontage is its own span. The
	--- centre's boxes never change size when land arrives — an expansion ADDS
	--- spans — and every opening stays on the centre span, which is what keeps
	--- "the gates are never rebuilt" true whatever the plot owns.
	function Config.wallSegments(side: string, left: number?, right: number?)
		local extent = Config.wallExtent(side, left, right)
		local segments = {}

		-- The split points: the centre pad's edges and each owned expansion's
		-- outer boundary, where they fall strictly inside the extent.
		local splits = {}
		if extent.axis == "X" then
			-- The centre/expansion boundary sits at the wall's INSET edge, the
			-- same 1 stud in from the ground joint the bare ring has always used,
			-- so the centre's spans are byte-identical at every land state and
			-- the first expansion adds a span without resizing a standing box.
			local halfX = Config.World.PlotSize.X / 2 - 1
			for _, boundary in ipairs({ -halfX, halfX }) do
				if boundary > extent.from and boundary < extent.to then
					table.insert(splits, boundary)
				end
			end
			for _, sideName in ipairs({ "left", "right" }) do
				local count = (sideName == "left") and (left or 0) or (right or 0)
				local steps = Config.landSteps(sideName)
				local sign = (sideName == "left") and -1 or 1
				for index = 1, math.min(count, #steps) do
					local boundary = sign * steps[index]
					if boundary > extent.from and boundary < extent.to then
						table.insert(splits, boundary)
					end
				end
			end
			table.sort(splits)
		end

		local function pushSolid(from, to)
			if to <= from then
				return
			end
			local cursor = from
			for _, split in ipairs(splits) do
				if split > cursor and split < to then
					table.insert(segments, { kind = "solid", from = cursor, to = split })
					cursor = split
				end
			end
			table.insert(segments, { kind = "solid", from = cursor, to = to })
		end

		local cursor = extent.from
		for _, opening in ipairs(Config.openingsIn(side)) do
			local openFrom = opening.centre - opening.width / 2
			local openTo = opening.centre + opening.width / 2
			pushSolid(cursor, openFrom)
			table.insert(segments, { kind = "opening", from = openFrom, to = openTo, opening = opening })
			cursor = openTo
		end
		pushSolid(cursor, extent.to)
		return segments, extent
	end

	--- Post centres along one wall at an even pitch: walked per SOLID run so no
	--- post lands in an opening, `clearance` of solid wall kept at every run
	--- edge, and the leftover split evenly so the row reads centred in its run.
	--- A run too short for the pitch still carries one centred post.
	local function postsAlong(side: string, left: number?, right: number?,
		spacing: number, clearance: number)
		local posts = {}
		for _, segment in ipairs(Config.wallSegments(side, left, right)) do
			if segment.kind == "solid" then
				local usable = (segment.to - segment.from) - 2 * clearance
				if usable >= 0 then
					local count = math.floor(usable / spacing) + 1
					local start = segment.from + clearance
						+ (usable - (count - 1) * spacing) / 2
					for index = 1, count do
						table.insert(posts, start + (index - 1) * spacing)
					end
				end
			end
		end
		return posts
	end

	--- Where one wall's buttress posts stand, along the wall's own axis:
	--- CORNER-ANCHORED (design:D-02, via #162). A post stands at each end of the
	--- wall's extent — the ring's corners — and the span between divides at the
	--- pitch nearest `spacing`, so the row reads centred on the wall whatever
	--- its length. A post whose footprint would land in an opening (plus the
	--- jamb clearance) is dropped, which is what flanks the gateway with the
	--- nearest surviving pair.
	function Config.buttressPositions(side: string, left: number?, right: number?)
		local b = Config.Structure.Buttress
		local extent = Config.wallExtent(side, left, right)
		local length = extent.to - extent.from
		local count = math.max(1, math.floor(length / b.spacing + 0.5))
		local pitch = length / count
		local posts = {}
		for index = 0, count do
			local post = extent.from + index * pitch
			local blocked = false
			for _, opening in ipairs(Config.openingsIn(side)) do
				local from = opening.centre - opening.width / 2 - b.clearance - b.width / 2
				local to = opening.centre + opening.width / 2 + b.clearance + b.width / 2
				if post > from and post < to then
					blocked = true
				end
			end
			if not blocked then
				table.insert(posts, post)
			end
		end
		return posts
	end

	--- Where one wall's torch brackets hang, along the wall's own axis.
	function Config.torchPositions(side: string, left: number?, right: number?)
		local torch = Config.Structure.Torch
		return postsAlong(side, left, right, torch.spacing,
			torch.clearance + torch.bracket[1] / 2)
	end

	--- invariant: how many parts one plot's shell costs, modelled from the spec
	--- above so the verifier can hold it to Config.Structure.PartBudget.
	---
	--- Per solid run: a sill, body and head course. Per opening: a lintel course
	--- over it, plus its leaves. Per side: a trim cap, the buttress posts, and
	--- two parts per torch (bracket + flame; the PointLight is not a Part).
	---
	--- IT MUST COUNT WHAT THE BUILDER EMITS, not what the wall spec implies. Its
	--- first version left out the trim, the light strip and the sign anchor, so it
	--- reported 59 against 68 actually built and 107 against 124 — a budget asserted
	--- 13% under the truth, which is a budget that passes right up until it matters.
	--- Both numbers were reconciled against a count taken from the real builder.
	function Config.shellPartCount(left: number?, right: number?): number
		local total = 0
		for _, side in ipairs(Config.Structure.Sides) do
			-- the trim cap along this wall's top
			total += 1
			total += #Config.buttressPositions(side, left, right)
			total += 2 * #Config.torchPositions(side, left, right)
			for _, segment in ipairs(Config.wallSegments(side, left, right)) do
				if segment.kind == "solid" then
					total += 3   -- sill, body and head course
				else
					total += 1 + segment.opening.leaves   -- lintel + gate leaves
				end
			end
		end
		return total
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- invariant: PROTOTYPES, and the graduates that used to be here
	--
	-- A flag in Config.Prototypes gates something UNSHIPPED, and every one of them
	-- defaults to OFF, so a build with all the flags false is byte-for-byte the game
	-- that ships today. That is the whole contract: a prototype you cannot turn off
	-- is not a prototype, it is a half-finished feature you have to finish before
	-- you can ship anything else.
	--
	-- The tables BELOW the flag table are a mix now. Config.PlayerUpgrades,
	-- Config.Utilities and Config.RebirthPerks are still prototype data; the offline
	-- and session families under them ship, and are ordinary Config like
	-- Config.Economy.
	--
	-- The sourcing for these is docs/design/research/IDEAS.md. Numbers here are
	-- first drafts, not balance.
	-- ─────────────────────────────────────────────────────────────────────────────

	-- GRADUATING DELETES THE FLAG, IT DOES NOT SET IT TRUE. The check in
	-- tools/verify_config.lua asserts every prototype flag ships off, so a feature
	-- that ships stops being a prototype rather than becoming the exception to the
	-- rule. `Floors`, `Offline` and `Sessions` all left this table that way, and the
	-- verifier now asserts by name that they do not come back.
	--
	--   Floors    the second floor is a purchase on the factory track, gated by
	--             owning its button like everything else.
	--   Offline   offline earnings, the welcome-back panel and the Vault Timer.
	--   Sessions  the daily streak, the playtime ladder, the boost button and the
	--             weekend bonus.
	Config.Prototypes = {
		PlayerUpgrades = false,-- walkspeed / magnet / cash multiplier shop
		Utilities = false,     -- a second weapon slot holding a verb, not a stat
		RebirthPerks = false,  -- rebirth grants four things instead of one number
		Sound = false,         -- the engine-asset sound layer
	}

	-- ── player upgrades ──────────────────────────────────────────────────────────
	--
	-- Deliberately small. Pet Sim 99's whole walkspeed track is +25% over two
	-- tiers, and its biggest stat track is +54% over eight. The large multipliers
	-- belong to rebirth; this shop is for shaving friction off the loop.
	Config.PlayerUpgrades = {
		{
			id = "speed", name = "Sahur Sprint",
			stat = "WalkSpeed", levels = 8,
			base = 22, perLevel = 1.1,        -- caps at 30.8, under the ~32 wall-clip ceiling
			cost = 250, costGrowth = 4,
			blurb = "Move %s studs/sec.",
		},
		{
			id = "magnet", name = "Tung Magnet",
			stat = "CollectRadius", levels = 7,
			base = 0, perLevel = 4,
			cost = 400, costGrowth = 3.4,
			blurb = "Pull drops in from %s studs.",
		},
		{
			id = "payout", name = "Vault Skimmer",
			stat = "CashMultiplier", levels = 7,
			base = 1, perLevel = 0.08,
			cost = 800, costGrowth = 5,
			blurb = "All income x%s.",
		},
		{
			id = "autocollect", name = "Auto Collector",
			stat = "AutoCollect", levels = 1,
			base = 0, perLevel = 1,
			cost = 60000, costGrowth = 1,
			blurb = "The vault collects itself.",
		},
	}

	-- ── the utility slot ─────────────────────────────────────────────────────────
	--
	-- Steal a Brainrot's weapon ladder is one archetype reskinned eleven times,
	-- scaling exactly one stat. All of its VARIETY lives in a second slot where
	-- every item is a new verb with one duration number. That split is the thing
	-- worth copying: progression in the weapon, variety in the utility.
	--- `radius` and `force` are per-verb, not global: how far a shove reaches is a
	--- property of the shove, and the moment they are shared constants the next
	--- utility has to fight them.
	Config.Utilities = {
		{ id = "freeze", name = "Sahur Freeze", verb = "freeze", duration = 4, cooldown = 18,
		  price = 40000, requires = "batforge", radius = 34 },
		{ id = "shove", name = "Tung Shove", verb = "shove", duration = 0, cooldown = 12,
		  price = 300000, requires = "upgrader3", radius = 26, force = 130 },
		{ id = "decoy", name = "Sahur Decoy", verb = "decoy", duration = 10, cooldown = 30,
		  price = 4000000, requires = "batforge2", radius = 6 },
	}

	-- ── rebirth perks ────────────────────────────────────────────────────────────
	--
	-- Four rewards per rebirth instead of one. The multiplier is the headline but
	-- the other three are what stop the re-grind feeling like a punishment, and
	-- what give MaxRebirths = 25 something on every rung.
	Config.RebirthPerks = {
		StartingCashPerRebirth = 2500,     -- compounding is handled by the multiplier
		StartingCashGrowth = 3.2,
		-- every Nth rebirth grants a permanent extra machine slot
		SlotEveryRebirths = 3,
		-- Milestone unlocks: rebirth -> what opens up. A milestone must name
		-- something NOTHING ELSE SELLS, and the verifier asserts that against
		-- Config.Buttons.
		--
		-- `[2] = { unlock = "mezzanine" }` used to sit at the top of this table and
		-- was stale from the day the second floor graduated: the mezzanine became
		-- the floor2 button on the factory track, so the milestone was either a
		-- second way to get something you had already bought or a promise of
		-- something you could not be given. Rebirth 2 grants the multiplier and the
		-- starting cash, and no unlock, until there is a real thing to unlock there.
		Milestones = {
			[4] = { unlock = "utility2", label = "Utility slot II" },
			[8] = { unlock = "goldplot", label = "Golden plot theme" },
		},
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- SHIPPED: offline earnings and the session loops
	--
	-- These two families used to be Config.Prototypes.Offline and .Sessions. They
	-- are ordinary config now — SessionService reads them unconditionally and every
	-- number below is live in front of players.
	-- ─────────────────────────────────────────────────────────────────────────────

	-- ── offline earnings ─────────────────────────────────────────────────────────
	Config.Offline = {
		Rate = 0.25,             -- fraction of your live income per second
		CapHours = 8,
		-- Extending the cap is a PURCHASE — the Vault Timer — which turns the cap
		-- into a goal rather than a wall you resent. Priced like a side-track rung:
		-- the verifier checks each tier against the income the factory has at the
		-- moment it can first bank that many tung.
		CapUpgradeHours = { 12, 16, 24 },
		CapUpgradeCost = { 250000, 5000000, 5500000000 },
		MinimumSeconds = 120,    -- below this, don't bother with the panel

		-- THE VAULT GAUGE — offline earnings made VISIBLE ON THE WAY OUT.
		--
		-- The panel on the way back in was never the missing half. A player who has
		-- not yet been away has no reason to believe that being away pays, and a
		-- popup at logout is read by nobody: it appears at the exact moment
		-- attention has already left. So the vault wears the number instead, all
		-- session, as a column you watch and a headline you read walking off the
		-- plot — "leaving now banks X over 8h", which grows with every dropper.
		--
		-- Two modes out of one formula. Online, banked is zero, the column reads
		-- empty and the headline is the PROMISE. On return, banked is the pending
		-- offline grant, the column is full and the headline is what is WAITING.
		Vault = {
			-- Roblox will not accept a zero-height part, and a gauge that vanishes
			-- when empty reads as "broken" rather than as "nothing yet". The empty
			-- column keeps a visible sliver.
			FillMin = 0.02,
			-- The headline is the plot's own number, read from the arena; the small
			-- print resolves only when you walk up to it. Names, not studs — the
			-- numbers behind them belong to Config.Style.Distance.
			Distance = "plot",
			NearDistance = "prop",
			-- How long the column takes to drain after a claim. It has to be long
			-- enough to WATCH: the drain is the counter ticking, and a gauge that
			-- snaps to empty shows nothing at all.
			PulseSeconds = 2.0,
			-- ProximityPrompt reach. Deliberately short and unrelated to the label
			-- tiers above: a prompt you can trigger from across the plot is a
			-- prompt you trigger by accident.
			PromptDistance = 12,
			PromptHoldSeconds = 0.4,
		},
	}

	-- ── session loops ────────────────────────────────────────────────────────────
	Config.Sessions = {
		-- 7-day loop with milestones. 48h of grace, because losing a 20-day streak
		-- to one missed evening is how you lose the player instead of the streak.
		DailyRewards = { 500, 1500, 4000, 10000, 25000, 60000, 150000 },
		DailyGraceHours = 48,
		DailyMilestones = { [7] = 250000, [14] = 750000, [30] = 3000000 },

		-- Pet Sim 99's ladder, and note the deliberately decaying cadence: close
		-- together early so the first one arrives while you are still deciding
		-- whether to stay.
		--
		-- The rungs are claimed once per UTC DAY, not once per session, so these
		-- rewards are a recurring daily income rather than a one-off. The verifier
		-- checks the ladder's running total against what the factory produces over
		-- the same minutes: it must supplement the plot, never out-earn it.
		PlaytimeMinutes = { 5, 10, 15, 20, 30, 40, 50, 60, 75, 90, 120, 180 },
		PlaytimeRewardBase = 1200,
		PlaytimeRewardGrowth = 1.9,

		-- The rewarded-video-ad shape with the ad removed: a big multiplier over a
		-- short window, which forces an active session rather than being banked.
		BoostMultiplier = 2,
		BoostSeconds = 600,
		BoostCooldown = 2400,

		-- near-zero code, real concurrency effect
		WeekendMultiplier = 2,
		WeekendDays = { [1] = true, [7] = true },   -- os.date("!*t").wday, Sun and Sat
	}

	-- ── sound ────────────────────────────────────────────────────────────────────
	--
	-- Every one of these ships INSIDE the Roblox client. No upload, no moderation,
	-- and they cannot be taken down. The old handoff assumed audio was blocked
	-- until someone uploads samples; it is not, and this is the cheapest quality
	-- win on the list.
	Config.Sound = {
		Library = {
			collect  = "rbxasset://sounds/electronicpingshort.wav",
			purchase = "rbxasset://sounds/switch3.wav",
			ui       = "rbxasset://sounds/button.wav",
			impact   = "rbxasset://sounds/impact_water.mp3",
			swing    = "rbxasset://sounds/swoosh.wav",
			rebirth  = "rbxasset://sounds/victory.wav",
			siren    = "rbxasset://sounds/action.wav",
		},
		-- Pool and round-robin; never Instance.new per drop. ~400 live Sound
		-- instances is where audio/video desync starts.
		PoolSize = 8,
		MinRepeatSeconds = 0.04,
		RollOffMaxDistance = 60,   -- so a neighbour's factory doesn't blare at you
		PitchPerCombo = 0.06,
		MaxPitch = 2,
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Derived lookups (built once at require time)
	-- ─────────────────────────────────────────────────────────────────────────────

	-- Resolved once, at require time, so every module sees the same numbers.
	-- The widest a plot can get: the centre plus every expansion on both sides.
	-- Derived here, after the land tables exist. Ring packing reserves this — a
	-- plot can max out, so the world has to hold the maxed chord.
	do
		local width = Config.World.PlotSize.X
		for _, side in ipairs({ "left", "right" }) do
			for _, def in ipairs(Config.landRows(side)) do
				width += def.width
			end
		end
		Config.World.PlotMaxWidth = width
	end

	-- Every strip's sub-belt joins Config.BeltPaths here, after the land tables
	-- and the path derivation both exist. Registered data, built parts: the belt
	-- assertions and the drop budget see all eleven paths, and ensureLand builds
	-- each strip's surfaces only when the strip is standing.
	for _, side in ipairs({ "left", "right" }) do
		for _, def in ipairs(Config.landRows(side)) do
			table.insert(Config.BeltPaths, Config.landBeltPath(def))
		end
	end

	Config.World.PlotCount = Config.plotCountFor()
	Config.World.PlotPlacements = Config.plotPlacements(Config.World.PlotCount)
	Config.World.PlotRadius = Config.World.PlotPlacements[1].radius   -- inner ring

	-- invariant: THE MERGE. The five track tables become one Config.Buttons, in
	-- track order, so every consumer downstream iterates a single array.
	--
	-- FACTORY FIRST IS LOAD-BEARING. It leaves every factory button with the same
	-- `order` it had when there was only one table, which is what lets
	-- Tycoon:assign keep replaying installs by sorting on `order` — weapons and
	-- armour land after the whole factory, and because no requirement crosses a
	-- track that ordering is trivially valid. It also keeps the verifier's
	-- "requires must point at an earlier index" check true without modification.
	--
	--   order       position in the merged array. The install-order key. Global.
	--   trackOrder  position within the button's own track. The gating and
	--               display key: it is what the buy-button billboard counts, what
	--               the three-state reveal measures its frontier against, and
	--               what the HUD calls a step.
	-- POWER WENT LAST FOR THIS REASON: appending leaves every existing button's
	-- `order` exactly where it was, so no save's install replay changes sequence.
	--
	-- STRUCTURE DOES NOT GO LAST, AND THAT BREAKS THE CONVENTION DELIBERATELY.
	-- Two things make it the right call anyway. The first is that the convention
	-- is already spent: pulling four rows out of FactoryButtons renumbers the
	-- merged array from index 5 onwards no matter where the new track is spliced
	-- in, so there is no placement that preserves the old `order` values. The
	-- second is that `order` is not a saved field. A profile stores
	-- `owned = { [id] = true }` and Tycoon:assign sorts those ids against the
	-- CURRENT Config every time it replays them, so renumbering costs nothing as
	-- long as ids never change — which is a rule this file already enforces for
	-- other reasons (see the WeaponButtons banner).
	--
	-- design:D-03, design:D-05 — POSITION IN THIS LIST IS THE BEACON.
	-- Config.TrackRank is the TrackOrder index, and both Tycoon:pointAt and the HUD
	-- card rank candidates by (rank, price). Nothing in the verifier can catch a
	-- beacon that points somewhere useless; it is a property of this list and it
	-- has to be decided here.
	Config.TrackOrder = { "factory", "structure", "weapons", "armor", "power", "landL", "landR" }
	Config.Tracks = {
		factory   = Config.FactoryButtons,
		structure = Config.StructureButtons,
		weapons   = Config.WeaponButtons,
		armor     = Config.ArmorButtons,
		power     = Config.PowerButtons,
		landL     = Config.LandLButtons,
		landR     = Config.LandRButtons,
	}

	-- invariant: EVERYTHING THAT IS TRUE OF A TRACK RATHER THAN OF A BUTTON, in
	-- one table.
	--
	-- Adding a fourth track is mostly an exercise in finding the per-track facts,
	-- because they were scattered across five tables in three files and one of them
	-- existed TWICE.
	--
	-- invariant: A MISSING ROW IN EACH FAILS DIFFERENTLY AND NONE FAIL LOUDLY:
	--
	--   where its buttons stand    Layout.Tracks[track] is nil -> indexing nil ->
	--                              buildButtons throws -> the plot fails to build
	--   survives a rebirth         asserted from two places with opposite polarity;
	--                              a missing row FAILS OPEN and the generator
	--                              survives the reset it is supposed to be part of
	--   beacon rank                one copy in Tycoon and one in HUD: the panel
	--                              names one purchase, the beacon glows on another
	--   preview depth              falls back to 3, so a 4-rung ladder previews
	--                              itself entirely from the moment you claim
	--   spine or detour            the verifier prices it as a side track, which is
	--                              wrong for anything that multiplies income
	--
	-- `rank` is not here because it is exactly the TrackOrder index; it is derived
	-- below, which deletes both copies rather than adding a third.
	Config.TrackInfo = {
		-- design:D-05, via #125 — THE PURCHASE SURFACE IS THREE CATEGORIES:
		-- conveyor (everything that makes the line earn more), generator, and
		-- plot (the ground and the shell on it). `category` is the label a pad
		-- and the HUD card wear; the TRACKS underneath stay chains, because the
		-- chains carry the orderings geometry forces (no L2 without L1) and the
		-- categories are what the player is asked to hold. The cabinet tracks
		-- keep their own labels until #108 moves them off the plot.
		--
		-- The conveyor outranks everything by TrackOrder POSITION, which is what
		-- "the conveyor's label sits highest" already means to the card and the
		-- beacon: both rank by (TrackRank, price).
		-- preview = 2 across the pad tracks (#162 tophat): the buyable rung and
		-- ONE ghost beyond it. At 3 the conveyor carried a second ghost and the
		-- plot read as a wall of pads before the second dropper.
		factory = { label = "CONVEYOR", category = "conveyor", preview = 2, keepOnRebirth = false, paced = "spine", furniture = "misc" },
		-- invariant: THE SHELL. Most of its facts are FORCED rather than chosen;
		-- preview is design:D-03.
		--
		-- paced = "spine" because the detour model prices a track against a curve
		-- it does not change AND assumes you can decline it, and the shell's
		-- purchases have historically been gated on and by the spine. Priced as a
		-- detour, the purchases do not stop happening — the verifier just stops
		-- counting them.
		--
		-- keepOnRebirth = false because rebirth() clears self.machines
		-- unconditionally and the wall ring lives there, not in self.props. Set it
		-- true and the ring is destroyed while `owned.walls` survives, so
		-- refreshButtons hides a pad for a building that is not standing and the
		-- plot has no shell for the rest of that owner's life. The cabinets get to
		-- be true because their props are the exempt folder; this track is not.
		--
		-- furniture = "misc" because these rows already have hand-placed positions
		-- in Layout.MiscButtons and they are exactly the case that table is for:
		-- unrelated purchases in a line down an open floor.
		--
		-- preview = 2 is the one real choice: the pad one rung out is visible, the
		-- rest of the ladder waits. #162's masonry tiers will lean on it the way
		-- the roof's price tag once did.
		structure = { label = "PLOT", category = "plot", preview = 2, keepOnRebirth = false, paced = "spine", furniture = "misc" },
		weapons = { label = "WEAPONS", category = "weapons", preview = 2, keepOnRebirth = true,  paced = "side",  furniture = "shop" },
		armor   = { label = "ARMORY",  category = "armor",  preview = 2, keepOnRebirth = true,  paced = "side",  furniture = "shop" },
		-- The generator multiplies exactly what a rebirth resets. Keeping it would
		-- stack x2 on top of MultiplierPerRebirth 2.25 for an effective 4.5x first
		-- prestige, which makes the asserted CostGrowth/MultiplierPerRebirth ratio
		-- a lie about the real pacing. It is plot machinery, same class as a
		-- dropper — not a monotone character grant like a bat or a suit of armour.
		-- preview = 0, and it is load-bearing rather than a taste call. All four
		-- rungs resolve to ONE pad position, so a preview pad would be built inside
		-- the lit one. At 2 it put three pads in the yard on a plot that had bought
		-- none of them, which is most of what "the generator is visually intrusive
		-- on plot creation" was about. The verifier asserts this is 0.
		power   = { label = "GENERATOR", category = "generator", preview = 0, keepOnRebirth = false, paced = "spine", furniture = "yard" },
		-- design:D-03 — LAND SURVIVES A REBIRTH (#88, via #78: rebirth raises the
		-- ceiling on what can exist; the ground is the ceiling). keepOnRebirth
		-- works here because ensureLand rebuilds the slabs from `owned` on the
		-- refreshButtons beat, so land needs no exempt props folder — the
		-- cabinet-only argument the verifier states is widened to name land.
		--
		-- preview = 0 for the power track's reason, which is load-bearing: every
		-- rung of a side resolves to ONE pedestal, so a preview pad would be built
		-- inside the lit one.
		--
		-- paced = "spine": land is the plot's own growth and the simulation walks
		-- it; priced as a detour it would stop counting toward the build.
		landL   = { label = "PLOT", category = "plot", preview = 0, keepOnRebirth = true, paced = "spine", furniture = "land" },
		landR   = { label = "PLOT", category = "plot", preview = 0, keepOnRebirth = true, paced = "spine", furniture = "land" },
	}

	Config.TrackLabel = {}
	Config.TrackRank = {}
	for rank, track in ipairs(Config.TrackOrder) do
		Config.TrackRank[track] = rank
		Config.TrackLabel[track] = Config.TrackInfo[track] and Config.TrackInfo[track].label or track:upper()
	end

	-- design:D-03 — WHAT A WHOLE LADDER WAITS ON, and why the cabinets and the
	-- shell all arrive on a gate rather than on claim.
	--
	-- invariant: DELIBERATELY NOT A `requires` ON EACH TRACK'S FIRST RUNG. The
	-- loader derives requirements within a track and the verifier asserts none ever
	-- crosses one; that guarantee is worth more than the convenience, and a
	-- precondition on an entire ladder is a different kind of thing from a link
	-- inside one.
	--
	-- A GATE MUST NAME A FACTORY BUTTON — asserted, because a side track gating a
	-- side track can deadlock. The gate is STICKY, so a rebirth that wipes
	-- `dropper3` does not take both cabinets with it.
	--
	-- `structure` waits for `dropper3` (#162 tophat): it opened on `dropper1`
	-- and the walls pad stood unaffordable for the first minutes of every
	-- session — a pad that appears is a pad that should be close to buyable,
	-- and by dropper3 the 1,500 is nearly banked. The greedy curve already
	-- bought `walls` after dropper3, so the pacing simulation does not move.
	Config.TrackUnlock = {
		weapons = "dropper3", armor = "dropper3", structure = "dropper3",
		-- Land opens once the centre pad is earning properly: mid-build, when the
		-- line is established and the next thing to want is room.
		landL = "dropper5", landR = "dropper5",
	}

	-- design:D-03, via #125 — Config.ButtonUnlock and its helper are GONE. The
	-- one entry ever shipped gated the mezzanine on the roof, and the mechanism
	-- retired with the storey system: three categories and per-track chains need
	-- nothing that gates ONE purchase across a ladder, and a mechanism nothing
	-- uses is a mechanism that silently rots. TrackUnlock is the surviving gate
	-- shape — a precondition on a whole ladder — and the reachability fixpoint
	-- still counts it.

	--- Whether `track` is open on a plot that owns `owned`.
	---
	--- STICKY, and derived rather than stored. Owning any rung of a track counts as
	--- having it open, which matters because rebirth wipes the factory (and so the
	--- gate button) while deliberately keeping weapons and armour. Without that
	--- clause a rebirth would make the cabinets vanish while the shelf displays and
	--- the granted bat survived — a cabinet-shaped hole with a bat floating in it.
	--- Derived this way it costs no new persisted field and no migration.
	function Config.trackUnlocked(track: string, owned): boolean
		local gate = Config.TrackUnlock[track]
		if not gate or owned[gate] then
			return true
		end
		for _, def in ipairs(Config.Tracks[track] or {}) do
			if owned[def.id] then
				return true
			end
		end
		return false
	end

	--- Whether one row survives a rebirth. Per-track via TrackInfo, with one
	--- carve-out: on a land track the GROUND survives (design:D-03 — rebirth
	--- raises the ceiling, and the ground is the ceiling) while the machines
	--- standing on it reset — an upgrader that outlived the wipe would multiply
	--- the next build from minute zero, which is the generator's argument one
	--- track over.
	function Config.keptOnRebirth(def): boolean
		local info = Config.TrackInfo[def.track]
		if not info or not info.keepOnRebirth then
			return false
		end
		if info.furniture == "land" then
			return def.kind == "Land"
		end
		return true
	end

	Config.Buttons = {}
	Config.ButtonById = {}
	for _, track in ipairs(Config.TrackOrder) do
		local defs = Config.Tracks[track]
		for trackOrder, def in ipairs(defs) do
			def.track = track
			def.trackOrder = trackOrder
			-- A track IS a chain, so derive the link rather than restating it.
			-- This is what makes "no requirement crosses a track" a property of
			-- the loader instead of a promise the verifier has to police, and it
			-- deletes the single most error-prone field in this file for every
			-- row that doesn't genuinely need something unusual.
			if def.requires == nil and trackOrder > 1 then
				def.requires = defs[trackOrder - 1].id
			end
			table.insert(Config.Buttons, def)
			def.order = #Config.Buttons
			Config.ButtonById[def.id] = def
		end
	end

	-- design:D-05, via #125 — the category ordinals the pads and the card count
	-- by. A pad says "PLOT 20/34" rather than naming one of three internal
	-- chains: the categories are what the player is asked to hold, and the
	-- count's width is the category's whole size.
	Config.CategoryCount = {}
	for _, def in ipairs(Config.Buttons) do
		local info = Config.TrackInfo[def.track]
		def.category = info and info.category or def.track
		Config.CategoryCount[def.category] = (Config.CategoryCount[def.category] or 0) + 1
		def.categoryOrder = Config.CategoryCount[def.category]
	end

	--- Every price on the SPINE, highest first.
	---
	--- The spine is what the progression simulation walks and what the build time
	--- is measured against. Weapons and armour are deliberately excluded: they are
	--- side tracks, priced against the factory rather than pacing it, and a bat
	--- costing more than a dropper is the entire point of that split.
	---
	--- READS `paced` RATHER THAN NAMING THE TRACKS. It listed factory and power by
	--- hand while its own comment argued from "what the simulation walks", which is
	--- two statements of one fact with a list as the tiebreak — the same shape as
	--- the two hand-kept copies of the beacon ranking that TrackRank replaced. A
	--- third spine track had to be added in two places or it would have been
	--- half-counted, and the half that got missed would have been this one, silently,
	--- because nothing downstream of here fails loudly on a slightly short list.
	function Config.spinePricesDescending(): { number }
		local prices = {}
		for _, track in ipairs(Config.TrackOrder) do
			if Config.TrackInfo[track].paced == "spine" then
				for _, def in ipairs(Config.Tracks[track]) do
					table.insert(prices, def.price)
				end
			end
		end
		table.sort(prices, function(a, b)
			return a > b
		end)
		return prices
	end

	--- What the rebirth pad costs: the price of the PriceRung-th most expensive
	--- thing on the spine, rounded to two significant figures.
	---
	--- The rounding is not cosmetic. Unrounded, this would change in its ninth
	--- digit every time anyone touched an unrelated dropper, and every one of those
	--- changes would rewrite build/ and land in a diff as noise.
	function Config.rebirthBaseCost(): number
		local prices = Config.spinePricesDescending()
		local raw = prices[Config.Rebirth.PriceRung] or prices[#prices] or 0
		if raw <= 0 then
			return 0
		end
		local magnitude = 10 ^ (math.floor(math.log(raw, 10)) - 1)
		return math.floor(raw / magnitude + 0.5) * magnitude
	end

	Config.Rebirth.BaseCost = Config.rebirthBaseCost()

	Config.BatById = {}
	for tier, def in ipairs(Config.Bats) do
		def.tier = tier
		Config.BatById[def.id] = def
	end

	Config.ArmorById = {}
	for tier, def in ipairs(Config.Armor.Tiers) do
		def.tier = tier
		Config.ArmorById[def.id] = def
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- invariant: ANALYTICS
	--
	-- The schema lives in Config for the same reason the fonts do: the verifier can
	-- only check what it can see, and EVERY limit below is a silent counting
	-- failure. Roblox does not error, warn, or drop a line in the output window when
	-- you exceed one — the event is accepted, the field is discarded, and the chart
	-- you look at three weeks later is simply wrong in a way that looks like data.
	--
	-- The four that bite, verbatim from the reference:
	--
	--   * THREE custom fields per event, and only under the keys
	--     Enum.AnalyticsCustomFieldKeys.CustomField01/02/03. A fourth key of any
	--     name is ignored.
	--   * Field values must be STRINGS. A number is dropped.
	--   * 8,000 unique combinations of field values PER EXPERIENCE — one shared
	--     budget across every event, not a per-event allowance. This is the limit
	--     that a well-meaning "let's also break it down by button" blows through,
	--     and it is why nothing continuous is ever allowed into a field.
	--   * 100 custom event names per experience.
	--
	-- The consequence of the third is the single rule this schema is built on:
	-- EVERYTHING CONTINUOUS GOES IN `value`, NEVER IN A FIELD. `value` is a real
	-- number Roblox aggregates for you and costs nothing from the combination
	-- budget. A field is a facet, and a facet with a thousand values is a facet you
	-- cannot afford.
	-- ─────────────────────────────────────────────────────────────────────────────

	Config.Analytics = {
		-- The kill switch. Analytics.lua ANDs this with "is a server" and "is not
		-- Studio", because the API silently no-ops on the client and in Studio.
		Enabled = true,

		-- Platform limits. Named rather than written as literals in the verifier so
		-- the failure message can quote the number that was exceeded.
		MaxFields = 3,
		-- Raised from 40 when the land rows joined the milestone set (48, then 72
		-- when #109 put each strip's machines on the chain): the set is every
		-- button plus "none", and the binding budget is MaxCombinations, which is
		-- asserted separately.
		MaxFieldValues = 72,      -- widest single value set we will allow ourselves
		MaxCombinations = 8000,
		MaxEventNames = 100,
		MaxEconomySkus = 100,
		MaxTransactionTypes = 20,
		MaxCurrencyTypes = 5,

		-- THE RATE LIMIT IS NOT IN THE REFERENCE DOCS. A Roblox staff forum post
		-- gives roughly 120 + 20 x CCU service calls per minute; nothing in the
		-- published documentation confirms it. Treat these two numbers as a design
		-- budget we chose, not as a contract Roblox has stated — if the real ceiling
		-- is lower we will find out by losing events silently, which is exactly why
		-- Analytics.lua counts its drops instead of assuming there are none.
		RateBurst = 120,
		RatePerPlayerPerMinute = 20,

		-- How long the join waits for the client's platform before giving up and
		-- logging "unknown". There is no edit path on a logged event, so a session
		-- that fires early with a wrong platform is wrong forever.
		HelloTimeoutSeconds = 10,
		-- Last N events kept in memory for `Analytics.tail`, which is the only way
		-- to answer "what did the server actually send" without a dashboard.
		TailSize = 64,

		-- The currency name Roblox aggregates economy events under. One currency, so
		-- the 5-type limit is not in play, but it is named so the verifier can see it.
		Currency = "Tung",
		-- Every transaction type we ever pass to LogEconomyEvent. Limit is 20 per
		-- experience and they are strings, so a typo is a new type, not an error.
		TransactionTypes = { "Shop", "Gameplay", "TimedReward" },
	}

	--- A FIELD is a named, CLOSED set of strings. Two shapes:
	---
	---   * a plain `values` list — a label per state, e.g. clipped / within_cap
	---   * `bounds` + `values`, which is a bucket ladder: #values == #bounds + 1,
	---     and Analytics.bucket() picks values[i] for the first bound the number
	---     does not exceed. Bounds are what turn a continuous quantity into a facet
	---     the combination budget can afford; the quantity itself still goes in
	---     `value`, so no resolution is lost.
	---
	--- Two of these are DERIVED from the ladder below rather than hand-listed, so a
	--- new button cannot drift out of the schema: a hand-typed button list would go
	--- stale the first time someone adds a dropper, and the symptom would be a
	--- purchase logged under the wrong facet rather than an error.
	Config.Analytics.Fields = {
		platform = { values = { "desktop", "mobile", "tablet", "console", "vr", "unknown" } },
		-- `unknown` is the sixth entry because GetJoinData is a network call in a
		-- pcall: it can fail, and a failed read is not a direct join.
		entry = { values = { "direct", "follow_friend", "referral", "teleport", "private_server", "unknown" } },

		sessionIndex = {
			bounds = { 1, 2, 5, 20 },
			values = { "1", "2", "3-5", "6-20", "21+" },
		},
		-- Time to the first purchase of the account. The first two buckets are
		-- narrow on purpose: onboarding either lands in the first minute or it is a
		-- different conversation.
		secondsBucket = {
			bounds = { 30, 60, 180, 600 },
			values = { "0-30s", "30-60s", "1-3m", "3-10m", "10m+" },
		},
		rebirthBand = {
			bounds = { 0, 1, 3, 9 },
			values = { "0", "1", "2-3", "4-9", "10+" },
		},
		-- Time away, both for `returned` and for what the offline vault was paying
		-- against. The 6-24h bucket straddles Offline.CapHours 8 deliberately: the
		-- `clipped` field on offline_claim is what answers the cap question, and
		-- splitting this set to answer it twice would cost combinations for nothing.
		awayBucket = {
			bounds = { 600, 3600, 21600, 86400, 604800 },
			values = { "<10m", "10m-1h", "1-6h", "6-24h", "1-7d", "7d+" },
		},
		-- Minutes into the session when a rebirth landed.
		minutesBucket = {
			bounds = { 10, 30, 60, 180, 480 },
			values = { "<10m", "10-30m", "30-60m", "1-3h", "3-8h", "8h+" },
		},
		clipped = { values = { "within_cap", "clipped" } },
		friendCount = {
			bounds = { 1, 2, 3 },
			values = { "1", "2", "3", "4+" },
		},
		serverKind = { values = { "public", "private" } },

		-- DERIVED below from Config.Tracks.factory and Config.Buttons.
		buttonId = { values = {} },
		milestone = { values = {} },
	}

	-- The factory track and nothing else: a first purchase is an ONBOARDING signal,
	-- and no other track can supply one. Adding a factory rung widens this set by
	-- one and the verifier re-prices the combination budget on the next run.
	--
	-- THE REASON HAS BEEN RESTATED TWICE AND WAS WRONG BOTH TIMES IN BETWEEN. It
	-- read "the side tracks are gated behind floor2 forty minutes in" for a round
	-- after round 8 moved that gate to `dropper3` at minute three. The durable form
	-- is the one that does not name a button: EVERY other track is gated on a
	-- factory rung (Config.TrackUnlock), and `power`, which is not, opens at 14000
	-- against a StartingCash of 100. So the first purchase is always a factory
	-- purchase, and it is `dropper1` in particular.
	--
	-- This set SHRANK by four when the shell moved to its own track, which is the
	-- derivation working: walls/gates/windows/roof were never reachable as a first
	-- buy and were costing combinations for a state that could not happen.
	for _, def in ipairs(Config.Tracks.factory) do
		table.insert(Config.Analytics.Fields.buttonId.values, def.id)
	end

	-- Every button on every track, plus "none" for a session that bought nothing.
	-- "How far did they get before they stopped" is the whole question `session_end`
	-- exists to answer, and it has to be able to answer "nowhere".
	for _, def in ipairs(Config.Buttons) do
		table.insert(Config.Analytics.Fields.milestone.values, def.id)
	end
	table.insert(Config.Analytics.Fields.milestone.values, "none")

	--- THE SEVEN EVENTS. `value` is prose: it names the number, because the number
	--- is the part a dashboard cannot label for you.
	---
	--- `friends_in_server` is deliberately NOT called `friend_bonus_active`. There
	--- is no friend bonus in this game, and an event named after a feature that does
	--- not exist reads as a bug six months from now. Named for what it measures, it
	--- also gives the co-play baseline BEFORE any bonus ships, which is the only
	--- thing that will make the bonus's effect readable.
	Config.Analytics.Events = {
		{
			name = "session_start", value = "session number",
			fields = { "platform", "entry", "sessionIndex" },
		},
		{
			name = "first_button_purchased", value = "seconds since join",
			fields = { "platform", "buttonId", "secondsBucket" },
		},
		{
			name = "session_end", value = "session seconds",
			fields = { "platform", "milestone", "rebirthBand" },
		},
		{
			name = "returned", value = "hours since last seen",
			fields = { "platform", "awayBucket", "sessionIndex" },
		},
		{
			name = "rebirth", value = "rebirth number",
			fields = { "platform", "minutesBucket", "rebirthBand" },
		},
		{
			name = "offline_claim", value = "Tung claimed",
			fields = { "platform", "clipped", "awayBucket" },
		},
		{
			name = "friends_in_server", value = "friends in server",
			fields = { "platform", "friendCount", "serverKind" },
		},
	}

	--- What this schema costs of the 8,000 combinations the whole EXPERIENCE gets.
	---
	--- Summed across events rather than maxed, because the budget is shared: two
	--- events with disjoint facets each spend their own product. One function, called
	--- by the verifier, by the specs and by anyone about to add a field, so nobody
	--- has to re-derive the arithmetic and get it wrong in the optimistic direction.
	function Config.analyticsCombinations(): number
		local total = 0
		for _, event in ipairs(Config.Analytics.Events) do
			local product = 1
			for _, field in ipairs(event.fields) do
				local set = Config.Analytics.Fields[field]
				product *= set and #set.values or 0
			end
			total += product
		end
		return total
	end

	--- Where a side track's buy button `slot` stands, in plot-local coordinates.
	---
	--- Component arithmetic on purpose: tools/verify_config.lua stubs Vector3 as a
	--- plain table with no operators, so anything that adds or scales a Vector3 at
	--- require time takes the whole verifier down.


	--- The cabinet body behind that column: centre, then size. Its long axis is Z,
	--- running the length of its own button column with four studs of overhang at
	--- each end so the case reads as containing the buttons rather than starting
	--- level with them.

	--- Shelf slot `slot` on the cabinet — where the display for a bought tier
	--- stands, so the case visibly fills up as you climb the track.

	function Config.requirementsOf(def)
		local req = def.requires
		if req == nil then
			return {}
		elseif type(req) == "string" then
			return { req }
		end
		return req
	end

	return Config
end


__MODULES["Fx"] = function()
	--[[
		Fx.lua — every particle / light / sound effect in the game, built from code.

		No asset uploads required: all textures use Roblox's built-in default
		particle sprites (rbxasset://textures/particles/*) which ship with the
		engine and are always available, so nothing here can be moderated away.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Sound = Req("Sound")

	local TweenService = game:GetService("TweenService")
	local Debris = game:GetService("Debris")

	local Fx = {}

	-- Built-in engine textures. These are shipped in the Roblox client itself.
	local SPARKLE = "rbxasset://textures/particles/sparkles_main.dds"
	local SMOKE   = "rbxasset://textures/particles/smoke_main.dds"
	local FIRE    = "rbxasset://textures/particles/fire_main.dds"

	local function emitter(part: BasePart, props: { [string]: any }): ParticleEmitter
		local p = Instance.new("ParticleEmitter")
		p.Name = "TungFx"
		p.Texture = SPARKLE
		p.Lifetime = NumberRange.new(0.4, 0.9)
		p.Rate = 12
		p.Speed = NumberRange.new(1, 3)
		p.SpreadAngle = Vector2.new(180, 180)
		p.LightEmission = 0.6
		p.LockedToPart = false
		for key, value in pairs(props) do
			(p :: any)[key] = value
		end
		p.Parent = part
		return p
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Per-variant recipes
	-- ─────────────────────────────────────────────────────────────────────────────

	local RECIPES: { [string]: (BasePart, any) -> () } = {}

	RECIPES.none = function() end

	RECIPES.sparkle = function(part, variant)
		emitter(part, {
			Color = ColorSequence.new(variant.accent, variant.wood),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.5),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 14,
			Lifetime = NumberRange.new(0.4, 0.8),
		})
	end

	RECIPES.dust = function(part, variant)
		emitter(part, {
			Texture = SMOKE,
			Color = ColorSequence.new(variant.wood),
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.5),
				NumberSequenceKeypoint.new(1, 1),
			}),
			Size = NumberSequence.new(1.2),
			Rate = 8,
			Speed = NumberRange.new(0.5, 1.5),
			LightEmission = 0,
		})
	end

	RECIPES.embers = function(part, variant)
		emitter(part, {
			Texture = FIRE,
			Color = ColorSequence.new(Color3.fromRGB(255, 160, 60), variant.wood),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.8),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 22,
			Speed = NumberRange.new(2, 5),
			Acceleration = Vector3.new(0, 6, 0),
			Lifetime = NumberRange.new(0.5, 1.1),
			LightEmission = 1,
		})
	end

	RECIPES.pulse = function(part, variant)
		emitter(part, {
			Color = ColorSequence.new(variant.wood),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0),
				NumberSequenceKeypoint.new(0.4, 1.1),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 26,
			Speed = NumberRange.new(0.5, 2),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.void = function(part, variant)
		emitter(part, {
			Color = ColorSequence.new(Color3.fromRGB(160, 80, 255), Color3.fromRGB(30, 0, 60)),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 1.4),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 24,
			Speed = NumberRange.new(-3, -1),  -- negative = sucked inward
			Lifetime = NumberRange.new(0.6, 1.2),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.eclipse = function(part, variant)
		RECIPES.embers(part, variant)
		emitter(part, {
			Color = ColorSequence.new(Color3.fromRGB(255, 150, 40)),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0),
				NumberSequenceKeypoint.new(0.5, 2.4),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Transparency = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.4),
				NumberSequenceKeypoint.new(1, 1),
			}),
			Rate = 6,
			Speed = NumberRange.new(0, 0.5),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.galaxy = function(part, _variant)
		emitter(part, {
			Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, Color3.fromRGB(120, 160, 255)),
				ColorSequenceKeypoint.new(0.5, Color3.fromRGB(200, 120, 255)),
				ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255)),
			}),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 0.7),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 40,
			Speed = NumberRange.new(1, 4),
			Rotation = NumberRange.new(0, 360),
			RotSpeed = NumberRange.new(-180, 180),
			Lifetime = NumberRange.new(0.7, 1.4),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	RECIPES.infinity = function(part, variant)
		RECIPES.galaxy(part, variant)
		emitter(part, {
			Texture = FIRE,
			Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Color3.fromRGB(255, 210, 90)),
			Size = NumberSequence.new({
				NumberSequenceKeypoint.new(0, 2.2),
				NumberSequenceKeypoint.new(1, 0),
			}),
			Rate = 30,
			Speed = NumberRange.new(3, 8),
			SpreadAngle = Vector2.new(180, 180),
			Lifetime = NumberRange.new(0.4, 0.9),
			LightEmission = 1,
			LightInfluence = 0,
		})
	end

	--- Applies a variant's signature effect + light to a part.
	--- `opts.light = false` skips the PointLight — important for conveyor drops,
	--- since Roblox only renders a limited number of lights and hundreds of
	--- glowing drops would starve the lights that actually matter.
	--- `opts.rateScale` thins out the particles for the same reason.
	function Fx.applyVariant(part: BasePart, variant, opts)
		opts = opts or {}
		local recipe = RECIPES[variant.fx or "none"] or RECIPES.none
		recipe(part, variant)

		if opts.rateScale then
			for _, child in ipairs(part:GetChildren()) do
				if child:IsA("ParticleEmitter") then
					child.Rate = math.max(1, child.Rate * opts.rateScale)
				end
			end
		end

		if variant.light and opts.light ~= false then
			local light = Instance.new("PointLight")
			light.Color = variant.light.color
			light.Range = variant.light.range
			light.Brightness = variant.light.brightness
			light.Shadows = false
			light.Parent = part
		end
	end

	--- The light a wall torch casts. A PointLight on the flame part, warm and
	--- shadowless — at up to a few dozen torches per plot across ten plots,
	--- shadows are off by necessity, and a shadowless Roblox light ignores
	--- occluders, which an open-air ring has none of at torch height anyway.
	---
	--- Every number comes from Config.Structure.Torch, because tools/verify_config
	--- reads Config and nothing else: a brightness typed here is a brightness no
	--- check can ever see.
	function Fx.torchLight(part: BasePart)
		local spec = Config.Structure.Torch
		local light = Instance.new("PointLight")
		light.Range = spec.range
		light.Brightness = spec.brightness
		light.Color = Color3.fromRGB(255, 176, 92)
		light.Shadows = false
		light.Parent = part
		return light
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- One-shot effects
	-- ─────────────────────────────────────────────────────────────────────────────

	--- A quick expanding ring. Used for purchases, upgrades and heavy hits.
	function Fx.burst(position: Vector3, color: Color3, size: number?, parent: Instance?)
		local ring = Instance.new("Part")
		ring.Name = "TungBurst"
		ring.Shape = Enum.PartType.Ball
		ring.Anchored = true
		ring.CanCollide = false
		ring.CanQuery = false
		ring.CanTouch = false
		ring.CastShadow = false
		ring.Material = Enum.Material.Neon
		ring.Color = color
		ring.Transparency = 0.25
		ring.Size = Vector3.one * 0.5
		ring.CFrame = CFrame.new(position)
		ring.Parent = parent or workspace

		local goalSize = Vector3.one * (size or 10)
		TweenService:Create(ring, TweenInfo.new(0.45, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), {
			Size = goalSize,
			Transparency = 1,
		}):Play()
		Debris:AddItem(ring, 0.6)
	end

	--- Floating "+1.2K" text.
	function Fx.floatingText(position: Vector3, text: string, color: Color3, parent: Instance?)
		local anchor = Instance.new("Part")
		anchor.Name = "TungFloatText"
		anchor.Anchored = true
		anchor.CanCollide = false
		anchor.CanQuery = false
		anchor.CanTouch = false
		anchor.Transparency = 1
		anchor.Size = Vector3.one * 0.2
		anchor.CFrame = CFrame.new(position)
		anchor.Parent = parent or workspace

		-- ONE OF THE TWO THINGS IN THIS GAME THAT DRAWS THROUGH WALLS. A damage
		-- number you can't see is a hit you didn't feel land, and the thing most
		-- likely to be standing between you and it is the enemy you just hit. (The
		-- other is enemy nameplates, and those are Roblox's own — it draws them on
		-- top whatever we ask for.)
		local billboard = Style.billboard(anchor, {
			name = "FloatText", width = 6, height = 2,
			distance = "prop", alwaysOnTop = true,
		})

		local label = Style.text(billboard, { text = text, color = color })

		TweenService:Create(anchor, TweenInfo.new(1.1, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
			CFrame = CFrame.new(position + Vector3.new(0, 6, 0)),
		}):Play()
		TweenService:Create(label, TweenInfo.new(1.1), { TextTransparency = 1, TextStrokeTransparency = 1 }):Play()
		Debris:AddItem(anchor, 1.3)
	end

	--- Procedural "tung" percussion. Generated from engine default sound ids that
	--- ship with Studio, pitched by index so each variant sounds different.
	---
	--- With Config.Prototypes.Sound on, both of these hand off to Sound.lua, which
	--- plays them out of a fixed pool instead of allocating one Sound per drop.
	--- With it off they keep the shipped behaviour exactly, down to the volumes
	--- and roll-off distances — the prototype has to be switchable, not merged.
	local TUNG_SOUND = "rbxasset://sounds/electronicpingshort.wav"
	local IMPACT_SOUND = "rbxasset://sounds/impact_water.mp3"

	function Fx.tung(part: BasePart, pitch: number?, volume: number?)
		if Config.Prototypes.Sound then
			Sound.playAt("collect", part, { pitch = pitch, volume = volume or 0.35 })
			return
		end
		local sound = Instance.new("Sound")
		sound.SoundId = TUNG_SOUND
		sound.PlaybackSpeed = pitch or 1
		sound.Volume = volume or 0.35
		sound.RollOffMaxDistance = 90
		sound.Parent = part
		sound:Play()
		Debris:AddItem(sound, 3)
	end

	function Fx.impact(part: BasePart, pitch: number?)
		if Config.Prototypes.Sound then
			-- combo is passed by callers that track one (bat swings); without it
			-- this is just the pitch they asked for
			Sound.playAt("impact", part, { pitch = pitch, volume = 0.6, rollOff = 120 })
			return
		end
		local sound = Instance.new("Sound")
		sound.SoundId = IMPACT_SOUND
		sound.PlaybackSpeed = pitch or 1
		sound.Volume = 0.6
		sound.RollOffMaxDistance = 120
		sound.Parent = part
		sound:Play()
		Debris:AddItem(sound, 3)
	end

	--- Named passthroughs for the rest of the library, so callers outside Fx do
	--- not have to know the asset keys. All no-ops with the flag off.
	function Fx.sfx(name: string, position: Vector3?, opts)
		if not Config.Prototypes.Sound then
			return
		end
		if position then
			Sound.playAt(name, position, opts)
		else
			Sound.play(name, opts)
		end
	end

	--- Trail between two attachments, used on bats mid-swing.
	function Fx.trail(a0: Attachment, a1: Attachment, color: Color3): Trail
		local trail = Instance.new("Trail")
		trail.Attachment0 = a0
		trail.Attachment1 = a1
		trail.Color = ColorSequence.new(color)
		trail.Transparency = NumberSequence.new({
			NumberSequenceKeypoint.new(0, 0.1),
			NumberSequenceKeypoint.new(1, 1),
		})
		trail.Lifetime = 0.22
		trail.LightEmission = 0.8
		trail.MinLength = 0.1
		trail.Enabled = false
		trail.Parent = a0.Parent
		return trail
	end

	return Fx
end


__MODULES["Net"] = function()
	--[[
		Net.lua — lazily creates and hands out the project's RemoteEvents.

		Server calls Net.event("Name") and it is created on demand.
		Client calls Net.event("Name") and it waits for it.
	]]

	local ReplicatedStorage = game:GetService("ReplicatedStorage")
	local RunService = game:GetService("RunService")

	local Net = {}

	local FOLDER_NAME = "TungNet"

	local folder: Folder
	if RunService:IsServer() then
		folder = ReplicatedStorage:FindFirstChild(FOLDER_NAME) :: Folder
		if not folder then
			folder = Instance.new("Folder")
			folder.Name = FOLDER_NAME
			folder.Parent = ReplicatedStorage
		end
	else
		folder = ReplicatedStorage:WaitForChild(FOLDER_NAME, 30) :: Folder
	end

	-- Every remote the game uses. Declared up front so the client never races.
	Net.NAMES = {
		"Notify",        -- S->C  { kind, title, body, color }
		"Stats",         -- S->C  { cash, rebirths, kills, batTier, armorTier, multiplier, owned, rebirthCost }
		"PlotAssigned",  -- S->C  plotIndex
		"Purchased",     -- S->C  { id, name, price }
		-- phase: idle | resting | warning | spawning | active | clear.
		-- `seconds` is sent ONCE per phase and counted down client-side.
		"WaveState",     -- S->C  { phase, wave, remaining, total, seconds, boss, forced,
		                 --         bossHp, bossMaxHp, bossScale }
		"SwingFx",       -- S->C  { character, combo, duration } — play a swing on that rig
		"HitFeedback",   -- S->C  { damage, crit, killed, position }
		"Knockback",     -- S->C  impulse Vector3, applied by the owning client
		"RequestRebirth",-- C->S
		"RequestReset",  -- C->S  (leave plot)
		"Sfx",           -- S->C  { name, position }
		-- The friend bonus. Deliberately NOT folded into the Stats payload above:
		-- Economy would then have to require SocialService, which is exactly the
		-- dependency Economy.setMultiplierHook exists to prevent. A separate remote
		-- keeps Economy ignorant, and lets this one carry friend NAMES for the toast.
		"SocialState",   -- S->C  { friends, cap, bonus, multiplier, names }
		"RequestInvite", -- C->S  (no payload; it exists for the server-side cooldown)

		-- Movement (#101). Sprint is server-written WalkSpeed so it replicates;
		-- the dash is client physics, and the remote is the server-side cooldown
		-- ledger that keeps its cadence honest.
		"SetSprint",     -- C->S  boolean
		"RequestDash",   -- C->S  (no payload) -> server fires back approval

		-- The party (#102). One remote both ways: C->S { action, target? } for
		-- invite/accept/decline/leave, S->C the whole party state (the SessionState
		-- arrangement — the server decides everything, the client renders it).
		"Party",         -- C->S action; S->C { members, invite }

		-- Recall (#103). The intent has no payload; the server owns the cast, the
		-- cancel rules and the cooldown.
		"RequestRecall", -- C->S (no payload)

		-- Disclosure (#96): the server owns the high-water and pushes the whole
		-- unlocked set; the client only renders it.
		"Disclosure",    -- S->C { ids = { id, ... } }

		-- The shop (#108). C->S { action = "buy", id }; S->C { open = true } when
		-- a world merchant is pressed. The catalog itself is Config, which the
		-- client already holds, and ownership rides the Stats payload.
		"Shop",          -- C->S buy; S->C open

		-- Objectives (#97). Server-pushed whole state: today's three, progress,
		-- done flags, and the hint line. The client renders and sends nothing.
		"Objectives",    -- S->C { rows, hint }

		-- The rebirth moment (#107): what just became true, derived server-side
		-- so a stale hand-written list is structurally impossible.
		"RebirthReport", -- S->C { rebirths, multiplier, rank, rankChanged, keeps, motto }

		-- The chase (#138): each robbed victim is told who is carrying their
		-- Tung, and told again when the chase ends. The compass draws it.
		"ThiefMark",     -- S->C { thiefUserId, gone? }

		-- The tower banner (#145): the run's state, pushed to its members on
		-- every floor event. secondsLeft rather than a deadline — the client's
		-- clock is not the server's.
		"TowerState",    -- S->C { floor, total, archetype, modifier, secondsLeft?, best, over? }

		-- PROTOTYPES (see Config.Prototypes). Declared here rather than created on
		-- demand so a client that connects with a flag off still resolves them and
		-- never sits in WaitForChild for 30 seconds.
		"UpgradeState",   -- S->C  { levels = {id = level}, costs = {id = price} }
		"RequestUpgrade", -- C->S  upgrade id
		"UseUtility",     -- C->S  (fire the equipped utility)
		"SessionState",   -- S->C  { daily, playtime, boost, offline }
		"RequestClaim",   -- C->S  { kind = "daily" | "playtime" | "offline", index }
		"RequestBoost",   -- C->S

		-- Roblox exposes no server-side device API, so the ONE thing the client has
		-- to tell us about itself is which kind of machine it is. Declared here
		-- rather than created on demand for the reason above: a client that resolves
		-- it lazily sits in WaitForChild, and this one fires in the first seconds of
		-- a session. Validated server-side against Config.Analytics.Fields.platform
		-- and used as a chart label only — it gates nothing.
		"ClientHello",    -- C->S  { platform = string }
	}

	if RunService:IsServer() then
		for _, name in ipairs(Net.NAMES) do
			if not folder:FindFirstChild(name) then
				local remote = Instance.new("RemoteEvent")
				remote.Name = name
				remote.Parent = folder
			end
		end
	end

	local cache: { [string]: RemoteEvent } = {}

	function Net.event(name: string): RemoteEvent
		local hit = cache[name]
		if hit then
			return hit
		end
		local remote
		if RunService:IsServer() then
			remote = folder:FindFirstChild(name)
			if not remote then
				remote = Instance.new("RemoteEvent")
				remote.Name = name
				remote.Parent = folder
			end
		else
			remote = folder:WaitForChild(name, 30)
			if not remote then
				error(("[Tung] remote %q never replicated"):format(name))
			end
		end
		cache[name] = remote
		return remote
	end

	return Net
end


__MODULES["ShopMath"] = function()
	--[[
		ShopMath.lua — shared maths and lookups for the two player-progression
		prototypes: the upgrade shop (Config.PlayerUpgrades) and the utility slot
		(Config.Utilities).

		IT WAS CALLED Utilities.lua, next to Util.lua, and the two are unrelated:
		Util is number formatting and welding, this is price curves. Two modules a
		letter apart, neither named after what it does, is a wrong guess every time
		somebody new opens the tree — and this one is reached from exactly two files
		while Util is reached from fifteen. Renamed for the reader, not for tidiness.

		Why one module for both: the server prices a purchase and the client draws
		the price, and if those two ever disagree the shop shows a number you can't
		actually buy at. Every formula the UI needs lives here so there is exactly
		one copy of it, and the server treats its own result as the authority.

		Pure data + maths only — no Instances, no remotes, so it is safe on both
		sides of the wire.
	]]

	local Req = __Req
	local Config = Req("Config")

	local ShopMath = {}

	export type UpgradeDef = {
		id: string, name: string, stat: string, levels: number,
		base: number, perLevel: number, cost: number, costGrowth: number,
		blurb: string,
	}

	export type UtilityDef = {
		id: string, name: string, verb: string,
		duration: number, cooldown: number, price: number, requires: string,
	}

	-- Config ships the two tables as arrays; index them once here rather than
	-- looping over four entries on every remote call.
	ShopMath.UpgradeById = {} :: { [string]: UpgradeDef }
	for _, def in ipairs(Config.PlayerUpgrades) do
		ShopMath.UpgradeById[def.id] = def
	end

	ShopMath.UtilityById = {} :: { [string]: UtilityDef }
	for _, def in ipairs(Config.Utilities) do
		ShopMath.UtilityById[def.id] = def
	end

	--- The value of an upgrade's stat at `level` (level 0 = unpurchased).
	function ShopMath.valueAt(def, level: number): number
		return def.base + def.perLevel * math.clamp(level, 0, def.levels)
	end

	--- What the NEXT level costs, or nil at max. Geometric, per IDEAS.md §7:
	--- x4–6 per tier for a ~7-level premium stat.
	function ShopMath.costAt(def, level: number): number?
		if level >= def.levels then
			return nil
		end
		return math.floor(def.cost * (def.costGrowth ^ level))
	end

	--- Trims trailing zeros so "23.10 studs/sec" reads as "23.1 studs/sec" without
	--- turning the payout multiplier into a bare "x1".
	function ShopMath.formatValue(value: number): string
		if value == math.floor(value) then
			return tostring(math.floor(value))
		end
		local s = ("%.2f"):format(value)
		s = s:gsub("0$", "")
		return s
	end

	--- The blurb with the current stat value substituted in. Some blurbs (the
	--- autocollect toggle) have no placeholder, hence the find().
	function ShopMath.describe(def, level: number): string
		if not def.blurb:find("%%s") then
			return def.blurb
		end
		return def.blurb:format(ShopMath.formatValue(ShopMath.valueAt(def, level)))
	end

	--- What each verb actually does, for the shop row. Config.Utilities carries a
	--- verb and a duration but no player-facing description, and the wording has
	--- to match what UpgradeService's implementation really does — so it lives
	--- next to the maths rather than in the UI, where it would be one more thing
	--- that can quietly stop being true.
	local VERB_BLURB = {
		freeze = "Roots nearby raiders for %ds. They can still swing.",
		shove = "Heavy knockback on everything nearby. No damage.",
		decoy = "Drops a decoy for %ds. PROTOTYPE: raiders ignore it.",
	}

	function ShopMath.verbBlurb(def): string
		local blurb = VERB_BLURB[def.verb] or ("%s nearby."):format(def.verb)
		if blurb:find("%%d") then
			return blurb:format(def.duration)
		end
		return blurb
	end

	--- Utilities are one-shot purchases, so their "level" is 0 or 1 and their cost
	--- is flat. Expressed through the same two functions as the upgrades so the
	--- shop UI can draw both kinds of row with one code path.
	function ShopMath.utilityCostAt(def, level: number): number?
		if level >= 1 then
			return nil
		end
		return def.price
	end

	return ShopMath
end


__MODULES["Sound"] = function()
	--[[
		Sound.lua — the whole audio layer, built on sounds that ship INSIDE the
		Roblox client (`rbxasset://sounds/*`). No upload, no moderation queue, and
		nothing here can 404 or be taken down, which is the same contract every
		other asset in this project honours.

		Three rules drive the shape of this file, and all three are failure modes
		rather than preferences:

		  * **Never `Instance.new` a Sound per event.** Around 400 live Sound
		    instances is where audio/video desync starts, and ten plots dropping a
		    Tung every 0.4s reach that inside a minute. Every sound name owns a
		    fixed pool of `Config.Sound.PoolSize` instances handed out round-robin;
		    the 9th overlapping play steals the oldest slot instead of allocating.
		  * **Server-side sound spam can take a 20-player server down.** Anything
		    the client can play for itself, it plays for itself — the server never
		    broadcasts audio it does not have to.
		  * **Everything goes through one SoundGroup.** "There is no way to turn
		    the sound off" is a recurring playtest complaint, and with a group the
		    fix is one property write.

		Gated on `Config.Prototypes.Sound`: with the flag off every entry point
		returns nil before touching a single instance, so a shipping build is
		byte-for-byte the audio it has today.
	]]

	local Req = __Req
	local Config = Req("Config")

	local RunService = game:GetService("RunService")
	local SoundService = game:GetService("SoundService")

	local Sound = {}

	local CFG = Config.Sound
	local GROUP_NAME = "TungSfx"
	local ANCHOR_FOLDER = "TungSfxAnchors"

	local IS_SERVER = RunService:IsServer()

	export type PlayOptions = {
		pitch: number?,       -- multiplies the resolved playback speed
		volume: number?,
		combo: number?,       -- pitch-stacks: 1 + combo * PitchPerCombo, clamped
		rollOff: number?,     -- override RollOffMaxDistance for one play
		looped: boolean?,
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- lazily-built plumbing
	-- ─────────────────────────────────────────────────────────────────────────────

	local group: SoundGroup? = nil
	local groupVolume = 1

	--- One group for every sound in the game. Found-or-created rather than always
	--- created: the server's group replicates, so a client that arrives late must
	--- adopt the existing one instead of stacking a second.
	local function soundGroup(): SoundGroup
		if group and group.Parent then
			return group :: SoundGroup
		end
		local existing = SoundService:FindFirstChild(GROUP_NAME)
		if existing and existing:IsA("SoundGroup") then
			group = existing :: SoundGroup
		else
			local made = Instance.new("SoundGroup")
			made.Name = GROUP_NAME
			made.Volume = groupVolume
			made.Parent = SoundService
			group = made
		end
		return group :: SoundGroup
	end

	local anchorFolder: Folder? = nil

	local function anchors(): Folder
		if anchorFolder and anchorFolder.Parent then
			return anchorFolder :: Folder
		end
		local existing = workspace:FindFirstChild(ANCHOR_FOLDER)
		if existing then
			anchorFolder = existing :: Folder
		else
			local made = Instance.new("Folder")
			made.Name = ANCHOR_FOLDER
			made.Parent = workspace
			anchorFolder = made
		end
		return anchorFolder :: Folder
	end

	--- A pooled positional sound needs somewhere permanent to live. Parenting it
	--- to the thing that made the noise looks obvious and is wrong: a drop being
	--- collected destroys its children, so the pool would quietly decay back into
	--- allocate-per-drop. Each slot owns a 0.2-stud invisible anchor we teleport
	--- to the emitter instead.
	local function newAnchor(): BasePart
		local part = Instance.new("Part")
		part.Name = "SfxAnchor"
		part.Anchored = true
		part.CanCollide = false
		part.CanQuery = false
		part.CanTouch = false
		part.CastShadow = false
		part.Locked = true
		part.Transparency = 1
		part.Size = Vector3.one * 0.2
		part.Parent = anchors()
		return part
	end

	type Slot = { sound: Sound, anchor: BasePart? }
	type Pool = { slots: { Slot }, cursor: number, lastPlay: number }

	local pools: { [string]: Pool } = {}
	local warned: { [string]: boolean } = {}

	local function buildPool(name: string, assetId: string, positional: boolean): Pool
		local pool: Pool = { slots = {}, cursor = 0, lastPlay = -math.huge }
		for i = 1, math.max(1, CFG.PoolSize) do
			local sound = Instance.new("Sound")
			sound.Name = ("%s_%d"):format(name, i)
			sound.SoundId = assetId
			sound.SoundGroup = soundGroup()
			sound.Volume = 0.5
			if positional then
				local anchor = newAnchor()
				-- RollOffMaxDistance is the whole reason a neighbour's factory
				-- does not blare across the ring: a plot is ~120 studs wide and
				-- the gap between plots is 44, so 60 studs dies out at the fence.
				sound.RollOffMode = Enum.RollOffMode.InverseTapered
				sound.RollOffMinDistance = 8
				sound.RollOffMaxDistance = CFG.RollOffMaxDistance
				sound.Parent = anchor
				table.insert(pool.slots, { sound = sound, anchor = anchor })
			else
				-- parented to a non-BasePart, a Sound is 2D and plays at full
				-- volume wherever the listener is — which is what UI wants
				sound.Parent = SoundService
				table.insert(pool.slots, { sound = sound })
			end
		end
		return pool
	end

	--- Round-robin, with the repeat-rate guard applied per sound NAME. Two drops
	--- landing in the same frame is one audible "tung", not two stacked into a
	--- clipped mush — and the guard is what stops a ten-plot server machine-gunning
	--- the same 40ms sample.
	---
	--- os.clock() here, not os.time(): this is a sub-second monotonic timer, and
	--- os.time() has 1-second resolution which would silence everything.
	local function acquire(name: string, positional: boolean): Slot?
		local assetId = CFG.Library[name]
		if not assetId then
			if not warned[name] then
				warned[name] = true
				warn(("[Tung] no sound named %q in Config.Sound.Library"):format(name))
			end
			return nil
		end

		local key = name .. (positional and "@3d" or "@2d")
		local pool = pools[key]
		if not pool then
			pool = buildPool(name, assetId, positional)
			pools[key] = pool
		end

		local now = os.clock()
		if now - pool.lastPlay < CFG.MinRepeatSeconds then
			return nil
		end
		pool.lastPlay = now

		pool.cursor = (pool.cursor % #pool.slots) + 1
		return pool.slots[pool.cursor]
	end

	--- `PlaybackSpeed = min(1 + combo * PitchPerCombo, MaxPitch)` — the combo
	--- pitch-stack. Rising pitch on a repeated hit is the single cheapest way to
	--- make one stock sample read as a streak instead of a stutter.
	function Sound.comboPitch(combo: number?): number
		return math.min(1 + (combo or 0) * CFG.PitchPerCombo, CFG.MaxPitch)
	end

	local function resolvePitch(opts: PlayOptions?): number
		local speed = (opts and opts.pitch) or 1
		if opts and opts.combo then
			speed *= Sound.comboPitch(opts.combo)
		end
		return math.clamp(speed, 0.2, CFG.MaxPitch)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- public
	-- ─────────────────────────────────────────────────────────────────────────────

	--- 2D one-shot: UI clicks, stings, anything that is not happening at a place.
	--- On the client this goes through `PlayLocalSound`, which never replicates and
	--- never asks the server for anything.
	function Sound.play(name: string, opts: PlayOptions?): Sound?
		if not Config.Prototypes.Sound then
			return nil
		end
		local slot = acquire(name, false)
		if not slot then
			return nil
		end

		local sound = slot.sound
		sound.PlaybackSpeed = resolvePitch(opts)
		sound.Volume = (opts and opts.volume) or 0.5
		sound.Looped = (opts and opts.looped) or false

		if IS_SERVER then
			sound:Play()
		else
			SoundService:PlayLocalSound(sound)
		end
		return sound
	end

	--- Positional one-shot at a part or a raw position.
	---
	--- Called from the server this replicates a *bounded* number of instances
	--- (PoolSize per name for the whole server), which is the point: the shipped
	--- code allocates one Sound per drop and lets Debris clean up after it.
	function Sound.playAt(name: string, where: any, opts: PlayOptions?): Sound?
		if not Config.Prototypes.Sound then
			return nil
		end

		local position: Vector3?
		if typeof(where) == "Vector3" then
			position = where
		elseif typeof(where) == "Instance" and where:IsA("BasePart") then
			position = where.Position
		elseif typeof(where) == "CFrame" then
			position = where.Position
		end
		if not position then
			return nil
		end

		local slot = acquire(name, true)
		if not slot or not slot.anchor then
			return nil
		end

		local anchor = slot.anchor :: BasePart
		anchor.CFrame = CFrame.new(position)

		local sound = slot.sound
		sound.PlaybackSpeed = resolvePitch(opts)
		sound.Volume = (opts and opts.volume) or 0.5
		sound.Looped = (opts and opts.looped) or false
		sound.RollOffMaxDistance = (opts and opts.rollOff) or CFG.RollOffMaxDistance
		sound:Play()
		return sound
	end

	--- The mute toggle a HUD checkbox would drive. Volume rather than
	--- SoundGroup.Parent = nil so a muted group still tracks playback position.
	function Sound.setVolume(volume: number)
		groupVolume = math.clamp(volume, 0, 1)
		if Config.Prototypes.Sound then
			soundGroup().Volume = groupVolume
		end
	end

	function Sound.setMuted(muted: boolean)
		Sound.setVolume(muted and 0 or 1)
	end

	function Sound.group(): SoundGroup?
		if not Config.Prototypes.Sound then
			return nil
		end
		return soundGroup()
	end

	--- Warms every pool up front so the first drop of the session is not the one
	--- that pays for eight instantiations. Safe to call more than once.
	function Sound.preload(positional: boolean?)
		if not Config.Prototypes.Sound then
			return
		end
		for name, assetId in pairs(CFG.Library) do
			local wants3d = positional ~= false
			local key = name .. (wants3d and "@3d" or "@2d")
			if not pools[key] then
				pools[key] = buildPool(name, assetId, wants3d)
			end
		end
	end

	return Sound
end


__MODULES["Style"] = function()
	--[[
		Style.lua — the one place that turns Config.Style into instances.

		Every label this game draws, in the world and on the screen, comes through
		here. Before it existed each site picked its own font, its own outline and
		its own view distance as it was written, which is how the plot ended up
		using three fonts, six outline settings and eleven view distances from 90
		studs to 1200 — none of them chosen against each other.

		WHY A MODULE AND NOT JUST CONSTANTS. Constants would have fixed the values
		and left the *shape* free: one site setting LightInfluence and the next
		forgetting, one billboard with StudsOffsetWorldSpace and the next without.
		The point of a builder is that the site cannot leave a field out. What a
		caller still gets to choose is what a label IS — its size, its colour, and
		how far away it stops mattering — and nothing else.

		tools/verify.py fails the build if `Enum.Font`, `TextStrokeTransparency` or
		`MaxDistance` appears anywhere in src/ outside this file. That lint is the
		only reason this stays true; the state it replaced is what happens without
		one.
	]]

	local Req = __Req
	local Config = Req("Config")

	local S = Config.Style

	local Style = {}

	--- The two faces. `title` is the display face — names, headlines, anything you
	--- read at a glance from across the plot. `body` is everything else: prices,
	--- step counters, blurbs, the small print on a panel.
	Style.Font = {
		title = (Enum.Font :: any)[S.TitleFont],
		body  = (Enum.Font :: any)[S.BodyFont],
	}

	--- Named view distances, resolved. Anything that wants a number reads
	--- `Style.distance("prop")` rather than writing 220.
	function Style.distance(tier: string): number
		local value = S.Distance[tier]
		if not value then
			-- Loud rather than silent: a typo'd tier that fell back to a default
			-- would be a label that quietly renders at the wrong range forever,
			-- which is exactly the class of bug this module exists to end.
			error(("[Tung] unknown view-distance tier %q; expected one of machine/prop/plot/world"):format(tostring(tier)), 2)
		end
		return value
	end

	--- A world-space label anchor.
	---
	---   width, height   studs (BillboardGui scale maps 1:1 to studs)
	---   distance        a Config.Style.Distance key
	---   offset          studs straight up from the adornee, world-space
	---   alwaysOnTop     draws through geometry. Two things in this game are
	---                   allowed it — damage numbers and enemy nameplates — and
	---                   the nameplates are Roblox's own. Everything else obeys
	---                   walls, which is the whole point of hiding behind one.
	function Style.billboard(parent: Instance, opts): BillboardGui
		local gui = Instance.new("BillboardGui")
		gui.Name = opts.name or "Label"
		gui.Size = UDim2.fromScale(opts.width, opts.height)
		gui.MaxDistance = Style.distance(opts.distance)
		gui.AlwaysOnTop = opts.alwaysOnTop == true
		gui.LightInfluence = S.LightInfluence
		if opts.offset then
			gui.StudsOffsetWorldSpace = Vector3.new(0, opts.offset, 0)
		end
		gui.Parent = parent
		return gui
	end

	--- A line of world text. Defaults to filling its billboard, because most of
	--- them hold exactly one line; the buy button is the only label with enough to
	--- say that it needs its own layout.
	function Style.text(parent: Instance, opts): TextLabel
		local label = Instance.new("TextLabel")
		label.Name = opts.name or "Text"
		label.BackgroundTransparency = 1
		label.Size = opts.size or UDim2.fromScale(1, 1)
		if opts.position then
			label.Position = opts.position
		end
		label.Font = (opts.weight == "body") and Style.Font.body or Style.Font.title
		label.Text = opts.text or ""
		label.TextColor3 = opts.color or Color3.new(1, 1, 1)
		label.TextStrokeTransparency = S.StrokeTransparency
		label.TextStrokeColor3 = S.StrokeColor
		label.TextScaled = opts.scaled ~= false
		label.Parent = parent
		return label
	end

	--- Retunes a live billboard's view distance. Some labels have more than one
	--- voice — a locked buy button drops out of sight sooner than a buyable one —
	--- and the tier still has to come from here rather than from a number written
	--- at the call site.
	function Style.setDistance(gui: BillboardGui, tier: string)
		gui.MaxDistance = Style.distance(tier)
	end

	--- Fades a label, outline included.
	---
	--- The outline has to fade WITH the text or a dimmed label keeps its hard dark
	--- edge and ends up reading as MORE contrasty than the bright one it was
	--- supposed to recede behind — which is the exact opposite of the point.
	function Style.fade(label: TextLabel, alpha: number)
		label.TextTransparency = alpha
		label.TextStrokeTransparency = alpha + (1 - alpha) * S.StrokeTransparency
	end

	return Style
end


__MODULES["SwingAnim"] = function()
	--[[
		SwingAnim.lua — procedural melee swings that move the CHARACTER, not just
		the bat.

		The old swing tweened Tool.Grip, which is the offset of the engine's
		RightGrip weld. That rotates the bat inside a motionless hand: the arm, the
		shoulders and the torso never moved, so a "swing" read as the bat pivoting
		in mid-air. This drives the rig itself.

		WHY NOT AN AnimationTrack? Roblox animations are uploaded assets. This game
		has zero uploads by design (see README), and an animation asset would also
		have to be authored twice, once per rig type. Writing the joints directly
		costs one PreSimulation connection and works on R6 and R15 from the same
		pose data.

		THE FOUR THINGS THAT MAKE THIS WORK
		  1. We write Motor6D.Transform, not C0. Transform is the channel the
		     Animator itself writes into every frame, so it composes with the
		     playing animation and leaves the rig's rest pose (C0/C1) untouched.
		     Stop writing and Roblox's own Animate script takes the limb straight
		     back over, with no restore step. (C0 is also becoming read-only on
		     character joints under the Avatar Joint Upgrade, so it is a dead end.)
		  2. We write on RunService.PreSimulation, and ONLY there. This is the part
		     that was wrong for the whole first version of this file, which used
		     BindToRenderStep at Enum.RenderPriority.Character + 1 and was
		     consequently a no-op: nothing moved, ever.

		     BindToRenderStep binds to PreRender, and the frame goes

		         PreRender -> render -> PreAnimation -> [Animator writes joint
		         transforms] -> PreSimulation -> [transforms applied to parts]

		     so a PreRender write is overwritten by the Animator later in the same
		     frame and is discarded before it ever reaches a part. PreSimulation is
		     the last Luau event before the batch apply. Enum.RenderPriority is a
		     bare ordering constant with no engine meaning; `Character = 300` does
		     not mark where characters are animated, and reading it that way is
		     what produced the bug. The reasoning was imported from the camera
		     shake in CombatClient, where binding at `RenderPriority.Camera + 1`
		     genuinely does work — because the default camera module really IS a
		     BindToRenderStep binding, so priority ordering applies to it. The
		     Animator is not, so no priority value could ever have won.
		  3. We MULTIPLY into Transform rather than assigning it. Assigning throws
		     away the Animator's pose for that joint, so the arm snaps out of the
		     tool-hold with no blending.
		  4. Poses are expressed in TORSO space, not joint space, and converted per
		     joint by conjugating with that joint's own C0 rotation:

		         Transform = C0.Rotation:Inverse() * Q * C0.Rotation

		     R6 and R15 bake completely different rotations into their shoulder C0s,
		     so a raw joint-space angle that raises an R15 arm forwards swings an R6
		     arm out sideways. Conjugating makes "rotate the arm 90 degrees about
		     the torso's X axis" mean the same thing on both rigs, and means this
		     file never has to know a single rig convention.

		This module runs on the CLIENT ONLY. Motor6D.Transform is not replicated, so
		every client plays every swing locally: the attacker predicts their own on
		Tool.Activated and everyone else plays it from the SwingFx broadcast.
	]]

	local Req = __Req
	local Config = Req("Config")

	local RunService = game:GetService("RunService")

	local SwingAnim = {}

	local ZERO = Vector3.new(0, 0, 0)

	--- invariant: poses are ABSOLUTE torso-space Euler angles in DEGREES —
	--- (pitch, yaw, roll),
	--- measured from the rig's bind pose — arms hanging straight down. They are not
	--- offsets from whatever the character is currently doing; see applyJoint.
	---
	--- THE FRAME. A Roblox character faces -Z, up is +Y, and +X is its own right.
	--- Both arms hang along -Y from their shoulder. So for an ARM joint:
	---
	---   pitch    0 = straight down      90 = straight forward (horizontal)
	---          180 = straight up       270 = straight back
	---   roll   +90 = out to the character's RIGHT      -90 = out to its LEFT
	---   yaw        = twist about the limb's own length; unused here
	---
	--- Note "right" and "left" are the CHARACTER's, in torso space, for BOTH arms.
	--- The rotation is applied to each arm identically, so a symmetric two-handed
	--- pose needs the off-arm's roll to reach ACROSS: positive roll swings the left
	--- arm toward the body's centre, negative swings it away. Mirroring the sign,
	--- which is the intuitive thing to write, splays the arms apart instead.
	---
	--- ORDER MATTERS. CFrame.Angles(x, y, z) composes as Rx * Ry * Rz, so roll is
	--- applied first, in the hanging frame, and pitch then swings the result up and
	--- over. Reading a pair as "point the arm here, then rotate to there" is why
	--- these are easier to reason about as a cone than as a direction vector.
	---
	--- For a TORSO joint (R15 Waist, R6 RootJoint) the same frame applies to the
	--- upper body: pitch +  leans BACK, pitch - leans forward, yaw + turns left.
	---
	--- Choreography lives here rather than in Config because these are drawings,
	--- not balance. The timings that damage depends on ARE in Config. design:D-05.
	local function P(arm: Vector3, offArm: Vector3?, torso: Vector3?)
		return { arm = arm, offArm = offArm or ZERO, torso = torso or ZERO }
	end

	--- One entry per step of the combo. `Config.Combat.SwingSteps` (which is
	--- ComboMaxStacks + 1, because stack 0 is the first swing of a chain) selects
	--- among these. Alternating the direction is what makes a chain read as a combo
	--- instead of as the same swing played four times.
	SwingAnim.SWINGS = {
		{   -- 1. overhead diagonal: cocked over the right shoulder, chopped down
		    -- across to the left hip. Wind-up pitch is past 180 so the arm goes up
		    -- and BEHIND; at 158 it was raised up and in FRONT, which reads as
		    -- presenting the bat rather than loading a swing.
			name = "diagonal",
			windUp = P(Vector3.new(200, 0, 35), Vector3.new(30, 0, -20), Vector3.new(-6, -30, 0)),
			strike = P(Vector3.new(60, 0, -45), Vector3.new(20, 0, 25), Vector3.new(-10, 28, 0)),
		},
		{   -- 2. backhand: low across the body on the left, swept up to the right
			name = "backhand",
			windUp = P(Vector3.new(55, 0, -70), Vector3.new(25, 0, 20), Vector3.new(-4, 32, 0)),
			strike = P(Vector3.new(120, 0, 60), Vector3.new(30, 0, -18), Vector3.new(-8, -30, 0)),
		},
		{   -- 3. flat horizontal sweep, right to left. Pitch stays near 90 through
		    -- both poses so the arm stays level and only the roll travels — that
		    -- level arc is what distinguishes it from the two diagonals.
			name = "sweep",
			windUp = P(Vector3.new(95, 0, 75), Vector3.new(28, 0, -22), Vector3.new(0, -38, 0)),
			strike = P(Vector3.new(95, 0, -68), Vector3.new(35, 0, 28), Vector3.new(0, 36, 0)),
		},
		{   -- 4. two-handed overhead slam; the combo finisher. Both rolls are
		    -- POSITIVE so the off-arm reaches across to meet the bat instead of
		    -- splaying away from it, and the torso leans back to load and forward
		    -- to land — which is the way round it was NOT written the first time.
			name = "slam",
			windUp = P(Vector3.new(196, 0, 6), Vector3.new(190, 0, 20), Vector3.new(16, 0, 0)),
			strike = P(Vector3.new(58, 0, -4), Vector3.new(62, 0, 12), Vector3.new(-24, 0, 0)),
		},
	}

	-- The server times its hitbox off the same two numbers, so they live in Config
	-- rather than here. If they drift apart, damage stops landing when the bat
	-- looks like it connects.
	assert(#SwingAnim.SWINGS == Config.Combat.SwingSteps,
		"SwingAnim.SWINGS and Config.Combat.SwingSteps disagree; the combo would repeat a swing")

	local active: { [Model]: any } = {}
	local bound = false

	local function angles(v: Vector3): CFrame
		return CFrame.Angles(math.rad(v.X), math.rad(v.Y), math.rad(v.Z))
	end

	--- A rig joint by name, accepting either class.
	---
	--- R15 characters are migrating from Motor6D to AnimationConstraint under the
	--- Avatar Joint Upgrade, and an upgraded character has no Motor6Ds at all.
	--- Both classes carry C0 and Transform with the same meaning, so everything
	--- here works on either — but only if we never filter on Motor6D. The name
	--- check alone is not enough: a rig part can hold other children.
	local function jointNamed(parent: Instance?, name: string): Instance?
		local joint = parent and parent:FindFirstChild(name)
		if joint and (joint:IsA("Motor6D") or joint:IsA("AnimationConstraint")) then
			return joint
		end
		return nil
	end

	--- The rig's joints, found once per swing. Named by ROLE, not by rig: `arm` is
	--- whichever joint swings the weapon, `torso` is whichever one twists the upper
	--- body relative to the root.
	local function jointsFor(character: Model)
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return nil
		end

		if humanoid.RigType == Enum.HumanoidRigType.R6 then
			local torso = character:FindFirstChild("Torso")
			local rootPart = character:FindFirstChild("HumanoidRootPart")
			if not torso or not rootPart then
				return nil
			end
			return {
				arm = jointNamed(torso, "Right Shoulder"),
				offArm = jointNamed(torso, "Left Shoulder"),
				-- R6 has no waist. RootJoint is the closest thing, but it is NOT
				-- equivalent to R15's Waist: every R6 limb joint hangs off the
				-- Torso, so a rotation here carries the arms, legs and head with
				-- it and the character bodily leans rather than twisting at the
				-- middle. Yaw only, and damped — that reads as a shoulder turn,
				-- where the raw pose would swing the feet.
				torso = jointNamed(rootPart, "RootJoint"),
				torsoGain = Vector3.new(0, 0.45, 0),
			}
		end

		local rightUpperArm = character:FindFirstChild("RightUpperArm")
		local leftUpperArm = character:FindFirstChild("LeftUpperArm")
		local upperTorso = character:FindFirstChild("UpperTorso")
		return {
			arm = jointNamed(rightUpperArm, "RightShoulder"),
			offArm = jointNamed(leftUpperArm, "LeftShoulder"),
			-- R15's Waist joins LowerTorso to UpperTorso, so the legs stay put
			torso = jointNamed(upperTorso, "Waist"),
			torsoGain = Vector3.new(1, 1, 1),
		}
	end

	--- Blend a joint from whatever the Animator put there this frame toward an
	--- absolute torso-space pose. See the header: conjugating by the joint's own
	--- C0 rotation is what makes one set of angles work on both rigs.
	---
	--- `state` carries, per joint, the Transform we wrote last frame and the pose
	--- we blended from. That pair is what stops the pose drifting. Normally the
	--- Animator resets Transform before every PreSimulation, so `current` is a
	--- fresh pose and there is nothing to undo — but it does NOT reset when the
	--- Animator is throttled (it reuses the previous frame's pose for distant
	--- characters, see Animator.EvaluationThrottled) or when no track is playing at
	--- all. In those frames Transform is still exactly what we wrote, so without
	--- this check a partial-weight blend would creep toward the target a little
	--- more every frame and the pose would slowly overshoot into a pose we never
	--- authored.
	local function applyJoint(state, joint: Instance?, rotation: Vector3, weight: number)
		if not joint or not joint.Parent then
			return
		end

		local current = (joint :: any).Transform
		if state.written[joint] == current then
			current = state.baseline[joint]
		end
		state.baseline[joint] = current

		-- BLEND toward the pose, do not stack onto it. Multiplying our rotation
		-- into the Animator's looks right until you remember the tool-hold has
		-- already raised the right arm about 90 degrees forward: a 200-degree
		-- wind-up then becomes 290 and the bat starts somewhere behind the
		-- character's back. Poses are absolute, so the Animator's contribution is
		-- what we blend FROM, not something we add to.
		--
		-- Lerping also makes the weight envelope do the whole job of easing in and
		-- out: at weight 0 this is exactly the Animator's pose, so a swing can
		-- start and end without a pop and without ever needing to restore anything.
		local basis = (joint :: any).C0.Rotation
		local target = basis:Inverse() * angles(rotation) * basis
		local result = current:Lerp(target, weight)
		;(joint :: any).Transform = result
		state.written[joint] = result
	end

	local function lerpPose(a, b, alpha: number)
		return {
			arm = a.arm:Lerp(b.arm, alpha),
			offArm = a.offArm:Lerp(b.offArm, alpha),
			torso = a.torso:Lerp(b.torso, alpha),
		}
	end

	local REST = P(ZERO, ZERO, ZERO)

	--- Where the rig should be, `t` seconds into a swing of length `duration`.
	--- Returns the pose plus a blend weight that fades the whole thing in over the
	--- first few frames and out over the tail, so nothing pops when Roblox's own
	--- animation takes the limbs back.
	local function evaluate(swing, t: number, duration: number)
		local f = math.clamp(t / duration, 0, 1)
		local windUpEnd = Config.Combat.SwingWindUp
		local strikeEnd = Config.Combat.SwingStrikeAt

		local pose
		if f < windUpEnd then
			-- decelerating into the top of the wind-up
			local a = f / windUpEnd
			pose = lerpPose(REST, swing.windUp, 1 - (1 - a) * (1 - a))
		elseif f < strikeEnd then
			-- accelerating through the strike: this is the fast part
			local a = (f - windUpEnd) / (strikeEnd - windUpEnd)
			pose = lerpPose(swing.windUp, swing.strike, a * a)
		else
			-- HOLD the strike and let the weight envelope carry the arm back into
			-- whatever the Animator is doing. This used to lerp the pose toward
			-- REST, which is the bind pose — arms hanging at the sides — so at full
			-- weight the arm was driven down to the hip and then snapped back up to
			-- the tool-hold as the weight finally released. That was the odd ending.
			pose = swing.strike
		end

		-- The weight envelope does all the easing in and out of the Animator's
		-- pose, so it has to reach 1 before the strike and be back at 0 by the end.
		local weight
		local riseEnd = windUpEnd * 0.6
		if f < riseEnd then
			local a = f / riseEnd
			weight = a * a
		elseif f < strikeEnd then
			weight = 1
		else
			local a = (f - strikeEnd) / (1 - strikeEnd)
			weight = (1 - a) * (1 - a)
		end
		return pose, weight
	end

	--- Start (or restart) a swing on `character`.
	function SwingAnim.play(character: Model?, comboIndex: number, duration: number)
		if not character or not character.Parent then
			return
		end
		local swing = SwingAnim.SWINGS[((comboIndex - 1) % #SwingAnim.SWINGS) + 1]
		if not swing then
			return
		end
		active[character] = {
			swing = swing,
			joints = jointsFor(character),
			elapsed = 0,
			duration = math.max(0.15, duration),
			freeze = 0,
			-- per-joint memory of what we wrote and what we layered onto; see
			-- applyJoint for why both are needed
			written = {},
			baseline = {},
		}
	end

	--- Freeze the pose for a moment. Called on a landed hit: stopping the arc dead
	--- for two or three frames is most of what makes a hit feel like it connected
	--- with something solid rather than passing through it.
	function SwingAnim.hitStop(character: Model?, seconds: number?)
		local entry = character and active[character]
		if entry then
			entry.freeze = math.max(entry.freeze, seconds or 0.07)
		end
	end

	function SwingAnim.stop(character: Model?)
		if character then
			active[character] = nil
		end
	end

	local function step(dt: number)
		for character, entry in pairs(active) do
			if not character.Parent then
				active[character] = nil
			else
				if entry.freeze > 0 then
					entry.freeze -= dt
				else
					entry.elapsed += dt
				end

				if entry.elapsed >= entry.duration then
					active[character] = nil
				else
					local joints = entry.joints
					if not joints or not joints.arm or not joints.arm.Parent then
						-- the character can respawn mid-swing
						joints = jointsFor(character)
						entry.joints = joints
					end
					if joints then
						local pose, weight = evaluate(entry.swing, entry.elapsed, entry.duration)
						applyJoint(entry, joints.arm, pose.arm, weight)
						applyJoint(entry, joints.offArm, pose.offArm, weight)
						applyJoint(entry, joints.torso, pose.torso * (joints.torsoGain or ZERO), weight * 0.8)
					end
				end
			end
		end
	end

	function SwingAnim.start()
		if bound then
			return
		end
		bound = true
		-- PreSimulation, and nothing else. See the header: this is the last Luau
		-- event before Motor6D transforms are applied to part CFrames, and the
		-- first one after the Animator has written its own. A render-step binding
		-- here does nothing at all — that was the original bug.
		--
		-- Do NOT "modernise" this to its deprecated alias Stepped. PreSimulation
		-- passes (deltaTime); Stepped passes (timeSinceStart, deltaTime). With
		-- Stepped, `step` would take the elapsed run time as its dt and every swing
		-- would blow past its duration on the first frame — invisible again, for a
		-- completely different reason.
		RunService.PreSimulation:Connect(step)
	end

	return SwingAnim
end


__MODULES["TungModels"] = function()
	--[[
		TungModels.lua — procedural Tung Tung Tung Sahur models.

		Everything here is built from primitives at runtime. That means:
		  * zero dependency on toolbox / free models that can vanish or be moderated
		  * every variant is a parameter change, not a new upload
		  * the whole game is one Rojo sync away from running

		The silhouette: a wooden baseball bat standing on two skinny legs, with
		stick arms, an angry face, and (usually) a smaller bat in one hand.

		Facing convention: the face points along -Z, which matches Roblox's
		CFrame.LookVector and Enum.NormalId.Front.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Util = Req("Util")
	local Fx = Req("Fx")

	local TungModels = {}

	local HALF_PI = math.pi / 2

	local function variantOf(name: string)
		return Config.Variants[name] or Config.Variants.classic
	end

	local function part(parent: Instance, name: string, size: Vector3, cf: CFrame, color: Color3, material: Enum.Material): Part
		local p = Instance.new("Part")
		p.Name = name
		p.Size = size
		p.CFrame = cf
		p.Color = color
		p.Material = material
		p.Anchored = true
		p.CanCollide = false
		p.CanQuery = false
		p.CanTouch = false
		p.CastShadow = false
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Parent = parent
		return p
	end

	--- Vertical cylinder helper (Roblox cylinders run along X, so we spin them).
	local function cylinder(parent, name, height, diameter, cf, color, material): Part
		local p = part(parent, name, Vector3.new(height, diameter, diameter), cf * CFrame.Angles(0, 0, HALF_PI), color, material)
		p.Shape = Enum.PartType.Cylinder
		return p
	end

	local function ball(parent, name, diameter, cf, color, material): Part
		local p = part(parent, name, Vector3.one * diameter, cf, color, material)
		p.Shape = Enum.PartType.Ball
		return p
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- The face — drawn with a SurfaceGui so it costs no extra physics parts.
	-- ─────────────────────────────────────────────────────────────────────────────

	local function circle(parent: Instance, size: UDim2, pos: UDim2, color: Color3, z: number): Frame
		local f = Instance.new("Frame")
		f.Size = size
		f.Position = pos
		f.AnchorPoint = Vector2.new(0.5, 0.5)
		f.BackgroundColor3 = color
		f.BorderSizePixel = 0
		f.ZIndex = z
		f.Parent = parent
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(1, 0)
		corner.Parent = f
		return f
	end

	--- Angry sahur face: wide eyes, hard brows, gritted mouth.
	function TungModels.paintFace(facePlate: BasePart, variant, mood: string?, maxDistance: number?)
		mood = mood or "angry"

		local gui = Instance.new("SurfaceGui")
		gui.Name = "Face"
		gui.Face = Enum.NormalId.Front
		gui.CanvasSize = Vector2.new(200, 200)
		gui.SizingMode = Enum.SurfaceGuiSizingMode.FixedSize
		gui.LightInfluence = Config.Style.LightInfluence
		gui.AlwaysOnTop = false
		-- A face is the most expensive label on screen — sixteen frames apiece, one
		-- per Tung on the belt — and the default used to be 0, which in
		-- SurfaceGui.MaxDistance means "never stop drawing". The arena statue and
		-- every raider inherited that. Callers that know better still pass their
		-- own (drops use `machine`); everything else gets the range at which a face
		-- has stopped being a face.
		gui.MaxDistance = maxDistance or Style.distance("plot")
		gui.Parent = facePlate

		local root = Instance.new("Frame")
		root.Size = UDim2.fromScale(1, 1)
		root.BackgroundTransparency = 1
		root.Parent = gui

		local dark = Color3.fromRGB(12, 10, 14)

		-- eye whites
		circle(root, UDim2.fromScale(0.30, 0.30), UDim2.fromScale(0.31, 0.40), variant.eye, 2)
		circle(root, UDim2.fromScale(0.30, 0.30), UDim2.fromScale(0.69, 0.40), variant.eye, 2)
		-- pupils
		circle(root, UDim2.fromScale(0.13, 0.15), UDim2.fromScale(0.33, 0.42), dark, 3)
		circle(root, UDim2.fromScale(0.13, 0.15), UDim2.fromScale(0.67, 0.42), dark, 3)
		-- glint
		circle(root, UDim2.fromScale(0.05, 0.05), UDim2.fromScale(0.30, 0.38), Color3.new(1, 1, 1), 4)
		circle(root, UDim2.fromScale(0.05, 0.05), UDim2.fromScale(0.64, 0.38), Color3.new(1, 1, 1), 4)

		if mood == "angry" then
			for i, x in ipairs({ 0.31, 0.69 }) do
				local brow = Instance.new("Frame")
				brow.Size = UDim2.fromScale(0.30, 0.075)
				brow.Position = UDim2.fromScale(x, 0.245)
				brow.AnchorPoint = Vector2.new(0.5, 0.5)
				brow.BackgroundColor3 = variant.accent
				brow.BorderSizePixel = 0
				brow.Rotation = (i == 1) and 16 or -16
				brow.ZIndex = 5
				brow.Parent = root
				Util.roundedFrame(brow, 6)
			end
		end

		-- mouth
		local mouth = Instance.new("Frame")
		mouth.Size = UDim2.fromScale(0.42, 0.16)
		mouth.Position = UDim2.fromScale(0.5, 0.70)
		mouth.AnchorPoint = Vector2.new(0.5, 0.5)
		mouth.BackgroundColor3 = dark
		mouth.BorderSizePixel = 0
		mouth.ZIndex = 2
		mouth.Parent = root
		Util.roundedFrame(mouth, 10)

		-- teeth
		for i = 0, 3 do
			local tooth = Instance.new("Frame")
			tooth.Size = UDim2.fromScale(0.075, 0.075)
			tooth.Position = UDim2.fromScale(0.325 + i * 0.117, 0.665)
			tooth.AnchorPoint = Vector2.new(0.5, 0.5)
			tooth.BackgroundColor3 = Color3.fromRGB(245, 245, 240)
			tooth.BorderSizePixel = 0
			tooth.ZIndex = 3
			tooth.Parent = root
		end

		return gui
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Bat body (no face) — reused by the character, the weapon, and props.
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Builds a bat aligned along +Y, centred at `origin`. Returns the barrel part.
	---
	--- The shape is deliberately five explicit parts rather than a sampled profile.
	--- A continuously tapered version was built and reverted: it satisfied every
	--- assertion written for it and still did not look right, which is the whole
	--- reason the shape lives in code you can see rather than in data you can only
	--- check.
	function TungModels.buildBatBody(parent: Instance, variantName: string, s: number, origin: CFrame): (Part, Part)
		local v = variantOf(variantName)
		s = s * (v.scale or 1)

		cylinder(parent, "Knob", 0.22 * s, 0.62 * s, origin * CFrame.new(0, -1.55 * s, 0), v.accent, v.material)
		local handle = cylinder(parent, "Handle", 1.50 * s, 0.44 * s, origin * CFrame.new(0, -0.75 * s, 0), v.accent, v.material)
		cylinder(parent, "Taper", 0.55 * s, 0.80 * s, origin * CFrame.new(0, 0.20 * s, 0), v.wood, v.material)
		local barrel = cylinder(parent, "Barrel", 2.05 * s, 1.34 * s, origin * CFrame.new(0, 1.45 * s, 0), v.wood, v.material)
		ball(parent, "Cap", 1.34 * s, origin * CFrame.new(0, 2.45 * s, 0), v.wood, v.material)

		-- wood grain rings
		for i = 1, 3 do
			local ring = cylinder(parent, "Grain" .. i, 0.06 * s, 1.37 * s,
				origin * CFrame.new(0, (0.85 + i * 0.42) * s, 0), v.accent, v.material)
			ring.Transparency = 0.35
		end

		return barrel, handle
	end

	--- A bat's extents at scale 1, measured off the parts buildBatBody actually
	--- emits: the knob's underside at -1.55 - 0.22/2, the cap's crown at
	--- 2.45 + 1.34/2. Anything that has to span or sit against a bat derives from
	--- these rather than restating a number that will not be updated with them.
	TungModels.BAT_BASE = -1.66
	TungModels.BAT_TOP = 3.12
	TungModels.BAT_LENGTH = TungModels.BAT_TOP - TungModels.BAT_BASE

	--- The barrel's radius at the local +Y offset `y`, in studs at the same scale.
	--- The barrel is a constant 1.34 across the whole face-plate region, so `y` is
	--- unused today — it is in the signature because the caller's question is "how
	--- wide is the body HERE", and the day the barrel stops being constant that is
	--- the question that still needs answering.
	function TungModels.batRadiusAt(y: number, s: number): number
		return 1.34 * s / 2
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Full character
	-- ─────────────────────────────────────────────────────────────────────────────

	export type BuildOptions = {
		scale: number?,
		anchored: boolean?,
		withEffects: boolean?,
		holdBat: boolean?,
		mood: string?,
		collide: boolean?,
	}

	--- The full Tung Tung Tung Sahur guy. PrimaryPart is `Core` at the model centre.
	function TungModels.build(variantName: string, opts: BuildOptions?): Model
		local o = opts or {}
		local v = variantOf(variantName)
		local s = (o.scale or 1) * (v.scale or 1)

		local model = Instance.new("Model")
		model.Name = "Tung_" .. variantName

		-- invisible physics core, sized to the whole silhouette
		local core = Instance.new("Part")
		core.Name = "Core"
		core.Size = Vector3.new(1.6 * s, 3.4 * s, 1.6 * s)
		core.CFrame = CFrame.new(0, 0, 0)
		core.Transparency = 1
		core.Anchored = true
		core.CanCollide = o.collide ~= false
		core.CanQuery = true
		core.CanTouch = true
		core.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.35, 0.2, 1, 1)
		core.Parent = model
		model.PrimaryPart = core

		local origin = CFrame.new(0, 0, 0)

		-- legs
		for i, sign in ipairs({ -1, 1 }) do
			local hip = origin * CFrame.new(sign * 0.34 * s, -2.15 * s, 0)
			local leg = cylinder(model, "Leg" .. i, 1.25 * s, 0.26 * s, hip, v.accent, Enum.Material.SmoothPlastic)
			leg.Color = Color3.fromRGB(232, 214, 186)
			local foot = part(model, "Foot" .. i, Vector3.new(0.52 * s, 0.24 * s, 0.92 * s),
				origin * CFrame.new(sign * 0.34 * s, -2.85 * s, -0.18 * s), Color3.fromRGB(60, 48, 40), Enum.Material.SmoothPlastic)
			local c = Instance.new("SpecialMesh")
			c.MeshType = Enum.MeshType.Sphere
			c.Scale = Vector3.new(1, 0.9, 1)
			c.Parent = foot
		end

		-- body
		local barrel = TungModels.buildBatBody(model, variantName, o.scale or 1, origin)

		-- Face plate, set 0.01 studs into the barrel so its 0.08 of depth leaves the
		-- front surface standing proud. Derived from the barrel's radius rather
		-- than written as the literal -0.66 it evaluates to: the two agree today
		-- only because the barrel is 1.34, and the literal would not notice if it
		-- stopped being.
		local faceY = 1.62 * s
		local faceRadius = TungModels.batRadiusAt(faceY, s)
		local face = part(model, "FacePlate", Vector3.new(1.16 * s, 1.16 * s, 0.08 * s),
			origin * CFrame.new(0, faceY, -(faceRadius - 0.01 * s)), v.wood, v.material)
		face.Transparency = 1
		TungModels.paintFace(face, v, o.mood)

		-- Arms. The RIGHT one — the one holding the bat — is built into its own
		-- sub-model so it can hang off a Motor6D instead of being welded rigidly to
		-- the body. Without that joint there is no way to raise a raider's bat:
		-- the R6 rig underneath is entirely invisible, so animating its shoulder
		-- rotates a stick nobody can see.
		local rightArm = Instance.new("Model")
		rightArm.Name = "RightArm"
		rightArm.Parent = model

		local shoulderCF, armRoot
		for _, sign in ipairs({ -1, 1 }) do
			local parent = (sign > 0) and rightArm or model
			local shoulder = origin * CFrame.new(sign * 0.72 * s, 1.15 * s, 0) * CFrame.Angles(0, 0, math.rad(sign * -34))
			local arm = cylinder(parent, "Arm", 1.30 * s, 0.22 * s, shoulder * CFrame.new(0, -0.55 * s, 0),
				Color3.fromRGB(232, 214, 186), Enum.Material.SmoothPlastic)
			arm.Name = (sign < 0) and "ArmLeft" or "ArmRight"
			local hand = ball(parent, "Hand", 0.34 * s,
				shoulder * CFrame.new(0, -1.25 * s, 0), Color3.fromRGB(240, 226, 200), Enum.Material.SmoothPlastic)
			hand.Name = (sign < 0) and "HandLeft" or "HandRight"

			if sign > 0 then
				shoulderCF = shoulder
				armRoot = arm
				-- the held bat rides with the arm, so it goes in the same sub-model
				if o.holdBat ~= false then
					local grip = CFrame.new(hand.Position) * CFrame.Angles(math.rad(-58), 0, math.rad(-18))
					TungModels.buildBatBody(rightArm, variantName, 0.34 * (o.scale or 1), grip * CFrame.new(0, 0.55 * s, 0))
				end
			end
		end

		-- signature effects
		if o.withEffects ~= false then
			Fx.applyVariant(barrel, v)
		end

		-- Assemble. Everything is welded rigidly to the core except the right arm,
		-- whose parts weld to each other and then join the body on one Motor6D —
		-- the only articulated joint on the visible model.
		for _, p in ipairs(model:GetDescendants()) do
			if p:IsA("BasePart") and p ~= core and p ~= armRoot then
				p.Anchored = true
				Util.weld(p:IsDescendantOf(rightArm) and armRoot or core, p)
			end
		end

		if armRoot then
			armRoot.Anchored = true
			local joint = Instance.new("Motor6D")
			joint.Name = "TungArm"
			joint.Part0 = core
			joint.Part1 = armRoot
			-- Pivot at the shoulder. Both C-frames are expressed relative to the
			-- same world point, so an identity Transform reproduces the pose the
			-- parts were built in.
			joint.C0 = core.CFrame:Inverse() * shoulderCF
			joint.C1 = armRoot.CFrame:Inverse() * shoulderCF
			joint.Parent = core
		end

		if not o.anchored then
			for _, p in ipairs(model:GetDescendants()) do
				if p:IsA("BasePart") then
					p.Anchored = false
				end
			end
		end

		model:SetAttribute("Variant", variantName)
		return model
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Conveyor drop — deliberately cheap (2 physics parts) because there can be
	-- hundreds of these alive at once.
	-- ─────────────────────────────────────────────────────────────────────────────

	function TungModels.buildDrop(variantName: string, scale: number?): Model
		local v = variantOf(variantName)
		local s = (scale or 0.5) * (v.scale or 1)

		local model = Instance.new("Model")
		model.Name = "Drop"

		local body = Instance.new("Part")
		body.Name = "Body"
		body.Shape = Enum.PartType.Cylinder
		body.Size = Vector3.new(2.4 * s, 1.15 * s, 1.15 * s)
		body.Color = v.wood
		body.Material = v.material
		body.Anchored = false
		body.CanCollide = true
		body.CastShadow = false
		body.TopSurface = Enum.SurfaceType.Smooth
		body.BottomSurface = Enum.SurfaceType.Smooth
		body.CustomPhysicalProperties = PhysicalProperties.new(0.6, 0.4, 0.1, 1, 1)
		body.CFrame = CFrame.Angles(0, 0, HALF_PI)
		body.Parent = model
		model.PrimaryPart = body

		local face = Instance.new("Part")
		face.Name = "FacePlate"
		face.Size = Vector3.new(0.95 * s, 0.95 * s, 0.06)
		face.Transparency = 1
		face.CanCollide = false
		face.CanQuery = false
		face.CanTouch = false
		face.CastShadow = false
		face.Massless = true
		face.CFrame = body.CFrame * CFrame.Angles(0, 0, -HALF_PI) * CFrame.new(0, 0.55 * s, -0.58 * s)
		face.Parent = model
		TungModels.paintFace(face, v, "angry", Style.distance("machine"))
		Util.weld(body, face)

		if v.fx and v.fx ~= "none" then
			-- no PointLight and fewer particles: there can be hundreds of these
			Fx.applyVariant(body, v, { light = false, rateScale = 0.35 })
		end

		model:SetAttribute("Variant", variantName)
		return model
	end

	--- The world CFrame a drop should be locked to so it rides the belt upright
	--- and looking back at whoever is walking alongside it.
	function TungModels.dropOrientation(beltDirection: Vector3): CFrame
		local look = CFrame.lookAt(Vector3.zero, -beltDirection.Unit)
		return look * CFrame.Angles(0, 0, HALF_PI)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- NPC rig — a real R6 Humanoid so pathfinding, MoveTo and damage all work,
	-- with the Tung visual welded on top of invisible limbs.
	-- ─────────────────────────────────────────────────────────────────────────────

	local function rigPart(model: Model, name: string, size: Vector3, cf: CFrame): Part
		local p = Instance.new("Part")
		p.Name = name
		p.Size = size
		p.CFrame = cf
		p.Transparency = 1
		p.Anchored = false
		p.CanCollide = false
		p.CastShadow = false
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Parent = model
		return p
	end

	local function motor(parent: BasePart, part0: BasePart, part1: BasePart, name: string, c0: CFrame, c1: CFrame): Motor6D
		local m = Instance.new("Motor6D")
		m.Name = name
		m.Part0 = part0
		m.Part1 = part1
		m.C0 = c0
		m.C1 = c1
		m.Parent = parent
		return m
	end

	export type NPCOptions = {
		scale: number?,
		health: number?,
		walkSpeed: number?,
		displayName: string?,
		boss: boolean?,
	}

	function TungModels.buildNPC(variantName: string, opts: NPCOptions?): Model
		local o = opts or {}
		local scale = o.scale or 1

		local model = Instance.new("Model")
		model.Name = o.displayName or ("Sahur Raider (" .. variantName .. ")")

		local base = CFrame.new(0, 0, 0)

		local hrp = rigPart(model, "HumanoidRootPart", Vector3.new(2, 2, 1) * scale, base)
		hrp.CanCollide = false

		local torso = rigPart(model, "Torso", Vector3.new(2, 2, 1) * scale, base)
		local head = rigPart(model, "Head", Vector3.new(1.2, 1.2, 1.2) * scale, base * CFrame.new(0, 1.5 * scale, 0))
		local la = rigPart(model, "Left Arm", Vector3.new(1, 2, 1) * scale, base * CFrame.new(-1.5 * scale, 0, 0))
		local ra = rigPart(model, "Right Arm", Vector3.new(1, 2, 1) * scale, base * CFrame.new(1.5 * scale, 0, 0))
		local ll = rigPart(model, "Left Leg", Vector3.new(1, 2, 1) * scale, base * CFrame.new(-0.5 * scale, -2 * scale, 0))
		local rl = rigPart(model, "Right Leg", Vector3.new(1, 2, 1) * scale, base * CFrame.new(0.5 * scale, -2 * scale, 0))

		-- an R6 Humanoid stands on its Torso + Legs; without collision here the
		-- raider sinks through the floor on spawn.
		torso.CanCollide = true
		ll.CanCollide = true
		rl.CanCollide = true

		motor(hrp, hrp, torso, "RootJoint", CFrame.new(0, 0, 0) * CFrame.Angles(-HALF_PI, 0, math.pi), CFrame.new(0, 0, 0) * CFrame.Angles(-HALF_PI, 0, math.pi))
		motor(torso, torso, head, "Neck", CFrame.new(0, 1 * scale, 0) * CFrame.Angles(-HALF_PI, 0, math.pi), CFrame.new(0, -0.5 * scale, 0) * CFrame.Angles(-HALF_PI, 0, math.pi))
		motor(torso, torso, la, "Left Shoulder", CFrame.new(-1 * scale, 0.5 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0), CFrame.new(0.5 * scale, 0.5 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0))
		motor(torso, torso, ra, "Right Shoulder", CFrame.new(1 * scale, 0.5 * scale, 0) * CFrame.Angles(0, HALF_PI, 0), CFrame.new(-0.5 * scale, 0.5 * scale, 0) * CFrame.Angles(0, HALF_PI, 0))
		motor(torso, torso, ll, "Left Hip", CFrame.new(-1 * scale, -1 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0), CFrame.new(-0.5 * scale, 1 * scale, 0) * CFrame.Angles(0, -HALF_PI, 0))
		motor(torso, torso, rl, "Right Hip", CFrame.new(1 * scale, -1 * scale, 0) * CFrame.Angles(0, HALF_PI, 0), CFrame.new(0.5 * scale, 1 * scale, 0) * CFrame.Angles(0, HALF_PI, 0))

		-- the visible guy
		local visual = TungModels.build(variantName, {
			scale = scale * 0.95,
			anchored = false,
			withEffects = true,
			holdBat = true,
			collide = false,
		})
		visual.Name = "Visual"
		local core = visual.PrimaryPart :: BasePart
		core.CanCollide = false
		core.CanQuery = false
		core.CanTouch = false
		for _, p in ipairs(visual:GetDescendants()) do
			if p:IsA("BasePart") then
				p.Massless = true
				p.CanCollide = false
			end
		end
		visual:PivotTo(torso.CFrame * CFrame.new(0, 0.7 * scale, 0))
		visual.Parent = model

		-- Motor6D (not a weld) so we can waddle it from code
		local sway = motor(torso, torso, core, "TungSway",
			CFrame.new(0, 0.7 * scale, 0), CFrame.new(0, 0, 0))
		sway.Name = "TungSway"

		local humanoid = Instance.new("Humanoid")
		humanoid.RigType = Enum.HumanoidRigType.R6
		humanoid.MaxHealth = o.health or 100
		humanoid.Health = o.health or 100
		humanoid.WalkSpeed = o.walkSpeed or 13
		humanoid.HipHeight = 0
		humanoid.AutoRotate = true
		humanoid.BreakJointsOnDeath = false
		humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.Viewer
		humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOn
		humanoid.NameDisplayDistance = 120
		humanoid.HealthDisplayDistance = 120
		humanoid.Parent = model

		model.PrimaryPart = hrp
		model:SetAttribute("Variant", variantName)
		model:SetAttribute("IsSahurNPC", true)
		if o.boss then
			model:SetAttribute("IsBoss", true)
		end

		return model
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- Weapon
	-- ─────────────────────────────────────────────────────────────────────────────

	--- How the Tool's visible bat sits relative to its Handle box. Named because
	--- the trail attachments have to span exactly this.
	local DECO_SCALE = 0.72
	local DECO_ORIGIN_Y = 1.9

	--- Builds the Handle part + decoration for a bat Tool.
	function TungModels.buildBatTool(batDef): Tool
		local v = variantOf(batDef.variant)

		local tool = Instance.new("Tool")
		tool.Name = batDef.name
		tool.RequiresHandle = true
		tool.CanBeDropped = false
		tool.ToolTip = ("%d dmg  •  click to swing"):format(batDef.damage)
		-- Held like a sword rather than straight up out of the fist: the grip drops
		-- the bat into the palm and cants it forward so the barrel reads as a blade
		-- you're about to swing. Grip is the offset of the engine's RightGrip weld,
		-- so this is a pose, not an animation, and it costs nothing.
		tool.Grip = CFrame.new(0, -0.15, 0.1) * CFrame.Angles(math.rad(-18), 0, math.rad(-8))

		local handle = Instance.new("Part")
		handle.Name = "Handle"
		handle.Size = Vector3.new(0.5, 1.6, 0.5)
		handle.Color = v.accent
		handle.Material = v.material
		handle.CanCollide = false
		handle.Massless = true
		handle.TopSurface = Enum.SurfaceType.Smooth
		handle.BottomSurface = Enum.SurfaceType.Smooth
		handle.Parent = tool

		local deco = Instance.new("Model")
		deco.Name = "Deco"
		deco.Parent = tool

		-- barrel above the grip
		local origin = CFrame.new(0, DECO_ORIGIN_Y, 0)
		TungModels.buildBatBody(deco, batDef.variant, DECO_SCALE, origin)

		for _, p in ipairs(deco:GetDescendants()) do
			if p:IsA("BasePart") then
				p.Massless = true
				p.CanCollide = false
				p.Anchored = false
				Util.weld(handle, p)
			end
		end

		-- Swing trail, spanning the deco the Tool actually built.
		--
		-- These were hardcoded at 0.8 and 3.4, which was wrong twice: the span did
		-- not scale with the variant, and a bat is not centred on its origin
		-- anyway — it runs from -1.66 to +3.12, so the fixed pair clipped the last
		-- three quarters of a stud off a `classic` and covered barely half of a
		-- `void`, which carries its own 1.3x on top.
		local decoScale = DECO_SCALE * (v.scale or 1)
		local a0 = Instance.new("Attachment")
		a0.Name = "TrailTop"
		a0.Position = Vector3.new(0, DECO_ORIGIN_Y + TungModels.BAT_BASE * decoScale, 0)
		a0.Parent = handle
		local a1 = Instance.new("Attachment")
		a1.Name = "TrailBottom"
		a1.Position = Vector3.new(0, DECO_ORIGIN_Y + TungModels.BAT_TOP * decoScale, 0)
		a1.Parent = handle
		local trail = Fx.trail(a0, a1, v.light and v.light.color or v.wood)
		trail.Name = "SwingTrail"

		tool:SetAttribute("BatId", batDef.id)
		tool:SetAttribute("Damage", batDef.damage)
		tool:SetAttribute("Cooldown", batDef.cooldown)
		tool:SetAttribute("Knockback", batDef.knockback)
		tool:SetAttribute("Reach", batDef.reach)
		tool:SetAttribute("Crit", batDef.crit)

		return tool
	end

	--- Big anchored decorative statue for the lobby / plot signage.
	function TungModels.buildStatue(variantName: string, scale: number): Model
		local model = TungModels.build(variantName, {
			scale = scale,
			anchored = true,
			withEffects = true,
			holdBat = true,
			collide = true,
		})
		model.Name = "TungStatue"
		for _, p in ipairs(model:GetDescendants()) do
			if p:IsA("BasePart") then
				p.Anchored = true
			end
		end
		return model
	end

	return TungModels
end


__MODULES["Util"] = function()
	--[[
		Util.lua — the leaf. Thirteen small helpers, required by fifteen files
		across both sides of the game.

		IT REQUIRES NOTHING, and that is a contract rather than an accident. There is
		no `Req` line and no service lookup anywhere below, so any module can require
		Util without thinking about the require graph, and the spec harness can load it
		with no mock standing behind it. Adding `Req("Config")` here would hand all
		fifteen of those files a new edge, and Req refuses a circular require at
		RUNTIME — a cycle introduced here does not fail the build, it fails the boot.

		IT IS COMPILED INTO BOTH PASTE BUILDS. tools/pack.py builds the server script
		from [src/shared, src/server] and the client one from [src/shared, src/client],
		so everything in src/shared ships to both. Nothing that only one side is
		allowed to do belongs here — src/client/UiKit.lua lives on the client for
		precisely this reason, and its header explains the failure.

		WHAT IS LOAD-BEARING, out of the thirteen:

		  abbreviate    the game's money formatter — fifty-odd call sites, and
		                Economy.format is an alias for it. Its trailing-zero trim is
		                gated on the text containing a decimal point: an
		                unconditional trim turned "320" into "32", so 320K rendered
		                as 32K. That guard is the whole function's history.
		  platformFrom  every string it can return must also appear in
		                Config.Analytics.Fields.platform.values. It cannot read
		                Config to check (see above), so analytics_spec.lua checks it
		                instead, through the Analytics.platformFrom re-export — which
		                is why that alias exists and must not be deleted as
		                redundant. The ORDER of the tests inside it is the function.
		  getRig        the sanctioned way to read a character's Humanoid and root.
		                Twelve call sites, every one of which relies on the nil, nil
		                return rather than on a pcall.

		shallowCopy IS SHALLOW, and its one caller makes that matter: Tycoon:rebirth
		copies the kept-buttons set with it. A Config.ButtonById def is one table
		shared by every plot on the server, so copying a def rather than a set of ids
		would hand you nested tables that are still shared with every other plot.

		comma, count, hash, newPart, setCollision and weldModel have no caller in src/
		today. They are available; they are not proven.
	]]

	local Util = {}

	local SUFFIXES = {
		"", "K", "M", "B", "T", "Qa", "Qi", "Sx", "Sp", "Oc", "No",
		"Dc", "UDc", "DDc", "TDc", "QaDc", "QiDc", "SxDc", "SpDc", "OcDc", "NoDc", "Vg",
	}

	--- 1234567 -> "1.23M"
	function Util.abbreviate(n: number): string
		if n ~= n then return "0" end            -- NaN guard
		local sign = n < 0 and "-" or ""
		n = math.abs(n)
		if n < 1000 then
			return sign .. tostring(math.floor(n + 0.5))
		end
		local index = math.floor(math.log(n, 1000))
		index = math.clamp(index, 1, #SUFFIXES - 1)
		local scaled = n / (1000 ^ index)
		local text
		if scaled >= 100 then
			text = string.format("%.0f", scaled)
		elseif scaled >= 10 then
			text = string.format("%.1f", scaled)
		else
			text = string.format("%.2f", scaled)
		end
		-- Trim trailing zeros, but ONLY past a decimal point. Trimming
		-- unconditionally turns "320" into "32", i.e. 320K displays as 32K.
		if text:find("%.") then
			text = text:gsub("0+$", "")
			text = text:gsub("%.$", "")
		end
		return sign .. text .. SUFFIXES[index + 1]
	end

	--- 1234567 -> "1,234,567"
	function Util.comma(n: number): string
		local whole = string.format("%.0f", math.abs(n))
		local out = whole:reverse():gsub("(%d%d%d)", "%1,"):reverse()
		out = out:gsub("^,", "")
		return (n < 0 and "-" or "") .. out
	end

	function Util.weld(a: BasePart, b: BasePart, name: string?): WeldConstraint
		local weld = Instance.new("WeldConstraint")
		weld.Name = name or "TungWeld"
		weld.Part0 = a
		weld.Part1 = b
		weld.Parent = a
		return weld
	end

	--- Welds every descendant BasePart of `model` to `root` and anchors nothing.
	function Util.weldModel(model: Model, root: BasePart)
		for _, part in ipairs(model:GetDescendants()) do
			if part:IsA("BasePart") and part ~= root then
				part.Anchored = false
				Util.weld(root, part)
			end
		end
	end

	function Util.setCollision(model: Instance, group: string)
		for _, part in ipairs(model:GetDescendants()) do
			if part:IsA("BasePart") then
				part.CollisionGroup = group
			end
		end
		if model:IsA("BasePart") then
			model.CollisionGroup = group
		end
	end

	function Util.newPart(props: { [string]: any }): Part
		local part = Instance.new("Part")
		part.Anchored = true
		part.CanCollide = false
		part.CastShadow = false
		part.TopSurface = Enum.SurfaceType.Smooth
		part.BottomSurface = Enum.SurfaceType.Smooth
		for key, value in pairs(props) do
			if key ~= "Parent" then
				(part :: any)[key] = value
			end
		end
		if props.Parent then
			part.Parent = props.Parent
		end
		return part
	end

	function Util.roundedFrame(parent: Instance, radius: number): UICorner
		local corner = Instance.new("UICorner")
		corner.CornerRadius = UDim.new(0, radius)
		corner.Parent = parent
		return corner
	end

	--- invariant: device class from a bag of input flags. One of
	--- Config.Analytics.Fields.platform.values, always.
	---
	--- HERE RATHER THAN IN Analytics.lua. Roblox has no server-side device API, so
	--- the ladder has to RUN on the client — and Analytics.lua is deliberately
	--- server-only, because an analytics call from a client silently does nothing
	--- forever. Written twice it would drift invisibly: two plausible ladders
	--- disagreeing about tablets. Analytics re-exports it as
	--- `Analytics.platformFrom` so the specs pin the server's contract.
	---
	--- ORDER IS THE WHOLE FUNCTION. A VR headset and a console both report
	--- TouchEnabled in some configurations, so a `TouchEnabled` test placed first
	--- files every headset in the game under "mobile" — and the resulting chart
	--- looks completely normal. VR and console are therefore asked first, and the
	--- touch test additionally requires that there is no keyboard.
	---
	--- The tablet split is a viewport width because Roblox does not expose a device
	--- class: 900px is where a phone in landscape stops and a tablet starts. It is a
	--- judgement call and it is the only line here that is.
	function Util.platformFrom(flags): string
		flags = flags or {}
		if flags.vr then
			return "vr"
		elseif flags.tenFoot then
			return "console"
		elseif flags.touch and not flags.keyboard then
			return (tonumber(flags.viewportX) or 0) >= 900 and "tablet" or "mobile"
		elseif flags.keyboard and flags.mouse then
			return "desktop"
		end
		return "unknown"
	end

	function Util.shallowCopy(t)
		local out = {}
		for k, v in pairs(t) do
			out[k] = v
		end
		return out
	end

	function Util.count(t): number
		local n = 0
		for _ in pairs(t) do
			n += 1
		end
		return n
	end

	--- Deterministic-ish pseudo random from a string seed (used for plot flavour).
	function Util.hash(s: string): number
		local h = 5381
		for i = 1, #s do
			h = (h * 33 + s:byte(i)) % 2147483647
		end
		return h
	end

	function Util.lerpColor(a: Color3, b: Color3, t: number): Color3
		return a:Lerp(b, math.clamp(t, 0, 1))
	end

	--- Safely reads a character's humanoid + root, or nil.
	function Util.getRig(model: Instance?): (Humanoid?, BasePart?)
		if not model or not model:IsA("Model") then
			return nil, nil
		end
		local humanoid = model:FindFirstChildOfClass("Humanoid")
		local root = model:FindFirstChild("HumanoidRootPart")
		if humanoid and root and root:IsA("BasePart") then
			return humanoid, root
		end
		return nil, nil
	end

	--- Two-argument arctangent, by hand.
	---
	--- The toolchain's `math.atan` definition is single-argument, and the analysis
	--- pass is allowed to fail the build on the two-argument call — so every site
	--- that needs a bearing writes this out. CompassUI had it first, and UiKit's
	--- `bar` primitive needs the same thing to turn two grid points into a
	--- Rotation, which is one copy too many.
	function Util.atan2(y: number, x: number): number
		if x > 0 then
			return math.atan(y / x)
		elseif x < 0 then
			return math.atan(y / x) + (y >= 0 and math.pi or -math.pi)
		end
		if y == 0 and x == 0 then
			-- Undefined mathematically. Zero is the answer that keeps a caller drawing
			-- a zero-length bar at a harmless angle rather than propagating a nan into
			-- a Rotation, which Roblox accepts silently.
			return 0
		end
		return y >= 0 and math.pi / 2 or -math.pi / 2
	end

	return Util
end


__MODULES["AdminService"] = function()
	--[[
		AdminService.lua — chat commands, for testing what the verifier cannot see.

		Every handoff since v3 has ended with a list of things only Studio can
		answer, and every one of those lists has gone unanswered. HANDOFF_v5 §5 item
		8 asked someone to own `power3` and `belt1` and read the belt speed; it went
		two rounds, and when a spec finally asked the question the answer was a
		number neither round had guessed. The reason nobody checked is that reaching
		that save meant a thirty-two minute grind, and there was no other way in.

		`!give power3` and `!give belt1` is that save, in two lines. That is what
		these commands are for. The cash grants are a convenience; `!give` is the
		one that pays for itself.

		AUTHORISATION IS PER-PLAYER, NOT PER-BUILD. See Config.Admin: Studio, the
		place owner, or an explicit allowlist. It is safe to ship — a random player
		on a live server qualifies under none of the three — but the point of it
		being shippable is that you can test on a real populated server, which is
		where most of the untested things in this repo actually live.

		COMMANDS GO THROUGH THE NORMAL PATHS. `!give` calls Tycoon:install, `!wave`
		drives the wave state machine, cash goes through Economy. A command that
		takes a shortcut tests the shortcut.

		IT OWNS NO STATE AND NO CONFIG. Everything it can do, some other service can
		already do; this file is a parser, an authorisation check, and a list of verbs.
		It writes profile.owned in exactly one place (`give`, mirroring tryPurchase)
		and otherwise only calls Economy, PlotService, Tycoon and NPCService.

		Config.Admin IS NOT A Config.Prototypes FLAG AND MUST NOT BECOME ONE.
		tools/verify_config.lua asserts every prototype flag ships false, so a
		prototype flag is one you cannot turn on — the opposite of what this needs.
		This feature is finished, is meant to be on, and is gated on WHO is asking.

		IT STARTS AFTER NPCService, in Main.server.lua, because `!wave` and `!clear`
		drive that service's schedule and forceWave/forceClear are meaningless before
		it has one. `hook` also runs over Players:GetPlayers() as well as PlayerAdded,
		because in Studio the one player who matters is always already there.

		WHAT TO READ FIRST. The load-window guard in AdminService.handle is the
		non-obvious part of this file and it explains itself at length: every command
		ends in a write that needs a loaded profile, DataService.get returns nil rather
		than yielding, and Economy.add fails silently on a nil profile — so without
		the guard a grant reported success and did nothing. That window is now up to
		~32 seconds wide on a contended session lock. Nothing here is covered by
		tools/test.py; the commands are the testing instrument, not the thing tested.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Economy = Req("Economy")
	local DataService = Req("DataService")
	local PlotService = Req("PlotService")
	local NPCService = Req("NPCService")

	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")

	local AdminService = {}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- who is allowed
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Studio, the place owner, or the allowlist.
	---
	--- CreatorType is checked before CreatorId is trusted: for a group-owned place
	--- `game.CreatorId` is the GROUP's id, and comparing a UserId against it would
	--- be comparing two numbers from different namespaces. They can collide, and
	--- the failure mode is handing a stranger the money command.
	local function isAdmin(player: Player): boolean
		if not Config.Admin.Enabled then
			return false
		end
		if RunService:IsStudio() then
			return true
		end
		if game.CreatorType == Enum.CreatorType.User and player.UserId == game.CreatorId then
			return true
		end
		for _, id in ipairs(Config.Admin.UserIds) do
			if player.UserId == id then
				return true
			end
		end
		return false
	end

	local function say(player: Player, title: string, body: string, kind: string?)
		Economy.notify(player, { kind = kind or "info", title = title, body = body })
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the commands
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Grant cash.
	---
	--- applyMultiplier is FALSE. Economy.add would otherwise scale the grant by the
	--- rebirth multiplier, so `$1000` after two rebirths would silently be $5062 —
	--- and the whole value of a debug grant is that you get the number you asked
	--- for. Economy.push follows because add only marks dirty for the batched 10 Hz
	--- replication, and a debug command that takes a tenth of a second to show up
	--- reads as a command that did not work.
	local function grant(player: Player, amount: number)
		Economy.add(player, amount, false)
		Economy.push(player)
		say(player, "Admin", ("+%s Tung."):format(Util.abbreviate(amount)), "claim")
	end

	--- Everything on the plot, at once.
	---
	--- Summed from Config rather than from a literal, so it keeps up with the
	--- ladder. The side tracks are included: floor2 gates both cabinets and this is
	--- meant to leave you able to buy the whole game, not the factory only.
	local function grantEverything(player: Player)
		local total = 0
		for _, def in ipairs(Config.Buttons) do
			total += def.price
		end
		total += Config.Rebirth.BaseCost
		grant(player, total)
	end

	--- Install a button without paying for it.
	---
	--- Writes profile.owned AND calls install, in that order, exactly as
	--- tryPurchase does — the profile write is what makes it survive a rejoin, and
	--- install is what actually builds the machine. Doing only the second gives you
	--- a machine that vanishes at next login, which is a confusing thing to hand
	--- someone who is mid-debug.
	---
	--- requirementsMet is deliberately NOT checked. `!give power3` has to work
	--- without power1 and power2, because "a save that somehow holds power3 without
	--- power2" is exactly the shape of state these commands exist to produce.
	local function give(player: Player, id: string): (boolean, string)
		local def = Config.ButtonById[id]
		if not def then
			return false, ("no button called %q"):format(id)
		end
		local tycoon = PlotService.plotOf(player)
		if not tycoon then
			return false, "you do not have a plot"
		end
		if tycoon.owned[id] then
			return false, ("you already own %s"):format(def.name)
		end

		local profile = DataService.get(player)
		if profile then
			profile.owned[id] = true
		end
		tycoon:install(id, false)
		Economy.push(player)
		return true, def.name
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- parsing
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Returns true if the message was a command, whether or not it succeeded.
	---
	--- Silent on anything that is not one: this runs on every line of chat from an
	--- admin, and a handler that answers back about messages it did not understand
	--- makes the chat unusable for the person who has the commands.
	function AdminService.handle(player: Player, message: string): boolean
		local text = message:match("^%s*(.-)%s*$")

		-- invariant: NOTHING RUNS WITHOUT A LOADED PROFILE. Every command here ends
		-- in a write that DataService.get has to resolve, and `get` returns nil
		-- until the load finishes rather than yielding until it does.
		--
		-- Economy.add's first line is `if not profile or amount <= 0 then return 0`
		-- — it fails SILENTLY — so without this, `$1000` typed during the load
		-- window grants nothing and then reports "+1.0M Tung." A debug command that
		-- lies about having worked is worse than one that refuses.
		--
		-- The window is wide: session locking makes a contended load take up to
		-- ~32 seconds, which is long enough to walk in and start typing.
		-- Gated on the message LOOKING like a command first. Guarding before that
		-- test would answer back on every ordinary line an admin types during the
		-- load window, which is the behaviour the "silent on anything that is not a
		-- command" rule above exists to prevent.
		if (text:sub(1, 1) == "$" or text:sub(1, 1) == "!") and not DataService.get(player) then
			say(player, "Admin", "Your save is still loading — try again in a moment.", "warn")
			return true
		end

		-- $$  — everything
		if text == "$$" then
			grantEverything(player)
			say(player, "Admin", "Granted enough for the whole plot.", "claim")
			return true
		end

		-- $ / $<amount>  — cash. The amount accepts 1e6 and 2.5e9 as well as plain
		-- digits, because the late ladder is priced in billions and typing those
		-- out is how you end up off by a zero.
		local money = text:match("^%$(.*)$")
		if money then
			if money == "" then
				grant(player, Config.Admin.DefaultGrant)
			else
				local amount = tonumber(money)
				if not amount or amount <= 0 then
					say(player, "Admin", ("%q is not an amount"):format(money), "warn")
				else
					grant(player, amount)
				end
			end
			return true
		end

		local verb, rest = text:match("^!(%a+)%s*(.*)$")
		if not verb then
			return false
		end
		verb = verb:lower()

		if verb == "give" then
			if rest == "" then
				say(player, "Admin", "!give <buttonId>", "warn")
				return true
			end
			local ok, what = give(player, rest)
			say(player, "Admin", ok and ("Installed %s."):format(what) or what, ok and "buy" or "warn")
			return true
		end

		if verb == "wave" then
			local ok = NPCService.forceWave()
			say(player, "Admin", ok and "Raid incoming." or "A raid is already running.",
				ok and "wave" or "warn")
			return true
		end

		-- Your own plot's siege, now (#89). The plot-wave schedule runs on rests
		-- of minutes; this collapses yours so the gate press, the stream-in and
		-- the siren can be exercised without waiting one out.
		if verb == "raidme" then
			local ok = NPCService.forcePlotWave(PlotService.plotOf(player))
			say(player, "Admin", ok and "Your plot's raid is coming." or "One is already running, or you have no plot.",
				ok and "wave" or "warn")
			return true
		end

		if verb == "clear" then
			local ok = NPCService.forceClear()
			say(player, "Admin", ok and "Wave cleared." or "No raid to clear.",
				ok and "wave" or "warn")
			return true
		end

		-- Damage your own plot's defences, through the same door a raid uses.
		-- The one caller in the game today — mobs arrive with #89, raiders with
		-- #94 — so this is how the break, the stump, the prompt and the repair
		-- get exercised in Studio at all.
		if verb == "siege" then
			local tycoon = PlotService.plotOf(player)
			if not tycoon then
				say(player, "Admin", "you do not have a plot", "warn")
				return true
			end
			local key, amountText = rest:match("^%s*(%S*)%s*(%d*)%s*$")
			if key == nil or key == "" then
				key = "gate_gateway"
			end
			local dealt = tycoon:damageStructure(key, tonumber(amountText) or 200)
			say(player, "Admin",
				dealt > 0 and ("%s takes %.0f."):format(key, dealt)
					or ("%s absorbed nothing — broken already, or not a siege key."):format(key),
				dealt > 0 and "info" or "warn")
			return true
		end

		return false
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- wiring
	-- ─────────────────────────────────────────────────────────────────────────────

	local function hook(player: Player)
		player.Chatted:Connect(function(message)
			-- Authorisation is checked per MESSAGE, not at connect time. The
			-- allowlist is Config and Config is reloadable in Studio, and a check
			-- baked in at join would mean rejoining to pick up a change.
			if not isAdmin(player) then
				return
			end
			local ok, err = pcall(AdminService.handle, player, message)
			if not ok then
				warn("[Tung] admin command error: " .. tostring(err))
			end
		end)
	end

	function AdminService.start()
		Players.PlayerAdded:Connect(hook)
		-- ...and everyone already here. PlayerAdded alone misses every player
		-- present when the server script starts, which in Studio is always you.
		for _, player in ipairs(Players:GetPlayers()) do
			hook(player)
		end
	end

	return AdminService
end


__MODULES["Analytics"] = function()
	--[[
		Analytics.lua — the seven events the game sends, and the one choke point
		they all go through.

		WHY THIS FILE IS IN src/server AND NOT src/shared. The Roblox AnalyticsService
		API is server-only and published-place-only. It does not error on the client;
		it does nothing. A module in TungShared is reachable from a LocalScript, and
		the first person to call it from one gets a function that returns
		successfully and sends nothing, forever, with no symptom but a chart that is
		quietly low. Putting it here makes that call a require failure instead.

		EVERYTHING ABOUT THIS API FAILS SILENTLY. Not one of the limits below raises,
		warns or logs:

		  * three custom fields per event, keyed ONLY by
		    Enum.AnalyticsCustomFieldKeys.CustomField01/02/03 (`.Name` is the
		    dictionary key). A fourth entry, or a key of any other name, is dropped.
		  * field values must be STRINGS. A number is dropped.
		  * 8,000 unique combinations of field values across the whole EXPERIENCE.
		  * 100 custom event names across the whole experience.

		That is the entire reason the schema lives in Config.Analytics and is
		verifier-checked rather than being written inline at each call site. A call
		site can be wrong; a call site that is wrong here produces no error and no
		missing data, just data that is subtly not what it says it is.

		ONE CHOKE POINT. Every event goes through Analytics.emit, which resolves the
		three field keys from the schema, tostring()s every value, snaps anything
		outside a declared value set back into it, appends to the tail, spends a
		rate-limit token and only then calls the sink. There is deliberately no
		second path.

		NEVER LOG AN ECONOMY EVENT PER COLLECTED DROP. Late game the vault eats
		roughly ten drops a second — Tycoon.lua says so in as many words next to the
		confetti throttle — which is 600 service calls a minute from ONE player on a
		ten-player server. Economy events fire on button purchases, on rebirth and on
		claims. Nothing that happens on a Touched handler is ever an economy event.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Net = Req("Net")
	local DataService = Req("DataService")

	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")

	local Analytics = {}

	local A = Config.Analytics

	--- The three keys Roblox will read, resolved once. `.Name` is the string the
	--- dictionary is keyed by; passing the EnumItem itself is one of the ways to
	--- get an event accepted with no fields on it.
	local FIELD_KEYS = {
		Enum.AnalyticsCustomFieldKeys.CustomField01.Name,
		Enum.AnalyticsCustomFieldKeys.CustomField02.Name,
		Enum.AnalyticsCustomFieldKeys.CustomField03.Name,
	}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- pure helpers — no Roblox types, so the harness can drive them directly
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Which bucket `value` falls in, as one of the field's declared strings.
	---
	--- `bounds` is inclusive-upper and ascending: the first bound the number does
	--- not exceed wins, and anything past the last bound gets the final label. A
	--- non-number lands in the first bucket rather than erroring, because an event
	--- that throws at a call site is a gameplay bug caused by telemetry, which is
	--- the one thing telemetry is never allowed to be.
	function Analytics.bucket(value: number?, field): string
		if type(field) ~= "table" or type(field.values) ~= "table" then
			return "unknown"
		end
		local n = tonumber(value) or 0
		for index, bound in ipairs(field.bounds or {}) do
			if n <= bound then
				return field.values[index]
			end
		end
		return field.values[#field.values]
	end

	--- Device class from the client's input flags. Re-exported from Util because
	--- the ladder has to run on the client (Roblox has no server-side device API)
	--- and this module must not be reachable from one — see Util.platformFrom for
	--- the argument and for why VR and console are asked before touch.
	Analytics.platformFrom = Util.platformFrom

	--- How the player got here. Entirely server-side and therefore trustworthy,
	--- which is what makes it worth more than the platform label: no remote, nothing
	--- the client can assert about itself.
	---
	--- Order matters. A followed join into a private server is a FOLLOW — the friend
	--- is why they came, the server is only where the friend was — and the follow is
	--- the co-play signal Roblox actually scores.
	function Analytics.entryPointFrom(followUserId: number?, joinData, privateServerId: string?): string
		if (tonumber(followUserId) or 0) ~= 0 then
			return "follow_friend"
		end
		if type(joinData) == "table" then
			if (tonumber(joinData.ReferredByPlayerId) or 0) ~= 0 then
				return "referral"
			end
			if (tonumber(joinData.SourcePlaceId) or 0) ~= 0 then
				return "teleport"
			end
		end
		if type(privateServerId) == "string" and privateServerId ~= "" then
			return "private_server"
		end
		return "direct"
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- schema, resolved once at require time
	-- ─────────────────────────────────────────────────────────────────────────────

	local EVENTS: { [string]: any } = {}
	for _, event in ipairs(A.Events) do
		EVENTS[event.name] = event
	end

	--- Membership sets for every field, plus the value an undeclared string is
	--- snapped to. Snapping rather than passing it through is the point: an
	--- undeclared value does not fail, it quietly spends one of the experience's
	--- 8,000 combinations and keeps spending more of them every time it appears.
	local MEMBERS: { [string]: any } = {}
	for name, field in pairs(A.Fields) do
		local index = {}
		for _, value in ipairs(field.values) do
			index[value] = true
		end
		MEMBERS[name] = {
			index = index,
			fallback = index["unknown"] and "unknown" or field.values[1],
		}
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the sink and the rate limit
	-- ─────────────────────────────────────────────────────────────────────────────

	--- ON in a published server, OFF anywhere the API would no-op. Read at emit
	--- time, and note what it does NOT gate: emit still resolves the schema, builds
	--- the field table and fills the tail when this is false. Field construction is
	--- where every bug in this file will live, so the harness has to be able to
	--- exercise it, and only the terminal service call is skipped.
	Analytics.enabled = A.Enabled and RunService:IsServer() and not RunService:IsStudio()

	--- The last TailSize events, oldest first. The only way to answer "what did the
	--- server actually send" without waiting a day for a dashboard.
	Analytics.tail = {}

	--- Events dropped by the rate limit, since boot. Counted rather than assumed
	--- away, because the limit this is designed against is unverified — see
	--- Config.Analytics.RateBurst.
	Analytics.dropped = 0

	--- Values that were not in their declared set and got snapped. Non-zero means
	--- the schema and a call site disagree.
	Analytics.coerced = 0

	local analyticsService = nil
	do
		-- GetService itself can fail on a place where the service is unavailable.
		-- An analytics module that stops the server booting is worse than no
		-- analytics.
		local ok, service = pcall(function()
			return game:GetService("AnalyticsService")
		end)
		analyticsService = ok and service or nil
	end

	local function defaultSink(record)
		if not analyticsService then
			return
		end
		if record.kind == "economy" then
			analyticsService:LogEconomyEvent(
				record.player, record.flow, record.currency, record.amount,
				record.balance, record.transaction, record.sku, record.fields)
		else
			analyticsService:LogCustomEvent(record.player, record.name, record.value, record.fields)
		end
	end

	local sink = defaultSink

	--- Swap the terminal call. The harness captures events with this; nothing in
	--- src/ calls it.
	function Analytics.setSink(fn)
		sink = fn or defaultSink
	end

	-- TOKEN BUCKET. The rate limit it is sized against is NOT in the reference
	-- documentation — a staff forum post gives roughly 120 + 20 x CCU service calls
	-- per minute, and that figure is unverified. It is modelled here anyway, because
	-- the failure mode of exceeding an unknown limit is silent loss, and a bucket
	-- that is too generous costs nothing while a bucket that is too tight only
	-- delays a chart.
	--
	-- Capacity scales with the player count for the same reason the quoted figure
	-- does: a fuller server legitimately produces more events.
	local tokens = A.RateBurst
	local lastRefill = os.clock()

	local function capacity(): number
		return A.RateBurst + A.RatePerPlayerPerMinute * #Players:GetPlayers()
	end

	local function spendToken(): boolean
		local now = os.clock()
		local size = capacity()
		tokens = math.min(size, tokens + (now - lastRefill) * (size / 60))
		lastRefill = now
		if tokens < 1 then
			return false
		end
		tokens -= 1
		return true
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- emit
	-- ─────────────────────────────────────────────────────────────────────────────

	local function remember(record)
		table.insert(Analytics.tail, record)
		while #Analytics.tail > A.TailSize do
			table.remove(Analytics.tail, 1)
		end
	end

	local function coerce(fieldName: string, raw): string
		local members = MEMBERS[fieldName]
		if not members then
			return tostring(raw)
		end
		local text = tostring(raw)
		if members.index[text] then
			return text
		end
		Analytics.coerced += 1
		warn(("[Tung] analytics field %s got %q, which is not in its declared set — snapped to %q so it cannot spend a new combination")
			:format(fieldName, text, tostring(members.fallback)))
		return members.fallback
	end

	--- Send one custom event. `fields` is keyed by the SCHEMA's field names, not by
	--- CustomField01: the mapping to the three keys is this function's job and
	--- exists in one place.
	---
	--- Returns the record it built, whether or not it was sent, so a caller (and the
	--- harness) can see what the field resolution produced.
	function Analytics.emit(name: string, player: Player?, value: number?, fields)
		local event = EVENTS[name]
		if not event then
			warn(("[Tung] analytics event %q is not in Config.Analytics.Events — it would log under a name nothing reads"):format(tostring(name)))
			return nil
		end

		local packed = {}
		for index, fieldName in ipairs(event.fields) do
			packed[FIELD_KEYS[index]] = coerce(fieldName, (fields or {})[fieldName])
		end

		local record = {
			kind = "custom",
			name = name,
			player = player,
			-- Roblox takes `value` as a number and aggregates it. Everything
			-- continuous lives here precisely because it costs no combinations.
			value = tonumber(value) or 0,
			fields = packed,
		}
		remember(record)

		if not Analytics.enabled then
			return record
		end
		if not spendToken() then
			Analytics.dropped += 1
			return record
		end
		-- pcall, always: a throttled or unavailable service must not take a
		-- purchase, a rebirth or a logout down with it.
		local ok, err = pcall(sink, record)
		if not ok then
			warn("[Tung] analytics sink failed: " .. tostring(err))
		end
		return record
	end

	--- Send one economy event. SEPARATE from emit because it is a different API
	--- with different limits (5 currency types, 20 transaction types, 100 SKUs per
	--- experience) and because its amounts are real numbers rather than strings.
	---
	--- `sku` is a button id, so the SKU budget is #Config.Buttons plus the handful
	--- of non-button skus below — which the verifier prices, because a fifth track
	--- is what actually reaches 100.
	function Analytics.economy(player: Player?, flow: string, amount: number, balance: number,
			transaction: string, sku: string)
		local record = {
			kind = "economy",
			player = player,
			flow = flow,
			currency = A.Currency,
			amount = math.floor(tonumber(amount) or 0),
			balance = math.floor(tonumber(balance) or 0),
			transaction = transaction,
			sku = sku,
		}
		remember(record)

		if not Analytics.enabled then
			return record
		end
		if not spendToken() then
			Analytics.dropped += 1
			return record
		end
		local ok, err = pcall(sink, record)
		if not ok then
			warn("[Tung] analytics economy sink failed: " .. tostring(err))
		end
		return record
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- per-session state
	--
	-- ITS OWN TABLE, READ FROM NOTHING ELSE AT REMOVAL. DataService.start connects
	-- PlayerRemoving -> save(player, true) -> profiles[userId] = nil, and Roblox
	-- does not order signal handlers. By the time this file's PlayerRemoving runs
	-- the profile may already be gone, so `session_end` reads only from here. Same
	-- shape as SessionService's `live`, for the same reason.
	-- ─────────────────────────────────────────────────────────────────────────────

	type Live = {
		player: Player,
		joinAt: number,          -- os.time(), for wall-clock session length
		platform: string,
		entry: string,
		helloSeen: boolean,
		started: boolean,
		lastSeen: number,        -- captured BEFORE anything re-stamps it
		sessionIndex: number,
		lastMilestone: string,
		rebirths: number,
	}

	local live: { [Player]: Live } = {}

	--- The furthest button this profile owns, by install order. "none" is a real
	--- answer and the most important one on this event.
	local function milestoneOf(profile): string
		local best, bestOrder = "none", -1
		for id, owned in pairs((profile and profile.owned) or {}) do
			local def = owned and Config.ButtonById[id]
			if def and def.order > bestOrder then
				best, bestOrder = id, def.order
			end
		end
		return best
	end

	local function friendsInServer(player: Player): number
		local count = 0
		for _, other in ipairs(Players:GetPlayers()) do
			if other ~= player then
				local ok, isFriend = pcall(function()
					return player:IsFriendsWith(other.UserId)
				end)
				if ok and isFriend then
					count += 1
				end
			end
		end
		return count
	end

	--- The three join events, fired together once the platform is known.
	---
	--- TOGETHER IS THE POINT. There is no edit path on a logged event: firing
	--- session_start early with platform "unknown" and correcting it later is not
	--- something this API can express, so the join waits instead.
	local function fireSessionStart(player: Player, entry: Live)
		if entry.started then
			return
		end
		entry.started = true
		local F = A.Fields

		Analytics.emit("session_start", player, entry.sessionIndex, {
			platform = entry.platform,
			entry = entry.entry,
			sessionIndex = Analytics.bucket(entry.sessionIndex, F.sessionIndex),
		})

		-- RETURNED, and this is the event the whole ordering dance exists for. A
		-- lastSeen of 0 is a profile that has never logged out — a first session, or
		-- a save from before the field existed — and "came back after 1970" is worse
		-- than no row at all.
		if entry.lastSeen > 0 then
			local away = math.max(0, entry.joinAt - entry.lastSeen)
			Analytics.emit("returned", player, away / 3600, {
				platform = entry.platform,
				awayBucket = Analytics.bucket(away, F.awayBucket),
				sessionIndex = Analytics.bucket(entry.sessionIndex, F.sessionIndex),
			})
		end

		-- Only when there IS a friend here. friendCount has no "0" value, and adding
		-- one would buy a fifth facet for a number session_start already implies:
		-- friends_in_server over session_start IS the co-play rate.
		local friends = friendsInServer(player)
		if friends > 0 then
			local privateId = tostring(game.PrivateServerId or "")
			Analytics.emit("friends_in_server", player, friends, {
				platform = entry.platform,
				friendCount = Analytics.bucket(friends, F.friendCount),
				serverKind = privateId ~= "" and "private" or "public",
			})
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- public entry points
	-- ─────────────────────────────────────────────────────────────────────────────

	--- MUST RUN BETWEEN DataService.load AND SessionService.onPlayer.
	---
	--- SessionService.onPlayer stamps `profile.lastSeen = os.time()` as its second
	--- act, and SessionService.step re-stamps it every second after that. Whatever
	--- the previous logout wrote is gone the moment either of those runs, and the
	--- whole value of `returned` — the only measurement of whether anybody comes
	--- back — is that one number. So it is captured here, into this file's own
	--- table, before anything else can touch it. Main.server.lua's ordering is
	--- load-bearing and says so.
	function Analytics.onPlayer(player: Player)
		local profile = DataService.get(player)
		local now = os.time()

		-- Read FIRST, before the counters below touch the profile at all.
		local lastSeen = math.max(0, math.floor(tonumber(profile and profile.lastSeen) or 0))

		local sessionIndex = 1
		if profile then
			if (tonumber(profile.firstJoin) or 0) <= 0 then
				profile.firstJoin = now
			end
			profile.totalSessions = math.max(0, math.floor(tonumber(profile.totalSessions) or 0)) + 1
			sessionIndex = profile.totalSessions
		end

		local joinData
		do
			local ok, data = pcall(function()
				return player:GetJoinData()
			end)
			joinData = ok and data or nil
		end

		local entry: Live = {
			player = player,
			joinAt = now,
			platform = "unknown",
			entry = Analytics.entryPointFrom(player.FollowUserId, joinData, tostring(game.PrivateServerId or "")),
			helloSeen = false,
			started = false,
			lastSeen = lastSeen,
			sessionIndex = sessionIndex,
			lastMilestone = milestoneOf(profile),
			rebirths = math.max(0, math.floor(tonumber(profile and profile.rebirths) or 0)),
		}
		live[player] = entry

		-- The platform arrives from the client, some time after the join. Wait for
		-- it, then fire the three join events; give up at HelloTimeoutSeconds and
		-- log "unknown", which is an honest answer and a countable one.
		task.spawn(function()
			local deadline = os.clock() + A.HelloTimeoutSeconds
			while not entry.helloSeen and os.clock() < deadline do
				task.wait(0.25)
			end
			if live[player] then
				fireSessionStart(player, entry)
			end
		end)
	end

	--- A purchase landed. Called from Tycoon:tryPurchase, which is the only place a
	--- button is ever bought with money.
	function Analytics.onPurchase(player: Player, def, balance: number)
		local entry = live[player]
		if entry then
			-- Furthest by install order, not most recent: the four tracks are bought
			-- interleaved, so "the last thing they clicked" is not "how far they got".
			local standing = Config.ButtonById[entry.lastMilestone]
			if def.order > (standing and standing.order or -1) then
				entry.lastMilestone = def.id
			end
		end

		Analytics.economy(player, "Sink", def.price, balance, "Shop", def.id)

		-- FIRST BUTTON, ONCE PER ACCOUNT, NOT ONCE PER SESSION. The number is
		-- persisted, so a returning player's first purchase of the evening is not
		-- onboarding and does not pretend to be. 0 means never.
		local profile = DataService.get(player)
		if not profile or (tonumber(profile.firstBuySeconds) or 0) > 0 then
			return
		end
		local seconds = entry and math.max(1, os.time() - entry.joinAt) or 1
		profile.firstBuySeconds = seconds

		-- Only factory buttons are in the buttonId set; the side tracks are gated
		-- forty minutes in and cannot be a first purchase. coerce() would snap one
		-- into the set rather than widen it, and warn — which is the right failure,
		-- but it should never happen.
		Analytics.emit("first_button_purchased", player, seconds, {
			platform = entry and entry.platform or "unknown",
			buttonId = def.id,
			secondsBucket = Analytics.bucket(seconds, A.Fields.secondsBucket),
		})
	end

	--- A rebirth landed. Called from Tycoon:rebirth, after the profile is updated.
	function Analytics.onRebirth(player: Player, rebirths: number, cost: number, balance: number)
		local entry = live[player]
		local minutes = entry and (os.time() - entry.joinAt) / 60 or 0
		if entry then
			entry.rebirths = rebirths
			-- A rebirth wipes the factory, so the milestone it was standing on is
			-- gone with it. Anything else would report the logout of a rebirthed
			-- player at a rung they no longer own.
			entry.lastMilestone = milestoneOf(DataService.get(player))
		end

		Analytics.emit("rebirth", player, rebirths, {
			platform = entry and entry.platform or "unknown",
			minutesBucket = Analytics.bucket(minutes, A.Fields.minutesBucket),
			rebirthBand = Analytics.bucket(rebirths, A.Fields.rebirthBand),
		})
		Analytics.economy(player, "Sink", cost, balance, "Gameplay", "rebirth")
	end

	--- An offline payout was claimed. Called from SessionService.claimOffline with
	--- the pending grant it just paid.
	function Analytics.onOfflineClaim(player: Player, pending, balance: number)
		local entry = live[player]
		Analytics.emit("offline_claim", player, pending.earned, {
			platform = entry and entry.platform or "unknown",
			clipped = pending.clipped and "clipped" or "within_cap",
			awayBucket = Analytics.bucket(pending.seconds, A.Fields.awayBucket),
		})
		Analytics.economy(player, "Source", pending.earned, balance, "TimedReward", "offline_claim")
	end

	--- The logout event. Reads `live` and nothing else — see the block comment above
	--- `live` for why touching DataService here would work in testing and fail in
	--- production about half the time.
	function Analytics.onRemoving(player: Player)
		local entry = live[player]
		live[player] = nil
		if not entry then
			return
		end

		-- A SESSION SHORTER THAN THE HELLO TIMEOUT STILL STARTED. Without this,
		-- anyone who leaves inside ten seconds produces a session_end and no
		-- session_start — and session_start is the DENOMINATOR that `returned` and
		-- `friends_in_server` are read against, so the shortest sessions in the game
		-- would quietly drop out of every rate we compute. They are also the exact
		-- sessions worth looking at.
		if not entry.started then
			fireSessionStart(player, entry)
		end

		-- The logout itself still has a length and still stopped somewhere, which
		-- are the two things this event is for. It fires with platform "unknown"
		-- rather than not firing.
		Analytics.emit("session_end", player, math.max(0, os.time() - entry.joinAt), {
			platform = entry.platform,
			milestone = entry.lastMilestone,
			rebirthBand = Analytics.bucket(entry.rebirths, A.Fields.rebirthBand),
		})
	end

	--- What this session looks like to the analytics layer. Exposed because "the
	--- chart disagrees with the game" is otherwise unanswerable from a live server.
	function Analytics.stateFor(player: Player)
		return live[player]
	end

	function Analytics.start()
		local clientHello = Net.event("ClientHello")

		clientHello.OnServerEvent:Connect(function(player, payload)
			local entry = live[player]
			if not entry or entry.helloSeen then
				return              -- once per player per session; a remote that can be spammed will be
			end
			entry.helloSeen = true

			-- A CLIENT CAN LIE, so this is validated against the declared set and
			-- otherwise thrown away. It must also never gate anything: `platform` is
			-- a label on a chart and touches no gameplay path anywhere in src/.
			local claimed = type(payload) == "table" and payload.platform or nil
			entry.platform = (type(claimed) == "string" and MEMBERS.platform.index[claimed]) and claimed or "unknown"
		end)

		Players.PlayerRemoving:Connect(Analytics.onRemoving)
	end

	return Analytics
end


__MODULES["CombatService"] = function()
	--[[
		CombatService.lua — bats, swinging, damage, knockback and PvP rules.

		Design notes
		  * The server is authoritative. Tool.Activated replicates, so the client
		    never gets to say "I hit them"; it only asks for a swing.
		  * PvP is legal everywhere, plots included (#89): the raid loop needs
		    combat exactly where the raider is standing.
		  * Sahur raiders can be hit anywhere.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Fx = Req("Fx")
	local Net = Req("Net")
	local TungModels = Req("TungModels")
	local DataService = Req("DataService")
	local Economy = Req("Economy")

	local Players = game:GetService("Players")
	local Debris = game:GetService("Debris")

	local CombatService = {}

	local hitFeedback = Net.event("HitFeedback")
	local knockbackRemote = Net.event("Knockback")
	local swingFx = Net.event("SwingFx")

	local state: { [Player]: { lastSwing: number, combo: number, comboAt: number } } = {}

	--- THE DAMAGE LEDGER HOOK, in the same shape as Economy.setMultiplierHook and
	--- for the same reason: NPCService needs to know who is hurting a boss, and
	--- CombatService must not learn what a raid is to tell it. NPCService registers
	--- one function at boot; this module never finds out what it does with it.
	---
	--- CombatService.damage is the ONLY TakeDamage call in the repo, which is what
	--- makes an authoritative ledger five lines rather than an audit.
	local damageObserver: ((Model, Player, number) -> ())? = nil

	function CombatService.setDamageObserver(fn: ((Model, Player, number) -> ())?)
		damageObserver = fn
	end

	--- The structure hook (#124), the setDamageObserver shape one target over:
	--- a swing that boxed PARTS hands them to whoever registered, with the
	--- swing-scoped dedup table, so this file never learns what a wall is.
	--- Main.server wires it to Tycoon.siegeStrike — registering here directly
	--- would put a require of Tycoon into a module Tycoon requires.
	local structureObserver: (({ BasePart }, Player, number, { [any]: any }) -> ())? = nil

	function CombatService.setStructureObserver(fn: (({ BasePart }, Player, number, { [any]: any }) -> ())?)
		structureObserver = fn
	end

	local function stateFor(player: Player)
		local s = state[player]
		if not s then
			s = { lastSwing = 0, combo = 0, comboAt = 0 }
			state[player] = s
		end
		return s
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- zones
	-- ─────────────────────────────────────────────────────────────────────────────

	-- Whether two players are allies (#102's party). Registered from Main.server
	-- — the observer shape, so this module never learns what a party is.
	local allyCheck: ((Player, Player) -> boolean)? = nil

	function CombatService.setAllyCheck(fn: ((Player, Player) -> boolean)?)
		allyCheck = fn
	end

	--- Can `attacker` (a Player) hurt `victimModel`?
	---
	--- design:D-04, via #89 — PvP is legal EVERYWHERE, plots included. A raider
	--- who breaks your gate stands in your factory, and killing the carrier is
	--- #94's whole anti-grief spine; a geographic safe zone would hollow both.
	--- The guards against grief are economic and already asserted: dying costs
	--- no cash, the kill-steal is a bounded fraction of overflow, and the safe
	--- half of the cap is unreachable. The arena gate this replaces lived here.
	--- The one refusal beyond yourself is your own party (#102) — a party with
	--- friendly fire is a party nobody forms.
	function CombatService.canDamage(attacker: Player, victimModel: Model): boolean
		if victimModel:GetAttribute("IsSahurNPC") then
			return true
		end
		local victimPlayer = Players:GetPlayerFromCharacter(victimModel)
		if not victimPlayer then
			return false
		end
		if victimPlayer == attacker then
			return false
		end
		return not (allyCheck and allyCheck(attacker, victimPlayer))
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- bats
	-- ─────────────────────────────────────────────────────────────────────────────

	local function removeBats(container: Instance?)
		if not container then
			return
		end
		for _, child in ipairs(container:GetChildren()) do
			if child:IsA("Tool") and child:GetAttribute("BatId") then
				child:Destroy()
			end
		end
	end

	--- Blocks until the player's profile has loaded, or gives up. A character can
	--- spawn before the DataStore read finishes on first join, and everything that
	--- dresses that character needs the profile.
	local function waitForProfile(player: Player)
		local profile = DataService.get(player)
		local deadline = os.clock() + 12
		while not profile and player.Parent and os.clock() < deadline do
			task.wait(0.25)
			profile = DataService.get(player)
		end
		return player.Parent and profile or nil
	end

	function CombatService.equipCurrentBat(player: Player)
		local profile = waitForProfile(player)
		if not profile then
			return
		end
		local tier = math.clamp(profile.batTier or 1, 1, #Config.Bats)
		local def = Config.Bats[tier]

		-- No Backpack, no tool: the spec harness's players carry none (#108's
		-- shop grants run headless), and a bat with nowhere to go is a bat the
		-- next spawn equips anyway.
		local backpack = player:FindFirstChildOfClass("Backpack")
		if not backpack then
			return
		end

		removeBats(backpack)
		removeBats(player.Character)

		local tool = TungModels.buildBatTool(def)
		-- straight into the Backpack: Roblox's own inventory + hotbar handles
		-- equipping, dropping and slot assignment, so we don't reimplement any of it
		tool.Parent = player:FindFirstChildOfClass("Backpack")

		CombatService.bind(player, tool)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- armour
	--
	-- Lives here rather than in a service of its own because CombatService already
	-- owns the two places armour has to touch: onCharacter, which is the only
	-- writer of a player's humanoid stats, and CombatService.damage, which is the
	-- only TakeDamage call in the repo. A separate service would have to race the
	-- first and reach across the second.
	-- ─────────────────────────────────────────────────────────────────────────────

	function CombatService.armorTierOf(player: Player)
		local profile = DataService.get(player)
		local tier = math.clamp(profile and profile.armorTier or 1, 1, #Config.Armor.Tiers)
		return Config.Armor.Tiers[tier]
	end

	function CombatService.applyArmor(player: Player, character: Model?)
		character = character or player.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return
		end
		local health = CombatService.armorTierOf(player).health
		local delta = health - humanoid.MaxHealth
		humanoid.MaxHealth = health
		-- Setting MaxHealth alone leaves Health where it was, so a fully-armoured
		-- player spawns showing 100/320 and looking like they are bleeding out. The
		-- bar IS the reward for this track, so it has to read right.
		--
		-- Raised by the DELTA rather than to full, so buying armour in the middle
		-- of a raid is not also a free heal.
		humanoid.Health = math.clamp(humanoid.Health + math.max(0, delta), 1, health)
	end

	function CombatService.grantArmor(player: Player, armorId: string)
		local def = Config.ArmorById[armorId]
		local profile = DataService.get(player)
		if not def or not profile then
			return
		end
		-- monotonic, like grantBat: re-installing a tier you already have on a
		-- claim or a replay must not be a downgrade
		if def.tier <= (profile.armorTier or 1) then
			return
		end
		profile.armorTier = def.tier
		CombatService.applyArmor(player)
		Economy.push(player)
		Economy.notify(player, {
			kind = "gear",
			title = "NEW ARMOR: " .. def.name,
			body = ("%d max health"):format(def.health),
		})
	end

	function CombatService.grantBat(player: Player, batId: string)
		local def = Config.BatById[batId]
		local profile = DataService.get(player)
		if not def or not profile then
			return
		end
		if def.tier <= (profile.batTier or 1) then
			return
		end
		profile.batTier = def.tier
		CombatService.equipCurrentBat(player)
		Economy.push(player)
		Economy.notify(player, {
			kind = "gear",
			title = "NEW BAT: " .. def.name,
			body = ("%d damage  •  %.0f%% crit"):format(def.damage, def.crit * 100),
		})
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- swinging
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Tells every client to play swing `comboIndex` on this character.
	---
	--- The animation itself is client-side (see SwingAnim): Motor6D.Transform does
	--- not replicate, so the server can only broadcast the fact of the swing and
	--- let each client draw it. The attacker's own client has already started the
	--- same swing from Tool.Activated — waiting for this round trip to begin the
	--- wind-up is exactly what makes networked melee feel like mud.
	local function broadcastSwing(character: Model, comboIndex: number, duration: number)
		swingFx:FireAllClients({
			character = character,
			combo = comboIndex,
			duration = duration,
		})
	end

	--- Applies damage to any humanoid, from a player or from an NPC.
	function CombatService.damage(victimModel: Model, amount: number, sourcePosition: Vector3?, knockback: number?, attacker: Player?, crit: boolean?)
		local humanoid, root = Util.getRig(victimModel)
		if not humanoid or not root or humanoid.Health <= 0 then
			return false
		end

		-- classic "creator" tag so whoever landed the last hit gets the credit
		if attacker then
			local old = humanoid:FindFirstChild("creator")
			if old then
				old:Destroy()
			end
			local tag = Instance.new("ObjectValue")
			tag.Name = "creator"
			tag.Value = attacker
			tag.Parent = humanoid
			Debris:AddItem(tag, 8)
		end

		-- THE APPLIED DELTA, NOT `amount`. A 10k overkill hit on a 2k-HP boss would
		-- otherwise buy 80% of a pot it only did 20% of the work for. What the
		-- ledger is told is what actually came off the health bar, so overkill is
		-- worth exactly what it killed.
		--
		-- npcAttack passes attacker = nil, so raider-on-player damage never reaches
		-- the ledger. The `creator` tag above is untouched: ordinary raiders and PvP
		-- KOs are still credited to the last hit, exactly as before.
		local before = humanoid.Health
		humanoid:TakeDamage(amount)
		if attacker and damageObserver then
			damageObserver(victimModel, attacker, before - humanoid.Health)
		end

		if knockback and knockback > 0 and sourcePosition then
			local direction = (root.Position - sourcePosition)
			direction = Vector3.new(direction.X, 0, direction.Z)
			if direction.Magnitude < 0.1 then
				direction = Vector3.new(0, 0, 1)
			end
			direction = direction.Unit
			local impulse = (direction * knockback + Vector3.new(0, knockback * 0.45, 0)) * root.AssemblyMass * 0.6

			local victimPlayer = Players:GetPlayerFromCharacter(victimModel)
			if victimPlayer then
				-- The victim's own client owns their character's physics, so a
				-- server-side ApplyImpulse is overwritten on the next replication
				-- tick. Ask the owning client to apply it instead.
				knockbackRemote:FireClient(victimPlayer, impulse)
			else
				root:ApplyImpulse(impulse)
			end
		end

		if attacker then
			hitFeedback:FireClient(attacker, {
				damage = amount,
				position = root.Position,
				killed = humanoid.Health <= 0,
				crit = crit == true,
			})
		end
		return true
	end

	local function hitscan(character: Model, reach: number, width: number): { Model }
		local root = character:FindFirstChild("HumanoidRootPart") :: BasePart
		if not root then
			return {}
		end
		local size = Config.Combat.HitboxSize
		local box = root.CFrame * CFrame.new(0, 0, -(reach / 2))
		local boxSize = Vector3.new(size.X * width, size.Y, reach)

		local params = OverlapParams.new()
		params.FilterType = Enum.RaycastFilterType.Exclude
		params.FilterDescendantsInstances = { character }
		params.MaxParts = 60

		local parts = workspace:GetPartBoundsInBox(box, boxSize, params)

		local seen = {}
		local victims = {}
		local boxed = parts
		for _, part in ipairs(parts) do
			-- Walk UP until we find the model that owns a Humanoid, rather than
			-- stopping at the first Model ancestor. A raider's visible body is a
			-- sub-model of the rig, and the arm is a sub-model of that, so the first
			-- Model above a hit part is often not the character at all.
			local model = part:FindFirstAncestorOfClass("Model")
			while model and not model:FindFirstChildOfClass("Humanoid") do
				model = model:FindFirstAncestorOfClass("Model")
			end
			if model and not seen[model] then
				local humanoid = model:FindFirstChildOfClass("Humanoid")
				if humanoid and humanoid.Health > 0 then
					seen[model] = true
					table.insert(victims, model)
				end
			end
		end
		return victims, boxed
	end

	--- Resolves one strike: box the area in front of the swinger and damage
	--- whatever is in it that we're allowed to hurt.
	local function resolveStrike(player: Player, character: Model, hit: { [Model]: boolean },
		struckStructures: { [any]: any }, reach: number, width: number, damage: number,
		knockback: number, crit: boolean)

		local origin = character:GetPivot().Position

		local victims, boxed = hitscan(character, reach, width)
		-- Structures first, dedup'd per SWING by the shared table: the second
		-- strike sample must not land a second hit on the same wall.
		if structureObserver then
			structureObserver(boxed, player, damage, struckStructures)
		end

		for _, victim in ipairs(victims) do
			-- one swing damages a given victim once, however many samples see them
			if not hit[victim] and CombatService.canDamage(player, victim) then
				hit[victim] = true
				CombatService.damage(victim, damage, origin, knockback, player, crit)
				local _, victimRoot = Util.getRig(victim)
				if victimRoot then
					Fx.burst(victimRoot.Position, crit and Color3.fromRGB(255, 120, 80) or Color3.fromRGB(255, 230, 160),
						crit and 12 or 7, workspace)
					Fx.floatingText(victimRoot.Position + Vector3.new(0, 3, 0),
						(crit and "CRIT " or "") .. tostring(math.floor(damage)),
						crit and Color3.fromRGB(255, 140, 90) or Color3.fromRGB(255, 250, 220), workspace)
					Fx.impact(victimRoot, crit and 0.75 or 1)
				end
			end
		end
	end

	function CombatService.swing(player: Player, tool: Tool)
		local character = player.Character
		if not character then
			return
		end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid or humanoid.Health <= 0 then
			return
		end

		local s = stateFor(player)
		local now = os.clock()
		local cooldown = tool:GetAttribute("Cooldown") or 0.55
		if now - s.lastSwing < cooldown then
			return
		end
		s.lastSwing = now

		-- combo. Stack 0 is the first swing of a chain, so the animation index is
		-- one higher; the last step of the chain is the overhead finisher.
		if now - s.comboAt <= Config.Combat.ComboWindow then
			s.combo = (s.combo + 1) % (Config.Combat.ComboMaxStacks + 1)
		else
			s.combo = 0
		end
		s.comboAt = now

		local comboIndex = s.combo + 1
		local finisher = comboIndex == Config.Combat.SwingSteps

		broadcastSwing(character, comboIndex, cooldown)

		local handle = tool:FindFirstChild("Handle") :: BasePart
		local trail = handle and handle:FindFirstChild("SwingTrail") :: Trail
		if trail then
			-- the trail belongs to the strike, not to the wind-up: leaving it on
			-- for the whole swing draws a streak of the bat sitting still
			task.delay(cooldown * Config.Combat.SwingWindUp, function()
				if trail.Parent then
					trail.Enabled = true
				end
			end)
			task.delay(cooldown * (Config.Combat.SwingStrikeAt + 0.18), function()
				if trail.Parent then
					trail.Enabled = false
				end
			end)
		end
		if handle then
			Fx.impact(handle, 1.4 + math.random() * 0.2)
		end

		local reach = (tool:GetAttribute("Reach") or 9) * (finisher and Config.Combat.FinisherReach or 1)
		local baseDamage = tool:GetAttribute("Damage") or 18
		local knockback = (tool:GetAttribute("Knockback") or 55) * (finisher and Config.Combat.FinisherKnockback or 1)
		local critChance = tool:GetAttribute("Crit") or 0.08

		local comboMult = 1 + s.combo * Config.Combat.ComboDamagePerStack
		local crit = math.random() < critChance
		local damage = baseDamage * comboMult
			* (crit and Config.Combat.CritMultiplier or 1)
			* (finisher and Config.Combat.FinisherDamage or 1)
		if crit then
			knockback *= Config.Combat.CritKnockback
		end
		-- the slam lands flat in front of you rather than in a narrow line
		local width = finisher and 1.3 or 1

		-- The swing is resolved on its STRIKE FRAME, not on the frame the player
		-- clicked. That is the whole point of the rewrite: damage used to land a
		-- full animation before the bat visibly reached anything, which is why
		-- combat read as clicking rather than as hitting. The cost is that a target
		-- can now step out of a telegraphed swing, which is the point.
		local generation = s.lastSwing
		local hit: { [Model]: boolean } = {}
		local struckStructures: { [any]: any } = {}

		local function strike()
			-- A second swing, a death, a respawn or a disconnect since we were
			-- scheduled all cancel this one. The player check matters: canDamage
			-- lets anyone hit an NPC without looking at the attacker, so without it
			-- a departing player's last swing still lands, tags a raider with a
			-- creator who is gone, and fires hit feedback at nobody.
			if s.lastSwing ~= generation
				or player.Parent == nil
				or player.Character ~= character
				or humanoid.Health <= 0
				or character.Parent == nil
			then
				return
			end
			resolveStrike(player, character, hit, struckStructures, reach, width, damage, knockback, crit)
		end

		task.delay(cooldown * Config.Combat.SwingStrikeAt, function()
			strike()
			-- The arc is still moving, so one instantaneous box misses anyone a few
			-- frames early or late. Sample again just after.
			task.delay(Config.Combat.SwingSampleGap, strike)
		end)
	end

	function CombatService.bind(player: Player, tool: Tool)
		tool.Activated:Connect(function()
			CombatService.swing(player, tool)
		end)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- lifecycle
	-- ─────────────────────────────────────────────────────────────────────────────

	function CombatService.onCharacter(player: Player, character: Model)
		local humanoid = character:WaitForChild("Humanoid", 10) :: Humanoid
		if not humanoid then
			return
		end
		humanoid.WalkSpeed = Config.Combat.WalkSpeed
		humanoid.JumpPower = Config.Combat.JumpPower
		humanoid.UseJumpPower = true

		task.wait(0.35)
		if not waitForProfile(player) then
			return
		end
		CombatService.applyArmor(player, character)
		CombatService.equipCurrentBat(player)

		-- Re-apply once a beat later. Roblox's own Health script and the respawn
		-- pipeline both write Humanoid.Health after CharacterAdded returns, and
		-- nothing orders those against this write. Guarded on the character still
		-- being current so a fast death-respawn cannot apply to the wrong body.
		task.delay(0.75, function()
			if player.Character == character and humanoid.Health > 0 then
				CombatService.applyArmor(player, character)
			end
		end)

		humanoid.Died:Connect(function()
			local killerTag = humanoid:FindFirstChild("creator") :: ObjectValue?
			if killerTag and killerTag.Value and killerTag.Value:IsA("Player") then
				CombatService.creditKill(killerTag.Value, player.Name)
			end
		end)
	end

	function CombatService.creditKill(player: Player, victimName: string)
		local profile = DataService.get(player)
		if not profile then
			return
		end
		profile.kills += 1
		Economy.push(player)
		Economy.notify(player, { kind = "ko", title = "KO!", body = victimName })
	end

	--- Used by NPCService so raider damage flows through the same path.
	function CombatService.npcAttack(npc: Model, victimModel: Model, damage: number)
		local _, npcRoot = Util.getRig(npc)
		if not npcRoot then
			return
		end
		CombatService.damage(victimModel, damage, npcRoot.Position, Config.Waves.AttackKnockback, nil)
	end

	function CombatService.start()
		Players.PlayerRemoving:Connect(function(player)
			state[player] = nil
		end)
	end

	return CombatService
end


__MODULES["DataService"] = function()
	--[[
		DataService.lua — DataStore persistence with SESSION LOCKING, retries,
		autosave and a safe shutdown flush. Falls back to in-memory only if
		DataStores are unavailable (Studio without API access), so the game still
		runs.

		THE LOCK LIVES INSIDE THE PROFILE RECORD, as `stored.__lock`, rather than
		under a key of its own. Roblox has no cross-key transaction, so a lock in a
		second key could only ever be CHECKED separately from the write it is meant
		to guard — and a check that is not the write is a race with a smaller
		window, not a fix. Keeping it in the record makes "only the lock holder may
		write" one UpdateAsync: the transform sees the lock and the data together
		and either writes both or writes neither. It also halves the request cost
		and lets a server that has lost its lock discover that on its next write for
		free, instead of by polling.

		NO PROFILE_VERSION BUMP AND NO MIGRATION IS NEEDED for it, which is worth
		knowing before someone adds one. reconcile() iterates the keys of a fresh
		DEFAULT (`for k, v in pairs(profile)`), so a key the default does not have
		is structurally invisible to it and `__lock` can never reach the in-memory
		profile; and save() builds an explicit payload table rather than cloning the
		profile, so it can never leak back out either. The `__` prefix matches the
		existing `__loadFailed` convention: fields the save format does not own.
	]]

	local Req = __Req
	local Config = Req("Config")

	local DataStoreService = game:GetService("DataStoreService")
	local Players = game:GetService("Players")
	local RunService = game:GetService("RunService")

	local DataService = {}

	local STORE_NAME = "TungTungTycoon_v1"

	--- Every timing this file runs on. They are in Config because they are numbers
	--- in relationships with each other and tools/verify_config.lua can see Config;
	--- see the PERSISTENCE banner there for what each relationship protects.
	local P = Config.Persistence

	--- WHO THIS SERVER IS, computed once. `game.JobId` is empty in Studio, and the
	--- fallback is the stable string "studio" rather than a fresh random id ON
	--- PURPOSE: BindToClose early-returns in Studio, so a Studio session never
	--- releases its lock, and a stable identity means the next Studio run walks
	--- straight back into its own lock instead of waiting out LockStaleSeconds.
	local SERVER_ID = (game.JobId ~= "" and game.JobId) or "studio"

	--- Bumped whenever a saved value's MEANING changes rather than its shape.
	--- reconcile() runs the migrations between the saved version and this one.
	---
	--- 1 -> 2: Config.Bats grew from three tiers to six, with ash and crimson
	---         inserted between oak and void. profile.batTier stores an INDEX, so
	---         a v1 save reading "3" meant void and now means ash — a silent
	---         downgrade of a purchase, and one nothing else in the game could
	---         detect.
	local PROFILE_VERSION = 2

	--- v1 bat tier -> v2 bat tier. { starter, oak, void } -> their new indices.
	local LEGACY_BAT_TIERS = { 1, 2, 5 }

	local store: DataStore? = nil
	local dataStoresUsable = true

	do
		local ok, result = pcall(function()
			return DataStoreService:GetDataStore(STORE_NAME)
		end)
		if ok then
			store = result
		else
			dataStoresUsable = false
			warn("[Tung] DataStores unavailable, running in memory-only mode: " .. tostring(result))
		end
	end

	local function defaultProfile()
		return {
			cash = Config.Economy.StartingCash,
			owned = {},        -- { [buttonId] = true }
			rebirths = 0,
			batTier = 1,
			armorTier = 1,
			kills = 0,
			playtime = 0,
			-- invariant: SESSION fields. reconcile() merges a saved value onto this
			-- default only when the TYPES match, so adding a field here is what makes every
			-- existing save keep loading: an old profile simply arrives with the
			-- default. Every one of these must ALSO appear in the hand-listed
			-- payload in save() below, or it is dropped on the way out.
			--
			-- lastSeen is 0 rather than os.time() deliberately. A profile that has
			-- never stored one has no knowable logout time, and seeding it with
			-- "now" would look like a zero-second session; seeding it with 0 means
			-- SessionService skips the offline payout for that first session and
			-- starts counting from the logout after it.
			--
			-- `unlocks` used to live here, holding the rebirth milestones a player
			-- had passed. It was a saved copy of something SessionService derives
			-- from profile.rebirths on every read, so it could only ever go stale;
			-- it is gone, and a save that still carries one is simply ignored.
			lastSeen = 0,
			-- #105: when this player first ran out of game — 0 until it happens.
			-- The stamp IS the telemetry: the players worth talking to are the
			-- ones this is non-zero for.
			frontier = 0,
			-- #97: the day's objectives — { day, baseline = { kills, buys,
			-- reputation }, done = { [id] = true } }. The baseline is the day's
			-- first sight of each stat; progress is live stat minus baseline, and
			-- the reset is day arithmetic like the tower's.
			objectives = { day = 0, baseline = {}, done = {} },
			-- #96: the disclosure high-water — { [surfaceId] = true }. Written
			-- once per surface, never cleared: nothing disappears once shown, and
			-- a returning player is never re-onboarded.
			disclosed = {},
			-- #95: the tower — the UTC day last climbed and the best floor
			-- reached that day. Compared against today's day number on read, so
			-- yesterday's best resets by arithmetic instead of by a job.
			tower = { day = 0, best = 0 },
			-- #123: the reputation stat — a weighted count of acts of help. A
			-- number rather than an int: gap weighting accrues halves.
			reputation = 0,
			-- #124: damaged defences, as { [siegeKey] = fraction of full health },
			-- only keys below full. Fractions rather than hit points, so the same
			-- dent survives the max moving when the plot buys land.
			structure = {},
			sessions = {},     -- streak / boost / cap / playtime state, shaped by SessionService
			upgrades = {},     -- { [upgradeId] = level }, shaped by UpgradeService (PROTOTYPE)
			utilityEquipped = "",  -- a Config.Utilities id; "" rather than nil so the
			                       -- type-matched reconcile can merge a saved value

			-- ANALYTICS. Three counters, and all three are ACCOUNT-scoped rather
			-- than session-scoped, which is the only reason they need persisting at
			-- all.
			--
			-- firstBuySeconds is the one worth explaining: 0 means "has never bought
			-- a button", so `first_button_purchased` fires once per ACCOUNT. A
			-- returning player's first purchase of the evening is not onboarding,
			-- and a session-scoped version of this number would say it was, every
			-- evening, forever — which is the shape of a metric that looks healthy
			-- while onboarding is broken.
			--
			-- No PROFILE_VERSION bump and no migration: reconcile() merges a saved
			-- value onto the default only when the types match, so every existing
			-- save simply arrives with 0. That is the correct answer for all three.
			firstJoin = 0,         -- os.time() of the account's first ever session
			totalSessions = 0,     -- incremented by Analytics.onPlayer
			firstBuySeconds = 0,   -- seconds from join to the first button ever bought
			version = PROFILE_VERSION,
		}
	end

	local profiles: { [number]: any } = {}
	local loading: { [number]: boolean } = {}

	local function key(userId: number): string
		return "player_" .. userId
	end

	local function retry(fn, attempts: number)
		local lastErr
		for i = 1, attempts do
			local ok, result = pcall(fn)
			if ok then
				return true, result
			end
			lastErr = result
			task.wait(0.6 * i)
		end
		return false, lastErr
	end

	--- Merges saved fields onto a fresh default so schema additions are safe.
	local function reconcile(saved)
		local profile = defaultProfile()
		if type(saved) ~= "table" then
			return profile
		end
		for k, v in pairs(profile) do
			if saved[k] ~= nil and type(saved[k]) == type(v) then
				profile[k] = saved[k]
			end
		end
		-- prune ids that no longer exist in Config
		local cleanOwned = {}
		if type(profile.owned) == "table" then
			for id, value in pairs(profile.owned) do
				if value and Config.ButtonById[id] then
					cleanOwned[id] = true
				end
			end
		end
		profile.owned = cleanOwned
		profile.cash = math.max(0, tonumber(profile.cash) or 0)
		profile.rebirths = math.clamp(math.floor(tonumber(profile.rebirths) or 0), 0, Config.Rebirth.MaxRebirths)
		profile.batTier = math.floor(tonumber(profile.batTier) or 1)

		-- MIGRATIONS. Run before the clamps, because a stale index is not out of
		-- range — it is in range and means the wrong thing, which is worse.
		local version = math.floor(tonumber(profile.version) or 1)
		if version < 2 then
			profile.batTier = LEGACY_BAT_TIERS[profile.batTier] or profile.batTier
		end
		profile.version = PROFILE_VERSION

		profile.batTier = math.clamp(profile.batTier, 1, #Config.Bats)
		profile.armorTier = math.clamp(math.floor(tonumber(profile.armorTier) or 1), 1, #Config.Armor.Tiers)

		-- A weapon or armour button is the RECORD of a granted tier, so it must
		-- never disagree with the tier itself. A save from before the weapons
		-- track existed owns batforge and batforge2 but none of the rungs now
		-- sitting between them — and because grantBat is monotonic, those rungs
		-- would light up as available and then take the player's money and do
		-- nothing. Backfill anything the tier already covers.
		--
		-- Idempotent, and it fixes the CLASS: the same divergence would reappear
		-- from any future reordering of Config.Bats.
		for _, def in ipairs(Config.Buttons) do
			if def.kind == "Gear" then
				local bat = Config.BatById[def.grants]
				if bat and bat.tier <= profile.batTier then
					profile.owned[def.id] = true
				end
			elseif def.kind == "Armor" then
				local tier = Config.ArmorById[def.grants]
				if tier and tier.tier <= profile.armorTier then
					profile.owned[def.id] = true
				end
			end
		end

		return profile
	end

	--- The saved shape of a profile, listed key by key.
	---
	--- EXPLICIT ON PURPOSE, and a new persisted field needs BOTH this and the key
	--- in defaultProfile() — with only the default it works all session and is gone
	--- at next login. It is also what keeps `__lock` and `__loadFailed` out of the
	--- save: a clone of the profile would carry whatever anyone hung off it.
	local function payloadOf(profile)
		return {
			cash = profile.cash,
			owned = profile.owned,
			rebirths = profile.rebirths,
			batTier = profile.batTier,
			armorTier = profile.armorTier,
			kills = profile.kills,
			playtime = profile.playtime,
			lastSeen = profile.lastSeen,
			frontier = profile.frontier,
			objectives = profile.objectives,
			disclosed = profile.disclosed,
			tower = profile.tower,
			reputation = profile.reputation,
			structure = profile.structure,
			sessions = profile.sessions,
			upgrades = profile.upgrades,
			utilityEquipped = profile.utilityEquipped,
			-- A FIELD ADDED TO defaultProfile() AND NOT TO THIS TABLE IS NEVER
			-- PERSISTED. It defaults correctly, works for the whole session, and is
			-- gone at logout with nothing anywhere saying so. HANDOFF_v4 §2 names
			-- this landmine by name; armorTier nearly repeated it.
			firstJoin = profile.firstJoin,
			totalSessions = profile.totalSessions,
			firstBuySeconds = profile.firstBuySeconds,
			version = profile.version,
		}
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- SESSION LOCKING
	-- ─────────────────────────────────────────────────────────────────────────────

	--- What a stored lock means to US, right now. Pure; `now` is passed in rather
	--- than read, because every caller is inside an UpdateAsync transform that may
	--- run more than once and must sample the clock itself.
	---
	--- A MISSING OR MALFORMED LOCK COUNTS AS FREE. The store is full of records
	--- written before this feature existed, and refusing to touch them would lock
	--- every existing player out of their own save.
	local function lockState(lock, now: number): string
		if type(lock) ~= "table" or type(lock.jobId) ~= "string" then
			return "free"
		end
		if lock.jobId == SERVER_ID then
			return "own"
		end
		if now - (tonumber(lock.heartbeat) or 0) >= P.LockStaleSeconds then
			return "stale"
		end
		return "held"
	end

	--- The one write primitive. Everything this file stores goes through it.
	---
	--- THE TRANSFORM CAN RUN MORE THAN ONCE. UpdateAsync re-runs it when it loses
	--- an internal conflict, so a mutator must be pure with respect to anything it
	--- captured: it ASSIGNS its result onto `outcome` and never accumulates onto
	--- it, and it builds the value it returns from scratch rather than editing
	--- something a previous run touched.
	local function transact(userId: number, mutate)
		local outcome = {}
		local ok, err = retry(function()
			return (store :: DataStore):UpdateAsync(key(userId), function(stored)
				-- os.time() SAMPLED HERE, inside the transform. A timestamp taken
				-- outside would be stale by exactly however long the conflict that
				-- caused the re-run cost us, which is the one case where a
				-- heartbeat being late matters.
				return mutate(stored, os.time(), outcome)
			end)
		end, 4)
		return ok, err, outcome
	end

	--- Take the lock, and read the profile in the same round trip.
	---
	--- Branches in priority order. Our own lock is taken unconditionally however
	--- old it is — that is a rejoin to the same server, and the only server that
	--- could be racing us is us. A stale foreign lock is stolen on the FIRST
	--- attempt, because waiting out a server that has been silent for five minutes
	--- helps nobody. A live foreign lock aborts the write by returning nil, which
	--- leaves the record untouched down to the byte.
	local function acquire(stored, now: number, outcome)
		outcome.stolen = nil
		local state = lockState(stored and stored.__lock, now)

		if state == "held" then
			outcome.status = "held"
			outcome.profile = nil
			return nil
		end
		if state == "stale" then
			local lock = stored.__lock
			outcome.stolen = {
				jobId = tostring(lock.jobId),
				age = now - (tonumber(lock.heartbeat) or 0),
			}
		end

		-- THE ACQUIRE IS THE READ: one round trip, no separate GetAsync. The record
		-- written back is built from a freshly reconciled profile rather than from
		-- `stored`, so a key no schema has mentioned in a year is dropped here
		-- instead of riding along forever.
		local profile = reconcile(stored)
		outcome.status = "acquired"
		outcome.profile = profile

		local out = payloadOf(profile)
		out.__lock = { jobId = SERVER_ID, heartbeat = now, placeId = game.PlaceId }
		return out
	end

	--- Write `payload`, refreshing the heartbeat — or, on release, dropping the
	--- lock entirely.
	---
	--- A FOREIGN LOCK MEANS WE LOST OURS, and the write is abandoned. It is the
	--- serious case: nothing else can put another jobId there while we still hold
	--- it, so reaching this branch means this server was frozen or throttled for
	--- longer than LockStaleSeconds and someone else has been the owner since.
	local function writer(payload, release: boolean)
		return function(stored, now: number, outcome)
			local state = lockState(stored and stored.__lock, now)
			if state == "held" or state == "stale" then
				outcome.status = "lost"
				return nil
			end

			outcome.status = if release then "released" else "written"
			local out = table.clone(payload)
			if not release then
				out.__lock = { jobId = SERVER_ID, heartbeat = now, placeId = game.PlaceId }
			end
			return out
		end
	end

	function DataService.load(player: Player)
		local userId = player.UserId

		-- WAIT FOR A LOAD ALREADY IN FLIGHT. `loading` was written and never read.
		-- That cost nothing while a load was a single GetAsync; it costs a second
		-- acquire against a key this server is already queueing for now that a load
		-- can take half a minute, because SessionService.onPlayer runs
		-- `DataService.get(player) or DataService.load(player)`.
		while loading[userId] do
			task.wait(0.2)
		end
		if profiles[userId] then
			return profiles[userId]
		end
		loading[userId] = true

		local profile
		if store and dataStoresUsable then
			for _ = 1, P.AcquireAttempts do
				local ok, err, outcome = transact(userId, acquire)
				if not ok then
					warn(("[Tung] load failed for %s: %s"):format(player.Name, tostring(err)))
					profile = reconcile(nil)
					profile.__loadFailed = true   -- never overwrite good data with a failed read
					break
				end
				if outcome.status == "acquired" then
					if outcome.stolen then
						warn(("[Tung] job %s took the session lock on %s from job %s, whose heartbeat is %ds old")
							:format(SERVER_ID, player.Name, outcome.stolen.jobId, outcome.stolen.age))
					end
					profile = outcome.profile
					break
				end
				-- Held by a live server. JITTER MATTERS: a mass teleport lands a
				-- dozen players at once, and unjittered retries arrive as a burst
				-- against one key's request budget.
				task.wait(P.AcquireRetrySeconds + math.random() * 2)
			end

			if not profile then
				warn(("[Tung] job %s could not take the session lock on %s after %d attempts; another server still holds it")
					:format(SERVER_ID, player.Name, P.AcquireAttempts))
				loading[userId] = nil
				player:Kick("Your save is still in use on another server. Please rejoin in a moment.")
				return nil
			end
		else
			profile = reconcile(nil)
			profile.__loadFailed = not dataStoresUsable
		end

		profiles[userId] = profile
		loading[userId] = nil
		return profile
	end

	function DataService.get(player: Player)
		return profiles[player.UserId]
	end

	function DataService.save(player: Player, release: boolean?)
		local userId = player.UserId
		local profile = profiles[userId]
		if not profile then
			return false
		end
		if profile.__loadFailed then
			-- data never loaded cleanly; refuse to clobber the real save
			if release then
				profiles[userId] = nil
			end
			return false
		end

		local payload = payloadOf(profile)

		local saved = false
		if store and dataStoresUsable then
			local ok, err, outcome = transact(userId, writer(payload, release == true))
			if not ok then
				warn(("[Tung] save failed for %s: %s"):format(player.Name, tostring(err)))
			elseif outcome.status == "lost" then
				-- WE ARE NOT THE OWNER ANY MORE. Do not write: whoever holds the
				-- lock has been loading, playing and saving this profile while we
				-- were frozen, and our payload is older than theirs by however long
				-- that was. From this instant the session is unsaveable, so it also
				-- ends — playing on is playing for nothing.
				profile.__loadFailed = true
				warn(("[Tung] job %s lost the session lock on %s and will not write; the session was frozen for over %ds")
					:format(SERVER_ID, player.Name, P.LockStaleSeconds))
				player:Kick("Your save was taken over by another server. Please rejoin.")
			else
				saved = true
			end
		end

		if release then
			profiles[userId] = nil
		end
		return saved
	end

	function DataService.start()
		Players.PlayerRemoving:Connect(function(player)
			DataService.save(player, true)
		end)

		-- THE HEARTBEAT RIDES THIS LOOP. There is deliberately no second timer for
		-- it: every autosave is already an UpdateAsync, and the transform refreshing
		-- `__lock.heartbeat` on its way past costs nothing. A separate heartbeat
		-- loop would double this game's write rate to buy nothing.
		task.spawn(function()
			while true do
				task.wait(P.AutosaveSeconds)
				for _, player in ipairs(Players:GetPlayers()) do
					local profile = profiles[player.UserId]
					if profile then
						profile.playtime += P.AutosaveSeconds
						task.spawn(DataService.save, player, false)
					end
				end
			end
		end)

		game:BindToClose(function()
			-- STUDIO WRITES NOTHING ON SHUTDOWN, which is also why SERVER_ID falls
			-- back to a stable "studio": the lock this session took is still there
			-- at the next run, and the next run recognises it as its own.
			if RunService:IsStudio() then
				return
			end
			local remaining = 0
			for _, player in ipairs(Players:GetPlayers()) do
				remaining += 1
				task.spawn(function()
					DataService.save(player, true)
					remaining -= 1
				end)
			end
			local deadline = os.clock() + P.ShutdownDrainSeconds
			while remaining > 0 and os.clock() < deadline do
				task.wait(0.1)
			end
		end)
	end

	return DataService
end


__MODULES["DisclosureService"] = function()
	--[[
		DisclosureService.lua — the game reveals itself as you can take it (#96).

		design:D-05. One beat computes, per player, which Config.Disclosure rows
		their ownership has earned; a newly earned row is written into
		profile.disclosed (the persisted HIGH-WATER — nothing ever disappears once
		shown, and a returning player is never re-onboarded), announced with one
		toast, and the whole set is pushed down the Disclosure remote for the
		client to render. The client never decides anything.

		GAMEPLAY GATES READ THE SAME TABLE. A row with `gate = true` holds a
		SYSTEM back, not just its pixels: NPCService asks unlocked() before it
		sieges a plot, because a raid siren in the first minute is the overload
		this file exists to prevent. unlocked() answers from the profile, so the
		gate and the interface can never disagree.

		The beat is a 3-second poll over present players — the refreshButtons
		cadence, and the same argument: ownership changes arrive from several
		writers (purchase, admin grant, rebirth wipe) and one reconciler beat is
		simpler than chasing them all. A rebirth wipes `owned` and NOT
		`disclosed`; the high-water is the point.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Net = Req("Net")
	local DataService = Req("DataService")

	local Players = game:GetService("Players")

	local DisclosureService = {}

	local remote = Net.event("Disclosure")

	--- The one question: has this player ever earned this surface?
	function DisclosureService.unlocked(player: Player, id: string): boolean
		local profile = DataService.get(player)
		return profile ~= nil and profile.disclosed ~= nil and profile.disclosed[id] == true
	end

	--- `fresh` is what arrived in THIS pass, and it rides the same push as the
	--- high-water set rather than a second remote: the client has to have the id in
	--- `ids` before it can render the surface the card is announcing, and two
	--- remotes would be two orderings to get right.
	---
	--- It is absent on a join push. A returning player owns most of this list
	--- already, and a card naming eleven things they have had for a week is not an
	--- announcement.
	local function push(player: Player, fresh)
		local profile = DataService.get(player)
		if not profile then
			return
		end
		local ids = {}
		for id in pairs(profile.disclosed or {}) do
			table.insert(ids, id)
		end
		remote:FireClient(player, { ids = ids, fresh = fresh })
	end

	--- One pass for one player: write every newly earned row into the high-water.
	--- Returns how many arrived, so the beat knows whether to push.
	function DisclosureService.reconcile(player: Player): (number, { { name: string, help: string } })
		local profile = DataService.get(player)
		if not profile then
			return 0
		end
		profile.disclosed = profile.disclosed or {}
		local has = function(id)
			return profile.owned[id] == true
		end
		local arrived = 0
		local fresh = {}
		for _, row in ipairs(Config.Disclosure) do
			if not profile.disclosed[row.id] and Config.disclosureEarned(row, has) then
				profile.disclosed[row.id] = true
				arrived += 1
				if row.after then
					-- the always-on rows announce nothing; an arrival is earned
					table.insert(fresh, { name = row.name, help = row.help })
				end
			end
		end
		-- COLLECTED, NOT ANNOUNCED ONE BY ONE. This used to send a toast per row,
		-- into the same side column as a knockout and a loot drop — so an addition
		-- to the game read as one more line of traffic. It is also a BATCH more
		-- often than not: buying `walls` earns siege, party and recall in one pass,
		-- and three toasts in a row is what made it traffic.
		return arrived, fresh
	end

	function DisclosureService.start()
		Players.PlayerAdded:Connect(function(player)
			task.defer(push, player)
		end)
		task.spawn(function()
			while true do
				task.wait(3)
				for _, player in ipairs(Players:GetPlayers()) do
					local ok, arrived, fresh = pcall(DisclosureService.reconcile, player)
					if ok and arrived > 0 then
						push(player, #fresh > 0 and fresh or nil)
					elseif not ok then
						warn("[Tung] disclosure error: " .. tostring(arrived))
					end
				end
			end
		end)
	end

	return DisclosureService
end


__MODULES["Economy"] = function()
	--[[
		Economy.lua — the single place cash is created, spent and replicated.

		IT OWNS profile.cash, the leaderstats folder, and the Stats payload the HUD
		draws itself from. Everything else asks: add, spend, steal, get.

		THERE IS EXACTLY ONE OTHER WRITER, and it is deliberate rather than a leak.
		Tycoon:rebirth resets profile.cash to Config.Economy.StartingCash as part of
		wiping the factory, because the reset and the wipe have to be one act;
		applyRebirthGrants below then tops that up to the rebirth's starting-cash
		grant. Any THIRD writer is a bug — the point of the rule is that "where did
		this money come from" has one answer per source.

		push AND markDirty ARE NOT INTERCHANGEABLE. add() and steal() only mark the
		player dirty and replicate on the 0.1s beat in start(), because droppers pay
		out several times a second and a remote per drop is a remote per drop. spend()
		and applyRebirthGrants() push synchronously, because a purchase that takes a
		tenth of a second to show up reads as a purchase that did not happen. A
		one-off grant therefore has to push for itself; AdminService does, and says
		why.

		THE MULTIPLIER HOOKS MULTIPLY, THEY DO NOT REPLACE. Three names are live:
		"friends" (SocialService), "sessions" (SessionService — the boost and the
		weekend bonus), and "upgrades" (UpgradeService, prototype). The registry is
		keyed so they compose instead of clobbering each other, and
		tools/testing/specs/weekend_spec.lua pins that: a boost on a Saturday must
		come out as x4, because a 3 means someone added them and a 2 means one is
		being silently dropped. Registration is inverted on purpose — the hooks
		register themselves at boot and Economy stays ignorant of what they are —
		because they all depend on Economy and Req refuses a circular require.

		SO A HOOK MUST BE AN O(1) TABLE READ. multiplier() runs on every add(), up to
		~10 times a second per plot at endgame, and every one of those calls walks the
		whole registry. Never a web call, never a DataStore read; SocialService
		resolves friendship on its own timer and the hook reads the result.

		DO NOT PASS applyMultiplier = true FOR A NUMBER THAT ALREADY CARRIES IT.
		SessionService's offline grant is computed from a per-second rate that already
		includes the rebirth multiplier, and AdminService's `$1000` is meant to be
		1000; both pass false, and both would be silently wrong the other way.

		setupLeaderstats SILENTLY DOES NOTHING WITHOUT A LOADED PROFILE — it returns
		on a nil profile rather than yielding — which is the whole reason
		Main.server.lua boots DataService before Economy and calls DataService.load
		before setupLeaderstats. Reordering those lines produces a server with no
		leaderstats and no error.

		BEFORE YOU CHANGE THE CURVE: MultiplierPerRebirth is compounded, not added
		(see multiplier below). tools/verify_config.lua asserts that
		Config.Economy.StartingCash covers the cheapest requirement-free button — a
		fresh player with no dropper has no income and deadlocks — that no other
		track's first rung is affordable from it, and that CostGrowth over
		MultiplierPerRebirth keeps the prestige ladder solvable. Run the verifier
		before you playtest a number in Config.Rebirth or Config.Economy; the curve
		checks are the slowest thing to rediscover by hand.

		This module also runs headless — it is in tools/test.py's SERVER_MODULES, and
		boost_spec, weekend_spec and playtime_spec all observe the game through
		Economy.multiplier and Economy.get. Keep it free of Touched handlers and of
		anything that needs a physics step, or those specs stop being runnable.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Net = Req("Net")

	local Players = game:GetService("Players")

	local DataService = Req("DataService")

	local Economy = {}

	local statsRemote = Net.event("Stats")
	local notifyRemote = Net.event("Notify")

	local dirty: { [Player]: boolean } = {}

	--- PROTOTYPE HOOKS. Timed boosts, the weekend bonus and (eventually) the
	--- player-upgrade cash multiplier all stack on top of rebirth, but Economy
	--- must not depend on any of them — they depend on Economy, and Req refuses a
	--- circular require. Each registers a named function here at boot and Economy
	--- stays ignorant of what they do.
	---
	--- Keyed rather than a single slot so two prototypes can both stack without
	--- silently overwriting each other.
	local multiplierHooks: { [string]: (Player) -> number } = {}

	function Economy.setMultiplierHook(name: string, fn: ((Player) -> number)?)
		multiplierHooks[name] = fn
	end

	function Economy.multiplier(player: Player): number
		local profile = DataService.get(player)
		if not profile then
			return 1
		end
		-- compounding, not linear: rebirth cost grows geometrically (CostGrowth^n)
		-- so a linear payout bonus would make each rebirth strictly worse than the
		-- last and the prestige loop would dead-end after two or three.
		local base = Config.Rebirth.MultiplierPerRebirth ^ profile.rebirths
		for _, hook in pairs(multiplierHooks) do
			base *= hook(player)
		end
		return base
	end

	function Economy.get(player: Player): number
		local profile = DataService.get(player)
		return profile and profile.cash or 0
	end

	function Economy.setupLeaderstats(player: Player)
		local profile = DataService.get(player)
		if not profile then
			return
		end

		local existing = player:FindFirstChild("leaderstats")
		if existing then
			existing:Destroy()
		end

		local folder = Instance.new("Folder")
		folder.Name = "leaderstats"
		folder.Parent = player

		local cash = Instance.new("NumberValue")
		cash.Name = Config.Economy.CurrencyName
		cash.Value = profile.cash
		cash.Parent = folder

		local rebirths = Instance.new("IntValue")
		rebirths.Name = "Rebirths"
		rebirths.Value = profile.rebirths
		rebirths.Parent = folder

		local kos = Instance.new("IntValue")
		kos.Name = "KOs"
		kos.Value = profile.kills
		kos.Parent = folder

		local rep = Instance.new("IntValue")
		rep.Name = "Rep"
		rep.Value = math.floor(profile.reputation or 0)
		rep.Parent = folder
	end

	local function syncLeaderstats(player: Player)
		local profile = DataService.get(player)
		local folder = player:FindFirstChild("leaderstats")
		if not profile or not folder then
			return
		end
		local cash = folder:FindFirstChild(Config.Economy.CurrencyName)
		if cash then
			(cash :: NumberValue).Value = profile.cash
		end
		local rebirths = folder:FindFirstChild("Rebirths")
		if rebirths then
			(rebirths :: IntValue).Value = profile.rebirths
		end
		local kos = folder:FindFirstChild("KOs")
		if kos then
			(kos :: IntValue).Value = profile.kills
		end
		local rep = folder:FindFirstChild("Rep")
		if rep then
			(rep :: IntValue).Value = math.floor(profile.reputation or 0)
		end
	end

	function Economy.push(player: Player)
		local profile = DataService.get(player)
		if not profile then
			return
		end
		syncLeaderstats(player)
		statsRemote:FireClient(player, {
			cash = profile.cash,
			rebirths = profile.rebirths,
			kills = profile.kills,
			batTier = profile.batTier,
			armorTier = profile.armorTier,
			multiplier = Economy.multiplier(player),
			owned = profile.owned,
			rebirthCost = Economy.rebirthCost(player),
		})
	end

	--- Coalesces rapid-fire updates (droppers) into ~10 replications/sec.
	function Economy.markDirty(player: Player)
		dirty[player] = true
	end

	function Economy.add(player: Player, amount: number, applyMultiplier: boolean?)
		local profile = DataService.get(player)
		if not profile or amount <= 0 then
			return 0
		end
		local final = amount
		if applyMultiplier then
			final = amount * Economy.multiplier(player)
		end
		-- design:D-02, via #98 — THE STORAGE CAP, applied at the one door money
		-- comes in through. Cash above what the unit holds is LOST, not queued:
		-- the cap exists to force spending, and a queue would be a second bank
		-- with no cap on it. The offline grant is deliberately NOT exempt —
		-- "log in before it overflows" is the return-visit pressure the cap is
		-- for. Spending and stealing are outflows and stay unclamped.
		local cap = Economy.storageCapFor(player)
		local room = cap - profile.cash
		if room <= 0 then
			return 0
		end
		final = math.min(final, room)
		profile.cash += final
		Economy.markDirty(player)
		return final
	end

	--- What this player's unit holds right now: the config formula against their
	--- own save, and their plot's unit if they have one standing. Economy cannot
	--- require Tycoon (Tycoon requires Economy), so the plot registers its
	--- broken-state reader here — the setMultiplierHook shape, one field over.
	local storageIntactFor: ((Player) -> boolean)? = nil

	function Economy.setStorageIntactHook(fn: ((Player) -> boolean)?)
		storageIntactFor = fn
	end

	function Economy.storageCapFor(player: Player): number
		local profile = DataService.get(player)
		if not profile then
			return Config.Storage.CapFloor
		end
		local owned = profile.owned or {}
		local intact = true
		if storageIntactFor then
			intact = storageIntactFor(player)
		end
		return Config.storageCap(function(id)
			return owned[id] == true
		end, profile.rebirths, intact)
	end

	function Economy.spend(player: Player, amount: number): boolean
		local profile = DataService.get(player)
		if not profile then
			return false
		end
		if profile.cash < amount then
			return false
		end
		profile.cash -= amount
		Economy.push(player)
		return true
	end

	--- An absolute outflow that takes what is there and reports what it got —
	--- the raid ledger's door (#94). The CALLER is responsible for sizing the
	--- amount from overflow; this clamps only at the floor of an empty bank.
	function Economy.take(player: Player, amount: number): number
		local profile = DataService.get(player)
		if not profile or amount <= 0 then
			return 0
		end
		local taken = math.min(math.floor(amount), profile.cash)
		if taken <= 0 then
			return 0
		end
		profile.cash -= taken
		Economy.markDirty(player)
		return taken
	end

	--- Raiders nibble a slice of your bank when they land a hit.
	function Economy.steal(player: Player, fraction: number): number
		local profile = DataService.get(player)
		if not profile then
			return 0
		end
		local taken = math.floor(profile.cash * fraction)
		if taken <= 0 then
			return 0
		end
		profile.cash -= taken
		Economy.markDirty(player)
		return taken
	end

	function Economy.rebirthCost(player: Player): number
		local profile = DataService.get(player)
		local n = profile and profile.rebirths or 0
		return math.floor(Config.Rebirth.BaseCost * (Config.Rebirth.CostGrowth ^ n))
	end

	--- mechanism: PROTOTYPE (Config.Prototypes.RebirthPerks). A rebirth pays four
	--- things, not one number. `Tycoon:rebirth()` owns two of them — it bumps profile.rebirths
	--- (the multiplier) and resets cash to Config.Economy.StartingCash — and it is
	--- owned by another track, so the starting-cash grant is applied here, from the
	--- one module allowed to create cash.
	---
	--- `perks` comes from SessionService.rebirthPerksFor(profile). Passing it in
	--- rather than computing it keeps the dependency arrow pointing one way.
	---
	--- Milestone unlocks are DERIVED ON READ and there is nothing here to write.
	--- A saved copy of a pure function of profile.rebirths can only go stale, and
	--- the one this used to keep had.
	---
	--- Idempotent on purpose: it tops cash UP to the grant instead of adding to
	--- it, so a double call (a retry, a re-detect) cannot be farmed.
	function Economy.applyRebirthGrants(player: Player, perks): number
		local profile = DataService.get(player)
		if not profile or not perks then
			return 0
		end

		local granted = 0
		local target = math.floor(tonumber(perks.startingCash) or 0)
		if target > profile.cash then
			granted = target - profile.cash
			profile.cash = target
		end

		Economy.push(player)
		return granted
	end

	function Economy.notify(player: Player, payload)
		notifyRemote:FireClient(player, payload)
	end

	function Economy.start()
		task.spawn(function()
			while true do
				task.wait(0.1)
				for player in pairs(dirty) do
					dirty[player] = nil
					if player.Parent then
						Economy.push(player)
					end
				end
			end
		end)

		Players.PlayerRemoving:Connect(function(player)
			dirty[player] = nil
		end)
	end

	Economy.format = Util.abbreviate

	return Economy
end


__MODULES["GateService"] = function()
	--[[
		GateService.lua — the doors in the shell, and the one loop that opens them.

		The shell has two deliberate openings: the front gateway you walk in through
		and the cut in the back wall onto the generator yard. Until this round they
		were holes. They have leaves now — one for the yard door, a pair for the
		gateway — and they slide out of the way when somebody walks up to them.

		Three decisions that look arbitrary and are not:

		  A DISTANCE TEST, NOT Touched/TouchEnded. This is the same trap the teleport
		  pads were deleted for. A character standing on a trigger bounces off its own
		  physics jitter, firing Touched and TouchEnded over and over, and the pads
		  needed a cooldown, an arrival lock and a TouchEnded sweep to paper over it —
		  about a hundred lines to notice somebody was standing there.
		  Config.Floors[1].ladder's comment is the long version. A gate asked "is
		  anybody within triggerRadius" on a fixed beat cannot bounce, because there
		  is no event to bounce.

		  ONE LOOP FOR THE WHOLE SERVER, not one per plot. Ten plots x
		  1 / Gate.tickRate is fifty coroutine wakeups a second to move at most three
		  parts. This walks Tycoon.all() from a single loop and skips a plot that has
		  no owner or has not bought the walls yet, so an empty server does nothing at
		  all.

		  IT HOLDS NO REFERENCE IT TRUSTS. Gate leaves are built into the walls model
		  in self.machines, and release() and rebirth() both do
		  machines:ClearAllChildren() — so a leaf can vanish under this service
		  between two ticks. Every tick checks Parent and re-resolves, exactly as

		WHERE THE GEOMETRY LIVES: not here. Tycoon:gateLeafSpecs (tycoon/Installers.lua)
		answers what a leaf is called, where it hangs closed and where it slides to,
		and the walls branch builds from the same list. Two copies of "one leaf width
		along the wall, away from the opening centre" is two answers the day either
		wall moves.

		THE GATE ANSWERS TO ITS OWNER AND THEIR PARTY, nobody else. Since #89 hostile things do
		reach gates — a plot wave stands at yours, and PvP raiders walk up to
		anyone's — so a door that opened for any nearby humanoid would hand both
		of them a free entrance and gut #124's break-in verb. Opening on the
		owner's own proximity keeps the plot usable and makes letting a fight in
		through your own door a choice. NPCs never open anything: the position
		sweep below reads Players, and mobs get in by breaking things.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Tycoon = Req("Tycoon")
	local PartyService = Req("PartyService")

	local Players = game:GetService("Players")
	local TweenService = game:GetService("TweenService")

	local GateService = {}

	local GATE = Config.Structure.Gate

	-- Eased out rather than linear: a door that decelerates into its stop reads as a
	-- door, and a linear slide reads as a part being moved by a script.
	local TRAVEL = TweenInfo.new(GATE.travelTime, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

	--- The button that builds the walls, found by WHAT IT BUILDS rather than by id.
	--- The leaves are part of the walls model, so before that purchase there is
	--- nothing on the plot to look for and no reason to look every fifth of a second
	--- for the whole session.
	local WALLS_BUTTON = (function(): string?
		for _, def in ipairs(Config.Buttons) do
			if def.kind == "Structure" and def.structure == "walls" then
				return def.id
			end
		end
		return nil
	end)()

	-- one entry per plot: { openings = { { centre, leaves = { { spec, part, open, tween } } } } }
	local state: { [any]: any } = {}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- what a plot's gates are
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Grouped BY OPENING, because the distance test is per opening and the tween is
	--- per leaf: the gateway's two leaves answer one question between them.
	---
	--- Cached per plot for the life of the server. The specs are pure arithmetic over
	--- Config and the plot's own CFrame, neither of which changes — what changes is
	--- whether the parts they name are standing, and that is resolved every tick.
	local function stateFor(tycoon)
		local entry = state[tycoon]
		if entry then
			return entry
		end

		local openings, byId = {}, {}
		for _, spec in ipairs(tycoon:gateLeafSpecs()) do
			local opening = byId[spec.opening]
			if not opening then
				opening = { centre = spec.centre, leaves = {} }
				byId[spec.opening] = opening
				table.insert(openings, opening)
			end
			table.insert(opening.leaves, { spec = spec, part = nil, open = false, tween = nil })
		end

		entry = { openings = openings }
		state[tycoon] = entry
		return entry
	end

	--- The leaf part, if it is still standing.
	---
	--- A leaf that has gone (release, rebirth) drops its cached state with it: the
	--- replacement is a NEW part built closed, so remembering that the old one was
	--- open would leave a gate that never opens again and never says why.
	local function resolve(tycoon, leaf)
		local part = leaf.part
		if part and part.Parent then
			return part
		end
		leaf.part = tycoon.machines:FindFirstChild(leaf.spec.name, true)
		leaf.open = false
		leaf.tween = nil
		return leaf.part
	end

	--- Slides one leaf, and only if it is not already going there. Re-tweening a leaf
	--- every tick while somebody stands in the doorway restarts the animation five
	--- times a second, which looks like a stuck door.
	local function setLeaf(leaf, part: BasePart, open: boolean)
		if leaf.open == open then
			return
		end
		leaf.open = open
		-- Cancel rather than overlap. TweenService does not replace a running tween on
		-- the same property; both keep writing CFrame and whichever ran last that
		-- frame wins, so a leaf reversed mid-travel would stutter between the two
		-- targets instead of turning round.
		if leaf.tween then
			leaf.tween:Cancel()
		end
		leaf.tween = TweenService:Create(part, TRAVEL, {
			CFrame = open and leaf.spec.open or leaf.spec.closed,
		})
		leaf.tween:Play()
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the loop
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Every player's root position, WITH its player, collected once per tick.
	---
	--- Once, because the alternative is a Character/HumanoidRootPart lookup per
	--- opening per plot: ten players against twenty openings is the same two hundred
	--- distance tests either way round, but ten instance walks instead of two
	--- hundred. Players rather than every Humanoid in the workspace on purpose:
	--- an NPC must never open a gate — mobs get in by breaking things.
	local function rootPositions(): { { player: Player, position: Vector3 } }
		local roots = {}
		for _, player in ipairs(Players:GetPlayers()) do
			local character = player.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if root and root:IsA("BasePart") then
				table.insert(roots, { player = player, position = root.Position })
			end
		end
		return roots
	end

	local function ownerNear(roots, owner: Player, centre: Vector3): boolean
		for _, entry in ipairs(roots) do
			if (entry.player == owner or PartyService.sameParty(entry.player, owner))
					and (entry.position - centre).Magnitude <= GATE.triggerRadius then
				return true
			end
		end
		return false
	end

	--- Opens or closes one plot's gates to match where its OWNER is standing.
	function GateService.sync(tycoon, roots)
		for _, opening in ipairs(stateFor(tycoon).openings) do
			local wanted = ownerNear(roots, tycoon.owner, opening.centre)
			for _, leaf in ipairs(opening.leaves) do
				local part = resolve(tycoon, leaf)
				if part then
					setLeaf(leaf, part, wanted)
				end
			end
		end
	end

	--- One beat for every gate in the game.
	function GateService.tick()
		local roots = rootPositions()
		for _, tycoon in ipairs(Tycoon.all()) do
			-- An unclaimed plot has no walls standing and nobody to open them for;
			-- a claimed plot that has not bought the walls has no leaves to find.
			if tycoon.owner ~= nil and (WALLS_BUTTON == nil or tycoon.owned[WALLS_BUTTON] == true) then
				GateService.sync(tycoon, roots)
			end
		end
	end

	function GateService.start()
		if #Config.Structure.Openings == 0 then
			return
		end
		task.spawn(function()
			while true do
				task.wait(GATE.tickRate)
				-- pcall'd so one plot's bad state cannot end the loop for the other
				-- nine and leave every gate in the game frozen where it was
				local ok, err = pcall(GateService.tick)
				if not ok then
					warn("[Tung] gate tick error: " .. tostring(err))
				end
			end
		end)
	end

	return GateService
end


__MODULES["HelpService"] = function()
	--[[
		HelpService.lua — kindness earns reputation and a short income boost (#123).

		design:D-04. The counterweight to #94: a server where everyone is prey
		loses its new players, so helping has to pay, and pay MORE for helping
		someone earlier in the game than you. credit() is the one door every
		qualifying act comes through — raid defence today (RaidService), visitor
		repair today (Tycoon's repair observer, wired in Main.server), parties and
		co-combat when #102 and the wave pot arrive.

		THE REWARD IS DELIBERATELY SMALL. A persistent reputation number, and
		BoostMinutes of a BoostMultiplier on income for both sides. At this scale
		two accounts farming each other is acceptable — friends helping friends is
		the behaviour being bought — which is what removes the need for an abuse
		system. The one guard is the per-pair cooldown, and it exists so a tame
		pair cannot hold a boost forever.

		THE WEIGHT IS THE POINT. Each rebirth the helper has over the helped adds
		GapWeightPerRebirth, capped at MaxWeight; the weight scales the reputation
		earned and the helper's boost minutes. A veteran pulling a new player up
		comes out ahead of two peers pairing, which is the issue's whole ask.

		The boost is a named Economy multiplier hook ("help"), the SessionService
		shape: an O(1) expiry read, registered at boot so the require arrow keeps
		pointing at Economy. Clocks are parameters everywhere except the hook,
		which reads os.clock() — the spec harness patches it.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Economy = Req("Economy")
	local DataService = Req("DataService")

	local Players = game:GetService("Players")

	local HelpService = {}

	local H = Config.Help

	-- boost expiry per player, monotonic seconds. The multiplier hook reads it.
	local boostUntil: { [Player]: number } = {}

	-- per helper: { [helpedUserId] = cooldown-end }. One pair, one credit per
	-- window.
	local lastCredit: { [Player]: { [number]: number } } = {}

	--- The gap weighting: 1 plus GapWeightPerRebirth per rebirth the helper has
	--- over the helped, capped. Helping DOWN the ladder is what pays extra;
	--- helping up or across pays the base.
	function HelpService.weightFor(helper: Player, helped: Player): number
		local hp = DataService.get(helper)
		local ep = DataService.get(helped)
		if not hp or not ep then
			return 1
		end
		local gap = math.max(0, hp.rebirths - ep.rebirths)
		return math.min(H.MaxWeight, 1 + H.GapWeightPerRebirth * gap)
	end

	--- Seconds of boost left, for the HUD and the specs.
	function HelpService.boostRemaining(player: Player, now: number): number
		return math.max(0, (boostUntil[player] or 0) - now)
	end

	local function extendBoost(player: Player, minutes: number, now: number)
		local from = math.max(boostUntil[player] or 0, now)
		boostUntil[player] = math.min(from + minutes * 60, now + H.MaxBoostMinutes * 60)
	end

	--- The one door. Every qualifying kindness lands here; `kind` names the act
	--- for the notification. Returns the reputation earned — 0 when refused
	--- (self-help, a missing profile, or the pair inside its cooldown).
	function HelpService.credit(helper: Player, helped: Player, kind: string, now: number): number
		if helper == helped then
			return 0
		end
		local profile = DataService.get(helper)
		if not profile or not DataService.get(helped) then
			return 0
		end

		local pairs_ = lastCredit[helper]
		if pairs_ and (pairs_[helped.UserId] or 0) > now then
			return 0
		end
		if not pairs_ then
			pairs_ = {}
			lastCredit[helper] = pairs_
		end
		pairs_[helped.UserId] = now + H.PairCooldownSeconds

		local weight = HelpService.weightFor(helper, helped)
		profile.reputation = (profile.reputation or 0) + weight
		Economy.markDirty(helper)

		extendBoost(helper, H.BoostMinutes * weight, now)
		extendBoost(helped, H.BoostMinutes, now)

		Economy.notify(helper, { kind = "claim", title = "Good deed",
			body = ("+%s Rep for %s — income boosted %d min."):format(
				Util.abbreviate(weight), kind, math.floor(HelpService.boostRemaining(helper, now) / 60)) })
		Economy.notify(helped, { kind = "info", title = "Helped",
			body = ("%s had your back (%s) — income boosted %d min."):format(
				helper.Name, kind, math.floor(HelpService.boostRemaining(helped, now) / 60)) })
		return weight
	end

	function HelpService.start()
		-- the boost, as a named multiplier: an O(1) table read, per the Economy
		-- hook contract
		Economy.setMultiplierHook("help", function(player)
			if (boostUntil[player] or 0) > os.clock() then
				return H.BoostMultiplier
			end
			return 1
		end)
		Players.PlayerRemoving:Connect(function(player)
			boostUntil[player] = nil
			lastCredit[player] = nil
		end)
	end

	return HelpService
end


__MODULES["LeaderboardService"] = function()
	--[[
		LeaderboardService.lua — the board by the spawn, and the frontier (#105).

		design:D-01. The leaderboard is a WORLD OBJECT — screen space is reserved
		for what is true wherever the player stands, and a board people gather at
		is a social surface a panel is not. Server-level, ranked on Tung, top
		five, repainted on a slow beat.

		THE FRONTIER IS TOLD THE TRUTH. A player who owns every button at the
		rebirth cap has finished what exists; hiding that abandons them, so the
		moment is detected, told to them plainly with their rank, announced to
		the server once, and STAMPED into profile.frontier — the stamp is the
		telemetry, because the players who run out of game are the ones worth
		talking to. Rank only: no currency, no sink, no boost, per the issue.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Style = Req("Style")
	local Economy = Req("Economy")
	local DataService = Req("DataService")

	local Players = game:GetService("Players")

	local LeaderboardService = {}

	local boardLabel

	--- Present players, richest first.
	function LeaderboardService.standings()
		local rows = {}
		for _, player in ipairs(Players:GetPlayers()) do
			table.insert(rows, { player = player, cash = Economy.get(player) })
		end
		table.sort(rows, function(a, b)
			return a.cash > b.cash
		end)
		return rows
	end

	--- This player's 1-based rank on the server.
	function LeaderboardService.rankOf(player): number
		for rank, row in ipairs(LeaderboardService.standings()) do
			if row.player == player then
				return rank
			end
		end
		return #Players:GetPlayers()
	end

	--- Out of game: every button owned, at the rebirth cap.
	function LeaderboardService.isFrontier(profile): boolean
		if (profile.rebirths or 0) < Config.Rebirth.MaxRebirths then
			return false
		end
		for _, def in ipairs(Config.Buttons) do
			if not profile.owned[def.id] then
				return false
			end
		end
		return true
	end

	--- Stamps and announces the frontier, exactly once per account.
	function LeaderboardService.checkFrontier(player, now: number): boolean
		local profile = DataService.get(player)
		if not profile or (profile.frontier or 0) ~= 0 or not LeaderboardService.isFrontier(profile) then
			return false
		end
		profile.frontier = now
		Economy.notify(player, { kind = "boss", title = "THE FRONTIER",
			body = ("You have bought everything that exists. Rank #%d on this server. More game is coming; you finished this one.")
				:format(LeaderboardService.rankOf(player)) })
		for _, other in ipairs(Players:GetPlayers()) do
			if other ~= player then
				Economy.notify(other, { kind = "boss", title = "THE FRONTIER",
					body = ("%s has reached the edge of what exists."):format(player.DisplayName) })
			end
		end
		print(("[Tung] FRONTIER: %s (%d) at %d"):format(player.Name, player.UserId, now))
		return true
	end

	local function paintBoard()
		if not boardLabel then
			return
		end
		local lines = { "TOP TUNG" }
		for rank, row in ipairs(LeaderboardService.standings()) do
			if rank > 5 then
				break
			end
			local profile = DataService.get(row.player)
			local star = (profile and (profile.frontier or 0) ~= 0) and "  ★" or ""
			table.insert(lines, ("%d. %s  •  %s%s"):format(
				rank, row.player.DisplayName, Util.abbreviate(row.cash), star))
		end
		boardLabel.Text = table.concat(lines, "\n")
	end

	local function buildBoard()
		local bearing = math.pi / math.max(Config.plotCountFor(), 1)
		local base = Vector3.new(
			math.sin(bearing) * (Config.World.SpawnRadius + 24),
			Config.World.GroundTopY,
			math.cos(bearing) * (Config.World.SpawnRadius + 24))

		local model = Instance.new("Model")
		model.Name = "Leaderboard"
		local post = Instance.new("Part")
		post.Name = "Post"
		post.Size = Vector3.new(1.5, 10, 1.5)
		post.CFrame = CFrame.new(base + Vector3.new(0, 5, 0))
		post.Anchored = true
		post.Color = Color3.fromRGB(70, 52, 40)
		post.Material = Enum.Material.Wood
		post.Parent = model
		local board = Instance.new("Part")
		board.Name = "Board"
		board.Size = Vector3.new(12, 7, 0.8)
		board.CFrame = CFrame.new(base + Vector3.new(0, 11, 0))
			* CFrame.Angles(0, bearing + math.pi, 0)
		board.Anchored = true
		board.Color = Color3.fromRGB(24, 18, 34)
		board.Material = Enum.Material.SmoothPlastic
		board.Parent = model
		model.Parent = workspace

		local billboard = Style.billboard(board, {
			name = "Standings", width = 22, height = 12, distance = "prop", offset = 1,
		})
		boardLabel = Style.text(billboard, {
			name = "Rows", text = "TOP TUNG",
			color = Color3.fromRGB(255, 236, 180),
		})
	end

	function LeaderboardService.start()
		buildBoard()
		task.spawn(function()
			while true do
				task.wait(10)
				local ok, err = pcall(function()
					paintBoard()
					for _, player in ipairs(Players:GetPlayers()) do
						LeaderboardService.checkFrontier(player, os.time())
					end
				end)
				if not ok then
					warn("[Tung] leaderboard error: " .. tostring(err))
				end
			end
		end)
	end

	return LeaderboardService
end


__MODULES["MapBuilder"] = function()
	--[[
		MapBuilder.lua — generates the whole world at runtime.

		Layout: the plot belt at Config.beltRadius() with every plot rotated to
		face inward, three mob bands between the belt and the middle, and the old
		arena stage at the centre — the dais, the statue and the central wave live
		there, in the strongest band. Danger is walked toward (#89).
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Util = Req("Util")
	local TungModels = Req("TungModels")

	local Lighting = game:GetService("Lighting")

	local MapBuilder = {}

	local W = Config.World

	local PALETTE = {
		ground   = Color3.fromRGB(106, 168, 79),   -- grass
		pad      = Color3.fromRGB(199, 195, 185),  -- light concrete
		padEdge  = Color3.fromRGB(255, 176, 60),   -- warm marker stripe
		arena    = Color3.fromRGB(178, 172, 160),
		arenaLip = Color3.fromRGB(255, 140, 40),
		wood     = Color3.fromRGB(150, 103, 60),
	}

	local function newPart(parent, name, size, cf, color, material)
		local p = Instance.new("Part")
		p.Name = name
		p.Size = size
		p.CFrame = cf
		p.Color = color
		p.Material = material or Enum.Material.SmoothPlastic
		p.Anchored = true
		p.CanCollide = true
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Parent = parent
		return p
	end

	--- Stock Roblox daylight. Deliberately plain: bright, neutral and readable.
	function MapBuilder.applyLighting()
		-- Lighting.Technology is not script-writable at runtime; it is set in
		-- default.project.json instead. Guarded so a manual/paste-in install
		-- doesn't take the whole boot sequence down with it.
		pcall(function()
			Lighting.Technology = Enum.Technology.ShadowMap
		end)
		Lighting.Ambient = Color3.fromRGB(0, 0, 0)
		Lighting.OutdoorAmbient = Color3.fromRGB(128, 128, 128)
		Lighting.Brightness = 3
		Lighting.ClockTime = 14.5
		Lighting.GeographicLatitude = 41.733
		Lighting.ExposureCompensation = 0
		Lighting.EnvironmentDiffuseScale = 1
		Lighting.EnvironmentSpecularScale = 1
		Lighting.FogColor = Color3.fromRGB(192, 192, 192)
		Lighting.FogStart = 0
		Lighting.FogEnd = 100000
		Lighting.GlobalShadows = true

		-- strip anything a previous (darker) build left behind, so re-running
		-- doesn't stack post-effects
		for _, existing in ipairs(Lighting:GetChildren()) do
			if existing:IsA("Atmosphere") or existing:IsA("PostEffect") then
				existing:Destroy()
			end
		end
	end

	--- Returns the CFrame for plot `index` (1-based). +Z of the CFrame points
	--- at the arena, matching the plot-local layout in Config.
	function MapBuilder.plotCFrame(index: number): CFrame
		local placement = W.PlotPlacements[index] or W.PlotPlacements[1]
		local angle, radius = placement.angle, placement.radius
		-- y = PlotSurfaceY, so plot-local y=0 is the top of the pad and sits
		-- clear of the ground plane instead of z-fighting with it
		local position = Vector3.new(math.sin(angle) * radius, W.PlotSurfaceY, math.cos(angle) * radius)
		-- look at the origin, then flip so plot-local +Z faces the arena
		local look = CFrame.lookAt(position, Vector3.new(0, 0, 0))
		return look * CFrame.Angles(0, math.pi, 0)
	end

	-- MVP arena: a floor, a low plinth, the statue and a sign. The torches, the
	-- 32-segment glowing rim and the 72-tile ring path were all decoration with
	-- no gameplay attached, so they are gone.
	local function buildArena(parent: Instance)
		local arena = Instance.new("Model")
		arena.Name = "Arena"
		arena.Parent = parent

		local floorThickness = 3
		local floor = newPart(arena, "ArenaFloor", Vector3.new(floorThickness, W.ArenaRadius * 2, W.ArenaRadius * 2),
			CFrame.new(0, W.ArenaFloorTopY - floorThickness / 2, 0) * CFrame.Angles(0, 0, math.pi / 2),
			PALETTE.arena, Enum.Material.Pebble)
		floor.Shape = Enum.PartType.Cylinder

		-- single ring border instead of 32 separate segments
		local rim = newPart(arena, "Rim", Vector3.new(1.2, W.ArenaRadius * 2 + 6, W.ArenaRadius * 2 + 6),
			CFrame.new(0, W.ArenaFloorTopY - 0.4, 0) * CFrame.Angles(0, 0, math.pi / 2),
			PALETTE.arenaLip, Enum.Material.Neon)
		rim.Shape = Enum.PartType.Cylinder
		rim.CanCollide = false

		local daisHeight = 4
		local daisTopY = W.ArenaFloorTopY + daisHeight
		local dais = newPart(arena, "Dais", Vector3.new(daisHeight, W.DaisRadius * 2, W.DaisRadius * 2),
			CFrame.new(0, daisTopY - daisHeight / 2, 0) * CFrame.Angles(0, 0, math.pi / 2),
			PALETTE.pad, Enum.Material.Slate)
		dais.Shape = Enum.PartType.Cylinder

		-- The statue's feet are 2.85 * scale below its pivot (see TungModels), and
		-- the infinity variant carries its own 1.5x scale. Stand it ON the dais
		-- instead of guessing a height and burying its legs in the platform.
		local statueScale = 3.5
		local footDrop = 2.85 * statueScale * Config.Variants.infinity.scale
		local statue = TungModels.buildStatue("infinity", statueScale)
		statue.Name = "ArenaStatue"
		statue:PivotTo(CFrame.new(0, daisTopY + footDrop, 0))
		statue.Parent = arena

		-- WHERE THE RAID IS ANNOUNCED. The client hangs its own billboard here and
		-- writes the wave state into it; the server only stands the anchor up, so
		-- the countdown can keep ticking locally instead of costing a remote a
		-- second. Empty and unowned until a client claims it.
		local raidAnchor = newPart(arena, "RaidAnchor", Vector3.new(1, 1, 1),
			CFrame.new(0, Config.Style.RaidSignY, 0), PALETTE.pad)
		raidAnchor.Transparency = 1
		raidAnchor.CanCollide = false
		raidAnchor.CanQuery = false

		-- ...and the game's own name above it. This used to sit at 34, which is
		-- across the statue's face — it tops out around 35.6.
		local sign = newPart(arena, "TitleAnchor", Vector3.new(1, 1, 1),
			CFrame.new(0, Config.Style.ArenaTitleY, 0), PALETTE.pad)
		sign.Transparency = 1
		sign.CanCollide = false

		local billboard = Style.billboard(sign, {
			name = "Title", width = 56, height = Config.Style.ArenaTitleHeight, distance = "world",
		})
		Style.text(billboard, {
			name = "Title", size = UDim2.fromScale(1, 0.62),
			text = "TUNG TUNG TYCOON", color = Color3.fromRGB(255, 214, 90),
		})
		Style.text(billboard, {
			name = "Subtitle", weight = "body",
			size = UDim2.fromScale(1, 0.34), position = UDim2.fromScale(0, 0.62),
			text = "the middle pays best. pvp everywhere.", color = Color3.fromRGB(255, 255, 255),
		})

		return arena
	end

	local function buildSpawn(parent: Instance)
		local spawnPad = Instance.new("SpawnLocation")
		spawnPad.Name = "TungSpawn"
		spawnPad.Size = Vector3.new(36, 1.5, 24)
		-- Out by the plot belt, between plot 1 and plot 2, in the quiet strip the
		-- verifier keeps clear of the outermost band's reach. It used to sit in
		-- front of the dais — which is now the strongest mobs' home patch, and a
		-- fresh player spawning into a level-15 pack is a fresh player gone.
		local bearing = math.pi / math.max(Config.plotCountFor(), 1)
		spawnPad.CFrame = CFrame.new(
			math.sin(bearing) * W.SpawnRadius, W.GroundTopY + 0.75, math.cos(bearing) * W.SpawnRadius)
			* CFrame.Angles(0, bearing + math.pi, 0)
		spawnPad.Anchored = true
		spawnPad.CanCollide = true
		spawnPad.Color = Color3.fromRGB(150, 103, 60)
		spawnPad.Material = Enum.Material.WoodPlanks
		spawnPad.TopSurface = Enum.SurfaceType.Smooth
		spawnPad.Duration = 0
		spawnPad.Neutral = true
		spawnPad.Parent = parent
		return spawnPad
	end

	function MapBuilder.build(): Folder
		local existing = workspace:FindFirstChild("TungWorld")
		if existing then
			existing:Destroy()
		end

		-- clear the default baseplate if the place still has one
		local defaultBase = workspace:FindFirstChild("Baseplate")
		if defaultBase then
			defaultBase:Destroy()
		end

		local world = Instance.new("Folder")
		world.Name = "TungWorld"
		world.Parent = workspace

		local groundThickness = 12
		local ground = newPart(world, "Ground", Vector3.new(W.BaseplateSize, groundThickness, W.BaseplateSize),
			CFrame.new(0, W.GroundTopY - groundThickness / 2, 0), PALETTE.ground, Enum.Material.Grass)
		ground.Anchored = true

		buildArena(world)
		buildSpawn(world)

		local plots = Instance.new("Folder")
		plots.Name = "Plots"
		plots.Parent = world

		MapBuilder.applyLighting()

		return world
	end

	--- Builds the flat pad + signage for one plot. The tycoon machinery is added
	--- later by Tycoon.lua; this is just the real estate.
	function MapBuilder.buildPlotPad(parent: Instance, index: number): (Model, CFrame)
		local cf = MapBuilder.plotCFrame(index)

		local model = Instance.new("Model")
		model.Name = "Plot" .. index
		model.Parent = parent

		local pad = newPart(model, "Pad", W.PlotSize, cf * CFrame.new(0, -W.PlotSize.Y / 2, 0), PALETTE.pad, Enum.Material.Concrete)
		pad:SetAttribute("PlotIndex", index)

		-- glowing border. The pad is no longer square, so the front/back strips key
		-- off half the DEPTH and the side strips off half the width; using one
		-- `half` for both left the front and back edges floating inside the pad.
		local half = W.PlotSize.X / 2
		local halfZ = W.PlotSize.Z / 2
		local edges = {
			{ Vector3.new(W.PlotSize.X, 1, 2), CFrame.new(0, 0.2, halfZ) },
			{ Vector3.new(W.PlotSize.X, 1, 2), CFrame.new(0, 0.2, -halfZ) },
			{ Vector3.new(2, 1, W.PlotSize.Z), CFrame.new(half, 0.2, 0) },
			{ Vector3.new(2, 1, W.PlotSize.Z), CFrame.new(-half, 0.2, 0) },
		}
		for i, edge in ipairs(edges) do
			local e = newPart(model, "Edge" .. i, edge[1], cf * edge[2], PALETTE.padEdge, Enum.Material.Neon)
			e.CanCollide = false
		end

		-- Claim totem, parked in the front-RIGHT corner. It used to stand at x = 0,
		-- directly on top of the pad you are meant to step on, and then in the
		-- front-left corner, which is where Tycoon builds the vault — the two
		-- models were interpenetrating on every plot.
		local totemCF = cf * CFrame.new(half - 12, 6, halfZ - 8)
		local totem = newPart(model, "Totem", Vector3.new(4, 12, 4), totemCF, Color3.fromRGB(70, 52, 40), Enum.Material.Wood)
		totem:SetAttribute("PlotIndex", index)

		local billboard = Style.billboard(totem, {
			name = "Sign", width = 26, height = 9, distance = "plot", offset = 9,
		})

		local frame = Instance.new("Frame")
		frame.Size = UDim2.fromScale(1, 1)
		frame.BackgroundColor3 = Color3.fromRGB(24, 18, 34)
		frame.BackgroundTransparency = 0.25
		frame.BorderSizePixel = 0
		frame.Parent = billboard
		Util.roundedFrame(frame, 12)

		local stroke = Instance.new("UIStroke")
		stroke.Color = PALETTE.padEdge
		stroke.Thickness = 3
		stroke.Parent = frame

		Style.text(frame, {
			name = "Owner",
			size = UDim2.fromScale(0.92, 0.9), position = UDim2.fromScale(0.04, 0.05),
			text = "UNCLAIMED PLOT " .. index .. "\nstep on the pad to claim",
			color = Color3.fromRGB(255, 236, 180),
		})

		return model, cf
	end

	return MapBuilder
end


__MODULES["MovementService"] = function()
	--[[
		MovementService.lua — sprint and dash (#101).

		SPRINT IS SERVER-WRITTEN WalkSpeed. A client cannot replicate its own
		WalkSpeed, so the toggle comes up a remote and the server writes the
		humanoid — clamped to exactly two states, walking and Config.Movement's
		SprintSpeed, so the remote carries one bit of intent and nothing a client
		sends can pick a number.

		THE DASH IS CLIENT PHYSICS, SERVER CADENCE. The client owns its
		character's assembly, so the impulse happens there for feel; what the
		server owns is the COOLDOWN — RequestDash answers approved or not, and
		MovementService.dashReady is the ledger any combat system reads when it
		needs to trust dash cadence (#94's escape arithmetic will).

		Sprint interacts with two existing writers of player WalkSpeed:
		CombatService.onCharacter (the baseline, on spawn) and UpgradeService
		(prototype, flag off). Respawn resets to walking here too — a sprint held
		across death would leave the corpse's toggle on the fresh humanoid.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Net = Req("Net")

	local Players = game:GetService("Players")

	local MovementService = {}

	local M = Config.Movement

	-- per-player: { sprinting = boolean, lastDash = seconds }
	local state: { [Player]: { sprinting: boolean, lastDash: number } } = {}

	local function stateFor(player: Player)
		local s = state[player]
		if not s then
			s = { sprinting = false, lastDash = -math.huge }
			state[player] = s
		end
		return s
	end

	local function humanoidOf(player: Player): Humanoid?
		local character = player.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		if humanoid and humanoid.Health > 0 then
			return humanoid
		end
		return nil
	end

	--- The one WalkSpeed decision: walking or sprinting, nothing a client picks.
	function MovementService.setSprint(player: Player, sprinting: boolean)
		local s = stateFor(player)
		s.sprinting = sprinting == true
		local humanoid = humanoidOf(player)
		if humanoid then
			humanoid.WalkSpeed = s.sprinting and M.SprintSpeed or Config.Combat.WalkSpeed
		end
	end

	--- Whether a dash is off cooldown, and the stamp if it is taken. `now` is a
	--- parameter so the spec can drive the clock; callers pass os.clock().
	function MovementService.tryDash(player: Player, now: number): boolean
		local s = stateFor(player)
		if now - s.lastDash < M.DashCooldown then
			return false
		end
		s.lastDash = now
		return true
	end

	--- Seconds until this player may dash again — #94's escape arithmetic reads
	--- cadence from here rather than trusting the client's word.
	function MovementService.dashReady(player: Player, now: number): boolean
		return now - stateFor(player).lastDash >= M.DashCooldown
	end

	function MovementService.start()
		local setSprint = Net.event("SetSprint")
		local requestDash = Net.event("RequestDash")

		setSprint.OnServerEvent:Connect(function(player, sprinting)
			MovementService.setSprint(player, sprinting == true)
		end)

		requestDash.OnServerEvent:Connect(function(player)
			if MovementService.tryDash(player, os.clock()) then
				-- the approval is the client's cue to fire the impulse; a denied
				-- request answers nothing and the client's local cooldown bar is
				-- what tells the player why
				requestDash:FireClient(player)
			end
		end)

		Players.PlayerRemoving:Connect(function(player)
			state[player] = nil
		end)
		Players.PlayerAdded:Connect(function(player)
			player.CharacterAdded:Connect(function()
				-- a sprint held across death must not ride onto the fresh
				-- humanoid; CombatService.onCharacter writes the walking baseline
				-- and this keeps the ledger agreeing with it
				stateFor(player).sprinting = false
			end)
		end)
	end

	return MovementService
end


__MODULES["NPCService"] = function()
	--[[
		NPCService.lua — every Sahur in the world.

		design:D-04, via #89. Three populations share one AI, one tick loop and
		one stat curve, differing only in where they live and what minted them:

		  * BAND ROAMERS — the open world's standing danger. Three annuli between
		    the plot belt and the centre, strongest in the middle, each kept at
		    its population by a slow census. Kill one, it pays its level.
		  * THE CENTRAL WAVE — the one shared event: the old wave machine, at the
		    dais, boss and pot included. Its number may climb with the server's
		    lifetime because nobody stands in the core by accident.
		  * PLOT SIEGES — each plot's own small raid, at the plot's OWN level,
		    spawned at its gate. They press the structures (#124's mobs, finally
		    arrived) and stream in when the gate breaks.

		All NPCs are ticked from one loop rather than a thread each.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Fx = Req("Fx")
	local Net = Req("Net")
	local TungModels = Req("TungModels")
	local Economy = Req("Economy")
	local DataService = Req("DataService")
	local CombatService = Req("CombatService")
	-- The GateService arrangement: walk Tycoon.all() on a beat. Tycoon does not
	-- require NPCService, so the arrow is one-way.
	local Tycoon = Req("Tycoon")

	local Players = game:GetService("Players")
	local Debris = game:GetService("Debris")

	local NPCService = {}

	local waveRemote = Net.event("WaveState")
	local notifyRemote = Net.event("Notify")

	local WV = Config.Waves
	local MB = Config.Mobs
	local PW = Config.PlotWave
	local SH = Config.Structure.Health

	-- Raider swing poses, in body space: arm overhead, then swung through to just
	-- past the target. See SwingAnim for why these are expressed this way.
	local TOP_PITCH = 158
	local CONTACT_PITCH = 22

	local active: { [Model]: any } = {}
	local folder: Folder

	--- THE SCHEDULE.
	---
	--- `waveNumber` is only ever read to mint a record. Everything a wave needs to
	--- know about itself lives on the record, and every raider holds a reference to
	--- the one that spawned it — which is what makes `remaining` per-wave instead
	--- of a global count of every living raider on the map.
	---
	--- phase ∈ idle | resting | warning | spawning | active | clear
	---
	--- `spawning` is a separate phase from `active` on purpose: it makes the clear
	--- test `spawnFinished and alive <= 0`, so the moment mid-drip when the count
	--- legitimately touches zero is structurally unreachable rather than guarded
	--- against.
	local waveNumber = 0
	local phase = "idle"
	local phaseUntil = 0
	local liveWave: any = nil
	local emptySince: number? = nil
	local nextBroadcast = 0

	-- raider flavour escalates with the wave number
	local WAVE_VARIANTS = { "classic", "oak", "ash", "crimson", "neon", "void", "eclipse", "galaxy", "infinity" }

	local function variantForWave(wave: number, boss: boolean): string
		local index = math.clamp(math.floor((wave - 1) / 2) + 1, 1, #WAVE_VARIANTS)
		if boss then
			index = math.clamp(index + 2, 1, #WAVE_VARIANTS)
		end
		return WAVE_VARIANTS[index]
	end

	--- The packet describing where the raid currently is. Built from the live
	--- record rather than passed around, so there is one description of the truth
	--- and a late joiner can be handed exactly what everyone else last saw.
	local function wavePacket()
		local seconds = math.max(0, math.ceil(phaseUntil - os.clock()))
		if phase == "idle" then
			return { phase = "idle" }
		elseif phase == "resting" then
			return { phase = "resting", wave = waveNumber + 1, seconds = seconds }
		end
		local w = liveWave
		if not w then
			return { phase = "idle" }
		end
		-- THE SHARED HEALTH BAR RIDES THIS PACKET. No new remote: the boss's health
		-- is part of where the raid currently is, so it belongs in the one
		-- description of that, and it reaches late joiners through pushTo for free.
		--
		-- Read off the record rather than by scanning `active`, and nil'd when the
		-- boss dies — otherwise the packet would report a bar sitting at 0% for the
		-- rest of the wave.
		local bossEntry = w.bossEntry
		local bossHumanoid = bossEntry and bossEntry.humanoid
		return {
			phase = phase,
			wave = w.number,
			boss = w.boss,
			remaining = w.alive,
			total = w.expected,
			forced = w.forced,
			seconds = (phase == "warning" or phase == "clear") and seconds or nil,
			bossHp = bossHumanoid and math.max(0, bossHumanoid.Health) or nil,
			bossMaxHp = bossEntry and bossEntry.maxHealth or nil,
			-- How many players the fight was scaled for, so the sign can say so.
			-- Sampled once at beginWave; see the note there.
			bossScale = bossEntry and w.players or nil,
		}
	end

	local function broadcast(payload)
		waveRemote:FireAllClients(payload or wavePacket())
	end

	-- ─────────────────────────────────────────────────────────────────────────────

	--- ONE snapshot of every live player, rebuilt at most every SnapshotInterval
	--- and read by every raider.
	---
	--- This used to be a scan per raider per repath, at four instance reads per
	--- player: 26 raiders x 10 players x ~1.7 Hz was about 1,700 property reads a
	--- second, and the tighter chase repath below would have made that worse
	--- rather than better. Rebuilding once a frame-ish makes it flat at ~400
	--- regardless of how many raiders are alive, and turns the per-raider work
	--- into float maths over a ten-entry array.
	---
	--- It is also the one place that decides what counts as a target, which is
	--- exactly the seam the `decoy` utility prototype needs — see the TODO in
	--- UpgradeService.
	local snapshot: { any } = {}
	local snapshotAt = 0

	local function refreshSnapshot(now: number)
		if now < snapshotAt then
			return
		end
		snapshotAt = now + WV.SnapshotInterval
		table.clear(snapshot)
		for _, player in ipairs(Players:GetPlayers()) do
			local character = player.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if humanoid and root and humanoid.Health > 0 then
				table.insert(snapshot, {
					player = player,
					character = character,
					root = root,
					position = root.Position,
					-- Recounted from scratch each rebuild by the tick below, so a
					-- raider that died or de-aggroed frees its slot without anyone
					-- having to remember to decrement anything.
					chasers = 0,
				})
			end
		end
	end

	--- The snapshot row for a character, or nil. Used to find the chaser slot a
	--- committed raider belongs to.
	local function snapshotFor(character: Model?)
		if not character then
			return nil
		end
		for _, entry in ipairs(snapshot) do
			if entry.character == character then
				return entry
			end
		end
		return nil
	end

	--- Counts, per player, how many raiders are currently chasing them. Rebuilt
	--- rather than maintained incrementally: a decrement that has to happen in
	--- four different places is a decrement that eventually does not.
	local function countChasers()
		for _, slot in ipairs(snapshot) do
			slot.chasers = 0
		end
		for _, entry in pairs(active) do
			if entry.ai == "chase" and not entry.dead then
				local slot = snapshotFor(entry.target)
				if slot then
					slot.chasers += 1
				end
			end
		end
	end

	--- Nearest live player to `position` within `maxDistance`, from the snapshot.
	--- Squared distances: nothing here needs the actual magnitude.
	--- The nearest live player's snapshot row within `maxDistance`, or nil. The row
	--- rather than the character, because the caller needs its chaser count too.
	--- Squared distances: nothing here needs the actual magnitude.
	local function nearestSnapshotEntry(position: Vector3, maxDistance: number)
		local best, bestD2 = nil, maxDistance * maxDistance
		for _, entry in ipairs(snapshot) do
			local offset = entry.position - position
			local d2 = offset.X * offset.X + offset.Y * offset.Y + offset.Z * offset.Z
			if d2 < bestD2 then
				best, bestD2 = entry, d2
			end
		end
		return best
	end

	--- Flat XZ distance. Every AI radius here is a ground distance — a raider on a
	--- ramp is not further away for being higher up.
	local function flatDistance(a: Vector3, b: Vector3): number
		local dx, dz = a.X - b.X, a.Z - b.Z
		return math.sqrt(dx * dx + dz * dz)
	end

	--- A point inside a disc of `radius` around `centre`. sqrt() on the random so
	--- points spread evenly over the area instead of clustering at the middle.
	local function pointInDisc(centre: Vector3, radius: number): Vector3
		local angle = math.random() * math.pi * 2
		local r = radius * math.sqrt(math.random())
		return Vector3.new(centre.X + math.sin(angle) * r, centre.Y, centre.Z + math.cos(angle) * r)
	end

	local function killReward(wave: number, boss: boolean): number
		local reward = WV.RewardBase * (WV.RewardGrowth ^ (wave - 1))
		if boss then
			reward *= WV.BossHealthMultiplier
		end
		return math.floor(reward)
	end

	--- THE DAMAGE LEDGER. Registered on CombatService at boot, which is the only
	--- TakeDamage call in the repo, so this sees every hit any player lands on
	--- anything — and cares about exactly one of them.
	---
	--- `applied` is the health that actually came off, not the damage that was
	--- asked for. See the note at the call site.
	local function onDamageDealt(victim: Model, attacker: Player, applied: number)
		if applied <= 0 then
			return
		end
		local entry = active[victim]
		-- Ordinary raiders keep their creator tag and nothing else; only a boss
		-- carries a ledger.
		if not entry or entry.dead or not entry.contrib then
			return
		end
		entry.contrib[attacker] = (entry.contrib[attacker] or 0) + applied
		entry.contribTotal += applied
		-- The health bar rides the existing 2 Hz coalescer rather than a remote per
		-- swing. Twelve people hitting a boss is a lot of swings.
		local record = entry.waveRecord
		if record == liveWave then
			record.dirty = true
		end
	end

	--- SPLITS THE BOSS POT, and is the whole reason any of this exists.
	---
	--- `fraction` is how much of the pot the fight earned: 1 on a kill, and
	--- contribTotal/maxHealth when the wave timed out with the boss still standing.
	--- Idempotent through `entry.paid`, because the timeout path deliberately kills
	--- its own survivors and would otherwise pay twice.
	---
	--- profile.kills goes to the TOP CONTRIBUTOR ONLY. Crediting everyone would
	--- inflate the KO leaderboard by twelve for one boss.
	local function payBoss(entry, fraction: number, pivot: Vector3?, escaped: boolean?)
		if entry.paid then
			return
		end
		entry.paid = true

		local record = entry.waveRecord
		local pot = killReward(entry.wave, true)
			* (record and record.rewardFactor or 1)
			* math.clamp(fraction, 0, 1)
		if pot <= 0 then
			return
		end

		-- WHO GETS PAID. A damage floor, so a player who landed one hit on their way
		-- past does not dilute the even split twelve ways; and still present, because
		-- Economy.add on a departed player writes to a profile nobody will save.
		local minDamage = WV.BossMinDamageFrac * entry.maxHealth
		local eligible, eligibleTotal = {}, 0
		local top, topDamage = nil, 0
		for player, damage in pairs(entry.contrib) do
			if damage >= minDamage and player.Parent then
				table.insert(eligible, { player = player, damage = damage })
				eligibleTotal += damage
				if damage > topDamage then
					top, topDamage = player, damage
				end
			end
		end
		if #eligible == 0 then
			return
		end

		for _, who in ipairs(eligible) do
			local share = Config.bossShare(who.damage, eligibleTotal, #eligible, pot)
			local gained = Economy.add(who.player, share, true)
			if who.player == top then
				local profile = DataService.get(who.player)
				if profile then
					profile.kills += 1
				end
			end
			Economy.push(who.player)
			-- The personal number is better as a payout than as a HUD element: it
			-- arrives once, in the place every other reward arrives.
			Economy.notify(who.player, {
				kind = "boss",
				title = "YOUR CUT",
				body = ("%s  •  %d%% of the boss"):format(
					Util.abbreviate(gained),
					math.floor((who.damage / entry.maxHealth) * 100 + 0.5)),
			})
		end

		if pivot then
			Fx.floatingText(pivot + Vector3.new(0, 8, 0), "+" .. Util.abbreviate(pot),
				Color3.fromRGB(255, 205, 90), workspace)
		end

		notifyRemote:FireAllClients({
			kind = "boss",
			title = escaped and "BOSS ESCAPED" or "BOSS DOWN",
			body = ("Wave %d. %s led with %d%%. %d player%s paid out."):format(
				entry.wave,
				top and top.DisplayName or "nobody",
				math.floor((topDamage / entry.maxHealth) * 100 + 0.5),
				#eligible, #eligible == 1 and "" or "s"),
		})
	end

	local function onRaiderDied(npc: Model, entry)
		if entry.dead then
			return
		end
		entry.dead = true
		-- Decrement THIS raider's own wave. A straggler from wave N therefore
		-- decrements wave N, and because that record is not the live one it emits
		-- nothing at all — which is what stops leftovers being counted against,
		-- and labelled with, the wave that came after them.
		local record = entry.waveRecord
		if record then
			record.alive = math.max(0, record.alive - 1)
		end

		local humanoid = npc:FindFirstChildOfClass("Humanoid")
		local tag = humanoid and humanoid:FindFirstChild("creator") :: ObjectValue?
		local killer = tag and tag.Value

		local pivot = npc:GetPivot().Position
		local variant = Config.Variants[npc:GetAttribute("Variant") or "classic"] or Config.Variants.classic
		Fx.burst(pivot, variant.wood, entry.boss and 40 or 18, workspace)

		if entry.contrib then
			-- A BOSS IS NOT PAID TO WHOEVER SWUNG LAST. It is the one fight in this
			-- game that takes more than one person, so the pot is split across
			-- everyone who did real damage to it — see payBoss.
			payBoss(entry, 1, pivot, false)
			if record then
				record.bossEntry = nil
			end
		elseif killer and killer:IsA("Player") and killer.Parent then
			local reward = killReward(entry.wave, entry.boss)
			local gained = Economy.add(killer, reward, true)
			local profile = DataService.get(killer)
			if profile then
				profile.kills += 1
			end
			Economy.push(killer)
			Fx.floatingText(pivot + Vector3.new(0, 6, 0), "+" .. Util.abbreviate(gained), Color3.fromRGB(255, 205, 90), workspace)
		end

		-- flop over, then clean up
		for _, part in ipairs(npc:GetDescendants()) do
			if part:IsA("Motor6D") then
				part.Enabled = false
			end
		end
		Debris:AddItem(npc, 4)
		active[npc] = nil

		-- No FireAllClients here. This used to send one packet per death — up to 27
		-- a wave, and a whole burst on a single frame when an AoE lands. Mark the
		-- record dirty instead and let the tick flush at most every
		-- BroadcastInterval; the driver sends phase changes immediately, so the
		-- kill that ENDS a wave is still instant.
		if record == liveWave then
			record.dirty = true
		end
	end

	--- mechanism: everything below the stat arithmetic, shared by all three
	--- populations.
	--- `opts`:
	---   level      — feeds the growth curves; the central wave passes its number
	---   boss       — central wave only
	---   position   — where the body lands
	---   home       — the patch it returns to; the leash measures from here
	---   leash      — chase tether
	---   record     — the schedule record whose alive/spawned it moves (optional;
	---                roamers have none, and onRaiderDied already guards for it)
	---   siege      — { tycoon = ... } for a plot raider; its objective is
	---                re-derived live as things break
	---   band       — band index, for the roamer census
	---   despawnAt  — absolute; roamers pass math.huge
	---   index/count — approach-ring slot spread (defaults spread randomly)
	---   healthScale/walkScale — the tower's daily modifier (#146); bounded by
	---                the verifier against the sprint line
	local function mintNPC(opts)
		local level = opts.level
		local boss = opts.boss == true
		local variantName = variantForWave(level, boss)
		local health = WV.BaseHealth * (WV.HealthGrowth ^ (level - 1)) * (boss and WV.BossHealthMultiplier or 1)
			* (opts.healthScale or 1)
		if boss then
			-- Scaled to the headcount the wave was MINTED with, never to the live
			-- one. See beginWave: re-reading it here would move a bar twelve
			-- people are watching every time somebody logged off.
			health *= (opts.record and opts.record.healthFactor or 1)
		end
		-- The cap is absolute. It used to be scaled by the boss multiplier along
		-- with the damage, which meant the ceiling written to stop a raider two-
		-- shotting a 100 HP player let a late boss hit for 61.
		local damage = math.min(
			WV.BaseDamage * (WV.DamageGrowth ^ (level - 1)) * (boss and WV.BossDamageMultiplier or 1),
			boss and WV.MaxBossDamage or WV.MaxDamage)

		local npc = TungModels.buildNPC(variantName, {
			scale = boss and WV.BossBodyScale or (0.9 + math.random() * 0.35),
			health = health,
			walkSpeed = (WV.WalkSpeed + (boss and -2 or math.random() * 4)) * (opts.walkScale or 1),
			displayName = boss and ("SAHUR BOSS  •  wave " .. level) or "Tung Tung Tung Sahur",
			boss = boss,
		})
		npc:PivotTo(CFrame.new(opts.position) * CFrame.Angles(0, math.random() * math.pi * 2, 0))
		npc.Parent = folder

		local humanoid = npc:FindFirstChildOfClass("Humanoid") :: Humanoid
		local torso = npc:FindFirstChild("Torso")
		-- The VISIBLE arm, not the R6 rig's. Every rig part is Transparency = 1
		-- (the rig exists so Humanoid/MoveTo/damage work); the guy you actually see
		-- is the Visual model, and TungArm is its one articulated joint.
		local visual = npc:FindFirstChild("Visual")
		local core = visual and visual.PrimaryPart
		local arm = core and core:FindFirstChild("TungArm")
		local record = opts.record
		local count = opts.count or 8
		local entry = {
			wave = level,
			waveRecord = record,
			despawnAt = opts.despawnAt,
			boss = boss,
			damage = damage,
			siege = opts.siege,
			band = opts.band,
			-- AI state. NOT `entry.phase` — that name is already the waddle's sine
			-- phase a few lines down, and reusing it would desync the walk cycle
			-- every time the raider changed its mind.
			ai = "wander",
			home = opts.home,
			leash = opts.leash,
			wanderUntil = 0,
			nextAggroCheck = 0,
			-- Where on the approach ring this raider stands. Fixed per raider so a
			-- pack spreads deterministically instead of jostling for the same spot.
			slotAngle = ((opts.index or math.random(count)) / math.max(count, 1)) * math.pi * 2 + math.random() * 0.5,
			-- How long it must hold you inside AggroRadius before committing.
			-- Random per raider, so a pack that all crosses the threshold on one
			-- tick still commits raggedly over ~2 seconds.
			aggroDelay = math.random() * WV.AggroStagger,
			aggroSince = nil,
			nextAttack = 0,
			nextRepath = 0,
			sway = torso and torso:FindFirstChild("TungSway"),
			phase = math.random() * math.pi * 2,
			spawnedAt = os.clock(),
			dead = false,
			-- attack telegraph. Raiders are server-owned, so unlike player swings
			-- these Motor6D writes replicate on their own and no remote is needed.
			arm = arm,
			armBase = arm and arm.C0,
			walkSpeed = humanoid.WalkSpeed,
			windUp = WV.AttackWindUp * (boss and WV.BossWindUpScale or 1),
			swingAt = nil,
			rootedUntil = 0,
		}
		-- The waddle used to rewrite the sway joint's C0 from a hardcoded 0.7, but
		-- buildNPC sets it to 0.7 * scale — so a 2.1x boss dropped a stud and a half
		-- into its own legs on the first frame it moved.
		if entry.sway then
			entry.swayBase = entry.sway.C0
		end

		active[npc] = entry
		if record then
			record.alive += 1
			record.spawned += 1
		end

		humanoid.Died:Connect(function()
			onRaiderDied(npc, entry)
		end)

		if boss then
			-- THE LEDGER, and the record's handle on it. `contrib` being non-nil is
			-- what marks an entry as carrying one at all, so nothing else in the
			-- tick has to ask whether a raider is a boss.
			--
			-- `maxHealth` is captured rather than read back off the humanoid because
			-- both the eligibility floor and the escaped-boss pro-rata are fractions
			-- of it, and a dead humanoid reports a MaxHealth nobody promised.
			entry.contrib = {}
			entry.contribTotal = 0
			entry.maxHealth = health
			entry.paid = false
			entry.humanoid = humanoid
			if record then
				record.bossEntry = entry
			end

			local _, root = Util.getRig(npc)
			if root then
				local light = Instance.new("PointLight")
				light.Color = Color3.fromRGB(255, 90, 60)
				light.Range = 40
				light.Brightness = 3
				light.Parent = root
			end
		end
		return entry
	end

	--- One central-wave raider. Land in CLUSTERS, not on one evenly-divided ring:
	--- a ring of 26 arrives as a wall closing from every direction at once; six
	--- clusters of four arrive as a raid. `groupAngle` is chosen per group by the
	--- caller and jittered per member here.
	---
	--- THE BOSS DOES NOT GET A BEARING AT ALL. It lands on a fixed spot just off
	--- the dais, every time. A shared objective that appears somewhere different
	--- every wave is one twelve people spend the first thirty seconds looking
	--- for. BossSpawnRadius clears the 26-diameter dais and the statue standing
	--- on it, which the verifier asserts.
	local function spawnRaider(record, index: number, count: number, boss: boolean, groupAngle: number?)
		local position
		if boss then
			position = Vector3.new(0, 12, WV.BossSpawnRadius)
		else
			local angle = (groupAngle or 0) + (math.random() - 0.5) * 2 * WV.GroupArc
			local radius = Config.World.ArenaRadius - 18
			position = Vector3.new(math.sin(angle) * radius, 8, math.cos(angle) * radius)
		end
		mintNPC({
			level = record.number,
			boss = boss,
			position = position,
			-- The patch this raider calls home. Scattered around the CENTRE rather
			-- than sitting at the spawn point: raiders land on the rim and then
			-- walk inward to mill about, which is what makes them read as
			-- gathering in the middle rather than as a ring closing in. The boss
			-- keeps to the dais it lands on, and is leashed tighter than a raider
			-- (BossLeashRadius), so the fight everyone is walking towards stays
			-- where they last saw it.
			home = pointInDisc(Vector3.zero, boss and WV.BossSpawnRadius or WV.HomeSpread),
			leash = boss and WV.BossLeashRadius or WV.LeashRadius,
			record = record,
			index = index,
			count = count,
			-- Strictly later than the wave's own deadline, so the wave-level
			-- timeout always fires first and this only ever catches a raider whose
			-- record was somehow lost.
			despawnAt = os.clock() + WV.MaxWaveTime + WV.StragglerGrace,
		})
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- band roamers (#89): the world's standing danger, kept at population by a
	-- slow census. No records, no schedule — a roamer lives until killed and its
	-- band refills one body at a time.
	-- ─────────────────────────────────────────────────────────────────────────────

	local nextRoamerSpawn: { [number]: number } = {}

	--- An area-uniform point in the band's annulus, clear of the edges by
	--- HomeMargin so a roamer's wander never straddles a boundary. The spawn
	--- pad needs no rejection sampling: it sits OUTSIDE every band, and the
	--- verifier holds the clearance.
	local function bandHome(band): Vector3
		local angle = math.random() * math.pi * 2
		local inner = band.inner + MB.HomeMargin
		local outer = math.max(band.outer - MB.HomeMargin, inner + 1)
		local r = math.sqrt(inner * inner + math.random() * (outer * outer - inner * inner))
		return Vector3.new(math.sin(angle) * r, 0, math.cos(angle) * r)
	end

	local function maintainRoamers(now: number)
		if not MB.Enabled or #Players:GetPlayers() == 0 then
			return
		end
		local alive = {}
		for _, entry in pairs(active) do
			if entry.band and not entry.dead then
				alive[entry.band] = (alive[entry.band] or 0) + 1
			end
		end
		for index, band in ipairs(MB.Bands) do
			if (alive[index] or 0) < band.count and now >= (nextRoamerSpawn[index] or 0) then
				nextRoamerSpawn[index] = now + MB.RespawnSeconds
				local home = bandHome(band)
				mintNPC({
					level = band.level,
					position = home + Vector3.new(0, 8, 0),
					home = home,
					leash = WV.LeashRadius,
					band = index,
					despawnAt = math.huge,
				})
			end
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- plot sieges (#89): each plot's own raid, at the plot's own level. The
	-- schedule is per-plot state on this table; the raiders are ordinary entries
	-- with `siege = { tycoon }`, and the tick presses whatever objective
	-- siegeObjective currently answers with.
	-- ─────────────────────────────────────────────────────────────────────────────

	local plotSieges: { [any]: any } = {}

	--- What a plot raider is here to break, right now: the gate while one is
	--- owned and standing, the storage unit after (or instead, on a plot that
	--- never bought gates), nil when everything is down — then they just mill
	--- and menace. Position second, so a caller can ask "anything left?" cheaply.
	local function siegeObjective(tycoon): (string?, Vector3?)
		if tycoon.owned and tycoon.owned.gates and not tycoon:structureBroken("gate_gateway") then
			return "gate", tycoon.cf:PointToWorldSpace(
				Vector3.new(Config.Layout.GateCentre, 0, Config.World.PlotSize.Z / 2))
		end
		local base = tycoon.storageBase
		if base and base.Parent and tycoon:storageIntact() then
			return "storage", base.Position
		end
		return nil, nil
	end

	local function endSiege(tycoon, state)
		for npc, entry in pairs(active) do
			if entry.siege and entry.siege.tycoon == tycoon and not entry.dead then
				local humanoid = npc:FindFirstChildOfClass("Humanoid")
				if humanoid then
					humanoid.Health = 0
				end
			end
		end
		state.record = nil
	end

	local function stepPlotSieges(now: number)
		if not PW.Enabled then
			return
		end
		local concurrent = 0
		for _, state in pairs(plotSieges) do
			if state.phase == "warning" or state.phase == "active" then
				concurrent += 1
			end
		end
		-- drop state for plots whose tenancy ended, and kill their raiders with it
		for tycoon, state in pairs(plotSieges) do
			if not tycoon.owner then
				endSiege(tycoon, state)
				plotSieges[tycoon] = nil
			end
		end
		for _, tycoon in ipairs(Tycoon.all()) do
			local owner = tycoon.owner
			if owner then
				local state = plotSieges[tycoon]
				if not state then
					-- a fresh tenancy gets half a rest before its first raid, so
					-- claiming a plot is never answered with an instant siege
					state = { phase = "resting",
						phaseUntil = now + PW.RestSeconds / 2 + math.random() * PW.RestJitter }
					plotSieges[tycoon] = state
				end

				if state.phase == "resting" then
					-- #96: the siege is a GATED disclosure — a raid siren in the
					-- first minute is the overload the system exists to prevent.
					-- The high-water lives on the profile, so the gate and the
					-- interface cannot disagree.
					local profile = DataService.get(owner)
					local disclosed = profile and profile.disclosed and profile.disclosed.siege == true
					if disclosed and now >= state.phaseUntil and concurrent < PW.MaxConcurrent then
						concurrent += 1
						local counts = tycoon:landState()
						state.level = Config.plotWaveLevel(counts.left + counts.right,
							profile and profile.rebirths or 0)
						state.count = math.min(PW.BaseCount + math.floor(state.level / 3), PW.MaxCount)
						state.phase = "warning"
						state.phaseUntil = now + WV.WarningTime
						-- The siren. WarningTime plus the gate's asserted breach
						-- floor is the run-home promise — see the verifier.
						Economy.notify(owner, { kind = "wave", title = "RAID ON YOUR PLOT",
							body = ("%d Sahur at your gate in %d seconds."):format(state.count, WV.WarningTime) })
					end
				elseif state.phase == "warning" then
					if now >= state.phaseUntil then
						state.phase = "active"
						state.phaseUntil = now + PW.MaxSiegeSeconds
						state.record = { number = state.level, alive = 0, spawned = 0 }
						local halfZ = Config.World.PlotSize.Z / 2
						for i = 1, state.count do
							local outside = tycoon.cf:PointToWorldSpace(Vector3.new(
								Config.Layout.GateCentre + (math.random() - 0.5) * 24, 0, halfZ + 24 + math.random() * 10))
							mintNPC({
								level = state.level,
								position = outside + Vector3.new(0, 6, 0),
								home = outside,
								-- generous: the objective walks inward as things
								-- break, and the leash must not strand them at
								-- the gate they broke
								leash = Config.World.PlotSize.Z + 60,
								record = state.record,
								siege = { tycoon = tycoon },
								index = i,
								count = state.count,
								despawnAt = now + PW.MaxSiegeSeconds + WV.StragglerGrace,
							})
						end
					end
				elseif state.phase == "active" then
					-- GateSlots raiders press the structure; the rest mill and
					-- menace. Reassigned every step so a dead slot frees itself.
					local slots = 0
					for _, entry in pairs(active) do
						if entry.siege and entry.siege.tycoon == tycoon and not entry.dead then
							slots += 1
							entry.siegeSlot = slots <= PW.GateSlots
						end
					end
					if not state.record or state.record.alive <= 0 then
						state.phase = "resting"
						state.phaseUntil = now + PW.RestSeconds + math.random() * PW.RestJitter
						Economy.notify(owner, { kind = "wave", title = "RAID CLEARED",
							body = "Your plot held. tung tung." })
					elseif now >= state.phaseUntil then
						endSiege(tycoon, state)
						state.phase = "resting"
						state.phaseUntil = now + PW.RestSeconds + math.random() * PW.RestJitter
					end
				end
			end
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────

	local function tick(dt: number)
		local now = os.clock()
		refreshSnapshot(now)
		countChasers()
		for npc, entry in pairs(active) do
			if not npc.Parent or entry.dead then
				continue
			end
			local humanoid, root = Util.getRig(npc)
			if not humanoid or not root or humanoid.Health <= 0 then
				continue
			end

			-- waddle
			if entry.sway and entry.swayBase then
				entry.phase += dt * (6 + humanoid.WalkSpeed * 0.25)
				local lean = math.sin(entry.phase) * 0.18
				local bob = math.abs(math.cos(entry.phase)) * 0.22
				entry.sway.C0 = entry.swayBase * CFrame.new(0, bob, 0) * CFrame.Angles(0, 0, lean)
			end

			-- Raise the bat over the wind-up, hold at the top for an instant, then
			-- chop down through the hit. The shape matters more than the numbers:
			-- what makes a raider fair is that the arm is visibly UP before the
			-- damage lands, and that they are rooted while it is.
			if entry.arm and entry.armBase then
				-- Raise, hold, chop — and the chop has to finish BEFORE the damage
				-- lands, not after it. The whole point of a telegraph is that the
				-- bat is visibly on its way down when it connects.
				local pitch = 0
				if entry.swingAt then
					local w = 1 - math.clamp((entry.swingAt - now) / entry.windUp, 0, 1)
					if w < 0.55 then
						pitch = TOP_PITCH * (w / 0.55)                 -- raise
					elseif w < 0.72 then
						pitch = TOP_PITCH                              -- hold at the top
					else
						-- chop, arriving at the contact pose exactly on the hit
						local k = (w - 0.72) / 0.28
						pitch = TOP_PITCH + (CONTACT_PITCH - TOP_PITCH) * (k ^ 0.6)
					end
				elseif now < entry.rootedUntil then
					-- follow-through settling back to rest
					pitch = CONTACT_PITCH * math.clamp((entry.rootedUntil - now) / WV.AttackRecover, 0, 1)
				end
				-- The pitch is in BODY space; conjugating by the joint's own C0
				-- rotation converts it, so this reads the same way as the player
				-- swing poses in SwingAnim and doesn't depend on how the shoulder
				-- happens to be oriented. +X pitch raises the arm forward.
				local basis = entry.armBase.Rotation
				entry.arm.C0 = entry.armBase * (basis:Inverse() * CFrame.Angles(math.rad(pitch), 0, 0) * basis)
			end

			-- ── AI: wander / chase / return ──────────────────────────────────────
			--
			-- Evaluated only when the raider is free to move. The telegraph above
			-- runs regardless of state ON PURPOSE: gating it on "chase" would
			-- freeze a raider mid-swing with its bat overhead the instant it
			-- de-aggroed.
			if now >= entry.rootedUntil and not entry.swingAt then
				-- a plot raider's home rides its objective: the gate until it
				-- breaks, the storage after it, the plot's heart when everything
				-- is down — which is what makes a broken gate an OPEN gate
				if entry.siege then
					local _, objectivePosition = siegeObjective(entry.siege.tycoon)
					entry.home = objectivePosition
						or entry.siege.tycoon.cf:PointToWorldSpace(Vector3.zero)
				end
				local homeDistance = flatDistance(root.Position, entry.home)

				if entry.ai == "chase" then
					local target = entry.target
					local targetRootPart = target and target.Parent
						and target:FindFirstChild("HumanoidRootPart")
					local targetHumanoid = target and target.Parent
						and target:FindFirstChildOfClass("Humanoid")
					local lost = not targetRootPart
						or not targetHumanoid
						or targetHumanoid.Health <= 0
						or flatDistance(targetRootPart.Position, root.Position) > WV.DeAggroRadius
						or homeDistance > entry.leash

					if lost then
						entry.ai = "return"
						entry.target = nil
						entry.nextRepath = 0
					end
				elseif entry.ai == "return" then
					if homeDistance <= WV.HomeArrive then
						entry.ai = "wander"
						entry.wanderUntil = 0
					end
				end

				-- Only a raider that is NOT already committed goes looking, and a
				-- returning one may not bite again until it is most of the way
				-- home — otherwise a player parked on the leash line yo-yos it.
				if entry.ai ~= "chase" and now >= entry.nextAggroCheck then
					entry.nextAggroCheck = now + WV.AggroCheck
					local mayAggro = entry.ai == "wander"
						or homeDistance <= entry.leash * WV.ReAggroFrac
					local slot = mayAggro and nearestSnapshotEntry(root.Position, WV.AggroRadius) or nil
					-- Cap how many may engage one player. The overflow keeps
					-- milling and steps in as slots free, which reads as
					-- reinforcements rather than as a queue.
					if slot and slot.chasers >= WV.MaxChasers then
						slot = nil
					end
					if slot then
						-- ...and even then, hold the player for this raider's own
						-- delay first. A pack that all crosses the threshold on one
						-- tick still commits raggedly.
						entry.aggroSince = entry.aggroSince or now
						if now - entry.aggroSince >= entry.aggroDelay then
							entry.ai = "chase"
							entry.target = slot.character
							entry.nextRepath = 0
							slot.chasers += 1
						end
					else
						entry.aggroSince = nil
					end
				end

				local interval = (entry.ai == "chase" and WV.RepathChase)
					or (entry.ai == "return" and WV.RepathReturn)
					or WV.RepathWander

				if now >= entry.nextRepath then
					entry.nextRepath = now + interval

					if entry.ai == "chase" then
						local targetRootPart = entry.target and entry.target.Parent
							and entry.target:FindFirstChild("HumanoidRootPart")
						if targetRootPart then
							-- A point on a ring AROUND the target, not the target
							-- itself. Twenty-six raiders all pathing to one stud
							-- is what made a wave read as a single blob standing
							-- inside itself.
							--
							-- ApproachStandoff is UNDER AttackRange, so a raider
							-- parked on its slot is already in swing range: the
							-- ring costs no damage output. The orbit term is
							-- folded into the repath rather than animated per
							-- frame, which at 0.35s is smooth enough and costs two
							-- trig calls per chasing raider per repath.
							local slotAngle = entry.slotAngle + now * WV.OrbitSpeed
							humanoid:MoveTo(targetRootPart.Position + Vector3.new(
								math.sin(slotAngle) * WV.ApproachStandoff,
								0,
								math.cos(slotAngle) * WV.ApproachStandoff))
						end
					elseif entry.ai == "return" then
						humanoid:MoveTo(entry.home)
					else
						-- Drift around the home patch. The old idle target was a
						-- hardcoded +/-60 world-space box unrelated to the arena,
						-- so idling raiders wandered off it.
						if now >= entry.wanderUntil then
							entry.wanderUntil = now
								+ WV.WanderDwellMin
								+ math.random() * (WV.WanderDwellMax - WV.WanderDwellMin)
							entry.wanderTarget = pointInDisc(entry.home, WV.WanderRadius)
						end
						humanoid:MoveTo(entry.wanderTarget or entry.home)
					end

					-- unstick
					if entry.lastPosition and (root.Position - entry.lastPosition).Magnitude < 1.5 then
						humanoid.Jump = true
					end
					entry.lastPosition = root.Position
				end
			end

			-- Rooted while winding up and recovering. This is the window a player
			-- punishes: before, the raider closed and dealt damage on the same
			-- tick, so being hit was pure proximity and there was nothing to read.
			--
			-- Still written EVERY frame, and still hard-zeroed while rooted. The
			-- per-state scale MULTIPLIES the captured entry.walkSpeed rather than
			-- replacing it, so each raider keeps the jitter buildNPC gave it.
			-- (UpgradeService's freeze verb anchors the assembly specifically
			-- because this write exists every frame — see the note there.)
			local speedScale = 1
			if entry.ai == "wander" then
				speedScale = WV.WanderSpeedScale
			elseif entry.ai == "return" then
				speedScale = WV.ReturnSpeedScale
			end
			humanoid.WalkSpeed = (now < entry.rootedUntil) and 0 or (entry.walkSpeed * speedScale)

			local target = entry.target
			local targetRoot = target and target.Parent and target:FindFirstChild("HumanoidRootPart")
			local inRange = targetRoot
				and (targetRoot.Position - root.Position).Magnitude <= WV.AttackRange

			-- A SLOTTED plot raider with no player in reach presses the structure
			-- instead (#89/#124). Players always outrank masonry: a defender who
			-- steps into range pulls the next swing onto themselves.
			local objectivePosition
			if entry.siege and entry.siegeSlot and not inRange then
				local _, position = siegeObjective(entry.siege.tycoon)
				if position and flatDistance(position, root.Position) <= WV.AttackRange + 6 then
					objectivePosition = position
				end
			end

			if entry.swingAt and now >= entry.swingAt then
				entry.swingAt = nil
				if entry.swingStructure then
					entry.swingStructure = nil
					-- resolved FRESH: the gate this swing wound up on may have
					-- broken under a packmate's bat mid-telegraph, and the hit
					-- has to land on whatever actually still stands
					local kind, position = siegeObjective(entry.siege.tycoon)
					if position and flatDistance(position, root.Position) <= WV.AttackRange + 6 then
						local tycoon = entry.siege.tycoon
						if kind == "gate" then
							tycoon:damageStructure("gate_gateway", entry.damage * SH.MobDamageScale)
						else
							tycoon:damageStorage(entry.damage * SH.MobDamageScale, nil)
						end
						Fx.impact(root, 0.85)
					end
				elseif inRange then
					-- The hit only lands if the target is STILL in range: walking
					-- out of a telegraphed swing has to actually work or the
					-- telegraph is a lie.
					CombatService.npcAttack(npc, target, entry.damage)
					Fx.impact(root, 0.85)

					local victim = Players:GetPlayerFromCharacter(target)
					if victim then
						local stolen = Economy.steal(victim, WV.StealPerHit)
						if stolen > 0 then
							Fx.floatingText(targetRoot.Position + Vector3.new(0, 4, 0),
								"-" .. Util.abbreviate(stolen), Color3.fromRGB(255, 110, 110), workspace)
						end
					end
				end
			elseif not entry.swingAt and now >= entry.nextAttack and (inRange or objectivePosition) then
				entry.swingAt = now + entry.windUp
				entry.rootedUntil = entry.swingAt + WV.AttackRecover
				entry.nextAttack = entry.rootedUntil + WV.AttackCooldown
				entry.swingStructure = (not inRange) and objectivePosition ~= nil
				local face = (targetRoot and targetRoot.Position) or objectivePosition
				if face then
					-- face the target so the wind-up reads as aimed at it
					root.CFrame = CFrame.lookAt(root.Position,
						Vector3.new(face.X, root.Position.Y, face.Z))
				end
				Fx.impact(root, 1.5)
			end

			-- despawn stragglers so a wave can't hang forever
			if now >= entry.despawnAt then
				humanoid.Health = 0
			end
		end

		-- Flush the coalesced counter update. Two comparisons a frame, against one
		-- FireAllClients per death before.
		if liveWave and liveWave.dirty and now >= nextBroadcast then
			liveWave.dirty = false
			nextBroadcast = now + WV.BroadcastInterval
			broadcast()
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────

	local function setPhase(newPhase: string, seconds: number?)
		phase = newPhase
		phaseUntil = os.clock() + (seconds or 0)
		-- Phase changes bypass the broadcast throttle. These are the packets that
		-- must never be late: a banner that says "1 RAIDER LEFT" for half a second
		-- after you killed the last one is worse than no banner.
		broadcast()
	end

	--- Mints the record for the next wave and puts the warning up.
	local function beginWave()
		waveNumber += 1
		local count = math.min(WV.BaseCount + (waveNumber - 1) * WV.CountPerWave, WV.MaxCount)
		local boss = (waveNumber % WV.BossEvery == 0)

		-- HOW BIG THE SERVER IS, SAMPLED ONCE AND NEVER AGAIN.
		--
		-- Both factors are minted here, into the record, and every later reader
		-- takes them from it. If the boss's health tracked the live player count,
		-- one person logging off mid-fight would move a bar that a dozen people are
		-- watching, and the pot would change under the ledger that is already
		-- half-written. Somebody who joins mid-fight therefore gets a free ride,
		-- which is the friendly direction to be wrong in.
		local players = #Players:GetPlayers()

		liveWave = {
			number = waveNumber,
			boss = boss,
			players = players,
			healthFactor = Config.bossHealthFactor(players),
			rewardFactor = Config.bossRewardFactor(players),
			bossEntry = nil,
			count = count,
			expected = count + (boss and 1 or 0),
			spawned = 0,
			alive = 0,
			spawnFinished = false,
			cleared = false,
			forced = false,
			dirty = false,
			deadline = math.huge,
			-- Generous: the drip itself is count * SpawnGap, and this only exists
			-- so a thread that dies mid-drip cannot wedge the schedule.
			spawnDeadline = os.clock() + WV.WarningTime + count * WV.SpawnGap * 4 + 10,
		}

		setPhase("warning", WV.WarningTime)
		notifyRemote:FireAllClients({
			kind = boss and "boss" or "wave",
			title = ("SAHUR RAID %d INCOMING"):format(waveNumber),
			body = boss and "A BOSS is coming. tung tung tung."
				or ("%d raiders in %d seconds."):format(count, WV.WarningTime),
		})
	end

	--- Drips the wave in. Runs in its OWN thread and only sets a flag the driver
	--- polls, so the driver itself never blocks — the old loop ran the warning wait
	--- and the whole drip inside the pcall'd startWave, which meant an error
	--- anywhere in there took the schedule down with it.
	local function spawnWave(record)
		task.spawn(function()
			local groups = math.max(1, math.ceil(record.count / WV.SpawnGroupSize))
			local index = 0
			for group = 1, groups do
				-- A bearing per cluster, spread around the rim and jittered, so
				-- successive waves do not land in the same six places.
				local groupAngle = ((group - 1) / groups) * math.pi * 2 + math.random() * 0.6
				for _ = 1, WV.SpawnGroupSize do
					index += 1
					if index > record.count then
						break
					end
					if record ~= liveWave then
						return
					end
					spawnRaider(record, index, record.count, false, groupAngle)
					task.wait(WV.SpawnGap)
				end
				if group < groups then
					task.wait(WV.SpawnGroupGap)
				end
			end
			if record.boss and record == liveWave then
				-- No bearing: the boss lands on the dais, at the same spot every
				-- time, so a server-wide objective is somewhere everyone can name.
				spawnRaider(record, 0, record.count, true, nil)
			end
			record.spawnFinished = true
			record.deadline = os.clock() + WV.MaxWaveTime
		end)
	end

	--- Kills whatever is left of a wave that has run out of time.
	local function forceEnd(record)
		record.forced = true

		-- PAY THE BOSS LEDGER FIRST, PRO-RATA.
		--
		-- The loop below zeroes every survivor with no creator tag, and the comment
		-- on it says no reward is paid for a wave nobody finished, "which is
		-- correct, not an oversight". That reasoning is right for ordinary raiders
		-- and WRONG for a shared boss: twelve people fighting for five straight
		-- minutes and running into MaxWaveTime would get nothing at all, which is
		-- the most player-visible bug this could ship. They are paid for the share
		-- of it they actually took down, and `paid` stops onRaiderDied — which is
		-- about to fire for this very boss — paying a second time.
		local boss = record.bossEntry
		if boss and not boss.paid then
			local humanoid = boss.humanoid
			local pivot = humanoid and humanoid.Parent and (humanoid.Parent :: Model):GetPivot().Position
			payBoss(boss, boss.contribTotal / math.max(boss.maxHealth, 1), pivot, true)
		end

		for npc, entry in pairs(active) do
			if entry.waveRecord == record and not entry.dead then
				local humanoid = npc:FindFirstChildOfClass("Humanoid")
				if humanoid then
					-- Through Died, so the flop and the Debris cleanup still run.
					-- No creator tag, so no reward is paid for a wave nobody
					-- finished — which is correct, not an oversight.
					humanoid.Health = 0
				end
			end
		end
	end

	function NPCService.clearAll()
		for npc in pairs(active) do
			npc:Destroy()
		end
		active = {}
		liveWave = nil
	end

	--- One step of the schedule. Polled rather than driven by signals: at 4 Hz the
	--- cost is nothing, and it keeps every transition in one readable place
	--- instead of spread across a death handler and three timers.
	local function step()
		local now = os.clock()
		local populated = #Players:GetPlayers() > 0

		-- An empty server runs no raid, and does not burn a wave number doing it.
		if not populated and phase ~= "idle" then
			NPCService.clearAll()
			emptySince = now
			setPhase("idle")
			return
		end

		if phase == "idle" then
			if populated then
				-- A server that sat empty long enough resets, so someone joining a
				-- stale one is not met by a wave-30 raider with 2.9k health.
				if emptySince and now - emptySince >= WV.EmptyResetAfter then
					waveNumber = 0
				end
				emptySince = nil
				setPhase("resting", WV.JoinGrace)
			end
			return
		end

		if phase == "resting" then
			if now >= phaseUntil then
				beginWave()
			end
			return
		end

		if phase == "warning" then
			if now >= phaseUntil then
				setPhase("spawning")
				spawnWave(liveWave)
			end
			return
		end

		if phase == "spawning" then
			-- The drip runs in its own thread, so an error inside it kills that
			-- thread and nothing else — `spawnFinished` would simply never arrive
			-- and the schedule would sit here forever. Time it out into `active`
			-- with whatever did spawn; if that is nothing, `active` clears it on
			-- the next step and the raid moves on.
			if liveWave.spawnFinished or now >= liveWave.spawnDeadline then
				liveWave.spawnFinished = true
				liveWave.deadline = math.min(liveWave.deadline, now + WV.MaxWaveTime)
				setPhase("active")
			end
			return
		end

		if phase == "active" then
			-- `spawnFinished` is what makes this safe. Without it the moment
			-- mid-drip when alive legitimately touches zero would read as a clear.
			if liveWave.alive <= 0 then
				setPhase("clear", WV.ClearBannerTime)
			elseif now >= liveWave.deadline then
				forceEnd(liveWave)
				setPhase("clear", WV.ClearBannerTime)
			end
			return
		end

		if phase == "clear" then
			if now >= phaseUntil then
				local rest = liveWave.boss and WV.RestTimeAfterBoss or WV.RestTime
				liveWave = nil
				setPhase("resting", rest)
			end
			return
		end
	end

	--- The tower's door into the one minting site (#95): a public wrapper so
	--- TowerService never grows its own AI. opts is mintNPC's contract.
	function NPCService.spawn(opts)
		return mintNPC(opts)
	end

	--- Read-only walk of every live entry — TowerService sweeps its own floor's
	--- bodies on a run ending. Nothing outside this file may write through it.
	function NPCService.activeEntries()
		return active
	end

	--- Hands a joining client the packet everyone else last saw, so a mid-wave
	--- joiner does not stare at a blank banner until the next death.
	function NPCService.pushTo(player: Player)
		waveRemote:FireClient(player, wavePacket())
	end

	function NPCService.start()
		folder = Instance.new("Folder")
		folder.Name = "SahurRaiders"
		folder.Parent = workspace

		-- One hook, registered once. CombatService does not know what a raid is and
		-- must not learn; this is the same arrangement Economy has with its
		-- multiplier hooks, and for the same reason.
		CombatService.setDamageObserver(onDamageDealt)

		game:GetService("RunService").Heartbeat:Connect(function(dt)
			local ok, err = pcall(tick, dt)
			if not ok then
				warn("[Tung] NPC tick error: " .. tostring(err))
			end
		end)

		Players.PlayerAdded:Connect(function(player)
			task.defer(NPCService.pushTo, player)
		end)

		-- The world loop: the roamer census and the plot-siege schedules. Gated
		-- on its own flags rather than on WV.Enabled — turning the central wave
		-- off must not empty the bands.
		task.spawn(function()
			while true do
				local ok, err = pcall(function()
					local now = os.clock()
					maintainRoamers(now)
					stepPlotSieges(now)
				end)
				if not ok then
					warn("[Tung] world step error: " .. tostring(err))
				end
				task.wait(MB.MaintainInterval)
			end
		end)

		if not WV.Enabled then
			return
		end

		task.spawn(function()
			task.wait(WV.FirstWaveDelay)
			while true do
				local ok, err = pcall(step)
				if not ok then
					warn("[Tung] wave step error: " .. tostring(err))
				end
				task.wait(0.25)
			end
		end)
	end

	function NPCService.currentWave(): number
		return liveWave and liveWave.number or waveNumber
	end

	--- How many raiders of the CURRENT wave are still standing. Nil when no wave
	--- is running, which is different from zero.
	function NPCService.remaining(): number?
		return liveWave and liveWave.alive or nil
	end

	--- ADMIN HOOKS, for AdminService's !wave and !clear.
	---
	--- Public functions rather than AdminService reaching in, because the whole
	--- reason the schedule is one readable `step` is that nothing else writes
	--- `phase` and `phaseUntil`. These two go through the state machine rather than
	--- around it: !wave collapses the rest timer so the next step begins a wave the
	--- ordinary way, and !clear ends the live one through forceEnd so the flop, the
	--- Debris cleanup and the clear banner all still run.
	---
	--- Neither is reachable without Config.Admin authorisation — see AdminService.

	--- Skip the wait before the next raid. False if one is already in flight.
	function NPCService.forceWave(): boolean
		if not WV.Enabled then
			return false
		end
		if phase == "idle" then
			setPhase("resting", 0)
			return true
		end
		if phase ~= "resting" then
			return false
		end
		phaseUntil = 0
		return true
	end

	--- Collapse this plot's rest timer so its next step begins the siege the
	--- ordinary way — the forceWave arrangement, one plot down. False while one
	--- is already warning or active, or before the plot has a schedule.
	function NPCService.forcePlotWave(tycoon): boolean
		if not PW.Enabled or not tycoon then
			return false
		end
		local state = plotSieges[tycoon]
		if not state or state.phase ~= "resting" then
			return false
		end
		state.phaseUntil = 0
		return true
	end

	--- Kill whatever is standing. False if nothing is.
	function NPCService.forceClear(): boolean
		if not liveWave or (phase ~= "active" and phase ~= "spawning") then
			return false
		end
		-- Without this the clear would be read as the mid-drip moment when `alive`
		-- legitimately touches zero, which is the case `spawnFinished` exists for.
		liveWave.spawnFinished = true
		forceEnd(liveWave)
		setPhase("clear", WV.ClearBannerTime)
		return true
	end

	return NPCService
end


__MODULES["ObjectiveService"] = function()
	--[[
		ObjectiveService.lua — three things to do today (#97).

		design:D-01. The day deals three objectives from the pool (the tower's
		seeded draw, identical on every server), each pays minutes of the
		player's OWN income on completion (the tower's denomination), and the
		verifier bounds what a whole day may pay — the streak and the offline
		grant are why players log in; this is a nudge.

		PROGRESS IS A BASELINE, NOT A COUNTER. The day's first beat snapshots the
		live profile stats (kills, owned count, reputation); progress is the live
		stat minus the snapshot, so nothing has to observe kills or purchases —
		the stats already persist, and the reset is the tower's day arithmetic.
		Completion is written into profile.objectives.done and paid once.

		The hint line rides the same push: the first Config.Hints row whose stat
		the player has not reached. The guide NPC (#100) reads hintFor too.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Net = Req("Net")
	local Economy = Req("Economy")
	local DataService = Req("DataService")
	local SessionService = Req("SessionService")

	local Players = game:GetService("Players")

	local ObjectiveService = {}

	local remote = Net.event("Objectives")

	local function ownedCount(profile): number
		local count = 0
		for _ in pairs(profile.owned or {}) do
			count += 1
		end
		return count
	end

	--- The live reading for one stat name.
	local function statOf(profile, stat: string, now: number): number
		if stat == "kills" then
			return profile.kills or 0
		elseif stat == "buys" then
			return ownedCount(profile)
		elseif stat == "reputation" then
			return math.floor(profile.reputation or 0)
		elseif stat == "towerBest" then
			local tower = profile.tower
			return (tower and tower.day == math.floor(now / 86400)) and tower.best or 0
		end
		return 0
	end

	--- The first hint the player has not earned past, or nil when they are past
	--- all of them. #100's guide speaks this line too.
	function ObjectiveService.hintFor(profile): string?
		for _, hint in ipairs(Config.Hints) do
			if (profile[hint.stat] or 0) < hint.atLeast then
				return hint.text
			end
		end
		return nil
	end

	--- One player's pass: roll the day, snapshot baselines, measure progress,
	--- pay crossings. Returns the renderable rows. `now` is UTC seconds.
	function ObjectiveService.reconcile(player, now: number)
		local profile = DataService.get(player)
		if not profile then
			return nil
		end
		local day = math.floor(now / 86400)
		local state = profile.objectives
		if not state or state.day ~= day then
			state = { day = day, baseline = {}, done = {} }
			profile.objectives = state
		end

		local rows = {}
		for _, def in ipairs(Config.objectivesFor(day)) do
			-- the baseline is the day's FIRST sight of the stat; towerBest is
			-- already day-scoped so its baseline is zero by construction
			local baseline = state.baseline[def.stat]
			if baseline == nil then
				baseline = def.stat == "towerBest" and 0 or statOf(profile, def.stat, now)
				state.baseline[def.stat] = baseline
			end
			local progress = math.max(0, statOf(profile, def.stat, now) - baseline)

			if progress >= def.count and not state.done[def.id] then
				state.done[def.id] = true
				local reward = math.floor(def.rewardMinutes * 60 * SessionService.incomePerSecondFor(profile))
				local gained = Economy.add(player, reward, false)
				Economy.push(player)
				Economy.notify(player, { kind = "claim", title = "Objective done",
					body = ("%s  •  +%s"):format(def.name, Util.abbreviate(gained)) })
			end

			table.insert(rows, {
				id = def.id,
				name = def.name,
				progress = math.min(progress, def.count),
				count = def.count,
				done = state.done[def.id] == true,
			})
		end
		return rows
	end

	function ObjectiveService.start()
		task.spawn(function()
			while true do
				task.wait(5)
				for _, player in ipairs(Players:GetPlayers()) do
					local ok, rows = pcall(ObjectiveService.reconcile, player, os.time())
					if ok and rows then
						local profile = DataService.get(player)
						remote:FireClient(player, {
							rows = rows,
							hint = profile and ObjectiveService.hintFor(profile) or nil,
						})
					elseif not ok then
						warn("[Tung] objective error: " .. tostring(rows))
					end
				end
			end
		end)
	end

	return ObjectiveService
end


__MODULES["PartyService"] = function()
	--[[
		PartyService.lua — deliberate grouping (#102).

		design:D-04. A party is a TRUST BOUNDARY as much as a bonus: partymates
		cannot damage each other, cannot raid each other's plots, and open each
		other's gates — the door #89's owner-only gates promised invited guests.
		Those three consumers reach the one predicate, sameParty, through hooks
		wired in Main.server (CombatService's ally check, Tycoon.allyCheck) or by
		requiring this module (GateService, RaidService); nothing here requires
		any of them back.

		SESSION-SCOPED. A party lives while two or more members are on this
		server, and dissolves to nothing below that. Persistence would need a
		roster nobody present can see; the co-play signal this exists for is
		per-session anyway.

		THE SERVER DECIDES EVERYTHING. One remote both ways: the client sends
		{ action, target } and renders whatever state comes back — the
		SessionState arrangement. Invites die quietly after InviteTimeoutSeconds;
		the expiry is checked on read, so no timer thread exists to leak.

		THE BONUS COMPOSES. "party" is a named Economy multiplier hook beside
		"friends" and "help", and the verifier bounds the whole stack. Forming a
		party is also a kindness: accept credits BOTH sides through
		HelpService.credit, so a veteran partying with a new player comes out
		ahead — #123's weighting, for free.

		Clocks are parameters on the ledger functions; start()'s handlers pass
		os.clock(). The module runs headless in the spec harness.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Net = Req("Net")
	local Economy = Req("Economy")
	local HelpService = Req("HelpService")

	local Players = game:GetService("Players")

	local PartyService = {}

	local P = Config.Party

	-- one shared members array per party; every member maps to the SAME table,
	-- which is what makes sameParty a two-read identity check
	local partyOf: { [Player]: { Player } } = {}

	-- invitee -> { from, expires }. One pending invite per invitee: a second
	-- invite overwrites the first, which is the friendly direction — the newest
	-- ask is the one on screen.
	local invites: { [Player]: { from: Player, expires: number } } = {}

	local remote = Net.event("Party")

	local function push(player: Player)
		local members = partyOf[player]
		local names = {}
		if members then
			for _, member in ipairs(members) do
				table.insert(names, { name = member.DisplayName, userId = member.UserId })
			end
		end
		local invite = invites[player]
		remote:FireClient(player, {
			members = names,
			invite = invite and { fromName = invite.from.DisplayName, fromUserId = invite.from.UserId } or nil,
		})
	end

	local function pushParty(members: { Player })
		for _, member in ipairs(members) do
			push(member)
		end
	end

	function PartyService.partyOf(player: Player): { Player }?
		return partyOf[player]
	end

	--- The predicate the trust boundary hangs on: same shared table, or false.
	function PartyService.sameParty(a: Player?, b: Player?): boolean
		if not a or not b or a == b then
			return false
		end
		return partyOf[a] ~= nil and partyOf[a] == partyOf[b]
	end

	--- Partymates present, for the income hook. Zero outside a party.
	function PartyService.mates(player: Player): number
		local members = partyOf[player]
		return members and math.max(0, #members - 1) or 0
	end

	--- Returns (ok, reason). The reasons are player-facing.
	function PartyService.invite(from: Player, to: Player, now: number): (boolean, string)
		if from == to then
			return false, "that is you"
		end
		if PartyService.sameParty(from, to) then
			return false, "already in your party"
		end
		if partyOf[to] then
			return false, ("%s is in another party"):format(to.DisplayName)
		end
		local members = partyOf[from]
		if members and #members >= P.MaxSize then
			return false, ("your party is full (%d)"):format(P.MaxSize)
		end
		invites[to] = { from = from, expires = now + P.InviteTimeoutSeconds }
		push(to)
		return true, to.DisplayName
	end

	function PartyService.accept(invitee: Player, now: number): (boolean, string)
		local invite = invites[invitee]
		invites[invitee] = nil
		if not invite or now >= invite.expires then
			push(invitee)
			return false, "that invite has expired"
		end
		local from = invite.from
		if not from.Parent then
			push(invitee)
			return false, "they left the server"
		end
		if partyOf[invitee] then
			return false, "you are already in a party"
		end
		local members = partyOf[from]
		if members and #members >= P.MaxSize then
			push(invitee)
			return false, "that party filled up"
		end
		if not members then
			members = { from }
			partyOf[from] = members
		end
		table.insert(members, invitee)
		partyOf[invitee] = members

		-- forming a party is a kindness both ways; #123's gap weighting rides in
		HelpService.credit(from, invitee, "partying up", now)
		HelpService.credit(invitee, from, "partying up", now)

		pushParty(members)
		return true, from.DisplayName
	end

	function PartyService.decline(invitee: Player)
		invites[invitee] = nil
		push(invitee)
	end

	function PartyService.leave(player: Player)
		local members = partyOf[player]
		if not members then
			return
		end
		partyOf[player] = nil
		for index, member in ipairs(members) do
			if member == player then
				table.remove(members, index)
				break
			end
		end
		-- a party of one is nobody's party
		if #members == 1 then
			partyOf[members[1]] = nil
		end
		push(player)
		pushParty(members)
	end

	function PartyService.start()
		-- the bonus: an O(1) read, per the Economy hook contract
		Economy.setMultiplierHook("party", function(player)
			return 1 + P.BonusPerMate * math.min(PartyService.mates(player), P.MaxSize - 1)
		end)

		remote.OnServerEvent:Connect(function(player, payload)
			if type(payload) ~= "table" then
				return
			end
			local now = os.clock()
			if payload.action == "invite" then
				local target = type(payload.target) == "number" and Players:GetPlayerByUserId(payload.target)
				if target then
					local ok, what = PartyService.invite(player, target, now)
					Economy.notify(player, { kind = ok and "info" or "warn", title = "Party",
						body = ok and ("Invited %s."):format(what) or what })
					if ok then
						Economy.notify(target, { kind = "info", title = "Party",
							body = ("%s invited you — check your party card."):format(player.DisplayName) })
					end
				end
			elseif payload.action == "accept" then
				local ok, what = PartyService.accept(player, now)
				Economy.notify(player, { kind = ok and "claim" or "warn", title = "Party",
					body = ok and ("You joined %s's party."):format(what) or what })
			elseif payload.action == "decline" then
				PartyService.decline(player)
			elseif payload.action == "leave" then
				PartyService.leave(player)
				Economy.notify(player, { kind = "info", title = "Party", body = "You left the party." })
			end
		end)

		Players.PlayerRemoving:Connect(function(player)
			PartyService.leave(player)
			invites[player] = nil
			-- and any invite FROM them dies with them
			for invitee, invite in pairs(invites) do
				if invite.from == player then
					invites[invitee] = nil
					push(invitee)
				end
			end
		end)
		Players.PlayerAdded:Connect(function(player)
			task.defer(push, player)
		end)
	end

	return PartyService
end


__MODULES["PlotService"] = function()
	--[[
		PlotService.lua — who owns which factory, and the only door in or out of one.

		IT OWNS THREE PIECES OF STATE. `plots`, the Config.World.PlotCount Tycoons
		built once by build(); `byOwner`, which is the server's answer to "whose plot
		is this" — AdminService and Main.server.lua both ask through plotOf() and
		nothing else keeps a copy; and `reserved`, the short hold that survives a
		disconnect.

		IT IS ALSO THE ONLY CALLER OF Tycoon:assign AND Tycoon:release in src/, and
		that is the interesting half of the contract. assign() replays the owner's
		saved purchases onto whatever plot they landed on and release() tears the
		factory back down to bare ground, so "claim" and "release" are the two points
		at which a plot's contents change wholesale. Anything that wants to react to
		that listens on Tycoon:onOwnedChanged (FloorService and VaultService do)
		rather than hooking claim from out here.

		A CLAIM DOES NOT WAIT FOR THE PROFILE, and this is the sharp edge.
		Tycoon:assign replays profile.owned only `if profile`, and DataService.get
		returns nil until the load finishes rather than yielding. So a claim that
		lands inside the load window builds a BARE plot for a player who owns twenty
		buttons, and nothing re-runs the replay afterwards. The only thing standing
		between the two is the task.delay(1.5) around autoAssign in Main.server.lua —
		and a contended DataStore load can now take ~32 seconds, because DataService
		retries against a held session lock. Widening that gap is the fix; do not
		shorten the delay.

		THE RESERVATION IS PROCESS-LOCAL AND LAZY. release(player, true) — which is
		what PlayerRemoving does — parks { userId, until_ } under the plot index for
		Config.Economy.OfflineGraceSeconds, and isReservedForSomeoneElse expires it on
		read rather than on a timer. It is measured with os.clock(), i.e. server
		uptime, deliberately: a hold that outlived the server it was made on would be
		meaningless, and this is the opposite of the os.time() rule offline earnings
		follow. RequestReset releases WITHOUT a hold, because that is a player
		deliberately giving the plot up.

		AND YOU USUALLY DO NOT GET YOUR OWN PLOT BACK. Three minutes is short, so a
		returning player normally lands on a different plot and has their factory
		replayed onto it. VaultService's header depends on that being true — it is why
		the vault gauge is honest about being a projection rather than a thing that
		fills while you are away.

		TWO ROBLOX TRAPS THAT ARE ALREADY PAID FOR:

		  NO PER-PLOT SpawnLocation. It would join the random-spawn pool and start
		  sending other players to your factory. Respawn placement is a reposition —
		  Main.server.lua defers teleportToPlot on CharacterAdded — not a spawn.

		  Players.MaxPlayers IS NOT SCRIPTABLE. The plot count follows
		  Config.World.MaxPlots and the place's cap has to be set by hand in Studio to
		  match. When it is not, this file simply leaves late joiners plotless until
		  someone disconnects; that is the designed behaviour, not a bug to fix here.

		build() FALLS BACK RATHER THAN FAILING: with no "Plots" child under the world
		it parents every Tycoon straight into `parent`. Rename that folder in
		MapBuilder and the plots still appear, in the wrong place, with nothing said.

		NOTHING HERE IS COVERED BY tools/test.py. PlotService is outside its
		SERVER_MODULES list because claiming runs through Touched and needs a physics
		step, and widening that list is its own piece of work. The verifier will only
		tell you this file parses and type-checks — every behaviour above has to be
		confirmed in Studio, which is what AdminService's `!give` is for: it builds a
		full factory in two lines, so "rejoin and check the replay" costs a minute
		instead of a grind.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Net = Req("Net")
	local Tycoon = Req("Tycoon")
	local Economy = Req("Economy")

	local Players = game:GetService("Players")

	local PlotService = {}

	local plots: { any } = {}
	local byOwner: { [Player]: any } = {}
	local reserved: { [number]: { userId: number, until_: number } } = {}

	local plotAssigned = Net.event("PlotAssigned")

	function PlotService.build(parent: Instance)
		local folder = parent:FindFirstChild("Plots") or parent
		for index = 1, Config.World.PlotCount do
			local tycoon = Tycoon.new(index, folder)
			plots[index] = tycoon
			PlotService.hookClaimPad(tycoon)
		end
	end

	function PlotService.hookClaimPad(tycoon)
		local lastTouch = 0
		local function onTouch(hit)
			-- cheapest possible early-out: an owned plot ignores touches entirely
			if tycoon.owner then
				return
			end
			if os.clock() - lastTouch < 0.5 then
				return
			end
			lastTouch = os.clock()
			local player = tycoon:playerFromHit(hit)
			if player and not byOwner[player] then
				PlotService.claim(player, tycoon.index)
			end
		end

		-- The marked pad is the affordance, but the ENTIRE plot floor claims an
		-- unclaimed plot. Hunting for a specific tile to stand on is a bad first
		-- thirty seconds, and there is no downside: the plot is free either way.
		for _, part in ipairs({ tycoon.claimPad, tycoon.padPart }) do
			if part then
				part.Touched:Connect(onTouch)
			end
		end
	end

	--- Puts a player on their own plot. Used on claim and on every respawn, so
	--- dying never costs you a walk back across the map.
	function PlotService.teleportToPlot(player: Player): boolean
		local tycoon = byOwner[player]
		local character = player.Character
		if not tycoon or not character or not character.PrimaryPart then
			return false
		end
		character:PivotTo(tycoon:ownerSpawnCFrame())
		return true
	end

	function PlotService.plotOf(player: Player)
		return byOwner[player]
	end

	local function isReservedForSomeoneElse(index: number, player: Player): boolean
		local hold = reserved[index]
		if not hold then
			return false
		end
		if os.clock() > hold.until_ then
			reserved[index] = nil
			return false
		end
		return hold.userId ~= player.UserId
	end

	function PlotService.claim(player: Player, index: number): boolean
		if byOwner[player] then
			return false
		end
		local tycoon = plots[index]
		if not tycoon or tycoon.owner then
			return false
		end
		if isReservedForSomeoneElse(index, player) then
			Economy.notify(player, {
				kind = "warn",
				title = "Plot reserved",
				body = "That factory is being held for a player who just disconnected.",
			})
			return false
		end

		reserved[index] = nil
		if not tycoon:assign(player) then
			return false
		end
		byOwner[player] = tycoon

		plotAssigned:FireClient(player, index)
		Economy.notify(player, {
			kind = "claim",
			title = "PLOT " .. index .. " CLAIMED",
			body = "Buy the first dropper to start the tung.",
		})
		Economy.push(player)

		PlotService.teleportToPlot(player)
		return true
	end

	function PlotService.release(player: Player, hold: boolean?)
		local tycoon = byOwner[player]
		if not tycoon then
			return
		end
		byOwner[player] = nil
		if hold then
			reserved[tycoon.index] = {
				userId = player.UserId,
				until_ = os.clock() + Config.Economy.OfflineGraceSeconds,
			}
		end
		tycoon:release()
	end

	--- Auto-place a player on the first free plot (used on join for convenience).
	function PlotService.autoAssign(player: Player): boolean
		-- honour a reservation from a recent disconnect first
		for index, hold in pairs(reserved) do
			if hold.userId == player.UserId and os.clock() <= hold.until_ then
				if PlotService.claim(player, index) then
					return true
				end
			end
		end
		for index = 1, Config.World.PlotCount do
			local tycoon = plots[index]
			if tycoon and not tycoon.owner and not isReservedForSomeoneElse(index, player) then
				return PlotService.claim(player, index)
			end
		end
		Economy.notify(player, {
			kind = "warn",
			title = "All plots taken",
			body = "Hang out in the arena — a plot frees up when someone leaves.",
		})
		return false
	end

	function PlotService.rebirth(player: Player)
		local tycoon = byOwner[player]
		if not tycoon then
			return
		end
		tycoon:rebirth(player)
	end

	function PlotService.start()
		Net.event("RequestRebirth").OnServerEvent:Connect(function(player)
			PlotService.rebirth(player)
		end)

		Net.event("RequestReset").OnServerEvent:Connect(function(player)
			PlotService.release(player, false)
			Economy.notify(player, { kind = "info", title = "Plot released", body = "Your progress is saved. Claim any plot to resume." })
		end)

		Players.PlayerRemoving:Connect(function(player)
			PlotService.release(player, true)
		end)

		-- keep the signage honest
		task.spawn(function()
			while true do
				task.wait(3)
				for _, tycoon in ipairs(plots) do
					local ok, err = pcall(function()
						tycoon:updateSign()
						if tycoon.owner then
							tycoon:refreshButtons()
						end
					end)
					if not ok then
						warn("[Tung] plot refresh error: " .. tostring(err))
					end
				end
			end
		end)
	end

	return PlotService
end


__MODULES["RaidService"] = function()
	--[[
		RaidService.lua — what a raid takes, who carries it, and how it gets home
		(#94).

		design:D-04. Breaking in is #124's verb and the storage unit is #93's
		object; this file owns the LOOT ARITHMETIC between them. Config.Raid holds
		every number, and the shape is: a safe amount is structurally out of reach,
		a break spills a fraction of the overflow above it into the raider's HANDS,
		and the spoils only become the raider's when they stand on their own plot.
		Until then the carrier can be killed, and a kill returns the loot.

		THE SAFE AMOUNT IS UNREACHABLE BY CONSTRUCTION. overflowOf subtracts
		SafeFraction x cap before anything is computed, and every taking — spill
		and kill-steal both — is sized from that remainder. There is no code path
		that reads the victim's cash without the subtraction, which is the only
		kind of guarantee worth making about a number griefers will probe.

		AN EMPTY UNIT STILL PAYS. Raiding has to reward the raider every time or
		the verb dies; a break over no overflow MINTS EmptyBountyFraction of the
		victim's cap for the attacker and the victim loses nothing. Camping decays
		both kinds the same way: spoils halve per repeat on the same victim inside
		the window, so farming one target converges on zero.

		CLOCKS ARE PARAMETERS. Every entry point takes `now` so the specs drive
		time; the wiring in start() passes os.clock(). The one Studio-only piece is
		the banking heartbeat — standing-on-your-own-plot is CFrame arithmetic the
		mock world does not claim to have — and the handoff names it.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Net = Req("Net")
	local Style = Req("Style")
	local Economy = Req("Economy")
	local HelpService = Req("HelpService")
	local PartyService = Req("PartyService")

	local Players = game:GetService("Players")

	local RaidService = {}

	local R = Config.Raid

	-- per-carrier: { total, sources = { [victimUserId] = amount } }. Sources are
	-- kept apart so a death can hand each victim back exactly what was theirs.
	local carried: { [Player]: { total: number, sources: { [number]: number } } } = {}

	-- camping ledger, attacker -> victimUserId -> { count, expires }. Counting
	-- resets when the window lapses; the factor is read BEFORE the increment, so
	-- the first break always pays full.
	local recent: { [Player]: { [number]: { count: number, expires: number } } } = {}

	--- The character wears the theft (#138): the attribute for anything that
	--- reads state, and a gold sack billboard over the head so every player on
	--- the server can SEE a thief worth chasing — the chase only happens if the
	--- server can see who to chase.
	local function mirrorCarry(player: Player)
		local character = player.Character
		if not character or not character.SetAttribute then
			return
		end
		local carry = carried[player]
		local total = carry and carry.total or 0
		character:SetAttribute("CarryingTung", total)

		local head = character:FindFirstChild("Head") or character:FindFirstChild("HumanoidRootPart")
		local existing = head and head:FindFirstChild("CarryMark")
		if total > 0 and head then
			if not existing then
				local billboard = Style.billboard(head, {
					name = "CarryMark", width = 12, height = 2.4,
					distance = "world", offset = 3.4, alwaysOnTop = true,
				})
				Style.text(billboard, {
					name = "Loot", text = "",
					color = Color3.fromRGB(255, 205, 90),
				})
				existing = billboard
			end
			local label = existing:FindFirstChild("Loot")
			if label then
				label.Text = ("CARRYING %s"):format(Util.abbreviate(total))
			end
		elseif existing then
			existing:Destroy()
		end
	end

	--- Every player currently carrying THIS victim's Tung — the compass mark's
	--- ledger, and the spec's window onto the pushes.
	function RaidService.thievesOf(victim: Player): { Player }
		local thieves = {}
		for carrier, carry in pairs(carried) do
			if carry.sources[victim.UserId] then
				table.insert(thieves, carrier)
			end
		end
		return thieves
	end

	--- Tell a robbed victim who to chase, or that the chase is over.
	local function markThief(victim: Player?, carrier: Player, gone: boolean?)
		if victim and victim.Parent then
			Net.event("ThiefMark"):FireClient(victim, {
				thiefUserId = carrier.UserId,
				gone = gone or nil,
			})
		end
	end

	--- The only Tung a raid can reach: cash above the safe fraction of the cap.
	function RaidService.overflowOf(victim: Player): number
		local safe = R.SafeFraction * Economy.storageCapFor(victim)
		return math.max(0, Economy.get(victim) - safe)
	end

	--- The camping decay: CampingHalving^breaks-inside-the-window. Read only —
	--- recordBreak advances the ledger, so a refused raid costs no decay.
	function RaidService.campingFactor(attacker: Player, victimUserId: number, now: number): number
		local ledger = recent[attacker]
		local entry = ledger and ledger[victimUserId]
		if not entry or now >= entry.expires then
			return 1
		end
		return R.CampingHalving ^ entry.count
	end

	local function recordBreak(attacker: Player, victimUserId: number, now: number)
		local ledger = recent[attacker]
		if not ledger then
			ledger = {}
			recent[attacker] = ledger
		end
		local entry = ledger[victimUserId]
		if not entry or now >= entry.expires then
			entry = { count = 0, expires = 0 }
			ledger[victimUserId] = entry
		end
		entry.count += 1
		entry.expires = now + R.CampingWindowSeconds
	end

	function RaidService.carriedBy(player: Player): number
		local carry = carried[player]
		return carry and carry.total or 0
	end

	local function addCarry(carrier: Player, victimUserId: number, amount: number)
		if amount <= 0 then
			return
		end
		local carry = carried[carrier]
		if not carry then
			carry = { total = 0, sources = {} }
			carried[carrier] = carry
		end
		carry.total += amount
		carry.sources[victimUserId] = (carry.sources[victimUserId] or 0) + amount
		mirrorCarry(carrier)
		markThief(Players:GetPlayerByUserId(victimUserId), carrier)
	end

	--- The storage unit broke with an attacker on the bat. Called through
	--- Tycoon's break observer (Main.server wires it — the service requires
	--- Tycoon's world, so the arrow cannot point back). Returns what the
	--- attacker now carries from this break.
	function RaidService.onStorageBroken(tycoon, attacker: Player, now: number): number
		local victim = tycoon.owner
		if not victim or not attacker or victim == attacker
				or PartyService.sameParty(victim, attacker) then
			return 0
		end

		local factor = RaidService.campingFactor(attacker, victim.UserId, now)
		recordBreak(attacker, victim.UserId, now)

		local overflow = RaidService.overflowOf(victim)
		local spoils
		if overflow >= 1 then
			spoils = math.floor(R.SpillFraction * overflow * factor)
			spoils = Economy.take(victim, spoils)
		else
			-- minted, so the raider is paid and the broke stay broke
			spoils = math.floor(R.EmptyBountyFraction * Economy.storageCapFor(victim) * factor)
		end
		if spoils <= 0 then
			return 0
		end

		addCarry(attacker, victim.UserId, spoils)
		Economy.notify(victim, { kind = "warn", title = "Raided!",
			body = ("%s broke your storage and grabbed %s. Kill them before they bank it!")
				:format(attacker.Name, Util.abbreviate(spoils)) })
		Economy.notify(attacker, { kind = "claim", title = "Loot",
			body = ("Carrying %s — get back to your plot."):format(Util.abbreviate(RaidService.carriedBy(attacker))) })
		return spoils
	end

	--- Standing on your own plot is what banks the carry. The deposit goes
	--- through Economy.add, so the CAP CLAMPS IT — loot above what your unit
	--- holds is lost, the same rule every other inflow obeys.
	function RaidService.bankCarry(player: Player): number
		local carry = carried[player]
		if not carry then
			return 0
		end
		carried[player] = nil
		mirrorCarry(player)
		for userId in pairs(carry.sources) do
			markThief(Players:GetPlayerByUserId(userId), player, true)
		end
		local banked = Economy.add(player, carry.total, false)
		Economy.notify(player, { kind = "claim", title = "Banked",
			body = banked < carry.total
				and ("Banked %s — your storage held no more."):format(Util.abbreviate(banked))
				or ("Banked %s of stolen Tung."):format(Util.abbreviate(banked)) })
		return banked
	end

	--- Any death drops the carry, and each victim gets their share straight back
	--- if they are still on the server (through Economy.add: their own cap
	--- clamps the return too). A killer who is a player also lifts
	--- KillStealFraction of the dead player's overflow — into a CARRY of their
	--- own, so the chase can chain.
	function RaidService.onPlayerDied(victim: Player, killer: Player?, now: number)
		local carry = carried[victim]
		if carry then
			carried[victim] = nil
			mirrorCarry(victim)
			for userId in pairs(carry.sources) do
				markThief(Players:GetPlayerByUserId(userId), victim, true)
			end
			for userId, amount in pairs(carry.sources) do
				local source = Players:GetPlayerByUserId(userId)
				if source then
					local returned = Economy.add(source, amount, false)
					if returned > 0 then
						Economy.notify(source, { kind = "claim", title = "Recovered",
							body = ("%s went down — %s of your Tung came home.")
								:format(victim.Name, Util.abbreviate(returned)) })
					end
					-- downing a thief is a kindness to everyone they robbed;
					-- getting your OWN money back is self-interest, and credit()
					-- refuses self-help anyway
					if killer and killer ~= source then
						HelpService.credit(killer, source, "raid defence", now)
					end
				end
			end
		end

		if killer and killer ~= victim and not PartyService.sameParty(killer, victim) then
			local steal = math.floor(R.KillStealFraction * RaidService.overflowOf(victim) *
				RaidService.campingFactor(killer, victim.UserId, now))
			steal = Economy.take(victim, steal)
			if steal > 0 then
				recordBreak(killer, victim.UserId, now)
				addCarry(killer, victim.UserId, steal)
				Economy.notify(victim, { kind = "warn", title = "Robbed",
					body = ("%s took %s off your body."):format(killer.Name, Util.abbreviate(steal)) })
			end
		end
	end

	function RaidService.start()
		-- deaths: the classic creator tag CombatService already plants is the
		-- killer credit; a death with no tag (fall, reset) still drops the carry
		local function hook(player: Player)
			player.CharacterAdded:Connect(function(character)
				mirrorCarry(player)
				local humanoid = character:WaitForChild("Humanoid", 10)
				if not humanoid then
					return
				end
				humanoid.Died:Connect(function()
					local tag = humanoid:FindFirstChild("creator")
					local credited = tag and tag.Value
					local killer = (credited and credited:IsA("Player")) and credited or nil
					RaidService.onPlayerDied(player, killer, os.clock())
				end)
			end)
		end
		Players.PlayerAdded:Connect(hook)
		for _, player in ipairs(Players:GetPlayers()) do
			hook(player)
		end
		Players.PlayerRemoving:Connect(function(player)
			carried[player] = nil
			recent[player] = nil
			for _, ledger in pairs(recent) do
				if player.UserId then
					ledger[player.UserId] = nil
				end
			end
		end)

		-- the banking heartbeat: a carrier standing on their own plot deposits.
		-- CFrame arithmetic — Studio owns proving the rectangle feels right.
		-- PlotService is required HERE: the ledger above runs in the spec
		-- harness, whose bundle carries neither PlotService nor a workspace,
		-- and start() is the one function only Roblox calls.
		local PlotService = Req("PlotService")
		task.spawn(function()
			while true do
				task.wait(2)
				for player, carry in pairs(carried) do
					if carry.total > 0 then
						local tycoon = PlotService.plotOf(player)
						local character = player.Character
						local root = character and character:FindFirstChild("HumanoidRootPart")
						if tycoon and tycoon.cf and root then
							local rel = tycoon.cf:PointToObjectSpace(root.Position)
							local half = Config.World.PlotSize / 2
							if math.abs(rel.X) <= half.X and math.abs(rel.Z) <= half.Z then
								RaidService.bankCarry(player)
							end
						end
					end
				end
			end
		end)
	end

	return RaidService
end


__MODULES["RecallService"] = function()
	--[[
		RecallService.lua — the way home (#103).

		design:D-04. The open world makes the trip home a recurring tax; recall
		pays it with six seconds standing still. The stillness is the whole
		anti-escape design: a caster is a free hit for anything already on them,
		moving or taking damage cancels the cast, and a raid carry blocks it
		outright — stolen Tung walks home (#94's chase must never end in a blink).

		THE LEDGER AND THE CAST ARE SPLIT. tryStart/complete are pure bookkeeping
		over a clock parameter — the cooldown, the carry block — and run headless
		in the spec harness. The cast watch (position drift, health drop) needs a
		character and lives in start()'s handler; the handoff owns proving it in
		Studio. Arrival is PlotService.teleportToPlot, the one placement everyone
		else already uses.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Net = Req("Net")
	local Economy = Req("Economy")
	local RaidService = Req("RaidService")

	local Players = game:GetService("Players")

	local RecallService = {}

	local R = Config.Recall

	local cooldownUntil: { [Player]: number } = {}
	local casting: { [Player]: boolean } = {}

	--- The bookkeeping gate. Returns (ok, reason); the reasons are player-facing.
	function RecallService.tryStart(player: Player, now: number): (boolean, string)
		if casting[player] then
			return false, "already recalling"
		end
		if now < (cooldownUntil[player] or 0) then
			return false, ("recall is resting — %ds left"):format(math.ceil((cooldownUntil[player] or 0) - now))
		end
		if RaidService.carriedBy(player) > 0 then
			return false, "not with stolen Tung in your hands — carry it home"
		end
		return true, ""
	end

	--- Stamps the cooldown. Called on a completed cast, never on a cancelled one
	--- — a cancel already cost the standing still.
	function RecallService.complete(player: Player, now: number)
		casting[player] = nil
		cooldownUntil[player] = now + R.CooldownSeconds
	end

	function RecallService.cancel(player: Player)
		casting[player] = nil
	end

	function RecallService.start()
		-- required here: the spec bundle carries neither PlotService nor a
		-- workspace, and start() is the one function only Roblox calls
		local PlotService = Req("PlotService")

		Net.event("RequestRecall").OnServerEvent:Connect(function(player)
			local now = os.clock()
			local ok, reason = RecallService.tryStart(player, now)
			if not ok then
				Economy.notify(player, { kind = "warn", title = "Recall", body = reason })
				return
			end
			local character = player.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			if not root or not humanoid or humanoid.Health <= 0 then
				return
			end

			casting[player] = true
			Economy.notify(player, { kind = "info", title = "Recall",
				body = ("Stand still for %d seconds."):format(R.CastSeconds) })

			local startPosition = root.Position
			local startHealth = humanoid.Health
			task.spawn(function()
				local deadline = now + R.CastSeconds
				while os.clock() < deadline do
					task.wait(0.2)
					if not casting[player] or not player.Parent then
						return
					end
					local liveRoot = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
					local liveHumanoid = player.Character and player.Character:FindFirstChildOfClass("Humanoid")
					-- moving, dying, respawning or getting hit all cancel; the
					-- cast is a promise to stand there and take it
					if not liveRoot or not liveHumanoid
						or liveHumanoid.Health < startHealth
						or (liveRoot.Position - startPosition).Magnitude > R.CancelMoveStuds then
						RecallService.cancel(player)
						Economy.notify(player, { kind = "warn", title = "Recall",
							body = "Cancelled — you moved, or something hit you." })
						return
					end
				end
				if casting[player] and player.Parent then
					RecallService.complete(player, os.clock())
					PlotService.teleportToPlot(player)
				end
			end)
		end)

		Players.PlayerRemoving:Connect(function(player)
			cooldownUntil[player] = nil
			casting[player] = nil
		end)
	end

	return RecallService
end


__MODULES["SessionService"] = function()
	--[[
		SessionService.lua — offline earnings, the four session loops (daily streak,
		playtime ladder, boost button, weekend bonus) and the three rebirth grants
		that Tycoon:rebirth() does not hand out.

		OFFLINE AND SESSIONS SHIP. They were Config.Prototypes.Offline and
		.Sessions; graduating them meant DELETING those flags rather than setting
		them true, because tools/verify_config.lua asserts every prototype flag is
		false and a feature that ships stops being a prototype. Everything in this
		file runs unconditionally now except the rebirth grants, which are still
		gated on Config.Prototypes.RebirthPerks — the one flag left here.

		TIME. Two rules, both of them bugs someone else already shipped:

		  * **os.time(), never tick().** tick() is the wall clock of whatever
		    machine the server happens to be running on. Storing one machine's
		    tick() and subtracting another's is how a developer accidentally
		    granted 1.6 billion from a few seconds of drift. os.time() is UTC
		    epoch seconds and is the same number everywhere.
		  * **Day buckets are math.floor(os.time() / 86400), never
		    os.date("%j").** The day-of-year restarts at 1 on January 1st, so a
		    streak keyed on it breaks for every player in the game on the same
		    night — and it breaks in the direction of resetting their streak.

		os.clock() still appears below, but only for monotonic in-session
		durations (activity sampling, rate limits) where it is the right tool and
		nothing is persisted.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Net = Req("Net")
	local DataService = Req("DataService")
	local Economy = Req("Economy")
	local Analytics = Req("Analytics")

	local Players = game:GetService("Players")

	local SessionService = {}

	local P = Config.Prototypes
	local S = Config.Sessions
	local O = Config.Offline
	local RP = Config.RebirthPerks

	local DAY = 86400
	local PUSH_SECONDS = 5        -- how often state is re-replicated if nothing changed
	local ACTIVITY_STUDS = 2      -- movement per sample that counts as "still playing"
	local CLAIM_COOLDOWN = 0.25   -- per-player floor between remote claims

	local sessionState = Net.event("SessionState")
	local requestClaim = Net.event("RequestClaim")
	local requestBoost = Net.event("RequestBoost")

	-- ─────────────────────────────────────────────────────────────────────────────
	-- per-session runtime state (never persisted)
	-- ─────────────────────────────────────────────────────────────────────────────

	--- `claimedPlaytime` used to live here and that was the rejoin farm: the ladder
	--- re-opened on every reconnect, so five minutes of walking was worth 1200 tung
	--- as many times as you cared to press Leave. The claimed set is persisted with
	--- a day bucket now (see `playtimeClaims`); only the MINUTES are session-scoped,
	--- because a session's activity is exactly what "active seconds" means.
	type Live = {
		player: Player,
		activeSeconds: number,        -- session-scoped, and only counts while active
		lastPosition: Vector3?,
		lastClaim: number,
		offline: any,                 -- pending welcome-back grant, nil once claimed
		rebirths: number,             -- last seen count, to detect a rebirth landing
		dirty: boolean,
		lastPush: number,
	}

	local live: { [Player]: Live } = {}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- profile shape
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The `sessions` sub-table of a profile.
	---
	--- DataService.reconcile() only type-checks TOP-LEVEL keys, so a table field
	--- arrives from the DataStore exactly as it was written — including from a
	--- build where the shape was different. Every field is re-derived here on
	--- every read, which is cheap and means no other function in this file has to
	--- wonder whether a number is a number.
	local function sessions(profile)
		local s = profile.sessions
		if type(s) ~= "table" then
			s = {}
			profile.sessions = s
		end
		s.dailyDay = math.floor(tonumber(s.dailyDay) or 0)
		s.streak = math.max(0, math.floor(tonumber(s.streak) or 0))
		s.boostUntil = math.floor(tonumber(s.boostUntil) or 0)
		s.boostReadyAt = math.floor(tonumber(s.boostReadyAt) or 0)
		s.offlineCapLevel = math.clamp(math.floor(tonumber(s.offlineCapLevel) or 0), 0, #O.CapUpgradeHours)
		s.playtimeDay = math.floor(tonumber(s.playtimeDay) or 0)
		s.playtimeClaimed = math.max(0, math.floor(tonumber(s.playtimeClaimed) or 0))
		return s
	end

	local function dayNumber(): number
		return math.floor(os.time() / DAY)
	end

	--- The playtime ladder's claimed rungs for TODAY, as a bitmask.
	---
	--- A BITMASK RATHER THAN A SET. The obvious shape is `{ [index] = true }`, and
	--- it is the wrong one for something that has to survive a DataStore: a table
	--- with sparse numeric keys goes through JSON as an OBJECT, so `{ [2] = true }`
	--- comes back as `{ ["2"] = true }` and the string key never matches the numeric
	--- index again. Nothing errors — the ladder just silently re-opens on the next
	--- load, which is the exact bug this field exists to close. A number has one
	--- representation and cannot round-trip into a different one.
	---
	--- The day bucket is the same `floor(os.time() / 86400)` the streak uses, for
	--- the same reason: os.date("%j") restarts at 1 every January and would reset
	--- every player in the game on the same night.
	--- Returns the `sessions` sub-table with today's bucket already rolled over, so
	--- every reader and the one writer go through the same expiry.
	local function playtimeClaims(profile)
		local s = sessions(profile)
		local today = dayNumber()
		if s.playtimeDay ~= today then
			-- `~=` rather than `<`: a stored bucket in the FUTURE (a clock that went
			-- backwards, a hand-edited save) would otherwise lock the ladder shut
			-- until the calendar caught up with it. Re-opening costs a rung; locking
			-- for a day costs the player the feature.
			s.playtimeDay = today
			s.playtimeClaimed = 0
		end
		return s
	end

	local function hasClaimedRung(profile, index: number): boolean
		return bit32.btest(playtimeClaims(profile).playtimeClaimed, bit32.lshift(1, index - 1))
	end

	--- UTC, because a server-wide "weekend" that depends on where the machine is
	--- would start at different times for different players.
	local function isWeekend(): boolean
		return S.WeekendDays[os.date("!*t").wday] == true
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- income, derived from the SAVED plot
	-- ─────────────────────────────────────────────────────────────────────────────

	--- invariant: income per second computed from PERSISTED PLOT STATE and nothing
	--- else. Never from a value cached at logout (a stale multiplier survives a
	--- nerf and pays out forever) and never from anything the client said. An
	--- offline player has no Tycoon instance to ask, which is why this mirrors
	--- `Tycoon:incomePerSecond()` rather than calling it.
	---
	--- DELIBERATELY EXCLUDES THE SESSION MULTIPLIERS — design:D-01. It includes the
	--- rebirth multiplier, because that is a property of the factory rather than of
	--- the session.
	---
	--- The same exclusion catches SocialService's friend bonus for free: that hook
	--- is registered on Economy and this function never calls Economy.multiplier.
	--- Anything added to this line must survive the same question.
	function SessionService.incomePerSecondFor(profile): number
		if type(profile) ~= "table" then
			return 0
		end
		local owned = profile.owned or {}
		local rebirths = math.max(0, math.floor(tonumber(profile.rebirths) or 0))
		-- Config.incomeRate includes the generator, for the same reason the
		-- rebirth multiplier is included and the boost is not: it is a property of
		-- the factory, bought once and standing there whether or not anyone is
		-- logged in. Session hooks are excluded by construction — the rate is the
		-- factory's, and the only per-player term an absent player keeps is the
		-- rebirth multiplier added here.
		return Config.incomeRate(function(id)
			return owned[id] == true
		end) * (Config.Rebirth.MultiplierPerRebirth ^ rebirths)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- offline earnings
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Hours of offline income this profile banks. The cap is a purchase, which is
	--- what turns it from a wall you resent into a goal you aim at.
	function SessionService.offlineCapHours(profile): number
		local level = sessions(profile).offlineCapLevel
		return O.CapUpgradeHours[level] or O.CapHours
	end

	--- The upgrade that WOULD have prevented the clip. Naming it on the panel is
	--- the difference between "we took your money" and "here is what to buy".
	local function nextCapUpgrade(profile)
		local level = sessions(profile).offlineCapLevel + 1
		local hours = O.CapUpgradeHours[level]
		if not hours then
			return nil
		end
		return {
			level = level,
			hours = hours,
			cost = O.CapUpgradeCost[level],
			name = ("Vault Timer %d"):format(level),
			label = ("Vault Timer %d — banks %dh offline instead of %dh"):format(
				level, hours, SessionService.offlineCapHours(profile)),
		}
	end

	--- What they earned while away. Returns nil when there is nothing worth
	--- showing a panel for — that is a real answer, not a failure.
	local function computeOffline(profile)
		local lastSeen = math.floor(tonumber(profile.lastSeen) or 0)
		if lastSeen <= 0 then
			return nil            -- no recorded logout: a save from before this shipped, or a first session
		end

		local away = os.time() - lastSeen
		-- A clock that went backwards (host migration, NTP correction) must pay
		-- nothing rather than something huge with a sign error in it.
		if away < O.MinimumSeconds then
			return nil
		end

		local perSecond = SessionService.incomePerSecondFor(profile)
		if perSecond <= 0 then
			return nil            -- no factory yet; there is nothing to have missed
		end

		local capSeconds = SessionService.offlineCapHours(profile) * 3600
		local credited = math.min(away, capSeconds)
		local earned = math.floor(credited * perSecond * O.Rate)
		if earned <= 0 then
			return nil
		end

		return {
			seconds = away,
			creditedSeconds = credited,
			earned = earned,
			rate = O.Rate,
			perSecond = perSecond,
			capHours = capSeconds / 3600,
			clipped = away > capSeconds,
			lost = math.max(0, math.floor((away - credited) * perSecond * O.Rate)),
			upgrade = nextCapUpgrade(profile),
		}
	end

	--- The pending welcome-back grant, or nil. A getter over the live table,
	--- because the vault gauge has to know whether there is anything IN the vault
	--- and `live` is file-local on purpose.
	function SessionService.pendingOffline(player: Player)
		local entry = live[player]
		return entry and entry.offline or nil
	end

	--- invariant: WHAT THE VAULT IS WORTH, in one formula with two modes falling
	--- out of it. design:D-01 for what the gauge is for.
	---
	--- Capacity is the most this profile can bank in a single absence: its offline
	--- income per second, for as many hours as its Vault Timer allows. That number
	--- is the PROMISE the gauge makes while you are standing on the plot — "leaving
	--- now banks this much" — and it is the denominator of the fill.
	---
	--- `banked` is what is actually sitting there, which is zero for everyone who
	--- has not just arrived. So the same call answers both halves: an online player
	--- reads an empty column against a big promise, and a returning one reads a
	--- full column against the grant waiting in it.
	---
	--- NOTE WHICH INCOME. incomePerSecondFor, never Tycoon:incomePerSecond — the
	--- boost, the weekend and the friend bonus all reach the latter and are
	--- deliberately excluded from the former. Quoting the boosted rate here would
	--- have the vault promise an offline payout at a rate offline will never pay,
	--- which is a worse bug than quoting nothing.
	function SessionService.vaultProjectionFor(profile, banked: number?)
		local perSecond = SessionService.incomePerSecondFor(profile)
		local capHours = SessionService.offlineCapHours(profile)
		local capacity = perSecond * O.Rate * capHours * 3600
		banked = math.max(0, tonumber(banked) or 0)

		-- FillMin is the floor rather than zero because the gauge is a physical
		-- part: see Tycoon.MIN_PART. An empty factory has capacity 0 and would
		-- divide by it, so it takes the same floor from the other direction — an
		-- empty vault and a vault with nothing in it look the same, which they are.
		local fraction = O.Vault.FillMin
		if capacity > 0 then
			fraction = math.clamp(banked / capacity, O.Vault.FillMin, 1)
		end

		return {
			perSecond = perSecond,
			rate = O.Rate,
			capHours = capHours,
			capacity = capacity,
			banked = banked,
			fraction = fraction,
		}
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- daily streak
	-- ─────────────────────────────────────────────────────────────────────────────

	local function dailyRewardFor(streak: number)
		-- the ladder loops, so day 8 restarts at day 1's payout and the MILESTONES
		-- carry the long tail
		local index = ((math.max(1, streak) - 1) % #S.DailyRewards) + 1
		local base = S.DailyRewards[index]
		local milestone = S.DailyMilestones[streak]
		return base + (milestone or 0), index, milestone
	end

	--- Streak arithmetic in whole UTC day buckets.
	---
	--- Grace is expressed in buckets rather than hours on purpose: buckets are
	--- coarse (claim at 23:00 and again at 01:00 two buckets later is 26 real
	--- hours), and every rounding error in a grace period should fall on the
	--- player's side. Losing a 20-day streak to one missed evening is how you lose
	--- the player, not the streak.
	local function nextStreak(s): number
		local graceBuckets = 1 + math.floor(S.DailyGraceHours / 24)
		if s.dailyDay <= 0 then
			return 1
		end
		local gap = dayNumber() - s.dailyDay
		if gap <= graceBuckets then
			return s.streak + 1
		end
		return 1
	end

	local function dailyState(profile)
		local s = sessions(profile)
		local streak = nextStreak(s)
		local reward, index, milestone = dailyRewardFor(streak)
		return {
			available = s.dailyDay < dayNumber(),
			streak = s.streak,
			nextStreak = streak,
			dayIndex = index,
			ladder = #S.DailyRewards,
			reward = reward,
			milestone = milestone,
			graceHours = S.DailyGraceHours,
			-- seconds until the next bucket opens, for the "come back in" line
			resetIn = ((dayNumber() + 1) * DAY) - os.time(),
		}
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- playtime ladder
	-- ─────────────────────────────────────────────────────────────────────────────

	local function playtimeReward(index: number): number
		return math.floor(S.PlaytimeRewardBase * (S.PlaytimeRewardGrowth ^ (index - 1)))
	end

	--- The ladder as the panel sees it.
	---
	--- Two different clocks, deliberately: a rung is CLAIMED for the rest of the UTC
	--- day, but the minutes that unlock it are this session's active minutes. So a
	--- rejoin costs you progress toward the next rung rather than handing you back
	--- the ones you already took, which is the whole difference between a daily
	--- engagement ladder and a reconnect button that prints money.
	local function playtimeState(entry: Live, profile)
		local rungs = {}
		for index, minutes in ipairs(S.PlaytimeMinutes) do
			local required = minutes * 60
			local status = "locked"
			if hasClaimedRung(profile, index) then
				status = "claimed"
			elseif entry.activeSeconds >= required then
				status = "ready"
			end
			rungs[index] = {
				index = index,
				minutes = minutes,
				reward = playtimeReward(index),
				status = status,
			}
		end
		return {
			activeSeconds = math.floor(entry.activeSeconds),
			-- seconds until the claimed set rolls over, so the panel can say when
			resetIn = ((dayNumber() + 1) * DAY) - os.time(),
			rungs = rungs,
		}
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- boost + weekend
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Everything the session layer multiplies income by. Registered onto Economy
	--- at start(), so `Economy.multiplier()` — and therefore every payout and
	--- every income/sec readout — picks it up without Economy knowing this file
	--- exists.
	function SessionService.incomeMultiplier(player: Player): number
		local profile = DataService.get(player)
		if not profile then
			return 1
		end
		local mult = 1
		if sessions(profile).boostUntil > os.time() then
			mult *= S.BoostMultiplier
		end
		if isWeekend() then
			mult *= S.WeekendMultiplier
		end
		return mult
	end

	local function boostState(profile)
		local s = sessions(profile)
		local now = os.time()
		return {
			active = s.boostUntil > now,
			secondsLeft = math.max(0, s.boostUntil - now),
			cooldownLeft = math.max(0, s.boostReadyAt - now),
			multiplier = S.BoostMultiplier,
			duration = S.BoostSeconds,
			cooldown = S.BoostCooldown,
			weekend = isWeekend(),
			weekendMultiplier = S.WeekendMultiplier,
		}
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- rebirth perks
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The four things a rebirth pays, for a given profile's CURRENT rebirth count.
	---
	--- Exposed rather than applied wholesale because `Tycoon:rebirth()` is owned by
	--- another track and already applies two of them (it increments
	--- profile.rebirths, which is the multiplier, and resets cash to
	--- Config.Economy.StartingCash). This function is the single description of
	--- all four; Economy.applyRebirthGrants() consumes two more, and the fourth is
	--- the TODO below.
	---
	--- Safe to call with the flag off: you get the shipped behaviour (multiplier
	--- only, default starting cash), which is what makes it usable as the one
	--- source of truth for a HUD.
	function SessionService.rebirthPerksFor(profile)
		local n = math.max(0, math.floor(tonumber(profile and profile.rebirths) or 0))
		local perks = {
			rebirths = n,
			multiplier = Config.Rebirth.MultiplierPerRebirth ^ n,
			startingCash = Config.Economy.StartingCash,
			capacityBonus = 0,
			milestone = nil,
			unlocks = {},
		}
		if not P.RebirthPerks or n == 0 then
			return perks
		end

		-- Geometric like the cost curve it is paid against; a flat per-rebirth
		-- grant is invisible by rebirth four.
		perks.startingCash = math.max(
			Config.Economy.StartingCash,
			math.floor(RP.StartingCashPerRebirth * (RP.StartingCashGrowth ^ (n - 1))))

		-- TODO(capacity): the third grant is a PERMANENT CAPACITY BUMP and it is
		-- the one part of this that cannot be applied from outside the tycoon.
		-- The consumer is `Tycoon:spawnDrop()`, whose guard reads
		--
		--     if self.dropCount >= Config.Economy.MaxDropsPerPlot then
		--
		-- and needs to become
		--
		--     local perks = SessionService.rebirthPerksFor(DataService.get(self.owner))
		--     if self.dropCount >= Config.Economy.MaxDropsPerPlot + perks.capacityBonus then
		--
		-- Tycoon.lua is owned by another track, so the number is computed and
		-- replicated here and is simply not read yet. Belt occupancy is verified
		-- in tools/verify_config.lua, so raising the cap needs that check re-run.
		perks.capacityBonus = math.floor(n / RP.SlotEveryRebirths)

		perks.milestone = RP.Milestones[n]
		-- Every milestone at or below the current count, so a player who somehow
		-- skipped one (a rollback, an admin grant) still owns everything they passed.
		--
		-- DERIVED, NEVER PERSISTED, and that is the whole point. There used to be a
		-- `profile.unlocks` copy of this table, written by Economy.applyRebirthGrants
		-- and read by a `SessionService.hasUnlock` that had no callers — a saved
		-- cache of a pure function of `profile.rebirths`. It could not be right and
		-- it could go wrong: it recorded "mezzanine" forever for everyone who passed
		-- rebirth 2, long after the mezzanine became a button on the factory track,
		-- and no migration would ever have cleared it. Whoever consumes an unlock
		-- asks `rebirthPerksFor(profile).unlocks[id]`, which is recomputed from the
		-- rebirth count and therefore cannot be stale.
		for at, milestone in pairs(RP.Milestones) do
			if n >= at then
				perks.unlocks[milestone.unlock] = milestone.label
			end
		end
		return perks
	end

	--- Detected rather than called: Tycoon:rebirth() is off limits, so the rebirth
	--- count is polled once a second and the extra grants land right behind it.
	local function onRebirthDetected(player: Player, profile, entry: Live)
		local perks = SessionService.rebirthPerksFor(profile)
		local granted = Economy.applyRebirthGrants(player, perks)

		local lines = { ("All payouts x%.2f"):format(perks.multiplier) }
		if granted > 0 then
			table.insert(lines, ("Starting cash %s"):format(Util.abbreviate(granted)))
		end
		if perks.capacityBonus > 0 then
			table.insert(lines, ("+%d permanent slot%s"):format(
				perks.capacityBonus, perks.capacityBonus == 1 and "" or "s"))
		end
		if perks.milestone then
			table.insert(lines, ("Unlocked: %s"):format(perks.milestone.label))
		end

		Economy.notify(player, {
			kind = "rebirth",
			title = ("REBIRTH %d PERKS"):format(perks.rebirths),
			body = table.concat(lines, "  •  "),
		})
		entry.dirty = true
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- replication
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The entire replicated payload for one player. Public because it is also the
	--- answer to "what does the server think my session is", which is the only
	--- useful thing to print when a claim button disagrees with the server.
	function SessionService.stateFor(player: Player)
		local entry = live[player]
		local profile = DataService.get(player)
		if not entry or not profile then
			return nil
		end
		return {
			-- one flag left: the rebirth grants are still a prototype
			enabled = { rebirth = P.RebirthPerks },
			daily = dailyState(profile),
			playtime = playtimeState(entry, profile),
			boost = boostState(profile),
			offline = entry.offline,
			-- The Vault Timer, as a thing you can buy rather than a thing the
			-- welcome-back panel mentions once and then forgets. nil at the top of
			-- the ladder, which is what makes the row disappear.
			capUpgrade = nextCapUpgrade(profile),
			capHours = SessionService.offlineCapHours(profile),
			rebirth = P.RebirthPerks and SessionService.rebirthPerksFor(profile) or nil,
		}
	end

	local function pushState(player: Player)
		local entry = live[player]
		local payload = SessionService.stateFor(player)
		if not entry or not payload then
			return
		end
		entry.dirty = false
		entry.lastPush = os.clock()
		sessionState:FireClient(player, payload)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- claims (server-authoritative; the client sends an intent, never an amount)
	-- ─────────────────────────────────────────────────────────────────────────────

	local function claimOffline(player: Player, entry: Live)
		local pending = entry.offline
		if not pending then
			return
		end
		-- cleared BEFORE the payout so a double-fired remote cannot pay twice
		entry.offline = nil

		Economy.add(player, pending.earned, false)   -- perSecond already carries the rebirth multiplier
		Economy.push(player)
		-- `clipped` is the only reason this event carries a facet at all: whether
		-- the 8-hour cap actually cut someone off is the question that decides
		-- whether the Vault Timer upgrades are worth anything.
		Analytics.onOfflineClaim(player, pending, Economy.get(player))
		Economy.notify(player, {
			kind = "claim",
			title = "OFFLINE TUNG COLLECTED",
			body = ("%s banked from %s away."):format(
				Util.abbreviate(pending.earned), SessionService.describeDuration(pending.seconds)),
		})
		entry.dirty = true
	end

	--- The SECOND way to collect the welcome-back grant: the ProximityPrompt on the
	--- vault, wired by VaultService. Public so that path exists at all, and a thin
	--- wrapper rather than a second implementation — the guard that matters is the
	--- one already inside claimOffline, which clears entry.offline BEFORE it pays.
	--- Two claim paths racing each other is exactly the double-fire that guard was
	--- written for; a prompt held down while the panel button is clicked is now a
	--- reachable way to make them race.
	---
	--- Pushes state itself: the remote path does that at the end of its handler and
	--- the prompt has no handler to do it in, and a panel still offering a grant
	--- that has already been paid is how a player learns the button lies.
	function SessionService.claimOfflineFor(player: Player): boolean
		local entry = live[player]
		if not entry or not entry.offline then
			return false
		end
		claimOffline(player, entry)
		pushState(player)
		return true
	end

	--- THE VAULT TIMER. The welcome-back panel has always named the upgrade that
	--- would have prevented the clip; until now there was no way to buy it —
	--- `offlineCapLevel` was clamped and read and never written by anything in the
	--- repo, so the panel advertised a product that did not exist.
	---
	--- Server-authoritative in the same shape as every other claim: the client sends
	--- an INTENT and never an amount, the price comes from Config, and the spend
	--- goes through Economy so there is exactly one place cash is destroyed.
	local function claimCapUpgrade(player: Player, entry: Live, profile)
		local s = sessions(profile)
		local level = s.offlineCapLevel + 1
		local hours, cost = O.CapUpgradeHours[level], O.CapUpgradeCost[level]
		if not hours or not cost then
			return                      -- already own the longest vault timer
		end

		if not Economy.spend(player, cost) then
			-- "warn" rather than a new kind: HUD.lua's KIND_COLOR is the owner of what
			-- a toast looks like, and an unknown kind falls back to the neutral accent
			-- — a refusal that reads like an announcement.
			Economy.notify(player, {
				kind = "warn",
				title = "NOT ENOUGH TUNG",
				body = ("Vault Timer %d costs %s."):format(level, Util.abbreviate(cost)),
			})
			return
		end

		s.offlineCapLevel = level

		-- The pending welcome-back grant was computed against the OLD cap and stays
		-- that way: buying a bigger vault does not retroactively refill it, and
		-- pretending otherwise would make the purchase a way to buy back hours you
		-- already spent. Only the upsell is refreshed, so the panel stops offering a
		-- timer that is now owned.
		if entry.offline then
			entry.offline.upgrade = nextCapUpgrade(profile)
		end

		Economy.notify(player, {
			kind = "gear",
			title = ("VAULT TIMER %d"):format(level),
			body = ("Your factory now banks %d hours offline instead of %d."):format(
				hours, level > 1 and O.CapUpgradeHours[level - 1] or O.CapHours),
		})
		entry.dirty = true
	end

	local function claimDaily(player: Player, entry: Live, profile)
		local s = sessions(profile)
		local today = dayNumber()
		if s.dailyDay >= today then
			return                      -- already claimed in this UTC bucket
		end

		local streak = nextStreak(s)
		local reward, _index, milestone = dailyRewardFor(streak)
		s.streak = streak
		s.dailyDay = today

		-- flat, unmultiplied: a login reward that scales with a 2x boost turns the
		-- boost button into a "wait before claiming" puzzle
		Economy.add(player, reward, false)
		Economy.push(player)
		Economy.notify(player, {
			kind = "claim",
			title = ("DAY %d STREAK"):format(streak),
			body = milestone
				and ("%s — including a %s milestone bonus."):format(Util.abbreviate(reward), Util.abbreviate(milestone))
				or ("%s. Come back tomorrow for more."):format(Util.abbreviate(reward)),
		})
		entry.dirty = true
	end

	local function claimPlaytime(player: Player, entry: Live, profile, index: number)
		local minutes = S.PlaytimeMinutes[index]
		if not minutes or hasClaimedRung(profile, index) then
			return
		end
		if entry.activeSeconds < minutes * 60 then
			return                      -- the client asked early; the server decides
		end

		-- Written into the profile, not into the session. This is the line that
		-- closes the rejoin farm.
		local s = playtimeClaims(profile)
		s.playtimeClaimed = bit32.bor(s.playtimeClaimed, bit32.lshift(1, index - 1))

		local reward = playtimeReward(index)
		Economy.add(player, reward, false)
		Economy.push(player)
		Economy.notify(player, {
			kind = "claim",
			title = ("%d MINUTES PLAYED"):format(minutes),
			body = ("%s. The ladder resets at midnight UTC."):format(Util.abbreviate(reward)),
		})
		entry.dirty = true
	end

	local function claimBoost(player: Player, entry: Live, profile)
		local s = sessions(profile)
		local now = os.time()
		if s.boostReadyAt > now then
			return
		end
		s.boostUntil = now + S.BoostSeconds
		s.boostReadyAt = now + S.BoostCooldown

		Economy.push(player)            -- the multiplier readout changes immediately
		Economy.notify(player, {
			kind = "gear",
			title = ("x%g BOOST ACTIVE"):format(S.BoostMultiplier),
			body = ("All income x%g for %d minutes."):format(S.BoostMultiplier, S.BoostSeconds // 60),
		})
		entry.dirty = true
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- activity
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The playtime ladder is gated on ACTIVITY, not wall clock. Paying for
	--- alt-tabbed minutes prices the reward against nothing and rewards the one
	--- behaviour a session loop exists to avoid.
	---
	--- Two signals, because either alone has a hole: position delta misses someone
	--- holding W into a wall, and MoveDirection misses someone being carried by a
	--- conveyor or a knockback. Neither misses someone actually playing.
	local function sampleActivity(entry: Live, profile, dt: number)
		local character = entry.player.Character
		if not character then
			entry.lastPosition = nil
			return
		end
		local root = character:FindFirstChild("HumanoidRootPart")
		if not root then
			return
		end

		local active = false
		local position = (root :: BasePart).Position
		if entry.lastPosition and (position - entry.lastPosition).Magnitude >= ACTIVITY_STUDS then
			active = true
		end
		entry.lastPosition = position

		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if humanoid and humanoid.MoveDirection.Magnitude > 0.1 then
			active = true
		end

		if active then
			local before = entry.activeSeconds
			entry.activeSeconds += dt
			-- a rung becoming claimable is the moment worth replicating
			for index, minutes in ipairs(S.PlaytimeMinutes) do
				local required = minutes * 60
				if before < required and entry.activeSeconds >= required and not hasClaimedRung(profile, index) then
					entry.dirty = true
					Economy.notify(entry.player, {
						kind = "claim",
						title = ("%d MINUTE REWARD READY"):format(minutes),
						body = ("Claim %s from the session panel."):format(Util.abbreviate(playtimeReward(index))),
					})
				end
			end
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- public
	-- ─────────────────────────────────────────────────────────────────────────────

	--- "2 days, 3 hours" — the panel has to state how long they were away, and
	--- "173,244 seconds" is not that.
	function SessionService.describeDuration(seconds: number): string
		seconds = math.max(0, math.floor(seconds))
		local days = seconds // DAY
		local hours = (seconds % DAY) // 3600
		local minutes = (seconds % 3600) // 60
		if days > 0 then
			return ("%dd %dh"):format(days, hours)
		elseif hours > 0 then
			return ("%dh %dm"):format(hours, minutes)
		elseif minutes > 0 then
			return ("%dm"):format(minutes)
		end
		return ("%ds"):format(seconds)
	end

	--- One beat of one player's session. Pulled out of the loop below so the loop
	--- reads as a loop, and so the whole of this file can be driven a step at a
	--- time from outside Roblox.
	function SessionService.step(player: Player, dt: number)
		local entry = live[player]
		local profile = DataService.get(player)
		if not entry or not profile then
			return
		end

		-- Keep the logout stamp fresh every beat. PlayerRemoving also writes it,
		-- but DataService connects its own PlayerRemoving save first and signal
		-- handler order is not a guarantee — this is what actually makes the
		-- offline calculation correct, and it costs a server crash at most one
		-- second of a player's banked time.
		profile.lastSeen = os.time()

		sampleActivity(entry, profile, dt)

		if P.RebirthPerks then
			local rebirths = math.max(0, math.floor(tonumber(profile.rebirths) or 0))
			if rebirths > entry.rebirths then
				entry.rebirths = rebirths
				onRebirthDetected(player, profile, entry)
			end
		end

		if entry.dirty or os.clock() - entry.lastPush >= PUSH_SECONDS then
			pushState(player)
		end
	end

	function SessionService.onPlayer(player: Player)
		local profile = DataService.get(player) or DataService.load(player)
		if not profile then
			return
		end

		local entry: Live = {
			player = player,
			activeSeconds = 0,
			lastPosition = nil,
			lastClaim = 0,
			offline = nil,
			rebirths = math.floor(tonumber(profile.rebirths) or 0),
			dirty = true,
			lastPush = 0,
		}
		live[player] = entry

		-- Read lastSeen BEFORE stamping it, then stamp it: from here on this
		-- session owns the clock.
		entry.offline = computeOffline(profile)
		profile.lastSeen = os.time()

		-- There used to be a retroactive unlock sync here, replaying every milestone
		-- into `profile.unlocks` on join. It went with the persisted copy: unlocks
		-- are derived from profile.rebirths on every read now, so there is nothing
		-- to backfill and no join-time write to get wrong.

		if entry.offline then
			Economy.notify(player, {
				kind = "welcome",
				title = "WELCOME BACK",
				body = ("Your factory ran for %s while you were gone."):format(
					SessionService.describeDuration(entry.offline.seconds)),
			})
		end

		-- the client's panel is built on the first push, so send one promptly
		task.delay(1, function()
			if live[player] then
				pushState(player)
			end
		end)
	end

	function SessionService.start()
		-- The boost and the weekend bonus reach every payout in the game through
		-- this one hook, so Economy never learns that this file exists.
		Economy.setMultiplierHook("sessions", SessionService.incomeMultiplier)

		requestClaim.OnServerEvent:Connect(function(player, payload)
			local entry = live[player]
			local profile = DataService.get(player)
			if not entry or not profile or type(payload) ~= "table" then
				return
			end
			-- cheap flood guard: the claims below are all idempotent, but a remote
			-- that can be spammed is a remote that will be
			if os.clock() - entry.lastClaim < CLAIM_COOLDOWN then
				return
			end
			entry.lastClaim = os.clock()

			local kind = payload.kind
			if kind == "offline" then
				claimOffline(player, entry)
			elseif kind == "daily" then
				claimDaily(player, entry, profile)
			elseif kind == "playtime" then
				local index = math.floor(tonumber(payload.index) or 0)
				claimPlaytime(player, entry, profile, index)
			elseif kind == "capUpgrade" then
				-- No level and no price in the payload: the server decides which rung
				-- is next and what it costs.
				claimCapUpgrade(player, entry, profile)
			end
			pushState(player)
		end)

		requestBoost.OnServerEvent:Connect(function(player)
			local entry = live[player]
			local profile = DataService.get(player)
			if not entry or not profile then
				return
			end
			if os.clock() - entry.lastClaim < CLAIM_COOLDOWN then
				return
			end
			entry.lastClaim = os.clock()
			claimBoost(player, entry, profile)
			pushState(player)
		end)

		Players.PlayerRemoving:Connect(function(player)
			local profile = DataService.get(player)
			if profile then
				-- Stamped here AND on the tick below. DataService connects its own
				-- PlayerRemoving save before this one and signal handlers are not
				-- ordered guarantees, so the tick is what actually makes this
				-- correct — this line just tightens the last few seconds.
				profile.lastSeen = os.time()
			end
			live[player] = nil
		end)

		-- One loop for everything: a 1-second beat is fine for session state and
		-- keeps the rebirth grant landing visibly right after the rebirth.
		task.spawn(function()
			while true do
				task.wait(1)
				for player in pairs(live) do
					if player.Parent then
						local ok, err = pcall(SessionService.step, player, 1)
						if not ok then
							warn("[Tung] session tick error: " .. tostring(err))
						end
					else
						live[player] = nil
					end
				end
			end
		end)
	end

	return SessionService
end


__MODULES["ShopService"] = function()
	--[[
		ShopService.lua — the storefront for gear (#108).

		design:D-03. The cabinets are gone; weapons and armour sell HERE, and the
		mechanics deliberately did not move an inch: the catalog is the same
		Config.Buttons rows (same ids, same prices, same chains — the tuned week
		walk still spends through them unchanged), a purchase still writes
		profile.owned and still lands as CombatService.grantBat/grantArmor, and
		both grants stay monotonic. What changed is the DOOR: a remote instead of
		a pedestal, so character progression travels with the character.

		TWO DOORS, ONE SHOP. The rail button (client-side, disclosure-gated) and
		the merchant by the spawn — a prompt whose whole job is FireClient
		{ open = true }. The server validates everything on buy: the row must be a
		shop-track row, its chain predecessor owned, its track open
		(Config.trackUnlocked — the dropper3 plot milestone), the shop disclosed,
		and the price paid through Economy.spend.

		The tycoon's `owned` mirror is kept in step when the buyer has a plot, so
		the frontier arithmetic and the replay path agree with the profile — the
		AdminService.give arrangement.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Net = Req("Net")
	local Economy = Req("Economy")
	local DataService = Req("DataService")
	local CombatService = Req("CombatService")
	local DisclosureService = Req("DisclosureService")

	local ShopService = {}

	local remote = Net.event("Shop")

	local SHOP_TRACKS = { weapons = true, armor = true }

	--- Returns (ok, reason); reasons are player-facing. Clock-free and pure over
	--- the profile, so the whole gate runs headless.
	function ShopService.tryBuy(player, id: string): (boolean, string)
		local def = Config.ButtonById[id]
		if not def or not SHOP_TRACKS[def.track] then
			return false, "the shop does not sell that"
		end
		local profile = DataService.get(player)
		if not profile then
			return false, "your save is still loading"
		end
		if profile.owned[id] then
			return false, "you already own that"
		end
		if not DisclosureService.unlocked(player, "shop") then
			return false, "keep building — the shop opens soon"
		end
		if not Config.trackUnlocked(def.track, profile.owned) then
			return false, "keep building — this counter opens soon"
		end
		for _, req in ipairs(Config.requirementsOf(def)) do
			if not profile.owned[req] then
				local blocker = Config.ButtonById[req]
				return false, ("buy %s first"):format(blocker and blocker.name or req)
			end
		end
		if not Economy.spend(player, def.price) then
			return false, ("you need %s more"):format(Util.abbreviate(def.price - Economy.get(player)))
		end

		profile.owned[id] = true
		if def.track == "weapons" then
			CombatService.grantBat(player, def.grants)
		else
			CombatService.grantArmor(player, def.grants)
		end
		Economy.push(player)
		return true, def.name
	end

	function ShopService.start()
		local PlotService = Req("PlotService")

		remote.OnServerEvent:Connect(function(player, payload)
			if type(payload) ~= "table" or payload.action ~= "buy" or type(payload.id) ~= "string" then
				return
			end
			local ok, what = ShopService.tryBuy(player, payload.id)
			Economy.notify(player, { kind = ok and "buy" or "warn", title = "Shop",
				body = ok and ("%s is yours."):format(what) or what })
			if ok then
				-- keep the plot's mirror in step, so the frontier arithmetic and
				-- the rejoin replay agree with the profile
				local tycoon = PlotService.plotOf(player)
				if tycoon then
					tycoon.owned[payload.id] = true
				end
			end
		end)

		-- the merchant: a Tung by the spawn pad whose prompt opens the shop
		local TungModels = Req("TungModels")
		local bearing = math.pi / math.max(Config.plotCountFor(), 1)
		local base = Vector3.new(
			math.sin(bearing) * (Config.World.SpawnRadius - 20),
			Config.World.GroundTopY,
			math.cos(bearing) * (Config.World.SpawnRadius - 20))
		local merchant = TungModels.buildStatue("golden", 1.4)
		merchant.Name = "Merchant"
		merchant:PivotTo(CFrame.new(base + Vector3.new(0, 4, 0)))
		merchant.Parent = workspace

		local anchor = merchant.PrimaryPart or merchant:FindFirstChildWhichIsA("BasePart")
		if anchor then
			local prompt = Instance.new("ProximityPrompt")
			prompt.Name = "OpenShop"
			prompt.ActionText = "Browse"
			prompt.ObjectText = "The Shop"
			prompt.HoldDuration = 0.5
			prompt.MaxActivationDistance = 12
			prompt.RequiresLineOfSight = false
			prompt.Parent = anchor
			prompt.Triggered:Connect(function(player)
				remote:FireClient(player, { open = true })
			end)
		end
	end

	return ShopService
end


__MODULES["SocialService"] = function()
	--[[
		SocialService.lua — who in this server is your friend, and what that is worth.

		GROWTH-TODO item 4: "Nobody has any reason to bring a friend, and Roblox is
		counting." One of the six things the platform scores this place on is
		INTENTIONAL CO-PLAY DAYS — days a person played with a friend through a join,
		an invite or a private server rather than through matchmaking. The repo had
		no social surface whatsoever, so that number was structurally zero.

		This file is the cheap half of the fix: a friend in your server pays +10%
		income each, capped at +30%, with the number on the HUD so another person has
		a visible price tag. The invite button beside it is the other half, and it is
		client-side (SocialService:PromptGameInvite must be called on the client).

		FRIEND DETECTION IS PAIRWISE AND CACHED.

		`Player:IsFriendsWith(userId)` answers one question about one other person.
		Config.World.MaxPlots is 10 and MaxPlayers is set to match, so the whole
		server is at most 45 unordered pairs and one join costs at most 9 calls. Each
		pair is resolved once and cached for the server's lifetime.

		`Players:GetFriendsAsync(userId)` was the obvious alternative and is REJECTED
		here. It returns a paginated FriendPages of unbounded length — a player with
		400 friends is many pages of web calls and many chances to fail — to answer a
		question about at most nine specific user ids we already hold. It becomes the
		right call somewhere north of 30 concurrent players, where the pair count
		stops being small. At ten it is strictly more work and strictly more failure
		surface.

		A FAILED CALL IS NEVER CACHED AS `false`. It is retried. Writing `false` into
		the cache on a web failure would silently delete the bonus for that pair for
		the rest of the session, which is the worst outcome available here: no error,
		no warning anyone reads, and a number on screen that is simply wrong.

		KNOWN LIMITATION: a friendship formed DURING a session is not picked up. The
		cache is keyed on the pair and written once, so two people who add each other
		mid-session keep their old answer until one of them rejoins. Re-polling every
		unfriended pair on a timer would cost a web call per pair per interval to
		catch an event that happens approximately never, and the failure it prevents
		is "you got the bonus one session late".
	]]

	local Req = __Req
	local Config = Req("Config")
	local Net = Req("Net")
	local Economy = Req("Economy")

	local Players = game:GetService("Players")

	local SocialService = {}

	local S = Config.Social

	local socialState = Net.event("SocialState")
	local requestInvite = Net.event("RequestInvite")

	-- ─────────────────────────────────────────────────────────────────────────────
	-- state (per server, never persisted)
	-- ─────────────────────────────────────────────────────────────────────────────

	--- pair key -> true | false. `nil` means UNKNOWN, which is not the same as
	--- `false` and is the single most important distinction in this file.
	local friendship: { [string]: boolean } = {}

	--- The hook below runs on EVERY Economy.add. This is what it reads.
	local count: { [Player]: number } = {}

	--- Friend display names, for the toast and the HUD. Kept beside `count` rather
	--- than derived in the hook, because the hook must not iterate anything.
	local names: { [Player]: { string } } = {}

	local lastInvite: { [Player]: number } = {}

	--- Set for the duration of PlayerRemoving. Roblox still lists a leaving player
	--- in Players:GetPlayers() while that signal runs, so a recount taken from
	--- inside the handler would count the person who is walking out of the door.
	local leaving: { [Player]: boolean } = {}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the pair cache
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Friendship is symmetric, so it is stored once. Sorting the two ids means
	--- key(a, b) == key(b, a) and the cache cannot hold two disagreeing answers
	--- about the same two people.
	local function key(a: number, b: number): string
		if a > b then
			a, b = b, a
		end
		return a .. ":" .. b
	end

	--- The resolve queue. ONE call in flight at a time, ResolveGap apart, because
	--- ten simultaneous joins would otherwise fire 45 web calls inside one frame
	--- and meet the per-player throttle. tools/verify_config.lua asserts that the
	--- fan-out for a single joiner still completes before that joiner's first raid.
	local queue: { { a: Player, b: Player, key: string } } = {}
	local queued: { [string]: boolean } = {}
	local pumping = false
	local pump

	local function enqueue(a: Player, b: Player)
		local k = key(a.UserId, b.UserId)
		if friendship[k] ~= nil or queued[k] then
			return                       -- already known, or already on its way
		end
		queued[k] = true
		table.insert(queue, { a = a, b = b, key = k })
		if not pumping then
			pumping = true
			task.spawn(pump)
		end
	end

	function pump()
		while #queue > 0 do
			-- THE GAP COMES FIRST. Nothing goes out to the web on the same frame as
			-- the join that asked for it — ten people arriving together would
			-- otherwise fire their first nine calls into one tick — and it keeps the
			-- whole feature off the join path, where a yield is a stall.
			task.wait(S.ResolveGap)

			local job = table.remove(queue, 1)
			queued[job.key] = nil
			local a, b = job.a, job.b

			if a.Parent and b.Parent and friendship[job.key] == nil then
				local ok, result = pcall(a.IsFriendsWith, a, b.UserId)
				if ok then
					friendship[job.key] = result == true
					SocialService.recountAll()
				else
					-- NOT cached. Not as false, not as anything. Retried.
					warn(("[Tung] IsFriendsWith(%s, %s) failed: %s — retrying in %ds")
						:format(a.Name, b.Name, tostring(result), S.RetrySeconds))
					task.delay(S.RetrySeconds, function()
						if a.Parent and b.Parent then
							enqueue(a, b)
						end
					end)
				end
			end
		end
		pumping = false
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- counting
	-- ─────────────────────────────────────────────────────────────────────────────

	local function present(player: Player): boolean
		return player.Parent ~= nil and not leaving[player]
	end

	local function friendsPresentFor(player: Player): { string }
		local found = {}
		for _, other in ipairs(Players:GetPlayers()) do
			if other ~= player and present(other) and friendship[key(player.UserId, other.UserId)] then
				table.insert(found, other.DisplayName or other.Name)
			end
		end
		table.sort(found)
		return found
	end

	--- The entire replicated payload for one player. Public for the same reason
	--- SessionService.stateFor is: it is the answer to "what does the server think
	--- my friend count is", which is the only useful thing to print when the number
	--- on the HUD is argued with.
	function SocialService.stateFor(player: Player)
		return {
			friends = count[player] or 0,
			cap = S.MaxFriends,
			bonus = S.BonusPerFriend,
			multiplier = SocialService.incomeMultiplier(player),
			names = names[player] or {},
		}
	end

	local function pushState(player: Player)
		socialState:FireClient(player, SocialService.stateFor(player))
	end

	--- A friend arriving or leaving changes YOUR income at that instant, and an
	--- unexplained income change reads as a bug. Both directions get a toast, and
	--- both reuse the Notify remote the HUD already listens on — zero new client
	--- code, landing at the exact moment the bonus becomes legible.
	local function announce(player: Player, name: string, joined: boolean, total: number)
		local percent = math.floor(math.min(total, S.MaxFriends) * S.BonusPerFriend * 100)
		local body
		if total <= 0 then
			body = "No friend bonus any more. Invite someone."
		else
			body = ("+%d%% income. %d friend%s here."):format(percent, total, total == 1 and "" or "s")
		end
		Economy.notify(player, {
			kind = joined and "claim" or "warn",
			title = ("%s %s"):format(name:upper(), joined and "JOINED" or "LEFT"),
			body = body,
		})
	end

	--- Recount EVERYONE, not just the player who moved.
	---
	--- Friendship is a pair, so one join changes the count of every friend already
	--- in the server as well as the count of the joiner. Recounting only the joiner
	--- is the obvious bug and it fails silently: their HUD is right, everyone
	--- else's is stale, and nobody can tell which one is lying.
	function SocialService.recountAll()
		for _, player in ipairs(Players:GetPlayers()) do
			if present(player) then
				local before = names[player] or {}
				local after = friendsPresentFor(player)

				local was = {}
				for _, name in ipairs(before) do
					was[name] = true
				end
				local is = {}
				for _, name in ipairs(after) do
					is[name] = true
				end

				names[player] = after
				count[player] = #after

				local changed = #before ~= #after
				for _, name in ipairs(after) do
					if not was[name] then
						changed = true
						announce(player, name, true, #after)
					end
				end
				for _, name in ipairs(before) do
					if not is[name] then
						changed = true
						announce(player, name, false, #after)
					end
				end

				if changed then
					pushState(player)
					-- the multiplier readout in the cash panel moved too
					Economy.push(player)
				end
			end
		end
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the multiplier
	-- ─────────────────────────────────────────────────────────────────────────────

	--- invariant: what the friend layer multiplies income by. Registered onto
	--- Economy under its own key at start(), so it STACKS with the session hook
	--- rather than overwriting it.
	---
	--- THIS RUNS ON EVERY Economy.add — up to ~10 times a second per plot at
	--- endgame, times ten plots. It is one table read and two arithmetic ops, and
	--- it must stay that way. Never a web call, never an iteration over
	--- Players:GetPlayers(); that is what `count` is maintained for.
	---
	--- IT DOES NOT BANK WHILE LOGGED OUT. design:D-01.
	--- `SessionService.incomePerSecondFor` derives offline income from the
	--- persisted plot and deliberately never calls `Economy.multiplier`, which is
	--- what excludes the boost and the weekend bonus too. The spec pins it.
	function SocialService.incomeMultiplier(player: Player): number
		return 1 + math.min(count[player] or 0, S.MaxFriends) * S.BonusPerFriend
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- lifecycle
	-- ─────────────────────────────────────────────────────────────────────────────

	function SocialService.onPlayer(player: Player)
		count[player] = count[player] or 0
		names[player] = names[player] or {}

		for _, other in ipairs(Players:GetPlayers()) do
			if other ~= player and present(other) then
				enqueue(player, other)
			end
		end

		-- Push immediately with what is known so far — usually zero — rather than
		-- waiting on the web. The zero state is the one the invite button lives on,
		-- and it is the state this whole feature exists to interrupt.
		SocialService.recountAll()
		pushState(player)
	end

	local function onPlayerRemoving(player: Player)
		leaving[player] = true
		count[player] = nil
		names[player] = nil
		lastInvite[player] = nil
		-- The pair cache is NOT dropped. It is keyed on user ids and valid for the
		-- server's lifetime, so a player who rejoins costs no web calls at all.
		SocialService.recountAll()
		leaving[player] = nil
	end

	function SocialService.start()
		-- THE KILL SWITCH. There is no Config.Prototypes flag for this feature (the
		-- verifier asserts every remaining flag ships false, and the precedent is
		-- that a flag is a thing you delete); zeroing the bonus is what turns it
		-- off, and it does so by never registering the hook rather than by
		-- registering one that returns 1 ten times a second.
		if S.BonusPerFriend <= 0 then
			return
		end

		-- Keyed, so it stacks with SessionService's "sessions" hook instead of
		-- silently replacing it.
		Economy.setMultiplierHook("friends", SocialService.incomeMultiplier)

		Players.PlayerAdded:Connect(SocialService.onPlayer)
		Players.PlayerRemoving:Connect(onPlayerRemoving)

		-- The client owns the prompt (PromptGameInvite is a client call), so this
		-- remote carries nothing and is trusted with nothing. It exists so the
		-- server has a per-player floor on how often it can be fired — the same
		-- shape as SessionService's CLAIM_COOLDOWN guard — and somewhere to hang
		-- an invite analytics event when item 8 lands.
		requestInvite.OnServerEvent:Connect(function(player)
			local now = os.clock()
			local last = lastInvite[player]
			if last and now - last < S.InviteCooldown then
				return
			end
			lastInvite[player] = now
		end)

		for _, player in ipairs(Players:GetPlayers()) do
			SocialService.onPlayer(player)
		end
	end

	return SocialService
end


__MODULES["TowerService"] = function()
	--[[
		TowerService.lua — the daily tower (#95).

		design:D-04. Combat with a shape: Config.towerFloors deals the day's
		composition from the UTC day number, a party (#102) or a lone player
		climbs it, each floor pays every member minutes of their OWN income on
		the spot, and a wipe keeps what it cleared. The top floor is always the
		boss.

		THE LEDGER AND THE RUN ARE SPLIT, the RecallService arrangement. today(),
		bestFloor and recordClear are arithmetic over clocks and profiles and run
		headless; the run driver — the platform in the sky, the spawns through
		NPCService.spawn, the timers, the wipe detection — needs characters and a
		workspace and lives below start(). The handoff owns proving it in Studio.

		FLOORS FIGHT ON A PLATFORM AT PlatformY, one platform per concurrent run,
		spaced along X. Enemies are ordinary Sahur through the one minting site,
		leashed to the platform; falling off the edge is the survival floor's
		failure mode and the platform is sized so that is a choice.

		ENTRY IS A PROMPT ON THE SPIRE at the core's edge. The prompt brings the
		presser's whole party; solo is a party of one. No remote: the intent has
		no payload, the CollectOffline argument.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Net = Req("Net")
	local Economy = Req("Economy")
	local DataService = Req("DataService")
	local SessionService = Req("SessionService")
	local PartyService = Req("PartyService")

	-- Resolved in start(): the run driver's dependency, and the spec bundle
	-- carries neither NPCService nor the workspace the driver needs.
	local NPCService = nil

	local TowerService = {}

	local T = Config.Tower

	--- The UTC day number — the weekend bonus's clock, so the tower and the
	--- weekend agree on when a day turns.
	function TowerService.today(now: number): number
		return math.floor(now / 86400)
	end

	--- The best floor this player has reached TODAY; yesterday's number reads as
	--- zero by arithmetic.
	function TowerService.bestFloor(player: Player, now: number): number
		local profile = DataService.get(player)
		if not profile or not profile.tower then
			return 0
		end
		return profile.tower.day == TowerService.today(now) and profile.tower.best or 0
	end

	--- One member's pay for one cleared floor: minutes of their OWN income rate,
	--- through the capped door like every other inflow. Progress persists as
	--- today's best.
	function TowerService.recordClear(player: Player, floor: number, now: number, bonusMinutes: number?): number
		local profile = DataService.get(player)
		if not profile then
			return 0
		end
		local reward = math.floor((T.FloorRewardMinutes + (bonusMinutes or 0)) * 60
			* SessionService.incomePerSecondFor(profile))
		local gained = Economy.add(player, reward, false)
		profile.tower = {
			day = TowerService.today(now),
			best = math.max(TowerService.bestFloor(player, now), floor),
		}
		Economy.push(player)
		return gained
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the run driver: everything below needs a workspace
	-- ─────────────────────────────────────────────────────────────────────────────

	local runs: { any } = {}   -- slot index -> run or nil
	local deckLabel = nil      -- the spire sign's rows; painted per day

	local function platformOrigin(slot: number): Vector3
		return Vector3.new((slot - 1) * T.PlatformSize * 3, T.PlatformY, 0)
	end

	local function membersOf(player: Player): { Player }
		local party = PartyService.partyOf(player)
		if party then
			return table.clone(party)
		end
		return { player }
	end

	--- The banner's packet (#145): pushed to every member on floor events.
	--- secondsLeft rather than a deadline, because the client's clock is not
	--- this server's.
	local function pushRun(run, over: boolean?)
		local now = os.clock()
		local secondsLeft = nil
		if run.surviveUntil then
			secondsLeft = math.max(0, math.ceil(run.surviveUntil - now))
		elseif run.floorDeadline and run.floorDeadline ~= math.huge then
			secondsLeft = math.max(0, math.ceil(run.floorDeadline - now))
		end
		for _, member in ipairs(run.members) do
			if member.Parent then
				Net.event("TowerState"):FireClient(member, {
					floor = run.floor,
					total = T.Floors,
					archetype = run.deck[run.floor],
					modifier = run.modifier and run.modifier.name or nil,
					secondsLeft = secondsLeft,
					best = TowerService.bestFloor(member, os.time()),
					over = over or nil,
				})
			end
		end
	end

	local function notifyRun(run, payload)
		for _, member in ipairs(run.members) do
			if member.Parent then
				Economy.notify(member, payload)
			end
		end
	end

	--- A member is still climbing while alive and on the platform's level.
	local function livingMembers(run): number
		local count = 0
		for _, member in ipairs(run.members) do
			local character = member.Parent and member.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if humanoid and root and humanoid.Health > 0
					and math.abs(root.Position.Y - T.PlatformY) < 80 then
				count += 1
			end
		end
		return count
	end

	local function teleportRun(run)
		for index, member in ipairs(run.members) do
			local character = member.Parent and member.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if root then
				root.CFrame = CFrame.new(run.origin + Vector3.new(index * 4 - 8, 4, T.PlatformSize / 3))
			end
		end
	end

	local function endRun(run, cleared: boolean)
		runs[run.slot] = nil
		pushRun(run, true)
		for npc, entry in pairs(NPCService.activeEntries()) do
			if entry.tower == run then
				local humanoid = npc:FindFirstChildOfClass("Humanoid")
				if humanoid then
					humanoid.Health = 0
				end
			end
		end
		if run.platform then
			run.platform:Destroy()
		end
		notifyRun(run, { kind = cleared and "boss" or "wave",
			title = cleared and "TOWER CLEARED" or "THE TOWER HOLDS",
			body = cleared and "Every floor, down. Come back tomorrow."
				or ("You fell on floor %d. Cleared floors stay paid."):format(run.floor) })
		-- home, the placement everything uses
		local PlotService = Req("PlotService")
		for _, member in ipairs(run.members) do
			if member.Parent then
				PlotService.teleportToPlot(member)
			end
		end
	end

	local function spawnFloor(run)
		local archetype = run.deck[run.floor]
		local level = Config.towerLevel(run.floor)
		local record = { number = level, alive = 0, spawned = 0 }
		run.record = record
		run.floorDeadline = archetype == "timed" and (os.clock() + T.TimedSeconds) or math.huge
		run.surviveUntil = archetype == "survival" and (os.clock() + T.SurvivalSeconds) or nil

		local count = archetype == "boss" and 1 or (T.WaveCount + #run.members - 1)
		if archetype == "survival" then
			count = math.max(2, math.floor(count / 2))
		end
		local modifier = run.modifier or {}
		for i = 1, count do
			local angle = (i / count) * math.pi * 2
			local radius = T.PlatformSize / 2 - 8
			local position = run.origin + Vector3.new(math.sin(angle) * radius, 6, math.cos(angle) * radius)
			local entry = NPCService.spawn({
				level = level,
				boss = archetype == "boss",
				position = position,
				home = run.origin + Vector3.new(0, 2, 0),
				leash = T.PlatformSize,
				record = record,
				index = i,
				count = count,
				despawnAt = os.clock() + 600,
				healthScale = modifier.healthScale,
				walkScale = modifier.walkScale,
			})
			entry.tower = run
		end

		local what = ({
			wave = ("floor %d — clear the pack"):format(run.floor),
			boss = ("floor %d — the boss"):format(run.floor),
			timed = ("floor %d — %d kills in %ds"):format(run.floor, count, T.TimedSeconds),
			survival = ("floor %d — survive %ds"):format(run.floor, T.SurvivalSeconds),
		})[archetype]
		notifyRun(run, { kind = "wave", title = "THE TOWER", body = what })
		pushRun(run)
	end

	local function stepRun(run)
		local now = os.clock()
		if livingMembers(run) == 0 then
			endRun(run, false)
			return
		end
		-- the banner's countdown rides the step beat; only clocked floors repush
		if run.surviveUntil or (run.floorDeadline and run.floorDeadline ~= math.huge) then
			pushRun(run)
		end
		local archetype = run.deck[run.floor]
		local clearedFloor = false
		if archetype == "survival" then
			clearedFloor = now >= run.surviveUntil
		else
			clearedFloor = run.record.alive <= 0
			if archetype == "timed" and now >= run.floorDeadline and not clearedFloor then
				endRun(run, false)
				return
			end
		end
		if clearedFloor then
			-- a survival floor is cleared by the CLOCK, so its pack can outlive
			-- it; the leftovers die before the next floor deals its own
			for npc, entry in pairs(NPCService.activeEntries()) do
				if entry.waveRecord == run.record and not entry.dead then
					local humanoid = npc:FindFirstChildOfClass("Humanoid")
					if humanoid then
						humanoid.Health = 0
					end
				end
			end
			local bonus = (run.modifier and run.modifier.bonusMinutes) or 0
			for _, member in ipairs(run.members) do
				if member.Parent then
					local gained = TowerService.recordClear(member, run.floor, os.time(), bonus)
					Economy.notify(member, { kind = "claim", title = "Floor cleared",
						body = ("+%s — your %d minutes of income."):format(Util.abbreviate(gained), T.FloorRewardMinutes + bonus) })
				end
			end
			if run.floor >= T.Floors then
				endRun(run, true)
				return
			end
			run.floor += 1
			spawnFloor(run)
		end
	end

	local function buildPlatform(origin: Vector3): Model
		local model = Instance.new("Model")
		model.Name = "TowerFloor"
		local floor = Instance.new("Part")
		floor.Name = "Deck"
		floor.Size = Vector3.new(T.PlatformSize, 2, T.PlatformSize)
		floor.CFrame = CFrame.new(origin)
		floor.Anchored = true
		floor.Color = Color3.fromRGB(58, 52, 74)
		floor.Material = Enum.Material.Slate
		floor.Parent = model
		model.Parent = workspace
		return model
	end

	local function beginRun(presser: Player)
		local slot
		for index = 1, T.MaxConcurrentRuns do
			if not runs[index] then
				slot = index
				break
			end
		end
		if not slot then
			Economy.notify(presser, { kind = "warn", title = "THE TOWER",
				body = "Every climb is taken — try again in a minute." })
			return
		end
		local members = membersOf(presser)
		for _, member in ipairs(members) do
			for _, run in pairs(runs) do
				for _, climber in ipairs(run.members) do
					if climber == member then
						Economy.notify(presser, { kind = "warn", title = "THE TOWER",
							body = "Someone in your party is already climbing." })
						return
					end
				end
			end
		end

		local day = TowerService.today(os.time())
		local run = {
			slot = slot,
			members = members,
			deck = Config.towerFloors(day),
			modifier = Config.towerModifier(day),
			floor = 1,
			origin = platformOrigin(slot),
		}
		runs[slot] = run
		run.platform = buildPlatform(run.origin)
		teleportRun(run)
		spawnFloor(run)
	end

	--- The spire at the core's edge, and the prompt that starts a climb.
	local function buildEntrance()
		local model = Instance.new("Model")
		model.Name = "Tower"
		local bearing = math.pi   -- opposite the spawn pad
		local base = Vector3.new(math.sin(bearing) * T.EntranceRadius, 0, math.cos(bearing) * T.EntranceRadius)
		for storey = 1, 6 do
			local part = Instance.new("Part")
			part.Name = "Spire" .. storey
			local width = 26 - storey * 3
			part.Size = Vector3.new(width, 14, width)
			part.CFrame = CFrame.new(base + Vector3.new(0, storey * 14 - 7, 0))
				* CFrame.Angles(0, storey * 0.2, 0)
			part.Anchored = true
			part.Color = Color3.fromRGB(44, 38, 58)
			part.Material = Enum.Material.Slate
			part.Parent = model
		end
		local door = Instance.new("Part")
		door.Name = "Door"
		door.Size = Vector3.new(8, 10, 2)
		door.CFrame = CFrame.new(base + Vector3.new(0, 5, 14))
		door.Anchored = true
		door.Color = Color3.fromRGB(255, 205, 90)
		door.Material = Enum.Material.Neon
		door.Parent = model

		local prompt = Instance.new("ProximityPrompt")
		prompt.Name = "EnterTower"
		prompt.ActionText = "Climb"
		prompt.ObjectText = "The Tower"
		prompt.HoldDuration = 1
		prompt.MaxActivationDistance = 14
		prompt.RequiresLineOfSight = false
		prompt.Parent = door
		prompt.Triggered:Connect(beginRun)

		-- #145: today's deck, previewed at the door — a party can talk about the
		-- climb before taking it. Repainted when the day turns.
		local Style = Req("Style")
		local billboard = Style.billboard(door, {
			name = "Deck", width = 24, height = 8, distance = "prop", offset = 8,
		})
		deckLabel = Style.text(billboard, {
			name = "Rows", text = "",
			color = Color3.fromRGB(235, 200, 255),
		})

		model.Parent = workspace
	end

	--- The sign's copy for one day: the deck in climb order, and the twist.
	local function paintDeck()
		if not deckLabel then
			return
		end
		local day = TowerService.today(os.time())
		local deck = Config.towerFloors(day)
		local names = {}
		for _, archetype in ipairs(deck) do
			table.insert(names, archetype:upper():sub(1, 4))
		end
		local modifier = Config.towerModifier(day)
		deckLabel.Text = ("THE TOWER  •  today: %s\n%s — %s\na new tower every day")
			:format(table.concat(names, " "), modifier.name, modifier.blurb)
	end

	function TowerService.start()
		NPCService = Req("NPCService")
		buildEntrance()
		paintDeck()
		local paintedDay = TowerService.today(os.time())
		task.spawn(function()
			while true do
				task.wait(1)
				for _, run in pairs(runs) do
					local ok, err = pcall(stepRun, run)
					if not ok then
						warn("[Tung] tower step error: " .. tostring(err))
					end
				end
				local day = TowerService.today(os.time())
				if day ~= paintedDay then
					paintedDay = day
					pcall(paintDeck)
				end
			end
		end)
	end

	return TowerService
end


__MODULES["UpgradeService"] = function()
	--[[
		UpgradeService.lua — PROTOTYPE. Two features that share one profile field:

		  * the player upgrade shop  (Config.Prototypes.PlayerUpgrades)
		  * the utility slot         (Config.Prototypes.Utilities)

		Both are gated; with both flags off every entry point returns on its first
		line and nothing here is ever constructed.

		Server-authoritative in the usual shape: the client may only ever ask. It
		sends RequestUpgrade with an id and gets a fresh UpgradeState back — it is
		never told "yes", it is told what the state now is, so a rejected purchase
		and a lost race look identical from the client's side.

		The utility slot is a KEYBIND, not a second Tool. A Tool would be the
		obvious reading of "second slot", and Roblox's hotbar would carry it for
		free — but only one Tool can be equipped at a time, so firing the utility
		would mean putting the bat away, which is exactly the moment you need it.
		The verbs here (freeze a pack of raiders, shove them off you) are things you
		do mid-swing. So: Q on desktop, an on-screen chip on touch, both routed
		through the UseUtility remote, and the equipped utility is chosen in the
		shop panel rather than by which Tool is in your hand.

		IT OWNS profile.upgrades AND profile.utilityEquipped and is their only writer.
		Both must appear in DataService twice over — in defaultProfile() and in the
		explicit save() payload — because reconcile() iterates the DEFAULT's keys and
		save() builds its own table; a field present in only one of the two is
		invisible in a way nothing reports. See the `profile state` banner below for
		why utilityEquipped defaults to "" and not nil.

		THE FREEZE VERB DEPENDS ON A CONTRACT IN ANOTHER FILE. NPCService's tick writes
		humanoid.WalkSpeed on EVERY Heartbeat, so an external WalkSpeed = 0 survives
		less than a frame; freezeRaider anchors the root assembly instead, precisely
		because that write exists. If NPCService ever moves its WalkSpeed write into a
		branch, this file is what breaks, and it breaks by a raider walking calmly out
		of a freeze rather than by an error.

		AND applySpeed RACES CombatService. Both write the player's WalkSpeed on
		respawn and nothing orders them but Main.server.lua's call sequence, which is
		why onCharacter re-applies a beat later. Do not "clean up" that second call.

		THREE READ APIS HAVE NO CONSUMER YET — magnetRadius, autoCollects and the
		`decoy` verb. Each carries a TODO naming the exact site that should read it
		(Tycoon's collector sweep, Tycoon's vault loop, NPCService's target snapshot),
		and each is deliberately left unconsumed rather than faked here: a decoy that
		teleports raiders would look right for one wave and fight the AI forever.

		WHAT TO READ FIRST. ShopMath owns the level/cost/describe arithmetic and
		the UpgradeById / UtilityById lookups; this file owns persistence,
		authorisation and the verbs. Config.PlayerUpgrades and Config.Utilities sit
		under the PROTOTYPES banner in Config.lua, and tools/verify_config.lua already
		asserts that every utility `requires` a real button, that its duration is
		shorter than its cooldown, and that it has a radius — so a Config edit is
		cheaper to check than to playtest. Nothing in this file is exercised by
		tools/test.py (it is not in SERVER_MODULES) and nothing in it runs in a
		shipping build, so treat both features as unproven at runtime whatever the
		line count suggests.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Fx = Req("Fx")
	local Net = Req("Net")
	local ShopMath = Req("ShopMath")
	local DataService = Req("DataService")
	local Economy = Req("Economy")
	local CombatService = Req("CombatService")

	local Players = game:GetService("Players")
	local Debris = game:GetService("Debris")

	local UpgradeService = {}

	local SHOP_ON = Config.Prototypes.PlayerUpgrades
	local UTILITY_ON = Config.Prototypes.Utilities
	local ENABLED = SHOP_ON or UTILITY_ON

	-- Reach and force are per-verb and live on the Config.Utilities row, because
	-- "how far does the shove reach" is a property of the shove: the moment they
	-- are shared constants the next utility has to fight them.
	local function reachOf(id: string, fallback: number): number
		local def = Config.Utilities and ShopMath.UtilityById[id]
		return (def and def.radius) or fallback
	end
	local function forceOf(id: string, fallback: number): number
		local def = Config.Utilities and ShopMath.UtilityById[id]
		return (def and def.force) or fallback
	end

	local USE_THROTTLE = 0.15       -- floor on UseUtility, independent of cooldowns
	local ICE = Color3.fromRGB(150, 220, 255)

	local upgradeState = Net.event("UpgradeState")
	local requestUpgrade = Net.event("RequestUpgrade")
	local useUtility = Net.event("UseUtility")
	local knockbackRemote = Net.event("Knockback")

	-- os.clock() timestamps, dropped when the player leaves.
	local cooldowns: { [Player]: { [string]: number } } = {}
	local lastUse: { [Player]: number } = {}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- profile state
	--
	-- PERSISTENCE. DataService whitelists what it saves twice over: reconcile()
	-- only copies keys that exist in defaultProfile(), and save() builds an
	-- explicit payload table. A new profile field is invisible until it is added
	-- to BOTH, which is why `upgrades` and `utilityEquipped` appear in each.
	--
	-- utilityEquipped defaults to "" rather than nil, and that matters: reconcile
	-- carries a saved value across only when type(saved[k]) == type(default[k]),
	-- and a nil default is not even iterated by pairs(), so a nil default would
	-- silently discard the field on every load. "" reads as "nothing equipped".
	-- Everything below also tolerates the fields being absent, so a profile saved
	-- before this prototype existed loads either way.
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Levels for BOTH tables live in one map. Ids can't collide (speed/magnet/
	--- payout/autocollect vs freeze/shove/decoy) and it keeps the persistence ask
	--- down to a single new field. A utility is level 0 or 1.
	local function ensure(player: Player)
		local profile = DataService.get(player)
		if not profile then
			return nil
		end
		if type(profile.upgrades) ~= "table" then
			profile.upgrades = {}
		end
		if type(profile.utilityEquipped) ~= "string" then
			profile.utilityEquipped = ""
		end
		-- A save written before a Config edit can carry a level above the new cap,
		-- or an id that no longer exists. Sanitising on read means every consumer
		-- below can trust the number.
		for id, level in pairs(profile.upgrades) do
			local def = ShopMath.UpgradeById[id]
			local utility = ShopMath.UtilityById[id]
			if def then
				profile.upgrades[id] = math.clamp(math.floor(tonumber(level) or 0), 0, def.levels)
			elseif utility then
				profile.upgrades[id] = math.clamp(math.floor(tonumber(level) or 0), 0, 1)
			else
				profile.upgrades[id] = nil
			end
		end
		if profile.utilityEquipped ~= "" and (profile.upgrades[profile.utilityEquipped] or 0) < 1 then
			profile.utilityEquipped = ""
		end
		return profile
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- public read API — for Tycoon / Economy / anyone else
	-- ─────────────────────────────────────────────────────────────────────────────

	function UpgradeService.levelOf(player: Player, id: string): number
		if not ENABLED then
			return 0
		end
		local profile = DataService.get(player)
		if not profile or type(profile.upgrades) ~= "table" then
			return 0
		end
		return tonumber(profile.upgrades[id]) or 0
	end

	--- The value of an upgrade's stat right now (WalkSpeed in studs/sec, magnet
	--- radius in studs, payout as a multiplier…). Level 0 returns the def's base,
	--- so this is safe to call for a player who has bought nothing.
	function UpgradeService.valueOf(player: Player, id: string): number
		local def = ShopMath.UpgradeById[id]
		if not def then
			return 0
		end
		if not SHOP_ON then
			return def.base
		end
		return ShopMath.valueAt(def, UpgradeService.levelOf(player, id))
	end

	--- Cash multiplier from the `payout` track. 1.0 when the prototype is off.
	---
	--- Registered with Economy.setMultiplierHook("upgrades") in start(), so this
	--- folds into every payout beside the rebirth multiplier. The registry is keyed
	--- so the session track's hook and this one compose rather than clobber.
	function UpgradeService.multiplierFor(player: Player): number
		if not SHOP_ON then
			return 1
		end
		return UpgradeService.valueOf(player, "payout")
	end

	--- Pickup radius from the `magnet` track, in studs.
	---
	--- TODO(consumer): Tycoon.lua's collector should sweep drops within this
	--- radius of the owner instead of requiring a touch, or the drop's own
	--- proximity check should widen by it. Tycoon.lua belongs to another track.
	function UpgradeService.magnetRadius(player: Player): number
		if not SHOP_ON then
			return 0
		end
		return UpgradeService.valueOf(player, "magnet")
	end

	--- Whether the vault empties itself.
	---
	--- TODO(consumer): Tycoon.lua's vault loop should, when this is true, pay the
	--- owner out on a timer rather than waiting for them to walk into the
	--- collector. Tycoon.lua belongs to another track.
	function UpgradeService.autoCollects(player: Player): boolean
		if not SHOP_ON then
			return false
		end
		return UpgradeService.levelOf(player, "autocollect") >= 1
	end

	function UpgradeService.equippedUtility(player: Player): string?
		if not UTILITY_ON then
			return nil
		end
		local profile = DataService.get(player)
		local id = profile and profile.utilityEquipped
		if type(id) == "string" and id ~= "" then
			return id
		end
		return nil
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- replication
	-- ─────────────────────────────────────────────────────────────────────────────

	local function cooldownRemaining(player: Player, id: string): number
		local byId = cooldowns[player]
		local readyAt = byId and byId[id]
		if not readyAt then
			return 0
		end
		return math.max(0, readyAt - os.clock())
	end

	function UpgradeService.push(player: Player)
		if not ENABLED or not player.Parent then
			return
		end
		local profile = ensure(player)
		if not profile then
			return
		end

		local levels: { [string]: number } = {}
		local costs: { [string]: number } = {}
		-- utilities gated behind a tycoon button they haven't bought yet, mapped to
		-- the name of the thing that unlocks them so the row can say why it's dead
		local locked: { [string]: string } = {}

		if SHOP_ON then
			for _, def in ipairs(Config.PlayerUpgrades) do
				local level = tonumber(profile.upgrades[def.id]) or 0
				levels[def.id] = level
				-- nil cost means maxed out; the client draws that as "MAX"
				costs[def.id] = ShopMath.costAt(def, level)
			end
		end

		local equipped = ""
		if UTILITY_ON then
			for _, def in ipairs(Config.Utilities) do
				local level = tonumber(profile.upgrades[def.id]) or 0
				levels[def.id] = level
				costs[def.id] = ShopMath.utilityCostAt(def, level)
				if level < 1 and def.requires and not (profile.owned and profile.owned[def.requires]) then
					local button = Config.ButtonById[def.requires]
					locked[def.id] = button and button.name or def.requires
				end
			end
			equipped = profile.utilityEquipped or ""
		end

		local cooldown, cooldownTotal = 0, 0
		if equipped ~= "" then
			local def = ShopMath.UtilityById[equipped]
			cooldown = cooldownRemaining(player, equipped)
			cooldownTotal = def and def.cooldown or 0
		end

		-- The declared payload is { levels, costs }; the rest is additive and a
		-- client that ignores it still draws a correct shop.
		upgradeState:FireClient(player, {
			levels = levels,
			costs = costs,
			locked = locked,
			equipped = equipped,
			-- seconds remaining at the moment this was sent. The client counts it
			-- down locally rather than trusting os.clock() to mean the same thing
			-- on both machines — it doesn't.
			cooldown = cooldown,
			cooldownTotal = cooldownTotal,
		})
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- applying the stat upgrades
	-- ─────────────────────────────────────────────────────────────────────────────

	--- WalkSpeed is the only upgrade with a live effect on the character; the rest
	--- are read by other services through the API above.
	local function applySpeed(player: Player, character: Model?)
		if not SHOP_ON then
			return
		end
		character = character or player.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		if not humanoid then
			return
		end
		humanoid.WalkSpeed = UpgradeService.valueOf(player, "speed")

		-- Mirrored onto the player so anything that wants the stat — the client,
		-- a future Tycoon collector sweep — can read it without a round trip. The
		-- server is still the only writer.
		player:SetAttribute("TungMagnetRadius", UpgradeService.magnetRadius(player))
		player:SetAttribute("TungCashMultiplier", UpgradeService.multiplierFor(player))
		player:SetAttribute("TungAutoCollect", UpgradeService.autoCollects(player))
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the utility verbs
	-- ─────────────────────────────────────────────────────────────────────────────

	--- NPCService parents every raider to workspace.SahurRaiders and exposes no
	--- accessor for the live set, so we read the folder. TODO(NPCService): a
	--- `NPCService.raidersNear(position, radius)` would let this stop reaching
	--- into the workspace by name. The IsSahurNPC attribute check is the same one
	--- CombatService.canDamage uses, so a stray Model in the folder can't be
	--- frozen by accident.
	local function raidersNear(position: Vector3, radius: number): { Model }
		local folder = workspace:FindFirstChild("SahurRaiders")
		local found: { Model } = {}
		if not folder then
			return found
		end
		for _, child in ipairs(folder:GetChildren()) do
			if child:IsA("Model") and child:GetAttribute("IsSahurNPC") then
				local humanoid, root = Util.getRig(child)
				if humanoid and root and humanoid.Health > 0
					and (root.Position - position).Magnitude <= radius
				then
					table.insert(found, child)
				end
			end
		end
		return found
	end

	type FrozenEntry = { root: BasePart, wasAnchored: boolean, thawAt: number, highlight: Highlight? }
	local frozen: { [Model]: FrozenEntry } = {}

	local function thaw(npc: Model)
		local entry = frozen[npc]
		if not entry then
			return
		end
		-- a second freeze landed while this one was pending; let the later one own
		-- the thaw so overlapping casts extend rather than cut each other short
		local remaining = entry.thawAt - os.clock()
		if remaining > 0.05 then
			task.delay(remaining, thaw, npc)
			return
		end
		frozen[npc] = nil
		if entry.highlight then
			entry.highlight:Destroy()
		end
		if entry.root.Parent then
			entry.root.Anchored = entry.wasAnchored
		end
	end

	--- Roots a raider by ANCHORING it, not by zeroing WalkSpeed.
	---
	--- NPCService's tick writes `humanoid.WalkSpeed` on every Heartbeat, so a
	--- WalkSpeed of 0 set from out here survives for less than a frame. Anchoring
	--- the root part anchors the whole welded assembly and no amount of MoveTo
	--- moves it, which is the only way to root a raider without editing
	--- NPCService. Side effect worth knowing: a raider frozen mid-air hangs there
	--- and drops when it thaws, and a frozen raider still swings if you stand in
	--- its reach — freeze buys you movement, not safety.
	local function freezeRaider(npc: Model, seconds: number)
		local humanoid, root = Util.getRig(npc)
		if not humanoid or not root then
			return
		end

		local entry = frozen[npc]
		if entry then
			entry.thawAt = math.max(entry.thawAt, os.clock() + seconds)
			return
		end

		-- Highlights are capped at 255 per client and disabled ones still hold a
		-- slot, so these are created per freeze and destroyed on thaw rather than
		-- living on every raider. A wave is capped well under the limit.
		local highlight = Instance.new("Highlight")
		highlight.FillColor = ICE
		highlight.FillTransparency = 0.55
		highlight.OutlineColor = Color3.fromRGB(235, 250, 255)
		highlight.DepthMode = Enum.HighlightDepthMode.Occluded
		highlight.Adornee = npc
		highlight.Parent = npc

		frozen[npc] = {
			root = root,
			wasAnchored = root.Anchored,
			thawAt = os.clock() + seconds,
			highlight = highlight,
		}
		root.Anchored = true
		Fx.burst(root.Position, ICE, 6, workspace)

		task.delay(seconds, thaw, npc)
	end

	local VERBS: { [string]: (Player, Model, BasePart, any) -> boolean } = {}

	VERBS.freeze = function(player: Player, character: Model, root: BasePart, def): boolean
		local targets = raidersNear(root.Position, reachOf("freeze", 34))
		for _, npc in ipairs(targets) do
			freezeRaider(npc, def.duration)
		end
		Fx.burst(root.Position, ICE, reachOf("freeze", 34) * 0.9, workspace)
		Fx.impact(root, 1.9)
		Economy.notify(player, {
			kind = "info",
			title = "SAHUR FREEZE",
			body = #targets == 0
				and "Nothing in range."
				or ("%d raider%s frozen for %ds."):format(#targets, #targets == 1 and "" or "s", def.duration),
		})
		return true
	end

	VERBS.shove = function(player: Player, character: Model, root: BasePart, def): boolean
		local origin = root.Position
		local pushed = 0

		local function impulseFor(victimRoot: BasePart): Vector3
			local direction = victimRoot.Position - origin
			direction = Vector3.new(direction.X, 0, direction.Z)
			if direction.Magnitude < 0.1 then
				direction = root.CFrame.LookVector * Vector3.new(1, 0, 1)
			end
			direction = direction.Unit
			-- same shape as CombatService.damage's knockback so a shove reads as a
			-- very heavy bat hit rather than as a different physics system
			return (direction * forceOf("shove", 130) + Vector3.new(0, forceOf("shove", 130) * 0.45, 0))
				* victimRoot.AssemblyMass * 0.6
		end

		for _, npc in ipairs(raidersNear(origin, reachOf("shove", 26))) do
			local _, npcRoot = Util.getRig(npc)
			-- A frozen raider is anchored, so an impulse does nothing to it. That
			-- interaction is deliberate: freeze pins them, shove scatters them, and
			-- you have to pick.
			if npcRoot and not npcRoot.Anchored then
				npcRoot:ApplyImpulse(impulseFor(npcRoot))
				pushed += 1
			end
		end

		for _, other in ipairs(Players:GetPlayers()) do
			local otherChar = other.Character
			local victimHumanoid, victimRoot = Util.getRig(otherChar)
			if other ~= player and otherChar and victimHumanoid and victimRoot and victimHumanoid.Health > 0
				and (victimRoot.Position - origin).Magnitude <= reachOf("shove", 26)
				-- Shove deals no damage, but it still displaces someone, so it obeys
				-- the same geography rule as the bat: only inside the arena, never
				-- onto someone standing on their own plot.
				and CombatService.canDamage(player, otherChar)
			then
				-- The victim's client owns their character's physics; a server
				-- ApplyImpulse here is discarded on the next replication tick, so
				-- the impulse is computed on the server and applied by them.
				knockbackRemote:FireClient(other, impulseFor(victimRoot))
				pushed += 1
			end
		end

		Fx.burst(origin, Color3.fromRGB(255, 190, 120), reachOf("shove", 26) * 0.9, workspace)
		Fx.impact(root, 0.7)
		Economy.notify(player, {
			kind = "info",
			title = "TUNG SHOVE",
			body = pushed == 0 and "Nothing in range." or ("Shoved %d."):format(pushed),
		})
		return true
	end

	--- STUB. It builds and shows the decoy, and raiders completely ignore it.
	---
	--- Making it real is a change in NPCService, not here, and that change now has
	--- exactly one site: `refreshSnapshot()` builds the single list of everything
	--- raiders consider a target, and `nearestSnapshotEntry()` reads it. Adding
	--- models tagged IsSahurDecoy to that list — plus a Humanoid on the decoy so
	--- raider swings have something to connect with — is the whole hook.
	---
	--- Left as a stub on purpose: faking it here (e.g. teleporting raiders at the
	--- decoy) would look right for one wave and fight the AI forever after.
	VERBS.decoy = function(player: Player, character: Model, root: BasePart, def): boolean
		local dummy = Instance.new("Part")
		dummy.Name = "TungDecoy"
		dummy.Anchored = true
		dummy.CanCollide = false
		dummy.Material = Enum.Material.Neon
		dummy.Color = Color3.fromRGB(255, 150, 60)
		dummy.Size = Vector3.new(2.4, 5.6, 2.4)
		dummy.CFrame = root.CFrame * CFrame.new(0, 0, -reachOf("decoy", 6))
		dummy:SetAttribute("IsSahurDecoy", true)
		dummy:SetAttribute("Owner", player.UserId)
		dummy.Parent = workspace
		Debris:AddItem(dummy, def.duration)

		Economy.notify(player, {
			kind = "warn",
			title = "DECOY (PROTOTYPE)",
			body = "The decoy spawns, but raiders don't target it yet.",
		})
		return true
	end

	--- Runs the equipped verb if it is off cooldown. Returns whether it fired, so
	--- a refusal never starts a cooldown.
	function UpgradeService.useUtility(player: Player): boolean
		if not UTILITY_ON then
			return false
		end
		local now = os.clock()
		if now - (lastUse[player] or 0) < USE_THROTTLE then
			return false
		end
		lastUse[player] = now

		local id = UpgradeService.equippedUtility(player)
		if not id then
			return false
		end
		local def = ShopMath.UtilityById[id]
		if not def or UpgradeService.levelOf(player, id) < 1 then
			return false
		end
		if cooldownRemaining(player, id) > 0 then
			-- the client hides this case already; a stale or hostile one gets a
			-- state push back so its readout resyncs instead of silence
			UpgradeService.push(player)
			return false
		end

		local character = player.Character
		local humanoid, root = Util.getRig(character)
		if not character or not humanoid or not root or humanoid.Health <= 0 then
			return false
		end

		local verb = VERBS[def.verb]
		if not verb then
			warn(("[Tung] utility %q has no verb implementation"):format(def.verb))
			return false
		end

		local ok, err = pcall(verb, player, character, root, def)
		if not ok then
			warn(("[Tung] utility %s failed: %s"):format(id, tostring(err)))
			return false
		end

		local byId = cooldowns[player]
		if not byId then
			byId = {}
			cooldowns[player] = byId
		end
		byId[id] = os.clock() + def.cooldown
		UpgradeService.push(player)
		return true
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- purchases
	-- ─────────────────────────────────────────────────────────────────────────────

	local function buyUpgrade(player: Player, profile, def): boolean
		local level = tonumber(profile.upgrades[def.id]) or 0
		local cost = ShopMath.costAt(def, level)
		if not cost then
			return false
		end
		if not Economy.spend(player, cost) then
			Economy.notify(player, {
				kind = "warn",
				title = "NOT ENOUGH TUNG",
				body = ("%s costs %s."):format(def.name, Util.abbreviate(cost)),
			})
			return false
		end

		profile.upgrades[def.id] = level + 1
		applySpeed(player)

		Economy.notify(player, {
			kind = "buy",
			title = ("%s  Lv %d"):format(def.name, level + 1),
			body = ShopMath.describe(def, level + 1),
		})
		local _, root = Util.getRig(player.Character)
		if root then
			Fx.burst(root.Position, Color3.fromRGB(190, 130, 255), 8, workspace)
		end
		return true
	end

	--- One remote does buy AND equip: clicking a utility you don't own buys it,
	--- clicking one you do own equips it. The alternative is a second C->S remote
	--- for equipping, and "the row you tap is the utility you get" is a simpler
	--- contract than two verbs on one row.
	local function buyOrEquipUtility(player: Player, profile, def): boolean
		local level = tonumber(profile.upgrades[def.id]) or 0
		if level >= 1 then
			if profile.utilityEquipped == def.id then
				return false
			end
			profile.utilityEquipped = def.id
			Economy.notify(player, {
				kind = "gear",
				title = "EQUIPPED: " .. def.name,
				body = ("Press Q  •  %ds cooldown"):format(def.cooldown),
			})
			return true
		end

		if def.requires and not (profile.owned and profile.owned[def.requires]) then
			local button = Config.ButtonById[def.requires]
			Economy.notify(player, {
				kind = "warn",
				title = "LOCKED",
				body = ("%s needs %s first."):format(def.name, button and button.name or def.requires),
			})
			return false
		end

		if not Economy.spend(player, def.price) then
			Economy.notify(player, {
				kind = "warn",
				title = "NOT ENOUGH TUNG",
				body = ("%s costs %s."):format(def.name, Util.abbreviate(def.price)),
			})
			return false
		end

		profile.upgrades[def.id] = 1
		-- equip it immediately: buying a verb and then having to select it is a
		-- second step nobody expects
		profile.utilityEquipped = def.id
		Economy.notify(player, {
			kind = "gear",
			title = "UTILITY: " .. def.name,
			body = ("Press Q  •  %ds cooldown"):format(def.cooldown),
		})
		return true
	end

	function UpgradeService.request(player: Player, id: string)
		if not ENABLED or type(id) ~= "string" then
			return
		end
		local profile = ensure(player)
		if not profile then
			return
		end

		local upgrade = SHOP_ON and ShopMath.UpgradeById[id]
		local utility = UTILITY_ON and ShopMath.UtilityById[id]
		if upgrade then
			buyUpgrade(player, profile, upgrade)
		elseif utility then
			buyOrEquipUtility(player, profile, utility)
		end

		-- Push regardless of the outcome. The client's own copy of the state is
		-- only ever a redraw of ours, so a rejected click resyncs it rather than
		-- leaving it showing a price it can't pay.
		UpgradeService.push(player)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- lifecycle
	-- ─────────────────────────────────────────────────────────────────────────────

	function UpgradeService.onPlayer(player: Player)
		if not ENABLED then
			return
		end
		task.spawn(function()
			-- the profile can still be loading on first join; the shop is not worth
			-- blocking the boot for, so wait for it out of band
			local deadline = os.clock() + 12
			while not DataService.get(player) and player.Parent and os.clock() < deadline do
				task.wait(0.25)
			end
			if not player.Parent then
				return
			end
			ensure(player)
			applySpeed(player)
			UpgradeService.push(player)
		end)
	end

	function UpgradeService.onCharacter(player: Player, character: Model)
		if not ENABLED then
			return
		end
		if not character:FindFirstChildOfClass("Humanoid") then
			character:WaitForChild("Humanoid", 10)
		end
		applySpeed(player, character)
		-- CombatService.onCharacter also writes WalkSpeed, and on respawn the order
		-- of the two is not guaranteed by anything stronger than Main's call order.
		-- Re-applying once a beat later is a cheap way to always win that race.
		task.delay(0.75, function()
			if player.Character == character then
				applySpeed(player, character)
			end
		end)
		UpgradeService.push(player)
	end

	function UpgradeService.start()
		if not ENABLED then
			return
		end

		-- Fold the `payout` track into every payout. The registry is keyed so the
		-- session track's own hook and this one compose instead of clobbering each
		-- other, and registering here rather than in Economy keeps Economy from
		-- having to know a prototype exists.
		if SHOP_ON then
			Economy.setMultiplierHook("upgrades", UpgradeService.multiplierFor)
		end

		requestUpgrade.OnServerEvent:Connect(function(player, id)
			UpgradeService.request(player, id)
		end)

		useUtility.OnServerEvent:Connect(function(player)
			UpgradeService.useUtility(player)
		end)

		Players.PlayerRemoving:Connect(function(player)
			cooldowns[player] = nil
			lastUse[player] = nil
		end)

		print(("[Tung] UpgradeService: %d upgrades, %d utilities%s")
			:format(SHOP_ON and #Config.PlayerUpgrades or 0,
				UTILITY_ON and #Config.Utilities or 0,
				UTILITY_ON and "" or " (utility slot off)"))
	end

	return UpgradeService
end


__MODULES["VaultService"] = function()
	--[[
		VaultService.lua — the number on the side of the vault.

		GROWTH-TODO item 3 is "there is no reason to come back tomorrow", and the
		part of it offline earnings does NOT cover is that the payout is invisible
		until after it has already happened. A player who has never been away has no
		evidence that being away pays anything, and a popup at logout is read by
		nobody — it arrives at the exact moment attention has already left. So the
		promise moves onto the plot, all session, as a column you watch and a
		headline you read on your way out: leaving now banks 2.4M over 8h, and that
		number goes up every time you buy a dropper.

		BE HONEST ABOUT WHAT THIS IS. Nothing on a plot literally fills while you
		are away. Config.Economy.OfflineGraceSeconds holds your plot for three
		minutes and then releases it; you usually come back to a DIFFERENT plot and
		Tycoon:assign replays your installs onto it. There is no object accruing in
		your absence, and pretending otherwise would mean lying with an animation.
		What there is, is one formula:

		    capacity = offline income/sec x Offline.Rate x your cap hours x 3600
		    banked   = the pending welcome-back grant, or 0
		    fraction = clamp(banked / capacity, FillMin, 1)

		Online, banked is 0: the column reads empty and the sign reads the promise.
		Returning, banked is the grant SessionService already computed at join: the
		column is full, the sign says what is waiting, and the prompt on the vault
		pays it out while the column drains.

		WHY A THIRD MODULE. SessionService must not require Tycoon or PlotService —
		its whole reason for existing is that it derives income from a SAVED profile
		so an absent player can be paid without a plot to ask — and Tycoon must not
		require SessionService, because Tycoon is required BY it in the other
		direction of the same argument. A leaf that requires all three keeps both

		AND WHY onOwnedChanged RATHER THAN CLAIM TIME. On return you land on a plot
		that is not the one you left, and assign() replays your purchases onto it as
		a sequence. Computing the projection once when the plot is claimed reads a
		factory that is still half-built. The owned-changed seam fires on every one
		of those installs — which is also exactly when the promise changes — so the
		gauge is driven off it, with a slow beat behind it to pick up the things
		that move without a purchase (a rebirth, a Vault Timer, a grant arriving).

		NET MESSAGES: ZERO. Parts and BillboardGuis replicate on their own, the same
		way the buy-button labels and the arena title already do, and the claim goes
		through a ProximityPrompt — a server-side signal with no payload, which
		satisfies "the client sends an intent, never an amount" more strictly than a
		remote can, because there is nothing to validate.

		WHAT IT OWNS: the text and the fill on every plot's vault. It is the only
		caller of Tycoon:setVaultGauge outside Tycoon:release, and it owns `wired` (one
		connection per Tycoon for the life of the server, not one per claim) and
		`draining` (the guard that stops a 5s beat snapping the column back to full
		underneath the payout animation).

		WHAT IT MUST NOT DO: hold or recompute the offline number. SessionService owns
		pendingOffline, vaultProjectionFor and claimOfflineFor, including the
		double-fire guard that clears entry.offline BEFORE paying — this file reads a
		projection and animates it, and the moment it starts keeping its own copy the
		sign and the wallet can disagree. It also must not create a remote; see above.

		READ THE PROTOTYPE-FLAG LINT IN tools/verify.py BEFORE ANYTHING ELSE. It exists
		because of this file: offline earnings graduated, graduating deletes the flag,
		and the three `not P.Offline` guards left behind read as `not nil` and returned
		out of start() forever. The gauge was dead on main with a green build — no
		check, no spec, no warning. The comment on `local O = Config.Offline` below is
		the full story.

		AND KNOW WHAT IS NOT VERIFIED. VaultService is not in tools/test.py's
		SERVER_MODULES: vault_spec.lua covers the projection (SessionService) and the
		gauge geometry (Tycoon), not the wiring in this file. Two things about it have
		only ever been reasoned about, per HANDOFF_v6 §G5 — which lateral face of the
		vault the gauge landed on, since that is derived from the belt's exitDir and a
		gauge facing a wall makes the whole feature invisible; and whether the column
		reads as a vault filling rather than as a bar stuck on a crate. Check the face
		first: it is cheap and it is total. Note also that the gauge is built inside
		Tycoon:buildCollector, which carries a runtime assert that the collector shell
		stays downstream of the belt run-off, so anything that moves the vault body has
		to clear it.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Tycoon = Req("Tycoon")
	local DataService = Req("DataService")
	local SessionService = Req("SessionService")

	local VaultService = {}

	-- `local P = Config.Prototypes` used to live here, and three guards below read
	-- P.Offline. Offline earnings SHIPPED in the round this file was written, and
	-- graduating a feature DELETES its flag -- so P.Offline became nil, `not
	-- P.Offline` became true, and VaultService.start() returned before wiring
	-- anything. The vault gauge was dead on main and nothing said so: no check, no
	-- spec, no warning, and a green build.
	--
	-- The two branches never conflicted, because they touched different files. See
	-- the prototype-flag lint in tools/verify.py, which exists because of this.
	local O = Config.Offline
	local V = O.Vault

	-- Slow on purpose. Everything that changes the promise fires onOwnedChanged;
	-- this beat exists only for what does not — a rebirth landing, a Vault Timer
	-- bought off the panel, and the welcome-back grant appearing a moment after the
	-- plot was claimed.
	local BEAT = 5

	-- Plots whose prompt has been wired. A Tycoon is built once and reused by every
	-- owner it ever has, so the connection must happen once and not once per claim.
	local wired: { [any]: boolean } = {}

	-- Plots currently playing the post-claim drain, so a beat landing mid-animation
	-- does not snap the column back to full underneath it.
	local draining: { [any]: boolean } = {}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the two sentences
	-- ─────────────────────────────────────────────────────────────────────────────

	--- The exit hook. Deliberately in the second person and deliberately about the
	--- FUTURE: the sign is being read by someone who is about to log off.
	local function promise(projection): (string, string)
		return
			("LEAVING NOW BANKS %s OVER %dh"):format(
				Util.abbreviate(math.floor(projection.capacity)), projection.capHours),
			("%dh  •  %d%%  •  %s/sec"):format(
				projection.capHours, projection.rate * 100, Util.abbreviate(projection.perSecond))
	end

	--- The entry hook, read by someone who has just walked back in.
	local function waiting(projection, pending): (string, string)
		return
			("%s WAITING"):format(Util.abbreviate(projection.banked)),
			("hold E at the vault  •  %s away  •  %s/sec"):format(
				SessionService.describeDuration(pending.seconds), Util.abbreviate(projection.perSecond))
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- the gauge
	-- ─────────────────────────────────────────────────────────────────────────────

	--- Recompute one plot's gauge from its owner's saved profile. Cheap enough to
	--- call on every purchase: it is two table walks and no instances.
	function VaultService.refresh(tycoon)
		if draining[tycoon] then
			return
		end
		local player = tycoon.owner
		if not player then
			-- Hands the sign back to Tycoon:updateSign, which paints the free-plot
			-- text on the next pass.
			tycoon:setVaultGauge(0, nil, nil, false)
			return
		end
		local profile = DataService.get(player)
		if not profile then
			return                      -- joined, plot claimed, profile still loading
		end

		local pending = SessionService.pendingOffline(player)
		local projection = SessionService.vaultProjectionFor(profile, pending and pending.earned or 0)

		local headline, detail
		if pending then
			headline, detail = waiting(projection, pending)
		elseif projection.capacity > 0 then
			headline, detail = promise(projection)
		end
		-- capacity 0 leaves headline nil, which hands the board back to
		-- Tycoon:updateSign and its income readout. A plot with no droppers on it
		-- has nothing to promise, and "LEAVING NOW BANKS 0 OVER 8h" is a worse
		-- first thing to read than the sign that was already there.
		tycoon:setVaultGauge(projection.fraction, headline, detail, pending ~= nil)
	end

	--- Pays the grant out and then EMPTIES THE COLUMN IN FRONT OF THE PLAYER.
	---
	--- The drain is the point of the whole feature and not decoration. A popup that
	--- says "you earned 2.4M" is a thing you dismiss; a column of gold visibly
	--- draining into a wallet counting up is the same information delivered as
	--- something you watched happen, and it is what teaches the promise on the sign
	--- is real — which is what makes it worth reading on the way out tomorrow.
	local function collect(tycoon, player: Player)
		if player ~= tycoon.owner or draining[tycoon] then
			return
		end
		local profile = DataService.get(player)
		local pending = SessionService.pendingOffline(player)
		if not profile or not pending then
			return
		end
		-- The double-fire guard lives inside SessionService (entry.offline is
		-- cleared BEFORE the payout), so this can be a straight call — but it
		-- reports whether it actually paid, and animating a drain for a claim that
		-- did not happen would be a lie the player has no way to see through.
		if not SessionService.claimOfflineFor(player) then
			return
		end

		local projection = SessionService.vaultProjectionFor(profile, pending.earned)
		local _, detail = promise(SessionService.vaultProjectionFor(profile, 0))

		draining[tycoon] = true
		task.spawn(function()
			local start = os.clock()
			while true do
				local alpha = math.min((os.clock() - start) / V.PulseSeconds, 1)
				if not tycoon.owner then
					break                 -- left mid-drain; the release already cleared it
				end
				tycoon:setVaultGauge(projection.fraction * (1 - alpha),
					("+%s COLLECTED"):format(Util.abbreviate(pending.earned)), detail, false)
				if alpha >= 1 then
					break
				end
				task.wait(0.05)
			end
			draining[tycoon] = nil
			VaultService.refresh(tycoon)
		end)
	end

	-- ─────────────────────────────────────────────────────────────────────────────
	-- wiring
	-- ─────────────────────────────────────────────────────────────────────────────

	function VaultService.start()
		for _, tycoon in ipairs(Tycoon.all()) do
			if not wired[tycoon] then
				wired[tycoon] = true
				tycoon:onOwnedChanged(VaultService.refresh)
				if tycoon.vaultPrompt then
					tycoon.vaultPrompt.Triggered:Connect(function(player)
						collect(tycoon, player)
					end)
				end
			end
			VaultService.refresh(tycoon)
		end

		task.spawn(function()
			while true do
				task.wait(BEAT)
				for _, tycoon in ipairs(Tycoon.all()) do
					local ok, err = pcall(VaultService.refresh, tycoon)
					if not ok then
						warn("[Tung] vault gauge error on plot " .. tostring(tycoon.index) .. ": " .. tostring(err))
					end
				end
			end
		end)
	end

	return VaultService
end


__MODULES["Belt"] = function()
	--[[
		tycoon/Belt.lua — the conveyor: its geometry, its running surfaces, its
		corner sensors, and the one speed the whole plot runs at.

		A BELT IS A POLYLINE, NOT AN L. `points` is the corner list and everything —
		runs, corner sensors, machines, buttons, flow markers — derives from leg(i),
		so a path with five corners builds exactly like the shipped two-legged one.
		resolvePath CARRIES each leg's outboard side rather than inferring it: the
		inference held only while every leg hugged an outer edge, and it inverted for
		an upper floor's return leg, putting that floor's machines over its walkway
		and its buy buttons out in space.

		NO PER-FRAME WORK, ANYWHERE. Drops are moved by a LinearVelocity in Plane
		mode and handed from leg to leg by one Touched sensor per bend, so an
		N-legged path costs N-1 triggers and no Heartbeat loop over hundreds of
		drops. The corner geometry depends on that: nothing solid stands near the
		belt, every leg's surface runs THROUGH its corner square, and the trim is
		decoration with CanCollide off.

		refreshBeltSpeed is the only writer of self.beltSpeed and it RECOMPUTES from
		the two inputs (additive Belt bonus, multiplicative generator factor) rather
		than accumulating. assign() replays a save by installing every owned button
		in `order`, so a `*=` here would land on the product of every rung instead of
		the top one — the Studio-only assertion in that function is the check that
		would have caught the generator shipping unassigned for two rounds.
	]]

	local Req = __Req
	local Config = Req("Config")
	local TungModels = Req("TungModels")
	local Tycoon = Req("Class")
	local Parts = Req("Parts")

	local RunService = game:GetService("RunService")

	local newPart = Parts.newPart
	local COLORS = Tycoon.COLORS

	local L = Config.Layout

	-- ── belt paths ───────────────────────────────────────────────────────────────

	--- Turns a path definition ({ id, y, points, outboard, collectorAt }) into
	--- resolved legs.
	---
	--- `outboard` is the SIDE each leg's machines stand on: its outboard normal is
	--- sign * (-dir.Z, 0, dir.X). It used to be inferred with
	--- `normal:Dot(midpoint) < 0` — "point away from the plot origin" — which holds
	--- only while every leg hugs an outer edge, and silently inverts for any leg
	--- whose midpoint doesn't. An upper floor's return leg runs back across the
	--- middle of its own deck, where the inferred side flips and puts the machines
	--- over the walkway and the buy buttons out in space. So the side is carried,
	--- not guessed. Both ground legs are +1, which is exactly what the old
	--- heuristic produced.
	local function resolvePath(def, outboard: { number }?)
		outboard = outboard or def.outboard
		local points = def.points
		assert(points and #points >= 2, "a belt path needs at least two points")

		local legs = {}
		for index = 1, #points - 1 do
			local a, b = points[index], points[index + 1]
			local delta = b - a
			local dir = delta.Unit
			local sign = (outboard and outboard[index]) or 1
			legs[index] = {
				a = a,
				b = b,
				dir = dir,
				length = delta.Magnitude,
				normal = Vector3.new(-dir.Z, 0, dir.X) * sign,
			}
		end

		return {
			id = def.id,
			y = def.y or 0,
			legs = legs,
			collectorAt = def.collectorAt,
			surfaces = {},
		}
	end

	-- ── belt ─────────────────────────────────────────────────────────────────────

	--- Builds the running surface, the corner sensors and the flow markers for one
	--- belt path. Called once for the ground floor at construction, and once more
	--- per floor above it — `parent` lets a floor keep its belt in its own folder
	--- so tearing the floor down takes the belt with it.
	function Tycoon:buildBelt(pathIndex: number?, parent: Instance?)
		pathIndex = pathIndex or 1

		local folder = parent
		if not folder then
			folder = Instance.new("Folder")
			folder.Name = "Belt"
			folder.Parent = self.model
			self.beltFolder = folder
			self:registerFactoryFolder(folder)
		end

		local width = L.BeltWidth
		local half = width / 2
		local GUARD = L.BeltGuard
		local surfaceY = L.BeltY
		local legs = self:legCount(pathIndex)

		--[[
			SEAMLESS CORNER, AND NOTHING SOLID NEAR THE BELT.

			The drops are driven by a LinearVelocity in Plane mode, which pins
			their lateral velocity to exactly zero — they physically cannot drift
			sideways off the belt. Side rails were therefore never load-bearing,
			and because each leg's rails ran its FULL length, leg 2's inboard rail
			crossed leg 1's path and vice versa: two solid walls straight across
			the conveyor, plus an 11x11 corner block sitting on the bend. That is
			what the drops were piling up against.

			So: the running surface is the only collidable thing here. The edge
			trim is decoration with CanCollide off, and every leg's surface runs
			THROUGH its corner square so there is no separate plate to seam
			against — the next leg simply starts a little way inside it.
		]]
		local function buildRun(index, fromDist, toDist)
			local length = toDist - fromDist
			local mid = (fromDist + toDist) / 2

			newPart(folder, "BeltBase" .. index, Vector3.new(width + L.BeltBaseProud, surfaceY - 0.2, length),
				self:segmentCF(index, mid, 0, (surfaceY - 0.2) / 2, pathIndex), COLORS.frame, Enum.Material.DiamondPlate)

			local surface = newPart(folder, "BeltSurface" .. index, Vector3.new(width, 0.4, length),
				self:segmentCF(index, mid, 0, surfaceY - 0.2, pathIndex), COLORS.belt, Enum.Material.SmoothPlastic)
			surface.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.02, 0.05, 1, 1)

			local texture = Instance.new("Texture")
			texture.Face = Enum.NormalId.Top
			texture.Texture = "rbxasset://textures/particles/sparkles_main.dds"
			texture.Transparency = 0.75
			texture.StudsPerTileU = 5
			texture.StudsPerTileV = 5
			texture.Color3 = COLORS.beltLine
			texture.Parent = surface

			return surface
		end

		-- invariant: the guard walls. A run on ONE leg, on both sides, ending
		-- flush against the NEIGHBOUR'S surface edge at every bend — half a belt
		-- width from the corner point. design:D-03.
		--
		-- The old rails ran each leg's full length, and because every leg's
		-- surface deliberately overruns its bend by half a belt width (see the
		-- loop below), leg 2's inboard rail crossed leg 1's path and vice versa.
		-- Flush at the neighbour's edge is the longest legal rail: touching is
		-- shared-face, never a wall across the conveyor, and the blunt 8-stud
		-- setback this replaces left seven railless studs downstream of every
		-- bend (#162 tophat).
		--
		-- Two parts a side: a solid kick plate at drop height's underside with a neon
		-- top rail sitting flush on it, so the pair reads as one guard with a lit
		-- cap rather than as two separate bars. The kick is sized off the rail's
		-- centre for exactly that reason — see the note in buildGuard.
		--
		-- NEVER COLLIDABLE. Same contract as the end cap and the flow markers, and
		-- the long argument is in Config.Layout.BeltGuard.
		--
		-- `height` IS THE BAR'S CENTRE, which is what Config says it is and what
		-- the kick plate is sized against: kickHeight is `height - bar/2 - kick`,
		-- so the plate's top lands at exactly the bar's underside and the two
		-- make one continuous guard. This read `height + bar` once and three
		-- things disagreed about one rail — Config documented the centre, the
		-- kick assumed it, the verifier modelled it — while only the builder
		-- added the extra section, floating the rail 0.35 studs clear of its own
		-- plate.
		local function guardPiece(index, fromDist, toDist, side, lateral, name)
			local run = toDist - fromDist
			if run <= Tycoon.MIN_PART then
				return
			end
			local mid = (fromDist + toDist) / 2
			local kickHeight = GUARD.height - GUARD.bar / 2 - GUARD.kick
			local kick = newPart(folder, "Guard" .. name,
				Vector3.new(GUARD.thickness, kickHeight, run),
				self:segmentCF(index, mid, side * lateral, surfaceY + GUARD.kick + kickHeight / 2, pathIndex),
				COLORS.frame, Enum.Material.DiamondPlate, false)
			kick.CanQuery = false
			local bar = newPart(folder, "GuardRail" .. name,
				Vector3.new(GUARD.bar, GUARD.bar, run),
				self:segmentCF(index, mid, side * lateral, surfaceY + GUARD.height, pathIndex),
				COLORS.beltLine, Enum.Material.Neon, false)
			bar.CanQuery = false
			bar.CastShadow = false
		end

		local path = self:beltPath(pathIndex)
		local surfaces = {}
		for index = 1, legs do
			local _, _, _, length = self:leg(index, pathIndex)
			-- The first leg starts a stud behind the first dropper; every other one
			-- starts just INSIDE the corner square its predecessor already covers,
			-- overlapping slightly so the two surfaces share a face rather than
			-- meeting at a hairline seam.
			local fromDist = (index == 1) and -1 or (half - 0.6)
			-- Every leg but the last owns the square at its far end: it runs half a
			-- belt-width past the bend so there is no separate corner plate.
			local toDist = (index == legs) and length or (length + half)
			surfaces[index] = buildRun(index, fromDist, toDist)
			-- The guard is the run pulled back AT EVERY END THAT MEETS ANOTHER LEG,
			-- measured off the surface's own span rather than off the leg's, so a
			-- leg that overruns its bend does not drag its rails over the neighbour.
			--
			-- PULLED BACK AT BENDS ONLY, WHICH IS WHERE THE REASON HOLDS. This set
			-- back both ends of every leg, and the setback's whole argument is about
			-- a neighbour: clear the corner square the surfaces overrun by half a
			-- belt width, and clear the turn sensor's leading face just past the
			-- bend. Leg 1 starts behind the first dropper and the last leg ends at
			-- the collector — no neighbour, no corner square, no sensor at either.
			-- So the ground belt ran its surface -1.0 .. 94.0 with rail only over
			-- 7.0 .. 86.0, and the eight bare studs at each open end were the rule
			-- being applied where its reason had run out.
			local startsAtBend = index > 1
			local endsAtBend = index < legs
			local railLateral = half - GUARD.bite + GUARD.thickness / 2
			for _, side in ipairs({ -1, 1 }) do
				guardPiece(index,
					startsAtBend and half or fromDist,
					endsAtBend and (length - half) or toDist,
					side, railLateral,
					("%d_%s"):format(index, side < 0 and "in" or "out"))
			end
		end
		path.surfaces = surfaces

		-- THE OUTER CORNER FILL (#162 tophat). The flush rails stop at the
		-- neighbour's surface edge, which leaves the bend's OUTER pocket — the
		-- corner square's two outboard edges — open. Two short guard pieces
		-- complete the L, stood a hair outside BOTH surfaces (no bite: there is
		-- no surface under them to bury a face in), so the rail reads continuous
		-- around the turn and still crosses neither conveyor. The outer side is
		-- derived per bend, so a path that turned the other way would fill the
		-- right pocket.
		local cornerLateral = half + GUARD.thickness / 2 + 0.05
		for index = 1, legs - 1 do
			local _, _, dirA, lengthA, normalA = self:leg(index, pathIndex)
			local _, _, dirB, _, normalB = self:leg(index + 1, pathIndex)
			local sideA = ((normalA.X * dirB.X + normalA.Z * dirB.Z) < 0) and 1 or -1
			local sideB = ((normalB.X * dirA.X + normalB.Z * dirA.Z) > 0) and 1 or -1
			local reach = cornerLateral + GUARD.thickness / 2
			guardPiece(index, lengthA - half, lengthA + reach,
				sideA, cornerLateral, ("Corner%d_a"):format(index))
			guardPiece(index + 1, -reach, half,
				sideB, cornerLateral, ("Corner%d_b"):format(index))
		end

		-- Visual end cap behind the first dropper. Non-collidable: nothing should
		-- ever reach it, and if something does we want it to slide off, not wedge.
		local cap = newPart(folder, "BeltCap", Vector3.new(width + L.BeltBaseProud, 1.6, 0.6),
			self:segmentCF(1, -1.2, 0, surfaceY + 0.8, pathIndex), COLORS.metal, Enum.Material.Metal, false)
		cap.CanQuery = false

		-- One trigger per bend, spanning the belt, handing a drop from leg i's
		-- direction to leg i+1's. No geometry, just a retarget — so an N-legged
		-- path costs N-1 triggers and still no per-frame work.
		for index = 1, legs - 1 do
			local _, _, _, length = self:leg(index, pathIndex)
			-- Widened like the others, but SHIFTED DOWNSTREAM by half the extra so
			-- its leading face stays where it was. An early trigger is harmless at
			-- an upgrader or the collector; at a corner it retargets the drop
			-- before it has reached the corner, which cuts it and puts it on the
			-- next leg off-centre.
			local turn = newPart(folder, "TurnSensor" .. index,
				Vector3.new(width + 1, 6, L.TriggerThickness),
				self:segmentCF(index, length + (L.TriggerThickness - 2.5) / 2, 0, surfaceY + 3, pathIndex),
				Color3.new(1, 1, 1), Enum.Material.Neon, false)
			turn.Transparency = 1
			turn.CanQuery = false
			turn.CanTouch = true
			turn.Touched:Connect(function(hit)
				self:onTurn(hit, pathIndex, index)
			end)
		end

		self:buildFlowMarkers(folder, pathIndex)
	end

	--- Chevrons painted on the floor beside the belt, pointing downstream.
	---
	--- An L-shaped conveyor with machinery on both sides does not tell you which
	--- end is the start. Following the arrows takes you from the first dropper to
	--- the vault, which is also the order the buy buttons come in — so "walk the
	--- arrows" is the whole tutorial for reading a plot.
	function Tycoon:buildFlowMarkers(parent: Instance, pathIndex: number?)
		local SPACING = 18
		local INBOARD = -(L.BeltWidth / 2 + 2.5)   -- clear of the belt, clear of the buttons

		for legIndex = 1, self:legCount(pathIndex) do
			local _, _, _, length = self:leg(legIndex, pathIndex)
			local at = SPACING * 0.5
			while at < length do
				-- two bars meeting at a point: a wedge read from above is just a
				-- rectangle, so the arrowhead has to be drawn rather than modelled
				for _, side in ipairs({ 1, -1 }) do
					local bar = newPart(parent, "Flow", Vector3.new(0.7, 0.25, 4),
						self:segmentCF(legIndex, at, INBOARD, 0.12, pathIndex)
							* CFrame.new(side * 1.1, 0, -1.1)
							* CFrame.Angles(0, math.rad(side * 32), 0),
						COLORS.beltLine, Enum.Material.Neon, false)
					bar.Transparency = 0.25
					bar.CanQuery = false
					bar.CanTouch = false
				end
				at += SPACING
			end
		end
	end

	--- Hands a drop from leg `fromLeg` of a path onto leg `fromLeg + 1`. Every
	--- corner on every floor shares this; the sensor closes over which one it is,
	--- so nothing here knows how many legs the path has.
	function Tycoon:onTurn(hit: BasePart, pathIndex: number, fromLeg: number)
		local drop = hit.Parent
		if not drop or not drop:IsA("Model") then
			return
		end
		if drop:GetAttribute("PlotIndex") ~= self.index then
			return
		end
		-- Drops that predate multi-floor have no Path attribute; treat them as the
		-- ground floor rather than dropping them on the corner.
		if (drop:GetAttribute("Path") or 1) ~= pathIndex or drop:GetAttribute("Leg") ~= fromLeg then
			return
		end
		local toLeg = fromLeg + 1
		drop:SetAttribute("Leg", toLeg)

		local body = drop.PrimaryPart
		if not body then
			return
		end
		local mover = body:FindFirstChild("BeltMover")
		local upkeep = body:FindFirstChild("StayUpright")
		local direction = self:legDirectionWorld(toLeg, pathIndex)

		if mover and mover:IsA("LinearVelocity") then
			mover.PrimaryTangentAxis = direction
			mover.SecondaryTangentAxis = self:legNormalWorld(toLeg, pathIndex)
			mover.PlaneVelocity = Vector2.new(self.beltSpeed, 0)
		end

		-- SNAP THE VELOCITY, never just the constraint (#162 tophat). Retargeting
		-- the plane leaves the drop's momentum pointing down the OLD leg, and the
		-- constraint has to grind all of it away as lateral error with MaxForce —
		-- which fits inside the corner square at the shipped speed and shoots the
		-- drop out the side of the bend at power3's. Setting the assembly's real
		-- velocity makes the turn exact at any speed; the vertical component is
		-- kept so a drop mid-settle does not have its fall erased.
		body.AssemblyLinearVelocity = direction * self.beltSpeed
			+ Vector3.new(0, body.AssemblyLinearVelocity.Y, 0)

		if upkeep and upkeep:IsA("AlignOrientation") then
			upkeep.CFrame = TungModels.dropOrientation(direction)
		end
	end

	-- ── belt geometry ────────────────────────────────────────────────────────────
	-- A belt is a POLYLINE, not an L. `points` is the corner list and everything —
	-- runs, corner sensors, machines, buttons, flow markers — derives from leg(i),
	-- so a path with five corners builds exactly like the shipped two-legged one.
	-- The ground floor is Config.BeltPaths[1], which is itself written in terms of
	-- Layout.BeltStart / BeltCorner / BeltEnd so the two cannot drift apart.

	--- Registers a belt path and returns its index. Idempotent by id, because a
	--- floor that is torn down and rebuilt must not stack up a second copy of its
	--- own geometry — the path is pure maths, only the parts get rebuilt.
	function Tycoon:addBeltPath(def, outboard: { number }?): number
		for index, existing in ipairs(self.paths) do
			if existing.id == def.id then
				return index
			end
		end
		table.insert(self.paths, resolvePath(def, outboard or def.outboard))
		return #self.paths
	end

	--- Recomputes the plot's belt speed from its two inputs and retargets whatever
	--- is already rolling.
	---
	--- ONE SPEED FOR THE WHOLE PLOT, every floor included: eachBeltSurface walks
	--- every registered path, and the drops read the cached product at spawn and at
	--- each corner. This adds no per-frame work — the retarget below is a one-shot
	--- sweep on purchase, and the "no Heartbeat loop over hundreds of drops" rule
	--- the conveyor is built around still holds.
	function Tycoon:refreshBeltSpeed()
		self.beltSpeed = (L.BeltSpeed + self.beltBonus) * self.powerFactor

		-- THE CHECK THAT WOULD HAVE CAUGHT THE GENERATOR, and it has to live beside
		-- the read rather than in verify_config.lua: the defect was a field declared
		-- in tycoon/Class.lua and assigned nowhere, and the verifier reads Config.lua
		-- and nothing else. Every config-level assertion about the power ladder
		-- passed while the belt ran at stock speed for two rounds. The field is now
		-- written in tycoon/Installers.lua and read here — two files, which is MORE
		-- reason for this assert rather than less.
		--
		-- Recomputed from `owned` and compared against the two cached inputs, so it
		-- fires on a powerFactor that was never set (the shipped bug, 37 instead of
		-- 62.2), on one accumulated across an install replay (78.1), and on a
		-- beltBonus applied after the multiply instead of before it (56).
		if RunService:IsStudio() then
			local want = (L.BeltSpeed + self.beltBonus) * Config.powerFactor(function(id: string): boolean
				return self.owned[id] == true
			end)
			assert(math.abs(self.beltSpeed - want) < 1e-6, ("belt speed is %.2f but this plot's owned set says %.2f")
				:format(self.beltSpeed, want))
		end

		for _, drop in ipairs(self.drops:GetChildren()) do
			local mover = drop:FindFirstChildWhichIsA("LinearVelocity", true)
			if mover then
				mover.PlaneVelocity = Vector2.new(self.beltSpeed, 0)
			end
		end
	end

	--- Seconds between drops for `def` on THIS plot right now.
	---
	--- Read fresh each cycle rather than baked into the loop, so a generator bought
	--- mid-run is picked up on the next drop of every dropper with no loop restart
	--- and no generation bump. NEVER writes def.dropRate: Config.ButtonById tables
	--- are shared by every plot on the server, so mutating one would speed up the
	--- neighbours' factories too.
	function Tycoon:dropInterval(def): number
		local factor = self.powerFactor
		if not factor or factor < 1 then
			factor = 1   -- a zero here would stop every dropper on the plot forever
		end
		return math.max(0.2, def.dropRate / factor)
	end

	function Tycoon:beltPath(pathIndex: number?)
		return self.paths[pathIndex or 1]
	end

	function Tycoon:legCount(pathIndex: number?): number
		return #self:beltPath(pathIndex).legs
	end

	--- start, finish, unit direction, length and the outboard normal of a leg,
	--- all in PLOT-LOCAL space, plus the path it belongs to.
	function Tycoon:leg(index: number, pathIndex: number?)
		local path = self:beltPath(pathIndex)
		local leg = path.legs[index]
		return leg.a, leg.b, leg.dir, leg.length, leg.normal, path
	end

	--- A point `distance` along a leg, offset sideways. Positive offset is
	--- outboard (toward the plot edge), negative is inboard (toward the floor).
	--- The path's own height is baked in, so a leg on the mezzanine lands on the
	--- mezzanine without every caller having to know which floor it is on.
	function Tycoon:pointOnLeg(index: number, distance: number, offset: number, pathIndex: number?): Vector3
		local a, _, dir, _, normal, path = self:leg(index, pathIndex)
		return a + dir * distance + normal * (offset or 0) + Vector3.new(0, path.y, 0)
	end

	function Tycoon:legDirectionWorld(index: number, pathIndex: number?): Vector3
		local _, _, dir = self:leg(index, pathIndex)
		return self.cf:VectorToWorldSpace(dir).Unit
	end

	function Tycoon:legNormalWorld(index: number, pathIndex: number?): Vector3
		local _, _, _, _, normal = self:leg(index, pathIndex)
		return self.cf:VectorToWorldSpace(normal).Unit
	end

	--- Which leg (and which path) a machine lives on: the slot tables split down
	--- their middle across the two mirrored ground paths (#162) — the first half
	--- of each rides the west line, the second half the east — with droppers on
	--- a path's side leg (leg 1) and upgraders on its back leg (leg 2).
	---
	--- A def may pin itself instead, which is how FloorService stands a dropper on
	--- an upper floor without inventing a second slot table.
	function Tycoon:legOf(def): (number, number, number)
		if def.legIndex then
			return def.legIndex, def.legDistance or 0, self:pathIndexOf(def)
		end
		if def.kind == "Dropper" then
			return 1, L.DropperDist[def.slot], def.slot * 2 <= #L.DropperDist and 1 or 2
		end
		return 2, L.UpgraderDist[def.slot], def.slot * 2 <= #L.UpgraderDist and 1 or 2
	end

	--- Which registered path a def means. A button carries `path` as an ID rather
	--- than an index, because the index is assigned at runtime by addBeltPath and
	--- Config has no way to know it. Falls back to the ground floor, which is what
	--- every button without a `path` means.
	function Tycoon:pathIndexOf(def): number
		if def.pathIndex then
			return def.pathIndex
		end
		if def.path then
			for index, path in ipairs(self.paths) do
				if path.id == def.path then
					return index
				end
			end
			warn("[Tung] button " .. tostring(def.id) .. " names belt path " .. tostring(def.path) .. ", which is not registered")
		end
		return 1
	end

	--- World CFrame of a box lying along a leg.
	function Tycoon:segmentCF(index: number, distance: number, offset: number, y: number, pathIndex: number?): CFrame
		local _, _, dir = self:leg(index, pathIndex)
		local point = self:pointOnLeg(index, distance, offset, pathIndex) + Vector3.new(0, y, 0)
		return self.cf * CFrame.lookAt(point, point + dir)
	end

	--- Every live belt surface on the plot, on every floor. Skips destroyed ones:
	--- tearing a floor down leaves its surfaces referenced but dead, and writing a
	--- property on a destroyed part throws.
	function Tycoon:eachBeltSurface(fn: (BasePart) -> ())
		for _, path in ipairs(self.paths) do
			for _, surface in ipairs(path.surfaces) do
				if surface.Parent then
					fn(surface)
				end
			end
		end
	end

	return Tycoon
end


__MODULES["Buttons"] = function()
	--[[
		tycoon/Buttons.lua — the buy buttons: where each one stands, what it says,
		which of its three states it is in, and the ghost of the machine it will
		build.

		THREE STATES, because both obvious designs fail: every button at once gives
		the plot no focal point, and only the next one hides the shape of the build
		from you. available / preview / hidden, with the label's two voices (BTN vs
		BTN_LOCKED) moving five properties together — colour alone is the first
		signal lost to a bright sky or a neon variant standing behind the label.

		refreshButtons IS THE BEAT. It runs on install, assign, release and rebirth,
		plus PlotService's 3-second loop, and it is where ensureCabinets,
		updateCabinetSigns, ensureYard and refreshGenerator hang. Anything that has
		to survive all four of those events, and is idempotent, belongs on this beat
		rather than on a listener of its own; anything expensive does not belong here
		at all.

		buttonBaseCF KEEPS THE HEIGHT. The conversion from a button position to a
		CFrame was written twice and both copies threw the Y away, which put
		everything an upper floor priced on the ground floor underneath its deck. The
		Studio-only assertion in buildButtons is the half of that no config check can
		reach: whether the pad that got built is where buttonPosition said.

		A gated track is HIDDEN, not previewed, and takes no ghost — nine dimmed
		pads with ghost machines on them is the same wall of labels with the
		brightness turned down.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Util = Req("Util")
	local Economy = Req("Economy")
	local Tycoon = Req("Class")
	local Parts = Req("Parts")

	local RunService = game:GetService("RunService")

	local newPart = Parts.newPart
	local MACHINE_MASSES = Parts.MACHINE_MASSES
	local COLORS = Tycoon.COLORS
	local MISC_SPOTS = Tycoon.MISC_SPOTS

	local L = Config.Layout
	local BTN = Config.Style.Button
	local BTN_LOCKED = Config.Style.ButtonLocked

	-- ── buttons ──────────────────────────────────────────────────────────────────

	--- Buy buttons line the INBOARD side of the belt, next to the machine they
	--- build, so the row you walk along is the row you buy from.
	function Tycoon:buttonPosition(def): Vector3
		if def.kind == "Dropper" or def.kind == "Upgrader" then
			local legIndex, distance, pathIndex = self:legOf(def)
			return self:pointOnLeg(legIndex, distance, -L.ButtonOffset, pathIndex)
		end
		-- Dispatched on what KIND of furniture the track has, not on "is it the
		-- factory". Shop tracks (#108) never reach here: buildButtons skips them,
		-- so a shop row has no pedestal and no position to answer.
		local furniture = def.track and Config.TrackInfo[def.track].furniture
		if furniture == "yard" then
			return Config.yardButtonPosition()
		elseif furniture == "land" then
			-- One pedestal per side, on the centre pad. Every rung of a side
			-- resolves here, which is why the land tracks preview 0 rungs.
			return Config.landButtonPosition(def.track)
		end
		return MISC_SPOTS[def.id] or Vector3.new(0, 0, 0)
	end

	--- invariant: where a buy button's pedestal actually stands, HEIGHT INCLUDED.
	---
	--- The conversion from "button position" to "CFrame" was written twice and both
	--- copies threw the Y away — `self:at(pos.X, 0, pos.Z)`. Nothing purchasable
	--- could then stand on an upper floor: everything would be built on the ground
	--- underneath the deck. One line, and it was the single blocker for a real
	--- second storey.
	---
	--- All the sources of a button position can answer with a height.
	--- Config.landButtonPosition answers at ground
	--- level; Layout.MiscButtons is all ground level; and belt buttons come
	--- through pointOnLeg, which bakes in `path.y`.
	---
	--- The Studio-only half is the assertion in buildButtons below: whether the pad
	--- that got built is where buttonPosition said. No config check can reach it.
	function Tycoon:buttonBaseCF(def): CFrame
		local pos = self:buttonPosition(def)
		return self:at(pos.X, pos.Y, pos.Z)
	end

	function Tycoon:buildButtons()
		for _, def in ipairs(Config.Buttons) do
			-- #108: shop rows sell off the plot; no pedestal, no ghost, no entry
			if def.track and Config.TrackInfo[def.track].furniture == "shop" then
				continue
			end
			local base = self:buttonBaseCF(def)

			local holder = Instance.new("Model")
			holder.Name = "Btn_" .. def.id
			holder.Parent = self.buttonsFolder

			-- Total height is Layout.ButtonHeight (1.4 studs). A Roblox humanoid
			-- steps over ~2 studs without jumping, so you can run straight across
			-- these instead of having to hop onto each one.
			local plinth = L.ButtonHeight * 0.55
			newPart(holder, "Pedestal", Vector3.new(5, plinth, 5), base * CFrame.new(0, plinth / 2, 0),
				COLORS.frame, Enum.Material.DiamondPlate)

			local pad = newPart(holder, "Pad", Vector3.new(4.6, L.ButtonHeight - plinth, 4.6),
				base * CFrame.new(0, (L.ButtonHeight + plinth) / 2, 0), COLORS.buttonOn, Enum.Material.Neon)
			pad.CanCollide = false
			pad:SetAttribute("ButtonId", def.id)

			local light = Instance.new("PointLight")
			light.Color = COLORS.buttonOn
			light.Range = 11
			light.Brightness = 1.4
			light.Shadows = false
			light.Parent = pad

			-- NOT AlwaysOnTop. Hiding behind a wall you are on the wrong side of is
			-- correct; hiding behind a machine two feet away is not, and the x-ray
			-- was covering the second case at the cost of the first — every locked
			-- pad on the plot showed through everything, which is most of why the
			-- plot read as a wall of labels. The label clears the machinery on its
			-- own now, by standing above it (Style.Button.lift, asserted against
			-- Layout.MachineTopY).
			local billboard = Style.billboard(pad, {
				name = "Info", width = BTN.width, height = BTN.height,
				distance = BTN.distance, offset = BTN.lift,
			})

			local frame = Instance.new("Frame")
			frame.Size = UDim2.fromScale(1, 1)
			frame.BackgroundColor3 = Color3.fromRGB(20, 16, 30)
			frame.BackgroundTransparency = BTN.panelAlpha
			frame.BorderSizePixel = 0
			frame.Parent = billboard
			Util.roundedFrame(frame, 10)

			local stroke = Instance.new("UIStroke")
			stroke.Color = COLORS.buttonOn
			stroke.Thickness = BTN.strokeThickness
			stroke.Parent = frame

			-- Four lines, in the order you ask the questions: where am I in the
			-- build, what is this, what does it do for me, what does it cost.
			--
			-- The track name, not a global ordinal. "STEP 21 OF 30" on a pedestal
			-- in front of a weapons cabinet tells you nothing; "WEAPONS 2/5" is
			-- the whole feature explained in three words.
			-- The CATEGORY, not the internal chain (#125): "PLOT 20/34" is one of
			-- three kinds of thing, "WEST LAND 5/15" was one of seven ladders.
			local step = Style.text(frame, {
				name = "Step", weight = "body",
				size = UDim2.fromScale(0.94, 0.18), position = UDim2.fromScale(0.03, 0.02),
				text = ("%s %d/%d"):format(
					Config.TrackLabel[def.track] or "STEP", def.categoryOrder or def.trackOrder,
					Config.CategoryCount[def.category] or #Config.Tracks[def.track]),
				color = Color3.fromRGB(150, 142, 172),
			})

			local title = Style.text(frame, {
				name = "Title",
				size = UDim2.fromScale(0.94, 0.32), position = UDim2.fromScale(0.03, 0.2),
				text = def.name, color = Color3.fromRGB(255, 240, 210),
			})

			local effect = Style.text(frame, {
				name = "Effect", weight = "body",
				size = UDim2.fromScale(0.94, 0.22), position = UDim2.fromScale(0.03, 0.52),
				text = def.blurb or "", color = Color3.fromRGB(150, 235, 190),
			})

			local price = Style.text(frame, {
				name = "Price", weight = "body",
				size = UDim2.fromScale(0.94, 0.24), position = UDim2.fromScale(0.03, 0.74),
				color = COLORS.buttonOn,
			})
			price.Text = "$" .. Util.abbreviate(def.price)

			local lastTouch = 0
			pad.Touched:Connect(function(hit)
				if os.clock() - lastTouch < 0.35 then
					return
				end
				lastTouch = os.clock()
				local player = self:playerFromHit(hit)
				if player then
					self:tryPurchase(player, def.id)
				end
			end)

			-- The half of "buttons honour their height" that no config check can
			-- reach: whether the part that got built is actually where
			-- buttonPosition said. Free in production, and it fails loudly the day
			-- somebody reintroduces the flattening on a floor that has content.
			if RunService:IsStudio() then
				local want = (self:buttonBaseCF(def)).Position.Y
				assert(math.abs(pad.Position.Y - want) < L.ButtonHeight + 0.01,
					("[Tung] button %s built at y=%.2f but buttonPosition says y=%.2f")
						:format(def.id, pad.Position.Y, want))
			end

			self.objects[def.id] = {
				def = def,
				holder = holder,
				pad = pad,
				pedestal = holder:FindFirstChild("Pedestal"),
				billboard = billboard,
				frame = frame,
				stroke = stroke,
				priceLabel = price,
				effectLabel = effect,
				stepLabel = step,
				titleLabel = title,
				-- every label the two voices have to fade together
				labels = { step, title, effect, price },
				light = light,
				machine = nil,
				ghost = nil,
			}
		end
	end

	function Tycoon:requirementsMet(id: string): boolean
		local def = Config.ButtonById[id]
		if not def then
			return false
		end
		-- ANDed in here rather than only in refreshButtons, so a stale Touched on a
		-- pad that is about to be hidden cannot buy through the gate.
		if not Config.trackUnlocked(def.track, self.owned) then
			return false
		end
		for _, req in ipairs(Config.requirementsOf(def)) do
			if not self.owned[req] then
				return false
			end
		end
		return true
	end

	--- A translucent stand-in for a machine you haven't bought yet, built from the
	--- same MACHINE_MASSES description as the real thing.
	---
	--- Showing the next few purchases as ghosts turns the plot into a plan you are
	--- filling in, rather than a row of anonymous pads with prices on them. It also
	--- answers the standing complaint about tycoon infrastructure — "why am I
	--- buying walls before I can buy upgraders" stops being a fair question once
	--- you can see the upgraders standing there waiting.
	function Tycoon:buildGhost(def)
		if not MACHINE_MASSES[def.kind] then
			return nil
		end
		local variant = Config.Variants[def.variant] or Config.Variants.classic

		local model = Instance.new("Model")
		model.Name = "Ghost_" .. def.id

		local parts = self:buildMasses(def, model, variant.wood, Enum.Material.ForceField)
		for name, part in pairs(parts) do
			-- A mass whose whole job is to be an invisible trigger has no business
			-- in a silhouette: drawn as a ghost, the upgrader's 5-stud ScanTrigger
			-- is a translucent slab across the belt where the real machine shows a
			-- 1-stud beam. The ghost is built from the same description as the real
			-- machine ON PURPOSE, so this is the one exception and it is named.
			if name:match("Trigger$") then
				part:Destroy()
				continue
			end
			part.Transparency = 0.72
			-- A ghost must never be walked into, stood on, or hit by a drop: it is
			-- a drawing, and the belt has to run through where it will stand.
			part.CanCollide = false
			part.CanTouch = false
			part.CanQuery = false
			part.CastShadow = false
		end
		return model
	end

	--- Buy buttons have three states, because the two obvious designs both fail:
	--- showing every button at once gives the plot no focal point, and showing
	--- only the next one hides the shape of the build from you.
	---
	---   available   full colour, lit, touchable, and the cheapest one wears a
	---               Highlight and a beacon so it is findable from anywhere
	---   preview     the next few steps: dimmed, inert, with a ghost of the
	---               machine standing where it will go
	---   hidden      everything further out, and everything already owned
	-- Preview depth and beacon rank both used to be tables here. They are
	-- Config.TrackInfo[track].preview and Config.TrackRank[track] now — the second
	-- of those existed TWICE, once here and once in the HUD, with a comment on the
	-- HUD copy warning that they had to stay identical. Rank is just the TrackOrder
	-- index, so deriving it deletes both copies rather than adding a third.

	--- Switches a buy button's label between its two voices.
	---
	--- `locked` is a Config.Style.ButtonLocked table, or nil for the full-volume
	--- one. Five properties move together because any one of them alone is a nudge
	--- and the point is a difference you cannot miss: the label shrinks, its panel
	--- fades, its outline thins, its text fades (outline along with it, or a dimmed
	--- label keeps a hard edge and reads as MORE contrasty than the bright one),
	--- and it stops drawing at a shorter range so a plot full of locked pads
	--- clears out as you walk away from it.
	function Tycoon:setButtonVoice(entry, locked)
		local scale = locked and locked.scale or 1
		entry.billboard.Size = UDim2.fromScale(BTN.width * scale, BTN.height * scale)
		Style.setDistance(entry.billboard, locked and locked.distance or BTN.distance)
		entry.frame.BackgroundTransparency = locked and locked.panelAlpha or BTN.panelAlpha
		entry.stroke.Thickness = locked and locked.strokeThickness or BTN.strokeThickness
		local alpha = locked and locked.textAlpha or 0
		for _, label in ipairs(entry.labels) do
			Style.fade(label, alpha)
		end
	end

	function Tycoon:refreshButtons()
		-- The ground reconciles before the pads: land is derived from `owned` the
		-- same way the buttons are, and it has to exist for the beat's other
		-- readers (the ring) to measure against. Runs on the ownerless
		-- path too — release wipes `owned`, and the slabs follow it down.
		self:ensureLand()
		if not self.owner then
			for _, entry in pairs(self.objects) do
				entry.holder.Parent = nil
				if entry.ghost then
					entry.ghost:Destroy()
					entry.ghost = nil
				end
			end
			if self.marker then
				self:pointAt(nil)
			end
			return
		end

		local cash = Economy.get(self.owner)

		-- How far along EACH track the player has got. One frontier per track is a
		-- strict generalisation of the old single scan: with one track it produces
		-- exactly the numbers that loop produced.
		local frontier = {}
		for track, defs in pairs(Config.Tracks) do
			frontier[track] = #defs + 1
			for _, def in ipairs(defs) do
				if not self.owned[def.id] then
					frontier[track] = def.trackOrder
					break
				end
			end
		end

		local target, targetRank, targetPrice = nil, math.huge, math.huge

		for id, entry in pairs(self.objects) do
			local def = entry.def
			local owned = self.owned[id] == true
			-- design:D-03 — a gated track is HIDDEN, not previewed, and takes no
			-- ghost.
			--
			local standing = Config.trackUnlocked(def.track, self.owned)
			local available = (not owned) and standing and self:requirementsMet(id)
			local preview = (not owned) and (not available) and standing
				and (def.trackOrder <= frontier[def.track] + Config.TrackInfo[def.track].preview)

			entry.holder.Parent = (available or preview) and self.buttonsFolder or nil

			if preview then
				-- inert: a preview pad you can buy from would just spam "you can't
				-- afford that yet" every time you crossed it
				entry.pad.CanTouch = false
				entry.pad.Color = COLORS.preview
				entry.pad.Transparency = 0.45
				if entry.pedestal then
					entry.pedestal.Transparency = 0.55
					entry.pedestal.CanCollide = false
				end
				entry.light.Enabled = false
				-- SMALLER, FAINTER, THINNER, AND IT GIVES UP SOONER. Colour on its
				-- own was never going to carry this: it is the first signal lost to
				-- a bright sky or a neon variant standing behind the label, and it
				-- was the ONLY thing separating a locked pad from the one you can
				-- press.
				self:setButtonVoice(entry, BTN_LOCKED)
				entry.stroke.Color = COLORS.preview
				entry.stepLabel.TextColor3 = COLORS.preview
				entry.titleLabel.TextColor3 = COLORS.preview
				-- design:D-05 — name the thing you have to buy, not an ordinal. "step N" meant
				-- one thing when there was one chain; with three tracks the global
				-- order is meaningless on a pedestal and the per-track one is
				-- ambiguous across cabinets. The requirement is right here, so say
				-- it: "locked — buy Oak Sahur Bat first".
				--
				local blocker
				for _, req in ipairs(Config.requirementsOf(def)) do
					if not self.owned[req] then
						blocker = Config.ButtonById[req]
						break
					end
				end
				entry.effectLabel.Text = blocker
					and ("locked — buy %s first"):format(blocker.name)
					or "locked"
				entry.effectLabel.TextColor3 = COLORS.preview
				entry.priceLabel.Text = "$" .. Util.abbreviate(def.price)
				entry.priceLabel.TextColor3 = COLORS.preview
			elseif available then
				local affordable = cash >= def.price
				local color = affordable and COLORS.buttonOn or COLORS.buttonOff
				entry.pad.CanTouch = true
				entry.pad.Transparency = 0
				entry.pad.Color = color
				if entry.pedestal then
					entry.pedestal.Transparency = 0
					entry.pedestal.CanCollide = true
				end
				entry.light.Enabled = true
				entry.light.Color = color
				self:setButtonVoice(entry, nil)
				entry.stroke.Color = color
				entry.stepLabel.TextColor3 = Color3.fromRGB(150, 142, 172)
				entry.titleLabel.TextColor3 = Color3.fromRGB(255, 240, 210)
				entry.effectLabel.Text = self:effectLine(def)
				entry.effectLabel.TextColor3 = Color3.fromRGB(150, 235, 190)
				entry.priceLabel.TextColor3 = color
				entry.priceLabel.Text = affordable
					and ("$" .. Util.abbreviate(def.price))
					or ("NEED " .. Util.abbreviate(def.price - cash) .. " MORE")

				-- (track, price) lexicographically. Cheapest-overall would park the
				-- beacon on the first cabinet rung for the whole early game, since
				-- a bat costs less than the next dropper for most of it.
				local rank = Config.TrackRank[def.track] or 99
				if rank < targetRank or (rank == targetRank and def.price < targetPrice) then
					target, targetRank, targetPrice = entry, rank, def.price
				end
			end

			-- ghosts stand for anything not yet built, available or previewed
			local wantsGhost = (available or preview) and MACHINE_MASSES[def.kind] ~= nil
			if wantsGhost and not entry.ghost then
				entry.ghost = self:buildGhost(def)
				if entry.ghost then
					entry.ghost.Parent = self.machines
				end
			elseif not wantsGhost and entry.ghost then
				entry.ghost:Destroy()
				entry.ghost = nil
			end
		end

		self:pointAt(target)
		-- The yard and its generator are refreshed on this beat because it is the
		-- one place that runs on install, assign, release and rebirth, and both
		-- of them have to survive all four. The cabinets used to hang here too;
		-- they left with #108.
		self:ensureYard()
		self:ensureGuide()
		self:refreshGenerator()
	end

	--- Moves the "buy this next" marker onto `entry`. One Highlight and one light
	--- column per plot, reparented, rather than one of each per button: Highlight
	--- is capped at 255 per client and disabled ones still occupy a slot.
	function Tycoon:pointAt(entry)
		if not self.marker then
			local marker = Instance.new("Model")
			marker.Name = "NextMarker"

			local beam = newPart(marker, "Beam", Vector3.new(4, 26, 4), CFrame.new(),
				COLORS.gold, Enum.Material.Neon, false)
			beam.Transparency = 0.75
			beam.CanQuery = false

			local highlight = Instance.new("Highlight")
			highlight.FillColor = COLORS.gold
			highlight.FillTransparency = 0.65
			highlight.OutlineColor = Color3.fromRGB(255, 255, 255)
			-- through your own machinery: the point of the marker is that you can
			-- find it from the far end of a plot you have already half filled
			highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
			highlight.Parent = marker

			self.marker = marker
			self.markerBeam = beam
			self.markerHighlight = highlight
		end

		if not entry then
			self.marker.Parent = nil
			self.markerHighlight.Adornee = nil
			return
		end

		self.markerHighlight.Adornee = entry.holder
		self.markerBeam.CFrame = entry.pad.CFrame * CFrame.new(0, 13, 0)
		self.marker.Parent = self.buttonsFolder
	end

	return Tycoon
end


__MODULES["Class"] = function()
	--[[
		tycoon/Class.lua — the Tycoon table itself, and the constructor that builds
		one plot out of it.

		THE ONE TABLE EVERY OTHER FILE IN THIS FOLDER HANGS ITS METHODS ON. This
		file requires no sibling, which is what keeps the folder acyclic: Req raises
		"circular dependency" at RUNTIME (Req.lua:70-73), so a mixin that required
		the aggregator back would fail the boot rather than the build.

		It owns the state a plot is made of — `paths`, `owned`, `objects`,
		`factoryFolders`, the two belt-speed inputs — and the values the mixins
		share. COLORS, MISC_SPOTS and MIN_PART hang off the class table rather than
		being file-locals because a file-local cannot be read from the file next
		door. They are read there, never written.

		Tycoon.new CALLS METHODS THIS FILE DOES NOT DEFINE (buildBelt,
		buildCollector, ensureGuide, updateSign, ...). That is safe because
		nothing reaches Tycoon.new without going through Req("Tycoon"), the
		aggregator, which requires every mixin first. Req("Class") on its own would
		hand you a class that builds a pad and nothing on it.
	]]

	local Req = __Req
	local Config = Req("Config")
	local MapBuilder = Req("MapBuilder")

	local L = Config.Layout

	local Tycoon = {}
	Tycoon.__index = Tycoon

	--- Roblox refuses a part thinner than this on any axis, and silently keeps the
	--- old size rather than erroring — so an empty gauge would keep whatever height
	--- it last had. The floor is here rather than in Config because it is a
	--- property of the engine, not a tuning knob.
	Tycoon.MIN_PART = 0.05

	--- Every plot built this session, in plot order. PlotService owns the plots and
	--- hands them out by player; a service that has to walk ALL of them (like
	--- FloorService) has nowhere else to get the list.
	local INSTANCES: { any } = {}

	function Tycoon.all(): { any }
		return INSTANCES
	end

	-- Buttons that aren't attached to a belt machine sit in a row on the open
	-- floor, spaced further apart than a button is wide. Positions live in Config
	-- so they scale with the plot instead of drifting into the wall when it grows.
	Tycoon.MISC_SPOTS = L.MiscButtons

	Tycoon.COLORS = {
		frame     = Color3.fromRGB(118, 122, 130),
		metal     = Color3.fromRGB(160, 164, 172),
		belt      = Color3.fromRGB(62, 62, 68),
		beltLine  = Color3.fromRGB(255, 176, 60),
		buttonOn  = Color3.fromRGB(110, 235, 150),
		buttonOff = Color3.fromRGB(230, 90, 90),
		preview   = Color3.fromRGB(126, 122, 146),
		vault     = Color3.fromRGB(146, 110, 72),
		gold      = Color3.fromRGB(255, 205, 90),
		-- The gauge in its two voices, on the same two-voice principle as
		-- Style.Button/ButtonLocked: bright gold is tung you can COLLECT, the
		-- duller amber is tung you would bank by leaving. Colour is not carrying
		-- the difference on its own — the empty column is also a sliver rather
		-- than a full pane, and the prompt is off.
		vaultPromise = Color3.fromRGB(196, 150, 70),
	}

	function Tycoon.new(index: number, parent: Instance)
		local self = setmetatable({}, Tycoon)

		self.index = index
		self.owner = nil :: Player?
		self.owned = {}
		self.objects = {}
		self.generation = 0
		-- BELT SPEED IS DERIVED, NOT ACCUMULATED. It has two inputs now — the
		-- additive Belt bonus and the multiplicative generator factor — and `+=` on
		-- the product is only safe while install() guards on `owned`. It does, but
		-- assign() replays a save by installing every owned button in `order`
		-- sequence, so a multiplicative installer written the same way as the Belt
		-- one would land on 1.19 x 1.42 x 1.68 x 2.00 rather than on 2.00. Keep the
		-- two inputs and recompute; the hot path still reads the cached product.
		self.beltBonus = 0
		self.powerFactor = 1
		self.beltSpeed = L.BeltSpeed
		self.dropCount = 0
		self.dropPool = {}   -- retired drop bodies, shelved per variant (Drops.lua)
		-- The storage unit's state (Storage.lua). A plain table here rather than
		-- resetStorage(), because Class must not call methods the mixins attach.
		self.storage = { health = Config.Storage.MaxHealth, broken = false }
		-- The walls' and gates' state (Siege.lua). Empty means nothing tracked
		-- yet; assign() fills it via resetSiege, then overwrites from the save.
		self.structureHealth = {}

		-- Folders that come and go with the factory. Registered as they are built
		-- rather than listed in setFactoryVisible; see registerFactoryFolder.
		self.factoryFolders = {}
		self.factoryShown = true
		self.ownedChangedListeners = {}

		-- BELT PATHS ARE REGISTERED UP FRONT, all of them, including floors nobody
		-- has bought yet. A path is pure maths — legs, directions, normals — and
		-- registering it builds nothing. It has to happen here because buy buttons
		-- are built once, on first claim, and a button standing on the mezzanine
		-- needs that path to exist to know its own height. The floor's PARTS still
		-- wait for the purchase.
		self.paths = {}
		for _, path in ipairs(Config.BeltPaths) do
			self:addBeltPath(path)
		end

		local model, cf = MapBuilder.buildPlotPad(parent, index)
		self.model = model
		self.cf = cf
		self.padPart = model:FindFirstChild("Pad")

		self.machines = Instance.new("Folder")
		self.machines.Name = "Machines"
		self.machines.Parent = model
		self:registerFactoryFolder(self.machines)

		-- Side-track props: the cabinets and whatever stands on their shelves.
		-- A SEPARATE folder from self.machines specifically because rebirth does
		-- machines:ClearAllChildren() — putting a bat display in there would wipe
		-- the cabinet every prestige while its purchase survived in the profile.
		-- release() still clears this one: new owner, different tiers.
		self.props = Instance.new("Folder")
		self.props.Name = "Props"
		self.props.Parent = model
		self:registerFactoryFolder(self.props)

		self.buttonsFolder = Instance.new("Folder")
		self.buttonsFolder.Name = "Buttons"
		self.buttonsFolder.Parent = model

		self.drops = Instance.new("Folder")
		self.drops.Name = "Drops"
		self.drops.Parent = model

		-- Two mirrored ground conveyors into one vault (#162): the west path
		-- builds the shared folders and the vault shell, the east path adds its
		-- surfaces and its own intake into the same vault.
		self:buildBelt(1)
		self:buildBelt(2, self.beltFolder)
		self:buildCollector(1, nil, true)
		self:buildCollectorIntake(2, self.collectorFolder,
			Config.Layout.Vault.bodyDepth, Config.Layout.Vault.bodyWidth)
		self:buildRebirthPad()
		self:buildClaimPad()
		-- The generator standing on the yard is a machine and comes and goes
		-- with a rebirth; the slab does not. Idempotent, and also re-run from
		-- refreshButtons, because release() clears self.props.
		self:ensureYard()

		-- An unclaimed plot shows a bare pad and a claim marker, nothing else.
		-- Leaving the vault and belt standing on an empty plot is what makes it
		-- look like there's a big block parked in front of the thing you're
		-- meant to walk onto.
		self:setFactoryVisible(false)
		self:updateSign()

		table.insert(INSTANCES, self)
		return self
	end

	--- Listener for "what this plot owns has changed" — a purchase, a claim, a
	--- release, a rebirth. FloorService hangs the mezzanine off this rather than
	--- polling every plot on a timer. One listener, because there is exactly one
	--- consumer; make it a list the day there are two.
	--- A LIST, as the comment here has been asking for. It was one slot with
	--- "make it a list the day there are two" written over it, and FloorService
	--- held it. There are two now.
	function Tycoon:onOwnedChanged(fn: ((any) -> ())?)
		if fn then
			table.insert(self.ownedChangedListeners, fn)
		end
	end

	function Tycoon:fireOwnedChanged()
		for _, fn in ipairs(self.ownedChangedListeners) do
			-- pcall'd per listener: one that throws must take neither the purchase
			-- nor the listeners after it down with it
			local ok, err = pcall(fn, self)
			if not ok then
				warn("[Tung] owned-changed listener error on plot " .. self.index .. ": " .. tostring(err))
			end
		end
	end

	--- Buy buttons are built on first claim, not at server start: every plot x 21
	--- buttons is a lot of instances to create just to immediately hide them.
	function Tycoon:ensureButtons()
		if self.buttonsBuilt then
			return
		end
		self.buttonsBuilt = true
		self:buildButtons()
	end

	--- Adds a folder to the set that appears and disappears with the factory.
	---
	--- Registration rather than a literal list, because setFactoryVisible used to
	--- walk `for i = 1, 4` over one: the fifth folder anyone added was silently
	--- left standing on an unclaimed plot, which is the exact bug the hidden
	--- factory exists to prevent. A folder registered while the factory is hidden
	--- is hidden immediately, so late arrivals (an upper floor) can't leak either.
	function Tycoon:registerFactoryFolder(folder: Instance)
		table.insert(self.factoryFolders, folder)
		if not self.factoryShown then
			folder.Parent = nil
		end
	end

	--- Shows/hides the whole factory. Machinery lives in folders so this is a
	--- reparent rather than a rebuild.
	function Tycoon:setFactoryVisible(visible: boolean)
		self.factoryShown = visible
		local target = visible and self.model or nil
		for _, folder in ipairs(self.factoryFolders) do
			folder.Parent = target
		end
	end

	function Tycoon:at(x: number, y: number, z: number): CFrame
		return self.cf * CFrame.new(x, y, z)
	end

	--- Where the owner is placed on claim and on every respawn: just inside the
	--- gateway, on the open aisle, looking down plot-local -Z. A CFrame looks
	--- along its own -Z by default, so with no rotation you land facing the length
	--- of the factory with the belt on your left and the buy buttons ahead of you.
	function Tycoon:ownerSpawnCFrame(): CFrame
		local spot = L.OwnerSpawnAt
		return self:at(spot.X, spot.Y, spot.Z)
	end

	return Tycoon
end


__MODULES["Drops"] = function()
	--[[
		tycoon/Drops.lua — spawning the things the belt carries, and the budget that
		stops a finished factory spawning without limit.

		DROPS CARRY THE MONEY. design:D-02, via #180 — a tung stamps its
		dropper's value at spawn and PAYS it at the vault, through the plot
		multiplier and the live session stack. A tung that never reaches the
		collector — launched, jammed, cleared, reaped — is income that never
		arrives, which is what makes the conveyor the real indication of how the
		money is made. Config.incomeRate stays the quote, the offline mirror and
		the pacing model: it is the drops' long-run average.

		ONE CONSTRAINT AND ONE MODEL. The constraint: a LinearVelocity in Plane mode
		plus an AlignOrientation, so a drop costs no per-frame script and physically
		cannot drift sideways off the belt. The model: PivotTo overwrites the body's
		rotation outright, so the upright pose has to be baked into the target CFrame
		or every drop spawns lying on its side.

		THE ATTRIBUTES ARE THE ROUTING. PlotIndex, Leg and Path are what the corner
		sensors, the upgrader triggers and the collector all filter on, so a drop on
		the mezzanine is invisible to the ground floor's geometry and vice versa. A
		drop built without them sails off the first bend and stands wherever it
		lands until the reaper takes it.

		Config.Economy.MaxDropsPerPlot and self.dropCount are the INCOME budget
		since #180: a spawn the cap refuses is money that never arrives. Every
		path that removes a drop — collected, expired, cleared — has to decrement
		the count, or the counter drifts up to the cap and the plot silently
		stops earning.

		THE POOL RECYCLES BODIES, per variant. A finished factory retires ~10
		drops a second, and building a Model with constraints for each one is the
		server cost the pool removes. recycleDrop is the ONE way off the belt for
		an intact drop: it wipes the ride's attributes and the flash's tint,
		unparents, and shelves the body under its variant. clearDrops destroys the
		pool with the live drops — release hands the plot to a new owner whose
		factory drops different variants, and a shelved body from the last tenant
		is a leak wearing the wrong colour.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Fx = Req("Fx")
	local TungModels = Req("TungModels")
	local Tycoon = Req("Class")

	local L = Config.Layout

	-- ── drops ────────────────────────────────────────────────────────────────────

	function Tycoon:spawnDrop(def, nozzle: BasePart, legIndex: number, pathIndex: number?)
		pathIndex = pathIndex or 1
		if not self.owner then
			return
		end
		if self.dropCount >= Config.Economy.MaxDropsPerPlot then
			return
		end
		self.dropCount += 1

		local pool = self.dropPool[def.variant]
		local drop = pool and table.remove(pool) or nil
		if drop then
			-- Wipe the last ride: every upgrader's once-flag and the collector's
			-- claim, or a recycled drop arrives pre-flashed and pre-collected.
			for id, buttonDef in pairs(Config.ButtonById) do
				if buttonDef.kind == "Upgrader" then
					drop:SetAttribute("up_" .. id, nil)
				end
			end
			drop:SetAttribute("Collected", nil)
		else
			drop = TungModels.buildDrop(def.variant, 0.62)
			drop:SetAttribute("Variant", def.variant)
		end
		drop:SetAttribute("PlotIndex", self.index)
		-- The money this tung is worth at the vault, before multipliers — stamped
		-- raw so the stack is read fresh at COLLECTION and a mid-ride upgrade
		-- pays through on everything still on the belt (#180).
		drop:SetAttribute("DropValue", def.dropValue)

		-- Which belt, and how far along it: the corner sensors and the collector
		-- all filter on these, so a drop on the mezzanine is invisible to the
		-- ground floor's geometry and vice versa.
		drop:SetAttribute("Leg", legIndex)
		drop:SetAttribute("Path", pathIndex)

		local body = drop.PrimaryPart :: BasePart
		-- the upgrader flash tints the body toward its variant; a pooled body
		-- comes back at the nozzle in its natural coat
		local variant = Config.Variants[def.variant] or Config.Variants.classic
		body.Color = variant.wood
		body.Material = variant.material
		local direction = self:legDirectionWorld(legIndex, pathIndex)
		local across = self:legNormalWorld(legIndex, pathIndex)
		local jitter = (math.random() - 0.5) * (L.BeltWidth * 0.35)

		-- NOTE: the model's pivot is the body, so PivotTo overwrites the body's
		-- rotation outright. The upright orientation has to be baked into the
		-- target CFrame or every drop spawns lying on its side.
		local upright = TungModels.dropOrientation(direction)
		local spawnPosition = nozzle.Position + across * jitter - Vector3.new(0, 1.6, 0)
		drop:PivotTo(CFrame.new(spawnPosition) * upright)

		-- A pooled body keeps its rig; a fresh one gets it here. The dynamic
		-- fields — the leg's axes, the plot's speed, the upright pose — are
		-- written either way, every spawn.
		local attachment = body:FindFirstChild("BeltAttach")
		if not attachment then
			attachment = Instance.new("Attachment")
			attachment.Name = "BeltAttach"
			attachment.Parent = body
		end

		-- conveyor motion, done with a constraint so there is no per-frame script
		local mover = body:FindFirstChild("BeltMover")
		if not mover then
			mover = Instance.new("LinearVelocity")
			mover.Name = "BeltMover"
			mover.Attachment0 = attachment
			mover.RelativeTo = Enum.ActuatorRelativeTo.World
			mover.VelocityConstraintMode = Enum.VelocityConstraintMode.Plane
			mover.MaxForce = 120000
			mover.Parent = body
		end
		mover.PrimaryTangentAxis = direction
		mover.SecondaryTangentAxis = across
		mover.PlaneVelocity = Vector2.new(self.beltSpeed, 0)

		-- keep the little guy standing up and facing back down the belt, so you
		-- see a queue of angry faces instead of a pile of rolling logs
		local upkeep = body:FindFirstChild("StayUpright")
		if not upkeep then
			upkeep = Instance.new("AlignOrientation")
			upkeep.Name = "StayUpright"
			upkeep.Mode = Enum.OrientationAlignmentMode.OneAttachment
			upkeep.Attachment0 = attachment
			upkeep.RigidityEnabled = true
			upkeep.Parent = body
		end
		upkeep.CFrame = upright

		-- The ride token. A recycled body still has the LAST ride's reaper
		-- pending on it, and "is it parented" cannot tell ride 2 from ride 1 —
		-- so the reaper only takes the ride it was armed for.
		local ride = (drop:GetAttribute("Ride") or 0) + 1
		drop:SetAttribute("Ride", ride)

		drop.Parent = self.drops

		-- SERVER-OWNED, EXPLICITLY (#162 tophat). Automatic network ownership
		-- hands a drop near a player to that player's client, and every retarget
		-- the server writes — the corner snap, the plane axes, the collect — then
		-- reaches the real simulation a round trip late. At the shipped 28
		-- studs/s that latency hid inside the corner square; at power3's 74 the
		-- drop crossed the bend and landed on the floor before its pivot arrived.
		-- The belt is constraint-driven precisely so drops cost no per-frame
		-- script, so keeping them on the server is cheap and keeps every corner
		-- exact. After Parent: ownership can only be set on a part in workspace.
		-- pcall because a drop spawned into a plot being torn down has no
		-- workspace to be owned in, and that ride is already over.
		pcall(function()
			body:SetNetworkOwner(nil)
		end)

		Fx.tung(body, 1.6 + math.random() * 0.3, 0.08)

		task.delay(Config.Economy.DropLifetime, function()
			if drop.Parent and drop:GetAttribute("Ride") == ride then
				self:recycleDrop(drop)
			end
		end)
	end

	--- The one way off the belt for an intact drop: back to its variant's shelf.
	--- Decrements the budget, unparents, and leaves the ride's attributes for the
	--- next spawn to wipe — spawnDrop resets everything it reuses.
	function Tycoon:recycleDrop(drop: Model)
		if not drop.Parent then
			return
		end
		self.dropCount = math.max(0, self.dropCount - 1)
		drop.Parent = nil
		local variant = drop:GetAttribute("Variant")
		local pool = self.dropPool[variant]
		if not pool then
			pool = {}
			self.dropPool[variant] = pool
		end
		table.insert(pool, drop)
	end

	function Tycoon:clearDrops()
		for _, drop in ipairs(self.drops:GetChildren()) do
			drop:Destroy()
		end
		-- The pool goes with the live drops: release hands the plot to an owner
		-- whose factory drops different variants, and a shelved body that
		-- survives the handover is a leak wearing the last tenant's colours.
		for _, pool in pairs(self.dropPool) do
			for _, drop in ipairs(pool) do
				drop:Destroy()
			end
		end
		self.dropPool = {}
		self.dropCount = 0
	end

	return Tycoon
end


__MODULES["Income"] = function()
	--[[
		tycoon/Income.lua — what a plot is worth per second, and the signs that quote
		it.

		THE MODEL LIVES IN Config.incomeRate, and this file is one of its three
		readers. incomePerSecond wraps it with the live multiplier stack;
		SessionService.incomePerSecondFor wraps it with the rebirth term from a
		SAVED profile, because an offline player has no plot to ask; the verifier's
		progression simulation reads it raw. Change the shape in Config and the
		wrappers stay one line each.

		THE PAYER LIVES IN Vault.lua NOW (design:D-02, via #180): a collected
		tung pays its dropper's value through Config.dropPayout and the live
		multiplier stack, and a tung that never reaches the vault pays nothing.
		incomeRate stays the quote and the mirror — the drops' long-run average.

		updateSign has a ONE-WRITER RULE. PlotService repaints every sign on a
		3-second beat and VaultService recomputes the gauge on its own schedule, so
		when the gauge has a headline it owns the board and the income readout is the
		fallback. Two writers make the label flicker between two different sentences
		a few times a minute.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Economy = Req("Economy")
	local DataService = Req("DataService")
	local Tycoon = Req("Class")

	-- ── income readout ───────────────────────────────────────────────────────────

	--- Estimated Tung/second with everything currently installed.
	---
	--- `extraId` pretends one more button is owned, which is how a buy button can
	--- advertise "+$28/sec" instead of only a price. A price alone is a cost with
	--- no stated benefit, and for an Upgrader the benefit is not even guessable —
	--- x1.85 of an unknown number is not information.
	function Tycoon:incomePerSecond(extraId: string?): number
		local function has(id: string): boolean
			return self.owned[id] == true or id == extraId
		end

		-- Economy.multiplier carries rebirth and every session hook; the factory
		-- itself is Config.incomeRate, the one copy of the arithmetic.
		local rebirthMult = self.owner and Economy.multiplier(self.owner) or 1
		return Config.incomeRate(has) * rebirthMult
	end

	-- design:D-02, via #180 — startIncomeLoop IS GONE. The live plot's payer is
	-- Tycoon:onCollect: a tung that enters the vault pays its dropper's value
	-- through Config.dropPayout and the live multiplier stack, and a tung that
	-- never arrives pays nothing. incomeRate stays the quote, the mirror and
	-- the simulation — the drops' long-run average — which is why this file
	-- keeps incomePerSecond and lost the loop.

	--- One line of plain English for what a button actually does for you. Income
	--- kinds get the measured delta; the rest get their blurb, because "walls" has
	--- no income to quote.
	function Tycoon:effectLine(def): string
		if def.kind == "Dropper" or def.kind == "Upgrader" then
			local delta = self:incomePerSecond(def.id) - self:incomePerSecond()
			if delta > 0 then
				return ("+%s/sec"):format(Util.abbreviate(delta))
			end
		elseif def.kind == "Belt" then
			return ("belt +%d studs/sec"):format(def.speedBonus)
		elseif def.kind == "Gear" then
			-- Same rule as the income kinds: quote the measured effect, not the
			-- flavour text. A bat's whole value is its numbers.
			local bat = Config.BatById[def.grants]
			if bat then
				return ("%d dmg  •  %.0f%% crit"):format(bat.damage, bat.crit * 100)
			end
		elseif def.kind == "Armor" then
			local tier = Config.ArmorById[def.grants]
			if tier then
				local previous = Config.Armor.Tiers[tier.tier - 1]
				return ("%d max health  (+%d)"):format(tier.health, tier.health - (previous and previous.health or 0))
			end
		end
		return def.blurb or ""
	end

	function Tycoon:updateSign()
		local ownerName = self.owner and self.owner.DisplayName or nil
		local sign = self.model:FindFirstChild("Totem")
		local billboard = sign and sign:FindFirstChild("Sign")
		-- the label lives inside a Frame inside the BillboardGui, so this lookup
		-- has to be recursive or it silently returns nil forever
		local label = billboard and billboard:FindFirstChild("Owner", true)
		if label then
			if ownerName then
				-- design:D-03, via #106 — the tier is public: the tag names the
				-- owner's rank beside their name, at the sign's existing close
				-- draw distance. The profile can lag a beat behind a rebirth; the
				-- 3-second repaint catches it up.
				local profile = DataService.get(self.owner)
				local rank = Config.tierName(profile and profile.rebirths or 0)
				label.Text = ("%s's TUNG FACTORY  •  %s\n%s Tung/sec")
					:format(ownerName, rank, Util.abbreviate(self:incomePerSecond()))
			else
				label.Text = ("UNCLAIMED PLOT %d\nstep on the pad to claim"):format(self.index)
			end
		end
		-- ONE writer at a time. PlotService repaints every sign on a 3-second beat
		-- and VaultService recomputes the gauge on its own schedule, so if both
		-- wrote this label it would flicker between two different sentences a few
		-- times a minute. When the gauge has a headline it owns the board; when it
		-- does not — an unclaimed plot, or a build with Prototypes.Offline off —
		-- the income readout this sign has always carried is the fallback.
		if self.vaultLabel then
			if not ownerName then
				self.vaultLabel.Text = "SAHUR VAULT"
			elseif self.vaultHeadline then
				self.vaultLabel.Text = self.vaultHeadline
			else
				self.vaultLabel.Text = ("SAHUR VAULT  •  %s/sec"):format(Util.abbreviate(self:incomePerSecond()))
			end
		end
		-- the whole claim rig (pad, beacon, halo, sign) appears and disappears
		-- together, so an owned plot never shows a stray "free" marker
		if self.claimFolder then
			self.claimFolder.Parent = (ownerName == nil) and self.model or nil
		end
		if self.rebirthLabel and self.owner then
			self.rebirthLabel.Text = ("SAHUR REBIRTH\n%s"):format(Util.abbreviate(Economy.rebirthCost(self.owner)))
		end
	end

	return Tycoon
end


__MODULES["Installers"] = function()
	--[[
		tycoon/Installers.lua — one case per `kind`, and the machines those cases
		build.

		ADDING CONTENT IS A Config.Buttons ROW, NEVER A CASE HERE. A new case means a
		new KIND of buyable, and it has to land in three places at once: this table,
		KNOWN_KINDS in tools/verify_config.lua, and the contract in the header of
		tycoon/Tycoon.lua.

		Every installer takes (self, def, silent) and runs AFTER install() has set
		self.owned[def.id], so a rung may count itself. They must be IDEMPOTENT UNDER
		REPLAY, because assign() reinstalls every owned button in `order`: Power
		assigns Config.powerFactor(owned) rather than multiplying into the factor,
		which is what makes it correct under a replay, under a double install, and
		under a save holding power3 without power2. Land is a documented no-op for a
		related reason — the ground outlives the purchase, so ensureLand reconciles
		it on the refreshButtons beat.

		THE SHELL IS EMITTED FROM Config.Structure AND NOTHING ELSE. buildWallRing
		walks Config.wallSegments and builds exactly the spans it is handed; it does
		not decide where a wall stops, how tall it is or where its openings are. That
		is not tidiness — the walls were five boxes at a local `h = 13` under a roof
		whose underside was 20, so every plot in the game had a seven-stud open band
		around it and none of the 2309 config checks could see the number that caused
		it. A span the verifier can sum is a span the verifier can hold to its extent.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local Util = Req("Util")
	local Fx = Req("Fx")
	local CombatService = Req("CombatService")
	local Tycoon = Req("Class")
	local Parts = Req("Parts")

	local newPart = Parts.newPart
	local COLORS = Tycoon.COLORS

	-- Config.Layout is no longer read here. The gateway's centre and width still
	-- live in it, but they are read by Config.Structure.Openings now: the shell is
	-- built from ONE spec, and a builder that reached into Layout for half a wall
	-- would be a second source for the same geometry.
	local S = Config.Structure

	-- The shell's palette. Colour is the one thing about the wall this rewrite did
	-- NOT move into Config: what changed is its geometry, and the wall you walk up
	-- to is the same colour and material it always was.
	local WALL_COLOR = Color3.fromRGB(150, 111, 74)

	-- THE NEON TRIM. Config.Structure.Trim, not derived from the wall's thickness.
	-- It was derived while this was written, which read as thrift and was actually
	-- a second source for a shipped number: Config.shellPartCount could not count
	-- a part whose existence it could not see, and the budget was being asserted
	-- 13% under what the builder emits.
	local TRIM_SECTION = S.Trim.section
	local TRIM_PROUD = S.Trim.proud

	-- ── the shell's geometry ─────────────────────────────────────────────────────

	--- The size and CFrame of a box lying along one wall of the ring.
	---
	--- WHICH OF X AND Z IS THE LENGTH AND WHICH IS THE THICKNESS IS
	--- Config.wallExtent'S BUSINESS. The old wall answered that question by hand,
	--- once per box, in five hand-written CFrames — and the asymmetry it encodes
	--- (the side walls run the full plot depth, the front and back sit between them)
	--- is four corners at once if any one of them is written differently.
	---
	--- `cross` is how far INBOARD of the wall plane the box's centre sits: 0 for
	--- everything in the wall itself, `gateCross(opening)` for a leaf hanging off it.
	local function alongWall(tycoon, extent, along: number, y: number, cross: number,
		length: number, height: number, thickness: number)
		local fixed = extent.fixed - extent.outward * cross
		if extent.axis == "X" then
			return Vector3.new(length, height, thickness), tycoon:at(along, y, fixed)
		end
		return Vector3.new(thickness, height, length), tycoon:at(fixed, y, along)
	end

	--- invariant: HOW FAR OFF THE WALL A GATE LEAF HANGS, and on which side.
	---
	--- `alongWall`'s `cross` is measured from the wall's CENTRE plane and positive is
	--- inboard, so this is half the wall, plus the stated air gap, plus half the leaf
	--- — and negated for an opening whose leaves hang outside.
	---
	--- The yard door hangs outboard and that is not a preference. Its doorway is
	--- flush to the end of the back wall, so its single leaf can only slide inward
	--- along x, and the inside of the back wall IS the dropper row: an inboard leaf
	--- passes 0.1 studs into dropper slot 1. Outboard it travels over the generator
	--- yard's own slab, which is empty for its whole run. Both the verifier and this
	--- builder found that independently, on the shipped numbers.
	---
	--- WHICH IS WHY A MISSPELLED FACE IS NOT LET THROUGH QUIETLY. It is not
	--- nil-shaped: it is a door built on the wrong side of a wall, and on one of these
	--- two walls the wrong side is a machine. Config declares both entries today, so
	--- this is for the third opening somebody adds.
	local function gateCross(opening): number
		if opening.face ~= "inboard" and opening.face ~= "outboard" then
			warn(("[Tung] opening %s has face %s; it must be \"inboard\" or \"outboard\"")
				:format(tostring(opening.id), tostring(opening.face)))
		end
		local offset = S.WallThickness / 2 + S.Gate.inset + S.Gate.thickness / 2
		return opening.face == "outboard" and -offset or offset
	end

	--- One course of one wall: `from`..`to` along the side's own axis, `bottom`..`top`
	--- in height, a wall thickness across. Callers restyle what comes back — a glass
	--- pane is this box with two properties changed, not a second constructor.
	local function wallBox(tycoon, parent: Instance, name: string, extent,
		from: number, to: number, bottom: number, top: number)
		local size, cf = alongWall(tycoon, extent, (from + to) / 2, (bottom + top) / 2, 0,
			math.max(to - from, Tycoon.MIN_PART), math.max(top - bottom, Tycoon.MIN_PART),
			S.WallThickness)
		return newPart(parent, name, size, cf, WALL_COLOR, Enum.Material.WoodPlanks)
	end

	--- The coping bar along one wall's top, STRADDLING the line it marks rather
	--- than sitting flush with it: two coplanar faces at one Y is the z-fight
	--- every stacked surface in this game is offset to avoid. Dark timber now
	--- (#162's castle look); it was neon while the trim doubled as the enclosed
	--- room's light cove.
	local TRIM_COLOR = Color3.fromRGB(96, 70, 46)
	local function trimBar(tycoon, parent: Instance, name: string, extent,
		from: number, to: number, y: number, thickness: number, cross: number)
		local size, cf = alongWall(tycoon, extent, (from + to) / 2, y, cross,
			to - from, TRIM_SECTION, thickness)
		local bar = newPart(parent, name, size, cf, TRIM_COLOR, Enum.Material.Wood, false)
		bar.CanQuery = false
		bar.CastShadow = false
		return bar
	end

	-- ── installers ───────────────────────────────────────────────────────────────

	Tycoon.INSTALLERS = {}

	--- The dropper machine itself: masses, dressing, nameplate.
	--- Returns the model, its nozzle, and the leg and path it feeds.
	function Tycoon:buildDropperMachine(def, parent: Instance)
		local variant = Config.Variants[def.variant] or Config.Variants.classic

		local model = Instance.new("Model")
		model.Name = "Dropper_" .. def.id
		model.Parent = parent

		local parts, legIndex, _, pathIndex = self:buildMasses(def, model, COLORS.frame, Enum.Material.DiamondPlate)

		local core = parts.Core
		core.Color = variant.wood
		core.Material = variant.material
		Fx.applyVariant(core, variant)

		parts.Arm.Color = COLORS.metal
		parts.Arm.Material = Enum.Material.Metal
		parts.Spout.Color = COLORS.metal
		parts.Spout.Material = Enum.Material.Metal

		local nozzle = parts.Nozzle
		nozzle.Color = variant.light and variant.light.color or variant.wood
		nozzle.Material = Enum.Material.Neon

		local billboard = Style.billboard(core, {
			name = "Plate", width = 9, height = 2.6, distance = "machine", offset = 3.4,
		})
		Style.text(billboard, {
			weight = "body", color = Color3.fromRGB(255, 250, 235),
			text = def.name .. "  •  $" .. Util.abbreviate(def.dropValue),
		})

		return model, nozzle, legIndex, pathIndex
	end

	--- Starts a dropper's drop loop. `alive` is polled each cycle so the caller
	--- decides what ends it: a bought dropper dies when its button is wiped by a
	--- rebirth, a floor's dropper dies when the floor is torn down (its model is
	--- destroyed, which the model.Parent check catches on its own).
	function Tycoon:startDropLoop(def, model: Model, nozzle: BasePart, legIndex: number, pathIndex: number?, alive: (() -> boolean)?)
		local generation = self.generation
		task.spawn(function()
			-- stagger so ten droppers don't fire on the same frame
			task.wait(math.random() * self:dropInterval(def))
			while self.generation == generation and model.Parent and (alive == nil or alive()) do
				self:spawnDrop(def, nozzle, legIndex, pathIndex)
				task.wait(self:dropInterval(def))
			end
		end)
	end

	Tycoon.INSTALLERS.Dropper = function(self, def, silent)
		local model, nozzle, legIndex, pathIndex = self:buildDropperMachine(def, self.machines)

		local entry = self.objects[def.id]
		if entry then
			entry.machine = model
		end

		self:startDropLoop(def, model, nozzle, legIndex, pathIndex, function()
			return self.owned[def.id] == true
		end)
	end

	Tycoon.INSTALLERS.Upgrader = function(self, def, silent)
		local variant = Config.Variants[def.variant] or Config.Variants.classic

		local model = Instance.new("Model")
		model.Name = "Upgrader_" .. def.id
		model.Parent = self.machines

		local parts = self:buildMasses(def, model, COLORS.metal, Enum.Material.Metal)

		local beam = parts.Beam
		beam.Color = variant.wood
		beam.Material = variant.material
		Fx.applyVariant(beam, variant)

		-- The plate you see, which catches nothing...
		local scanner = parts.Scanner
		scanner.Color = variant.light and variant.light.color or variant.wood
		scanner.Material = Enum.Material.Neon
		scanner.Transparency = 0.55
		scanner.CanTouch = false

		-- ...and the volume that does, which you don't. Five studs deep so a drop
		-- cannot cross it between two physics steps on a plot nobody is standing on.
		local trigger = parts.ScanTrigger
		trigger.Transparency = 1
		trigger.CanTouch = true
		trigger.CanQuery = false
		trigger.CastShadow = false

		local billboard = Style.billboard(beam, {
			name = "Plate", width = 11, height = 3, distance = "machine", offset = 3,
		})
		Style.text(billboard, {
			text = ("%s  x%.2g"):format(def.name, def.multiplier),
			color = Color3.fromRGB(255, 240, 210),
		})

		-- The flash. design:D-02 — the upgrader's multiplier lives in
		-- Config.incomeRate; what the trigger does is make the arch visibly work a
		-- drop as it passes. The once-flag stays because Touched fires twice, and
		-- a double flash reads as a stutter.
		local flagName = "up_" .. def.id
		trigger.Touched:Connect(function(hit)
			local drop = hit.Parent
			if not drop or not drop:IsA("Model") then
				return
			end
			if drop:GetAttribute("PlotIndex") ~= self.index then
				return
			end
			if drop:GetAttribute(flagName) then
				return
			end
			drop:SetAttribute(flagName, true)

			local body = drop.PrimaryPart or drop:FindFirstChild("Body")
			if body and body:IsA("BasePart") then
				body.Color = Util.lerpColor(body.Color, variant.wood, 0.55)
				body.Material = variant.material
				Fx.burst(body.Position, variant.wood, 4, self.model)
				Fx.tung(body, 1.15 + math.random() * 0.2, 0.12)
			end
		end)

		local entry = self.objects[def.id]
		if entry then
			entry.machine = model
		end
	end

	Tycoon.INSTALLERS.Belt = function(self, def, silent)
		self.beltBonus += def.speedBonus
		self:refreshBeltSpeed()
		-- one speed for the whole plot, every floor included
		self:eachBeltSurface(function(surface)
			surface.Color = Color3.fromRGB(92, 70, 40)
		end)
	end

	Tycoon.INSTALLERS.Power = function(self, def, silent)
		-- invariant: THE FACTOR HAS TO BE ASSIGNED HERE. Nothing else writes it on
		-- a purchase, and the generator shipped for two rounds doing nothing at all
		-- because this line was missing — the belt and every dropper ran at stock
		-- speed while incomePerSecond, which reads Config.powerFactor(has) directly,
		-- went on quoting the full multiplier on the HUD, on the buy button and
		-- through SessionService's offline mirror.
		--
		-- DERIVED, NEVER ACCUMULATED. assign() replays a save by installing every
		-- owned button in `order`, so a *= here would land on
		-- 1.19 x 1.42 x 1.68 x 2.00 = 5.67 rather than on 2.00. Config.powerFactor
		-- takes the last owned rung because `factor` is cumulative, which makes
		-- this idempotent under replay, under a double install, and under a save
		-- that somehow holds power3 without power2. install() has already set
		-- self.owned[def.id] before dispatching here, so the rung being bought
		-- counts itself.
		self.powerFactor = Config.powerFactor(function(id: string): boolean
			return self.owned[id] == true
		end)
		self:refreshBeltSpeed()
		-- The machine is derived from `owned` by refreshGenerator, which install()
		-- reaches through refreshButtons on the next line of its own body. It lives
		-- in self.machines rather than self.props, which is what makes a rebirth
		-- take it down along with the droppers it was speeding up while the yard
		-- around it stays.
		self:refreshGenerator()
	end


	-- #108: gear and armour sell from the SHOP and build nothing on the plot.
	-- The installers survive as the replay path — assign() re-walks `owned` and
	-- these re-grant, which is idempotent because both grants are monotonic.
	Tycoon.INSTALLERS.Gear = function(self, def, silent)
		local owner = self.owner
		if owner then
			CombatService.grantBat(owner, def.grants)
		end
	end

	Tycoon.INSTALLERS.Armor = function(self, def, silent)
		local owner = self.owner
		if owner then
			CombatService.grantArmor(owner, def.grants)
		end
	end

	--- Land (#88). The ground outlives the purchase — release, rebirth and
	--- re-claim all have to rebuild or drop it and none of them go through
	--- install() — so the whole job is ensureLand's, and it also runs on the
	--- refreshButtons beat for exactly those three other events.
	Tycoon.INSTALLERS.Land = function(self, def, silent)
		self:ensureLand()
	end

	--- Every gate leaf the ring's openings carry: what to build, where it hangs
	--- closed, and where it slides to.
	---
	--- ONE FUNCTION FOR THE BUILDER AND FOR GateService. The walls branch builds
	--- these and GateService moves them, and "where does this leaf slide to" written
	--- twice is two answers the day either wall moves. GateService finds the parts by
	--- the `name` here, so this is also the naming contract between the two files.
	function Tycoon:gateLeafSpecs()
		local specs = {}
		local counts = self:landState()

		for _, side in ipairs(S.Sides) do
			local segments, extent = Config.wallSegments(side, counts.left, counts.right)
			for index, segment in ipairs(segments) do
				if segment.kind ~= "opening" then
					continue
				end
				local opening = segment.opening
				local leafWidth = opening.width / opening.leaves
				local bottom, top = 0, opening.height

				-- WHICH WAY A LONE LEAF SLIDES. A pair opens from the middle, one
				-- leaf each way. A single leaf has no middle to open from, so it
				-- slides into whichever neighbouring solid run is LONGER: the yard
				-- door sits at the right-hand end of the back wall with nothing but
				-- the corner on that side, and a leaf sliding the other way would
				-- travel out past the plot edge. Travel is one leaf width, which is
				-- the minimum run length Config.Structure.Gate says beside an opening.
				local before, after = segments[index - 1], segments[index + 1]
				local beforeRun = (before and before.kind == "solid") and (before.to - before.from) or 0
				local afterRun = (after and after.kind == "solid") and (after.to - after.from) or 0
				local lone = (beforeRun >= afterRun) and -1 or 1

				-- The centre of the opening, IN THE WALL PLANE — not out on the leaf
				-- with `gateCross`: what GateService measures a humanoid's distance to
				-- is the doorway, not the door. Following the leaves would put the yard
				-- door's trigger two studs BEHIND the back wall, so walking up to it
				-- from inside the factory would need two studs more approach than
				-- walking up to the inboard gateway does — the same opening measured
				-- differently because of which way its leaf happens to swing.
				local _, centreCF = alongWall(self, extent, opening.centre, (bottom + top) / 2,
					0, opening.width, top - bottom, S.WallThickness)

				for leaf = 1, opening.leaves do
					local closed = segment.from + (leaf - 0.5) * leafWidth
					local direction = lone
					if opening.leaves > 1 then
						direction = (closed < opening.centre) and -1 or 1
					end
					local size, closedCF = alongWall(self, extent, closed, (bottom + top) / 2,
						gateCross(opening), leafWidth, top - bottom, S.Gate.thickness)
					local _, openCF = alongWall(self, extent, closed + direction * leafWidth,
						(bottom + top) / 2, gateCross(opening), leafWidth, top - bottom, S.Gate.thickness)
					table.insert(specs, {
						name = ("Gate_%s_%d"):format(opening.id, leaf),
						opening = opening.id,
						size = size,
						closed = closedCF,
						open = openCF,
						centre = centreCF.Position,
					})
				end
			end
		end

		return specs
	end

	--- invariant: the ring of walls — the courses Config.wallSegments describes,
	--- the gate leaves in its openings, a coping cap along the top of each side,
	--- the buttress posts off the outer face and the torches along the inner one
	--- (both from their Config position functions, which is what lets the
	--- verifier and shellPartCount see them).
	---
	--- invariant: THREE COURSES PER SOLID RUN — sill, body, head — one lintel per
	--- opening. The sill is the course a broken wall keeps as its repair stump
	--- (tycoon/Siege.lua), so the split is load-bearing, and the course heights
	--- are Config.Structure.Course.
	function Tycoon:buildWallRing(model: Instance)
		local course = S.Course
		local floorY = 0
		local top = S.WallHeight
		local sill = floorY + course.sill
		local head = sill + course.body
		local counts = self:landState()

		for _, side in ipairs(S.Sides) do
			local segments, extent = Config.wallSegments(side, counts.left, counts.right)
			for index, segment in ipairs(segments) do
				local tag = ("%s_%d"):format(side, index)
				if segment.kind == "solid" then
					wallBox(self, model, "Sill_" .. tag, extent, segment.from, segment.to, floorY, sill)
					wallBox(self, model, "Body_" .. tag, extent, segment.from, segment.to, sill, head)
					wallBox(self, model, "Head_" .. tag, extent, segment.from, segment.to, head, top)
				else
					-- A lintel, not a full-height cut: a 20-stud gateway is not a
					-- door, so the opening keeps its own height and the wall closes
					-- over it.
					wallBox(self, model, "Lintel_" .. tag, extent, segment.from, segment.to,
						floorY + segment.opening.height, top)
				end
			end

			-- ONE CAP PER SIDE, not one per box. The old wall drew a trim over each
			-- of its five pieces; this one is several boxes a side, and that many
			-- slivers is that many parts to say one line. The cap straddles the
			-- wall plane, so the band reads from both faces.
			trimBar(self, model, "Trim_" .. side, extent,
				extent.from - TRIM_PROUD / 2, extent.to + TRIM_PROUD / 2, top,
				S.WallThickness + TRIM_PROUD, 0)

			-- The buttress posts, on the OUTER face. Embedded 0.4 studs into the
			-- wall so the meeting faces never sit coplanar.
			local buttress = S.Buttress
			local buttressDepth = buttress.proud + 0.4
			local buttressCross = -(S.WallThickness / 2 - 0.4 + buttressDepth / 2)
			for postIndex, along in ipairs(Config.buttressPositions(side, counts.left, counts.right)) do
				local size, cf = alongWall(self, extent, along, buttress.height / 2, buttressCross,
					buttress.width, buttress.height, buttressDepth)
				newPart(model, ("Buttress_%s_%d"):format(side, postIndex), size, cf,
					WALL_COLOR, Enum.Material.WoodPlanks)
			end

			-- The torches, on the INNER face, above the machine line (asserted):
			-- a bracket embedded into the wall and a neon flame on its tip,
			-- carrying the PointLight.
			local torch = S.Torch
			local bracketDepth = torch.bracket[3] + 0.4
			local bracketCross = S.WallThickness / 2 - 0.4 + bracketDepth / 2
			local flameCross = S.WallThickness / 2 + torch.bracket[3] - torch.flame[3] / 2
			for torchIndex, along in ipairs(Config.torchPositions(side, counts.left, counts.right)) do
				local size, cf = alongWall(self, extent, along, torch.height, bracketCross,
					torch.bracket[1], torch.bracket[2], bracketDepth)
				local bracket = newPart(model, ("Torch_%s_%d"):format(side, torchIndex), size, cf,
					TRIM_COLOR, Enum.Material.Wood, false)
				bracket.CanQuery = false
				local flameSize, flameCf = alongWall(self, extent, along,
					torch.height + torch.bracket[2] / 2 + torch.flame[2] / 2, flameCross,
					torch.flame[1], torch.flame[2], torch.flame[3])
				local flame = newPart(model, ("TorchFlame_%s_%d"):format(side, torchIndex),
					flameSize, flameCf, Color3.fromRGB(255, 170, 70), Enum.Material.Neon, false)
				flame.CanQuery = false
				flame.CastShadow = false
				Fx.torchLight(flame)
			end
		end

		-- invariant: THE UPGRADE THIS RING MAY ALREADY HAVE BEEN SOLD.
		--
		-- `walls` and `gates` are two purchases and an installer runs once, so a
		-- ring built after `gates` was bought — assign() replaying a save — has to
		-- arrive already carrying its leaves.
		self:applyStructureUpgrades(model)

		-- ...and the DAMAGE it may already have taken (#124). The health table is
		-- the authority; without this line every rebuild on the refreshButtons
		-- beat would resurrect a wall the raiders earned.
		self:applySiegeState(model)
	end

	--- Whether this plot owns a `Structure` button of the given kind.
	---
	--- Derived from `owned` rather than stored, so it survives release, rebirth and
	--- re-claim for free — the same argument as Config.trackUnlocked. A plot that
	--- has been rebirthed has lost `walls` too, so there is no state where the
	--- leaves outlive the wall they hang on.
	function Tycoon:hasStructure(structure: string): boolean
		for id in pairs(self.owned) do
			local def = Config.ButtonById[id]
			if def and def.kind == "Structure" and def.structure == structure then
				return true
			end
		end
		return false
	end

	--- Hang the ring's gate leaves, off the face `opening.face` names.
	---
	--- They live in the WALL's model rather than one of their own, so release() and
	--- rebirth() take them down with everything else — which is why GateService
	--- checks a leaf's Parent before it moves it rather than holding a reference and
	--- trusting it. Idempotent by name: `gates` can be replayed by assign() over a
	--- ring that already has them.
	function Tycoon:hangGateLeaves(model: Instance)
		-- Darker than the wall so a closed gate reads as a DOOR in the ring
		-- rather than more wall — the trim's timber, one shade down.
		local hung = 0
		for _, leaf in ipairs(self:gateLeafSpecs()) do
			if not model:FindFirstChild(leaf.name, true) then
				newPart(model, leaf.name, leaf.size, leaf.closed,
					Color3.fromRGB(118, 86, 56), Enum.Material.WoodPlanks)
				hung += 1
			end
		end
		return hung
	end

	--- How many masonry tiers this plot owns. The tier rows are a chain, so the
	--- count IS the highest tier standing; counting stays correct even under a
	--- save holding a later tier without an earlier one.
	function Tycoon:masonryTiers(): number
		local owned = 0
		for _, tier in ipairs(Config.Structure.Tiers) do
			if self:hasStructure(tier.structure) then
				owned += 1
			end
		end
		return owned
	end

	--- The material and colour the ring's masonry currently wears: the owned
	--- tier's, or the wooden default.
	function Tycoon:masonryLook(): (Enum.Material, Color3)
		local tier = Config.Structure.Tiers[self:masonryTiers()]
		if tier then
			return Enum.Material[tier.material], tier.color
		end
		return Enum.Material.WoodPlanks, WALL_COLOR
	end

	-- The parts a masonry tier restyles: the courses, the lintels and the
	-- buttresses — the wall itself. The trim and the torches keep their timber,
	-- and so do the gate leaves: a castle's doors are wood, and a stone door
	-- reads as more wall.
	local MASONRY_PREFIXES = { Sill = true, Body = true, Head = true, Lintel = true, Buttress = true }

	--- Restyle the standing ring to the owned tier. The glazing mechanism
	--- generalised: idempotent, and it adds no parts, which is what keeps
	--- Config.shellPartCount and the whole PartBudget argument tier-blind.
	function Tycoon:applyMasonry(model: Instance)
		local material, color = self:masonryLook()
		local restyled = 0
		for _, part in ipairs(model:GetChildren()) do
			if part:IsA("BasePart") and MASONRY_PREFIXES[part.Name:match("^(%a+)_") or ""] then
				part.Material = material
				part.Color = color
				restyled += 1
			end
		end
		return restyled
	end

	--- Bring the ring up to whatever this plot has bought.
	function Tycoon:applyStructureUpgrades(model: Instance)
		if self:hasStructure("gates") then
			self:hangGateLeaves(model)
		end
		self:applyMasonry(model)
	end

	--- The wall ring standing on this plot right now, handed to `fn`, or nothing.
	---
	--- Found by its own trim bar rather than by a folder reference, so a caller
	--- never holds a model that a release or rebirth already destroyed. This is
	--- the same lookup GateService does for a leaf, and it is here so that
	--- `gates` does not have to learn where the ring lives.
	function Tycoon:withWallRing(fn)
		local marker = "Trim_" .. S.Sides[1]
		for _, folder in ipairs(self.factoryFolders) do
			local part = folder:FindFirstChild(marker, true)
			if part and part.Parent then
				fn(part.Parent)
				return 1
			end
		end
		return 0
	end

	Tycoon.INSTALLERS.Structure = function(self, def, silent)
		local model = Instance.new("Model")
		model.Name = "Structure_" .. def.id
		model.Parent = self.machines

		if def.structure == "walls" then
			self:buildWallRing(model)
		else
			-- ADDITIVE — never a rebuild. The obvious implementation is to re-emit
			-- the wall with the upgrade included, and that would destroy the gate
			-- leaves GateService may be mid-tween on and re-emit dozens of parts
			-- that have not changed. A leaf is a part with nothing standing where
			-- it goes, and a masonry tier is a material change on parts already
			-- standing, so neither needs the wall touched.
			--
			-- `model` stays empty for these and that is deliberate: the leaves and
			-- the restyle belong to the ring, so a rebirth takes them down with
			-- the wall rather than leaving doors floating in a plot with no shell.
			-- The entry below still records the model so the object bookkeeping is
			-- uniform. applySiegeState runs after a restyle so a standing stump
			-- keeps its char over the new stone.
			self:withWallRing(function(ring)
				if def.structure == "gates" then
					self:hangGateLeaves(ring)
				else
					self:applyMasonry(ring)
					self:applySiegeState(ring)
				end
			end)
		end

		local entry = self.objects[def.id]
		if entry then
			entry.machine = model
		end
	end

	return Tycoon
end


__MODULES["Land"] = function()
	--[[
		tycoon/Land.lua — the ground a plot grows into, reconciled from `owned`.

		design:D-02, via #88. Land is bought outward from the centre and the centre
		pad is the permanent anchor. ensureLand runs on the refreshButtons beat and
		makes the world match `owned`: slabs and their edge strips per expansion,
		and the wall ring re-emitted around whatever ground is standing. Purchase,
		release, rebirth and re-claim all reach
		refreshButtons, which is why there is no service and no listener — the
		FloorService this replaces existed to catch those four events, and a
		derived reconciler catches them by construction.

		THE RING RE-EMITS COURSES AND NEVER TOUCHES A LEAF. Rebuilding wall boxes
		is safe — nothing tweens them; rebuilding a gate leaf mid-tween is the
		defect GateService's Parent check exists for. So rebuildWallRing destroys
		everything in the ring EXCEPT Gate_* parts, re-emits the courses from
		Config.wallSegments at the current land state, and leaves the leaves
		alone. The openings never move — they live on the centre span — so a
		surviving leaf is exactly where its spec still says it belongs.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Tycoon = Req("Class")
	local Parts = Req("Parts")

	local newPart = Parts.newPart
	local W = Config.World

	local SLAB_COLOR = Color3.fromRGB(112, 105, 98)
	local EDGE_COLOR = Color3.fromRGB(255, 196, 84)

	--- How many expansions each side owns. Derived from `owned` on every call,
	--- never cached — a cached count is a second copy of the save (#35).
	function Tycoon:landState()
		return Config.landCounts(self.owned)
	end

	--- One expansion's ground: the slab, neon strips along its front, back and
	--- (for the outermost owned strip) outer edge — and the sub-belt it arrives
	--- with (#109): the strip's own path gets its surfaces, corner sensors and a
	--- plain collector, all parented into this model so tearing the strip down
	--- takes its conveyor with it.
	local function buildSlab(self, folder, def, outermost)
		local rect = Config.landRect(def.id)
		local model = Instance.new("Model")
		model.Name = "Land_" .. def.id
		model.Parent = folder

		local width = rect.toX - rect.fromX
		local centreX = (rect.fromX + rect.toX) / 2
		newPart(model, "Slab", Vector3.new(width, W.PlotSize.Y, W.PlotSize.Z),
			self:at(centreX, -W.PlotSize.Y / 2, 0), SLAB_COLOR, Enum.Material.Concrete)

		local pathIndex = self:pathIndexOf({ id = def.id, path = def.id })
		if pathIndex and self.paths[pathIndex] then
			self:buildBelt(pathIndex, model)
			self:buildCollector(pathIndex, model, false)
		end

		local halfZ = W.PlotSize.Z / 2
		local edges = {
			{ Vector3.new(width, 1, 2), self:at(centreX, 0.2, halfZ) },
			{ Vector3.new(width, 1, 2), self:at(centreX, 0.2, -halfZ) },
		}
		if outermost then
			local outerX = (rect.side == "left") and rect.fromX or rect.toX
			table.insert(edges, { Vector3.new(2, 1, W.PlotSize.Z), self:at(outerX, 0.2, 0) })
		end
		for index, edge in ipairs(edges) do
			local strip = newPart(model, "Edge" .. index, edge[1], edge[2], EDGE_COLOR, Enum.Material.Neon)
			strip.CanCollide = false
		end
		return model
	end

	--- Re-emit the ring's courses at the current land state, leaves excepted.
	function Tycoon:rebuildWallRing()
		self:withWallRing(function(ring)
			for _, part in ipairs(ring:GetChildren()) do
				if part.Name:sub(1, 5) ~= "Gate_" then
					part:Destroy()
				end
			end
			self:buildWallRing(ring)
		end)
	end

	--- Make the ground and the ring match `owned`. Idempotent: called on every
	--- refreshButtons beat, it builds what is missing, destroys what is no longer
	--- owned, and touches nothing that already agrees.
	function Tycoon:ensureLand()
		-- A stub plot (the spec harness's fakes) has no model and no plot CFrame;
		-- there is no world for the ground to exist in, so there is nothing to
		-- reconcile.
		if not (self.model and self.cf) then
			return
		end
		local counts = self:landState()

		local folder = self.landFolder
		if not folder or not folder.Parent then
			folder = Instance.new("Folder")
			folder.Name = "Land"
			folder.Parent = self.model
			self.landFolder = folder
		end

		local changed = false
		for _, side in ipairs({ "left", "right" }) do
			local rows = Config.landRows(side)
			for index, def in ipairs(rows) do
				local wanted = index <= counts[side]
				local existing = folder:FindFirstChild("Land_" .. def.id)
				if wanted and not existing then
					buildSlab(self, folder, def, index == counts[side])
					changed = true
				elseif not wanted and existing then
					existing:Destroy()
					changed = true
				elseif wanted and existing then
					-- the outer edge strip belongs to the outermost strip only;
					-- an expansion that stopped being outermost sheds it
					local outer = existing:FindFirstChild("Edge3")
					if outer and index ~= counts[side] then
						outer:Destroy()
					end
				end
			end
		end

		if changed then
			self:rebuildWallRing()
		end
	end

	return Tycoon
end


__MODULES["Ownership"] = function()
	--[[
		tycoon/Ownership.lua — claim, leave, prestige: the three transitions a plot
		makes, and what each of them has to put back.

		assign REPLAYS THE SAVE by installing every owned button in `order`,
		cheapest-first so requirements resolve as they are reached. That replay is
		why every installer has to be idempotent and why nothing derived from `owned`
		may be accumulated.

		release AND rebirth DIFFER IN ONE THING, and it is not how much they wipe.
		release is a new owner: machines and props both go, cabinet signs with them,
		the gauge is cleared BEFORE updateSign runs so the last owner's "leaving now
		banks 2.4M" never sits on a free plot's sign. rebirth is a factory reset for
		the same player: machines go, props stay, and the tracks marked
		keepOnRebirth survive in both profile.owned and self.owned. That rule is one
		table read twice — Config.TrackInfo[track].keepOnRebirth — because two name
		tests with opposite polarity fail OPEN, and the fourth track missing from one
		of them means the generator survives the reset it is part of.

		All three end with refreshButtons() then fireOwnedChanged(), in that order:
		buttons first, listeners second.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Fx = Req("Fx")
	local Economy = Req("Economy")
	local Net = Req("Net")
	local DataService = Req("DataService")
	local Analytics = Req("Analytics")
	local Tycoon = Req("Class")

	local COLORS = Tycoon.COLORS

	-- ── ownership ────────────────────────────────────────────────────────────────

	function Tycoon:assign(player: Player)
		if self.owner then
			return false
		end
		self.owner = player
		self.generation += 1
		self:ensureButtons()
		self:setFactoryVisible(true)
		-- Before the install replay: the replay builds walls, and applySiegeState
		-- reads this table to know what may stand.
		self:resetSiege()

		local profile = DataService.get(player)
		if profile then
			-- rebuild everything they had, cheapest-first so requirements resolve
			local ids = {}
			for id, owned in pairs(profile.owned) do
				if owned and Config.ButtonById[id] then
					table.insert(ids, id)
				end
			end
			table.sort(ids, function(a, b)
				return Config.ButtonById[a].order < Config.ButtonById[b].order
			end)
			for _, id in ipairs(ids) do
				self:install(id, true)
			end
			-- After the replay stood the walls up: the saved dents scale onto the
			-- current maxes and the ring is made to agree (#124).
			self:restoreSiege(profile)
		end

		self:refreshButtons()
		self:updateSign()
		self:fireOwnedChanged()
		self:resetStorage()
		return true
	end

	function Tycoon:release()
		self.owner = nil
		self.generation += 1
		self.owned = {}
		self.beltBonus, self.powerFactor = 0, 1
		self:refreshBeltSpeed()

		for _, entry in pairs(self.objects) do
			if entry.machine then
				entry.machine:Destroy()
				entry.machine = nil
			end
		end
		self.machines:ClearAllChildren()
		self.props:ClearAllChildren()
		self:clearDrops()
		self:setFactoryVisible(false)

		self:eachBeltSurface(function(surface)
			surface.Color = COLORS.belt
		end)
		-- Dropped BEFORE updateSign runs below, not left for VaultService to clear
		-- on the owned-changed that follows: for those few lines the plot has no
		-- owner, and the last owner's "leaving now banks 2.4M" would be sitting on
		-- a free plot's sign while the claim beacon lit up next to it.
		self:setVaultGauge(0, nil, nil, false)
		-- Storage and siege state are tenancy-scoped: the next claimant starts
		-- with an intact plot, whatever the last one let happen to it.
		self:resetStorage()
		self:resetSiege()

		self:refreshButtons()
		self:updateSign()
		self:fireOwnedChanged()
	end

	--- Wipes the factory but keeps the player, and hands out a rebirth.
	function Tycoon:rebirth(player: Player): boolean
		if player ~= self.owner then
			return false
		end
		local profile = DataService.get(player)
		if not profile then
			return false
		end
		local cost = Economy.rebirthCost(player)
		if profile.rebirths >= Config.Rebirth.MaxRebirths then
			Economy.notify(player, { kind = "warn", title = "Max rebirths", body = "You have ascended as far as sahur allows." })
			return false
		end
		if profile.cash < cost then
			Economy.notify(player, {
				kind = "warn",
				title = "Not enough Tung",
				body = ("Rebirth costs %s."):format(Util.abbreviate(cost)),
			})
			return false
		end

		profile.rebirths += 1
		profile.cash = Config.Economy.StartingCash

		-- A rebirth is a FACTORY reset, not an account reset. The cabinets are
		-- bought with the same wallet but they are not part of the thing being
		-- rebuilt, and re-earning your bat every prestige is exactly the coupling
		-- this split exists to remove.
		--
		-- This also closes a live bug. Rebirth used to wipe `owned` wholesale
		-- while leaving profile.batTier alone, and CombatService.grantBat is
		-- monotonic — so re-buying batforge afterwards took your money and did
		-- nothing at all.
		local kept = {}
		for id in pairs(profile.owned) do
			local def = Config.ButtonById[id]
			-- One derivation, not two name tests with opposite polarity — a track
			-- missing from one of them fails OPEN and the generator survives the
			-- reset it is part of. keptOnRebirth also carries #109's carve-out:
			-- land ground survives, the machines on it reset.
			if def and Config.keptOnRebirth(def) then
				kept[id] = true
			end
		end
		profile.owned = kept

		self.generation += 1
		self.owned = Util.shallowCopy(kept)
		self.beltBonus, self.powerFactor = 0, 1
		self:refreshBeltSpeed()
		for _, entry in pairs(self.objects) do
			-- Side-track props live in self.props and are not cleared below, so
			-- their entries must keep their handle or the model outlives its
			-- reference and can never be cleaned up.
			if not Config.keptOnRebirth(entry.def) then
				entry.machine = nil
			end
		end
		self.machines:ClearAllChildren()
		self:clearDrops()

		self:refreshButtons()
		self:updateSign()
		self:fireOwnedChanged()
		Economy.push(player)

		-- After profile.owned has been wiped, so the milestone Analytics carries
		-- forward is the one this player now stands on rather than the one the
		-- rebirth just took away.
		Analytics.onRebirth(player, profile.rebirths, cost, profile.cash)

		Economy.notify(player, {
			kind = "rebirth",
			title = "SAHUR REBIRTH #" .. profile.rebirths,
			body = ("All payouts are now x%.2f."):format(Economy.multiplier(player)),
		})

		-- #107: the moment's report, DERIVED — every line reads Config or the
		-- profile, so a new tier row cannot ship with a stale list. The client
		-- only renders it.
		do
			local landCount = 0
			for id in pairs(kept) do
				local def = Config.ButtonById[id]
				if def and (def.track == "landL" or def.track == "landR") then
					landCount += 1
				end
			end
			local bat = Config.Bats[math.clamp(profile.batTier or 1, 1, #Config.Bats)]
			local armor = Config.Armor.Tiers[math.clamp(profile.armorTier or 1, 1, #Config.Armor.Tiers)]
			local row = Config.tierRow(profile.rebirths)
			Net.event("RebirthReport"):FireClient(player, {
				rebirths = profile.rebirths,
				multiplier = Economy.multiplier(player),
				rank = row.name,
				motto = row.motto,
				rankChanged = Config.tierName(profile.rebirths) ~= Config.tierName(profile.rebirths - 1),
				keeps = {
					("%s, in your hand"):format(bat and bat.name or "your bat"),
					("%s, on your back"):format(armor and armor.name or "your armour"),
					landCount > 0 and ("%d pieces of ground"):format(landCount) or nil,
					(profile.reputation or 0) >= 1 and ("%d Rep"):format(math.floor(profile.reputation)) or nil,
				},
			})
		end

		local character = player.Character
		if character and character.PrimaryPart then
			Fx.burst(character:GetPivot().Position, Color3.fromRGB(200, 120, 255), 60, workspace)
		end
		return true
	end

	return Tycoon
end


__MODULES["Parts"] = function()
	--[[
		tycoon/Parts.lua — every Part on a plot is made here, and the description a
		belt machine's masses are built from.

		newPart is the plot's one part constructor: anchored, smooth surfaces,
		collidable unless told otherwise. The aggregator re-exports it as
		`Tycoon.part` because FloorService builds its deck out of the same defaults,
		and a second near-identical local copy that drifts is what that re-export
		prevents.

		MACHINE_MASSES exists so the GHOST PREVIEW and the real machine are built
		from ONE description — buildMasses below, buildGhost in tycoon/Buttons.lua.
		A silhouette hand-copied from the installer stops matching the machine the
		first time either is touched.

		It reads a def's `kind` and nothing else about it. Which def gets built, and
		when, belongs to Buttons and Installers; the offsets and heights belong to
		Config.Layout, so a mass sized from a literal here is a mass the verifier
		cannot check against the belt it hangs over.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Tycoon = Req("Class")

	local L = Config.Layout

	local Parts = {}

	-- ─────────────────────────────────────────────────────────────────────────────
	-- construction helpers
	-- ─────────────────────────────────────────────────────────────────────────────

	local function newPart(parent, name, size, cf, color, material, collide)
		local p = Instance.new("Part")
		p.Name = name
		p.Size = size
		p.CFrame = cf
		p.Color = color
		p.Material = material or Enum.Material.SmoothPlastic
		p.Anchored = true
		p.CanCollide = collide ~= false
		p.TopSurface = Enum.SurfaceType.Smooth
		p.BottomSurface = Enum.SurfaceType.Smooth
		p.Parent = parent
		return p
	end

	-- ── machine geometry ─────────────────────────────────────────────────────────

	--- The masses a belt machine is made of: { name, size, offset, y, collide }.
	--- Offset is outboard of the belt, y is the centre height, both in the leg's
	--- own frame (see Tycoon:segmentCF).
	---
	--- This exists so the GHOST PREVIEW and the real machine are built from one
	--- description. A silhouette hand-copied from the installer is a silhouette
	--- that stops matching the machine the first time either is touched.
	local MACHINE_MASSES = {
		Dropper = function()
			-- Sized to Layout.MachineFootprint so neighbouring droppers can never
			-- overlap. The arm hangs directly over the running surface, so it is
			-- non-collidable: a tall drop has to pass under it untouched.
			local depth = L.MachineFootprint
			return {
				{ "Base", Vector3.new(depth, 3.6, depth), L.MachineOffset, 1.8, true },
				{ "Core", Vector3.new(depth - 1.4, 2.2, depth - 1.4), L.MachineOffset, 4.7, true },
				{ "Arm", Vector3.new(L.MachineOffset, 1, 1.4), L.MachineOffset / 2, L.BeltY + 5, false },
				{ "Spout", Vector3.new(2.4, 1.8, 2.4), 0, L.BeltY + 4.2, false },
				{ "Nozzle", Vector3.new(1.8, 0.5, 1.8), 0, L.BeltY + 3.2, false },
			}
		end,
		Upgrader = function()
			-- Single post on the OUTBOARD side with a cantilevered beam, rather
			-- than an arch straddling the belt: keeps the inboard walkway clear.
			local reach = L.MachineOffset + L.BeltWidth / 2
			return {
				{ "Post", Vector3.new(1.8, 6, 1.8), L.MachineOffset, 3, true },
				{ "Beam", Vector3.new(reach, 1.5, 2.2), (L.MachineOffset - L.BeltWidth / 2) / 2, L.BeltY + 4.6, false },
				-- The VISIBLE plate. One stud thick, because that is what it should
				-- look like: a scanner beam, not a wall. It no longer does the
				-- catching.
				{ "Scanner", Vector3.new(L.BeltWidth, 3.6, 1), 0, L.BeltY + 1.8, false },
				-- ...and the volume that actually catches drops, invisible and five
				-- studs deep. Same split, and for the same reason, as the
				-- mezzanine's invisible guard behind its visible railing: what a
				-- thing looks like and what it has to physically be are different
				-- questions, and a 1-stud trigger loses drops at belt speed.
				{ "ScanTrigger", Vector3.new(L.BeltWidth, 3.6, L.TriggerThickness), 0, L.BeltY + 1.8, false },
			}
		end,
	}

	--- Builds a machine's masses into `parent` and returns them keyed by name.
	function Tycoon:buildMasses(def, parent: Instance, color: Color3, material: Enum.Material)
		local shape = MACHINE_MASSES[def.kind]
		if not shape then
			return {}
		end
		local legIndex, distance, pathIndex = self:legOf(def)
		local parts = {}
		for _, mass in ipairs(shape()) do
			local name, size, offset, y, collide = mass[1], mass[2], mass[3], mass[4], mass[5]
			parts[name] = newPart(parent, name, size,
				self:segmentCF(legIndex, distance, offset, y, pathIndex), color, material, collide)
		end
		return parts, legIndex, distance, pathIndex
	end

	-- Exported because the files that build parts are other files now. `newPart`
	-- was a file-local when there was one file; MACHINE_MASSES is read by
	-- tycoon/Buttons.lua, which draws the ghost from the same description the real
	-- machine is built from.
	Parts.newPart = newPart
	Parts.MACHINE_MASSES = MACHINE_MASSES

	return Parts
end


__MODULES["Props"] = function()
	--[[
		tycoon/Props.lua — the furniture around the belt: the claim rig, the
		rebirth pad, the generator yard and the generator standing on it. The
		side-track cabinets stood here until #108 moved weapons and armour into
		the shop.

		THE self.props / self.machines SPLIT IS THE POINT OF THIS FILE. The yard
		slab goes in self.props; the generator that stands on the yard is a
		machine, so a rebirth — machines:ClearAllChildren() — takes it down and
		leaves the slab standing. release() clears props as well, and that is why
		ensureYard is IDEMPOTENT and re-run from refreshButtons. It used to be
		buildYard(), called once from the constructor: the first owner to leave a
		plot took its slab and fence with them for the rest of the server's life,
		and every later owner bought generators that stood in mid-air.

		refreshGenerator is DERIVED STATE, not an install side effect. It shows the
		LAST owned power rung — the same rule Config.powerFactor uses, because the
		factor is cumulative and so is the machine that represents it — and rebuilds
		only when that rung changes, so the refresh on every purchase costs one
		attribute read. It deliberately does not write self.objects[id].machine: four
		button entries would share one model handle and release() would destroy
		through one of them and leave three dangling.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Style = Req("Style")
	local TungModels = Req("TungModels")
	local Fx = Req("Fx")
	local Economy = Req("Economy")
	local Tycoon = Req("Class")
	local Parts = Req("Parts")

	local newPart = Parts.newPart
	local COLORS = Tycoon.COLORS

	local L = Config.Layout

	-- ── claim pad ────────────────────────────────────────────────────────────────

	function Tycoon:buildClaimPad()
		local folder = Instance.new("Folder")
		folder.Name = "Claim"
		folder.Parent = self.model
		self.claimFolder = folder

		local frontX, frontZ = L.ClaimPadAt.X, L.ClaimPadAt.Z

		-- The pad itself. Safe to centre now that the factory is hidden while
		-- unclaimed -- there is nothing standing on the frontage to hide behind.
		local pad = newPart(folder, "ClaimPad", Vector3.new(34, 1.2, 20),
			self:at(frontX, 0.6, frontZ), Color3.fromRGB(120, 230, 160), Enum.Material.Neon)
		pad.CanCollide = false
		pad:SetAttribute("PlotIndex", self.index)
		self.claimPad = pad

		-- A beacon, because a flat pad on the floor is invisible from more than a
		-- few studs away or from any angle that isn't directly above it. THIS is
		-- the thing you actually navigate by.
		local beacon = newPart(folder, "ClaimBeacon", Vector3.new(7, 80, 7),
			self:at(frontX, 40, frontZ), Color3.fromRGB(120, 255, 170), Enum.Material.Neon, false)
		beacon.Transparency = 0.55
		beacon.CanQuery = false

		local halo = newPart(folder, "ClaimHalo", Vector3.new(0.6, 44, 44),
			self:at(frontX, 0.35, frontZ) * CFrame.Angles(0, 0, math.pi / 2),
			Color3.fromRGB(80, 220, 130), Enum.Material.Neon, false)
		halo.Shape = Enum.PartType.Cylinder
		halo.Transparency = 0.4
		halo.CanQuery = false

		-- Sign high up the beacon so it clears the walls of neighbouring plots and
		-- is readable from the arena.
		local signAnchor = newPart(folder, "ClaimSign", Vector3.new(1, 1, 1),
			self:at(frontX, 62, frontZ), Color3.new(1, 1, 1), nil, false)
		signAnchor.Transparency = 1
		signAnchor.CanQuery = false

		-- `world`, not `plot`: a free plot has to be findable from anywhere on the
		-- ring, and the two furthest-apart plots are a full diameter apart. This is
		-- the one label whose old 1200 was doing a real job rather than being the
		-- number somebody happened to type.
		local billboard = Style.billboard(signAnchor, {
			name = "ClaimSign", width = 34, height = 12, distance = "world",
		})
		local label = Style.text(billboard, {
			text = "PLOT " .. self.index .. "\nFREE — WALK ON IT",
			color = Color3.fromRGB(190, 255, 215),
		})
		self.claimLabel = label
	end

	-- ── rebirth pad ──────────────────────────────────────────────────────────────

	--- invariant: the generator yard — a small slab behind the plot's back-right
	--- corner, with a fence around three sides of it.
	---
	--- Permanent plot furniture in self.props. The GENERATOR that stands on it
	--- goes into self.machines instead, so a rebirth takes it down with the
	--- droppers it was speeding up and leaves the yard standing.
	---
	--- IDEMPOTENT AND RE-RUN FROM refreshButtons: release() does
	--- props:ClearAllChildren(), so a yard built once from the constructor goes
	--- with the first owner who leaves and never comes back: every subsequent
	--- owner buys generators that stand in mid-air.
	---
	--- NO SIGN. design:D-05: the pad twelve studs away already
	--- carries the track, the tier name, the effect and the price.
	function Tycoon:ensureYard()
		local Y = L.Yard
		if self.props:FindFirstChild("Yard") then
			return
		end
		local model = Instance.new("Model")
		model.Name = "Yard"
		model.Parent = self.props

		newPart(model, "Slab", Y.Size,
			self:at(Y.Centre.X, Y.LocalY - Y.Size.Y / 2, Y.Centre.Z),
			Color3.fromRGB(96, 96, 104), Enum.Material.Concrete)

		-- Fence on three sides. The plot side is left open: it is where you walk in
		-- from, through the doorway the wall leaves for it.
		--
		-- Inset by half its own thickness so it stands ON the slab rather than
		-- straddling the edge. With the yard now flush against the plot's own
		-- x-extent at 60, the old straddling fence would have hung half a stud past
		-- it and made the containment assertion a lie by exactly that much.
		local halfX = Y.Size.X / 2 - Y.FenceThickness / 2
		local halfZ = Y.Size.Z / 2 - Y.FenceThickness / 2
		local sides = {
			{ Vector3.new(Y.Size.X, Y.FenceHeight, Y.FenceThickness), Vector3.new(0, 0, -halfZ) },
			{ Vector3.new(Y.FenceThickness, Y.FenceHeight, Y.Size.Z), Vector3.new(-halfX, 0, 0) },
			{ Vector3.new(Y.FenceThickness, Y.FenceHeight, Y.Size.Z), Vector3.new(halfX, 0, 0) },
		}
		for index, side in ipairs(sides) do
			newPart(model, "Fence" .. index, side[1],
				self:at(Y.Centre.X + side[2].X, Y.LocalY + Y.FenceHeight / 2, Y.Centre.Z + side[2].Z),
				COLORS.frame, Enum.Material.DiamondPlate)
		end
	end

	--- The one generator, showing the highest power rung this plot owns.
	---
	--- DERIVED STATE, not an install side effect. It used to be buildYardMachine(),
	--- called from INSTALLERS.Power, which built a NEW machine per rung in a slot of
	--- its own — four generators standing in a row for a track whose rungs are
	--- upgrades of each other. Now each rung replaces the machine in place and the
	--- visible change is the variant: golden, crimson, void, infinity.
	---
	--- Rebuilt only when the tier actually changes, so a refresh on every button
	--- purchase costs one attribute read. Lives in self.machines, so a rebirth
	--- takes it down and leaves the yard standing.
	function Tycoon:refreshGenerator()
		local Y = L.Yard

		-- The LAST owned rung, the same rule Config.powerFactor uses, because
		-- `factor` is cumulative and so is the machine that represents it.
		local top = nil
		for _, def in ipairs(Config.Tracks.power) do
			if self.owned[def.id] then
				top = def
			end
		end

		local existing = self.machines:FindFirstChild("Generator")
		if existing and existing:GetAttribute("PowerId") == (top and top.id or nil) then
			return existing
		end
		if existing then
			existing:Destroy()
		end
		if not top then
			return nil
		end

		local variant = Config.Variants[top.variant] or Config.Variants.classic
		local spot = Config.yardMachinePosition()

		local model = Instance.new("Model")
		model.Name = "Generator"
		model:SetAttribute("PowerId", top.id)
		model.Parent = self.machines

		newPart(model, "Body", Y.MachineSize,
			self:at(spot.X, spot.Y + Y.MachineSize.Y / 2, spot.Z), COLORS.metal, Enum.Material.Metal)
		local core = newPart(model, "Core",
			Vector3.new(Y.MachineSize.X - 4, Y.MachineSize.Y - 5, Y.MachineSize.Z - 4),
			self:at(spot.X, spot.Y + Y.MachineSize.Y / 2, spot.Z),
			variant.light and variant.light.color or variant.wood, Enum.Material.Neon, false)
		core.Transparency = 0.35
		Fx.applyVariant(core, variant)

		-- Deliberately NOT written to self.objects[id].machine. Four button entries
		-- would share one model handle, and release() destroys through one of them
		-- and leaves three dangling. machines:ClearAllChildren() already covers it
		-- in both release() and rebirth().
		return model
	end


	-- The guide's mouth (#100): Main.server points this at the hint machinery,
	-- so the mixin never learns what an objective is. (tycoon, player) -> ().
	Tycoon.guideSpeaker = nil :: ((any, Player) -> ())?

	--- The guide (#100): a small Tung beside the spawn aisle that speaks the
	--- current hint. Idempotent by name, on the refreshButtons beat like the
	--- yard; props-parented, so it leaves with the tenancy. Purely informational
	--- — its whole mechanical surface is one prompt.
	function Tycoon:ensureGuide()
		-- fixture plots in the harness carry no props folder; the guide is parts
		if not self.props then
			return
		end
		local existing = self.props:FindFirstChild("Guide")
		if not self.owner then
			if existing then
				existing:Destroy()
			end
			return
		end
		if existing then
			return
		end
		local model = Instance.new("Model")
		model.Name = "Guide"
		model.Parent = self.props

		local spot = Config.Layout.GuideAt
		local guide = TungModels.buildStatue("classic", 0.9)
		guide:PivotTo(self:at(spot.X, 2.6, spot.Z) * CFrame.Angles(0, math.pi, 0))
		guide.Parent = model

		local anchor = guide.PrimaryPart or guide:FindFirstChildWhichIsA("BasePart")
		if anchor then
			local prompt = Instance.new("ProximityPrompt")
			prompt.Name = "TalkToGuide"
			prompt.ActionText = "Talk"
			prompt.ObjectText = "Your Tung"
			prompt.HoldDuration = 0
			prompt.MaxActivationDistance = 10
			prompt.RequiresLineOfSight = false
			prompt.Parent = anchor
			prompt.Triggered:Connect(function(player)
				if Tycoon.guideSpeaker then
					Tycoon.guideSpeaker(self, player)
				end
			end)
		end
	end

	function Tycoon:buildRebirthPad()
		local folder = Instance.new("Folder")
		folder.Name = "Rebirth"
		folder.Parent = self.model
		self.rebirthFolder = folder
		self:registerFactoryFolder(folder)

		local spot = L.RebirthPadAt
		local pad = newPart(folder, "RebirthPad", Vector3.new(12, 1.2, 12),
			self:at(spot.X, 0.9, spot.Z), Color3.fromRGB(200, 120, 255), Enum.Material.Neon)
		pad.CanCollide = false
		self.rebirthPad = pad

		local ring = newPart(folder, "RebirthRing", Vector3.new(0.4, 16, 16),
			self:at(spot.X, 0.3, spot.Z) * CFrame.Angles(0, 0, math.pi / 2),
			Color3.fromRGB(120, 60, 200), Enum.Material.Neon, false)
		ring.Shape = Enum.PartType.Cylinder

		local billboard = Style.billboard(pad, {
			name = "Sign", width = 16, height = 6, distance = "prop", offset = 6,
		})
		self.rebirthLabel = Style.text(billboard, {
			name = "Label", text = "SAHUR REBIRTH",
			color = Color3.fromRGB(235, 200, 255),
		})

		-- keyed by UserId, not by Player, so leaving players aren't kept alive
		local debounce: { [number]: number } = {}
		pad.Touched:Connect(function(hit)
			local player = self:playerFromHit(hit)
			if not player or player ~= self.owner then
				return
			end
			local last = debounce[player.UserId]
			if last and os.clock() - last < 3 then
				return
			end
			debounce[player.UserId] = os.clock()
			Economy.notify(player, {
				kind = "rebirthPrompt",
				title = "SAHUR REBIRTH",
				body = ("Wipe your factory for a permanent x%.2f payout boost?"):format(Config.Rebirth.MultiplierPerRebirth),
				cost = Economy.rebirthCost(player),
			})
		end)
	end

	return Tycoon
end


__MODULES["Purchase"] = function()
	--[[
		tycoon/Purchase.lua — the two ways a button becomes owned, and the difference
		between them.

		tryPurchase IS THE ONLY PLACE A BUTTON IS EVER BOUGHT WITH MONEY. It checks
		the owner, the requirements and the wallet, writes profile.owned, and emits
		the economy event. install() applies a purchase and is ALSO replayed for
		every owned button at assign(), which is exactly why the Analytics call sits
		in tryPurchase: logging it in install() would report a returning player's
		whole factory as bought again this second.

		requirementsMet is re-checked here as well as in refreshButtons, so a stale
		Touched on a pad that is about to be hidden cannot buy through a closed gate.

		install() dispatches through Tycoon.INSTALLERS on `kind` and warns rather
		than throwing when there is no case for it, so an unknown kind costs one
		button instead of the plot's construction. KNOWN_KINDS in
		tools/verify_config.lua is what stops one reaching production.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Util = Req("Util")
	local Fx = Req("Fx")
	local Economy = Req("Economy")
	local DataService = Req("DataService")
	local Analytics = Req("Analytics")
	local Tycoon = Req("Class")

	-- ── purchasing ───────────────────────────────────────────────────────────────

	function Tycoon:playerFromHit(hit: BasePart): Player?
		local character = hit and hit:FindFirstAncestorOfClass("Model")
		if not character then
			return nil
		end
		local humanoid = character:FindFirstChildOfClass("Humanoid")
		if not humanoid or humanoid.Health <= 0 then
			return nil
		end
		return game:GetService("Players"):GetPlayerFromCharacter(character)
	end

	function Tycoon:tryPurchase(player: Player, id: string)
		if player ~= self.owner then
			return
		end
		local def = Config.ButtonById[id]
		if not def or self.owned[id] then
			return
		end
		if not self:requirementsMet(id) then
			return
		end
		if not Economy.spend(player, def.price) then
			local short = def.price - Economy.get(player)
			Economy.notify(player, {
				kind = "warn",
				title = "Not enough Tung",
				body = ("You need %s more for %s."):format(Util.abbreviate(short), def.name),
			})
			return
		end

		local profile = DataService.get(player)
		if profile then
			profile.owned[id] = true
		end

		self:install(id, false)

		-- THE ONLY PLACE A BUTTON IS EVER BOUGHT WITH MONEY, which is why the
		-- economy event goes here and not in install() — install() also runs for
		-- every button of a save being replayed at assign(), and logging those would
		-- report a returning player's whole factory as bought again this second.
		Analytics.onPurchase(player, def, Economy.get(player))

		Economy.notify(player, {
			kind = "buy",
			title = def.name,
			body = def.blurb or "",
			price = def.price,
		})
		Economy.push(player)
	end

	--- Applies a purchase. `silent` skips effects (used when loading a save).
	function Tycoon:install(id: string, silent: boolean?)
		local def = Config.ButtonById[id]
		if not def or self.owned[id] then
			return
		end
		self.owned[id] = true

		local entry = self.objects[id]
		if entry then
			entry.holder.Parent = nil
		end

		local installer = Tycoon.INSTALLERS[def.kind]
		if installer then
			installer(self, def, silent)
		else
			warn("[Tung] no installer for kind " .. tostring(def.kind))
		end

		if not silent then
			-- The twin of the bug buttonBaseCF fixes: the purchase confetti used a
			-- literal world 5 rather than five studs above the button, so a
			-- mezzanine purchase would have burst on the ground floor underneath it.
			local variant = Config.Variants[def.variant or "classic"]
			Fx.burst((self:buttonBaseCF(def) * CFrame.new(0, 5, 0)).Position, variant.wood, 18, self.model)
		end

		self:refreshButtons()
		self:fireOwnedChanged()
	end

	return Tycoon
end


__MODULES["Siege"] = function()
	--[[
		tycoon/Siege.lua — the walls and the gate can be broken, and anyone
		present can stand them back up.

		design:D-02, via #124. The wall is the boundary the open world will press
		against: mobs will wear it down when #89 lets them reach it, a raiding
		player breaks the GATE to get in (#94), and both scale with the land —
		level is expansions owned + 1, so toughness arrives with the ground and
		there is no separate wall ladder.

		AUTHORITY IS THE TABLE, THE PARTS ARE A PICTURE. self.structureHealth maps
		a siege key — "wall_front", "wall_left", "gate_gateway", one per side and
		one per opening — to hit points, assigned from Config.wallMaxHealth /
		gateMaxHealth and never accumulated. A broken wall has no parts to carry
		an attribute, which is why the table is the authority; applySiegeState
		makes the ring agree with it after every rebuild, so the refreshButtons
		beat cannot resurrect a wall the raiders earned.

		KEYS ARE STABLE ACROSS LAND STATES. A side is one damage unit whatever its
		span count — course names shift as land splits the runs, sides do not —
		and an opening's id never changes. That is what lets damage persist (#124
		ships it as fractions in the profile) without a rename ever forgiving it.

		DAMAGE COMES THROUGH ONE DOOR. Tycoon.siegeStrike receives the parts a
		swing boxed (Main.server wires it into CombatService's structure observer,
		keeping the require arrows one-way), resolves them to plot + key, refuses
		the plot's own owner, and applies one hit per key per swing. Mobs get the
		same door when #89 wires them.

		NO REMOTE, the CollectOffline argument: a repair intent has no payload, so
		the ProximityPrompt on the stump is the whole interface. Since #123 the
		repair is open to anyone — it only ever helps the plot — and a stranger's
		repair earns a kindness credit through Tycoon.repairObserver, with the
		breaker themselves the one exclusion.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Fx = Req("Fx")
	local DataService = Req("DataService")
	local Tycoon = Req("Class")

	local S = Config.Structure
	local H = S.Health

	local STUMP_COLOR = Color3.fromRGB(64, 48, 38)

	-- Course prefixes that belong to a wall side. `Sill` is deliberately absent:
	-- the sill course survives a break as the stump the repair prompt stands on.
	-- `Buttress` is a chunk of the wall's face, so it falls with its side and a
	-- swing on it lands on the wall.
	local BREAKABLE_PREFIXES = { Body = true, Head = true, Lintel = true, Buttress = true }

	-- The torches are dressing, never targets: a swing on one lands nowhere. But
	-- they hang on a wall, so when that wall breaks they go down with it — a
	-- floating torch over a breach is the fixture-ghost bug with a flame on it.
	local RIDES_ON_WALL = { Torch = true, TorchFlame = true }

	--- The siege level: expansions owned + 1. Derived, never stored.
	function Tycoon:siegeLevel(): number
		local counts = self:landState()
		return counts.left + counts.right + 1
	end

	--- Full health for one siege key at the current level and masonry tier.
	function Tycoon:siegeMaxHealth(key: string): number
		if key:sub(1, 5) == "gate_" then
			return Config.gateMaxHealth(self:siegeLevel(), self:masonryTiers())
		end
		return Config.wallMaxHealth(self:siegeLevel(), self:masonryTiers())
	end

	--- Every siege key this plot has: one per side, one per opening.
	function Tycoon:siegeKeys(): { string }
		local keys = {}
		for _, side in ipairs(S.Sides) do
			table.insert(keys, "wall_" .. side)
		end
		for _, opening in ipairs(S.Openings) do
			table.insert(keys, "gate_" .. opening.id)
		end
		return keys
	end

	--- Fresh tenancy or repair: every key at full. assign() overwrites this from
	--- the saved fractions right after.
	function Tycoon:resetSiege()
		self.structureHealth = {}
		for _, key in ipairs(self:siegeKeys()) do
			self.structureHealth[key] = self:siegeMaxHealth(key)
		end
	end

	--- Mirror the dents into the profile, as fractions of full health — only
	--- keys below full, so a healthy plot saves an empty table and a dent
	--- survives the max moving when the plot buys land. Called on every damage,
	--- repair and reset; a plot with no owner has no profile to write.
	function Tycoon:syncSiege()
		local owner = self.owner
		local profile = owner and DataService.get(owner)
		if not profile then
			return
		end
		local out = {}
		for _, key in ipairs(self:siegeKeys()) do
			local hp = self.structureHealth[key]
			local max = self:siegeMaxHealth(key)
			if hp and hp < max then
				out[key] = hp / max
			end
		end
		profile.structure = out
	end

	--- The other half of the round trip, run by assign() after the install
	--- replay has stood the walls up: saved fractions scale onto the CURRENT
	--- maxes, and the ring is made to agree.
	function Tycoon:restoreSiege(profile)
		for key, fraction in pairs(profile.structure or {}) do
			if type(fraction) == "number" and self.structureHealth[key] ~= nil then
				self.structureHealth[key] = self:siegeMaxHealth(key) * math.clamp(fraction, 0, 1)
			end
		end
		self:withWallRing(function(ring)
			self:applySiegeState(ring)
		end)
	end

	function Tycoon:structureBroken(key: string): boolean
		local hp = self.structureHealth and self.structureHealth[key]
		return hp ~= nil and hp <= 0
	end

	--- The side a wall-course part belongs to, or the opening a leaf hangs in,
	--- as a siege key — nil for anything that is not siege-able.
	function Tycoon.siegeKeyForPart(part: BasePart): string?
		local prefix, rest = part.Name:match("^(%a+)_(.+)$")
		if not prefix then
			return nil
		end
		if prefix == "Gate" then
			local opening = rest:match("^([%w]+)_%d+$")
			return opening and ("gate_" .. opening) or nil
		end
		if BREAKABLE_PREFIXES[prefix] or prefix == "Sill" then
			local side = rest:match("^(%a+)")
			if side == "back" or side == "front" or side == "left" or side == "right" then
				return "wall_" .. side
			end
		end
		return nil
	end

	--- The storage unit is a swing target too (#94): its body resolves to the
	--- reserved key "storage", which siegeStrike routes to damageStorage. Kept
	--- out of siegeKeyForPart — the wall/gate machinery (max health, repair
	--- prompts, saved fractions) must never see it.
	local function isStorageBody(part: BasePart): boolean
		return part.Name == "VaultBase"
	end

	--- Make the standing ring agree with the health table: a broken side keeps
	--- its sill course as a charred stump and loses everything above it; a broken
	--- gate loses its leaves. Idempotent, and called at the end of buildWallRing,
	--- so the refreshButtons beat re-applies breakage instead of healing it.
	function Tycoon:applySiegeState(ring: Instance)
		for _, part in ipairs(ring:GetChildren()) do
			if part:IsA("BasePart") then
				local key = Tycoon.siegeKeyForPart(part)
				if key and self:structureBroken(key) then
					local prefix = part.Name:match("^(%a+)_")
					if prefix == "Sill" then
						part.Color = STUMP_COLOR
					elseif prefix == "Gate" or BREAKABLE_PREFIXES[prefix] then
						part:Destroy()
					end
				elseif key then
					local prefix = part.Name:match("^(%a+)_")
					if prefix == "Sill" and part.Color == STUMP_COLOR then
						-- Healed: back to whatever the masonry currently wears,
						-- so a stone plot's repaired stump stops reading charred
						-- without dropping back to wood.
						part.Color = select(2, self:masonryLook())
					end
				else
					-- The torches resolve to no key — they are dressing — but
					-- they ride their wall down. Repair rebuilds the ring, so
					-- they come back with the courses.
					local prefix, rest = part.Name:match("^(%a+)_(%a+)")
					if prefix and RIDES_ON_WALL[prefix]
							and self:structureBroken("wall_" .. tostring(rest)) then
						part:Destroy()
					end
				end
			end
		end
		self:refreshSiegePrompts(ring)
	end

	--- One repair prompt per broken key, standing on the stump (walls) or on an
	--- invisible anchor at the opening (gates). Enabled only while broken.
	function Tycoon:refreshSiegePrompts(ring: Instance)
		for _, key in ipairs(self:siegeKeys()) do
			local anchorName = "SiegeAnchor_" .. key
			local anchor = ring:FindFirstChild(anchorName, true)
			local broken = self:structureBroken(key)
			if broken and not anchor then
				-- The host outlives the break by construction: a wall's sill
				-- course is the stump a break leaves, and a gate break destroys
				-- only its leaves, so the lintel over the opening still stands.
				local hostPrefix, hostKey = "Sill_", key
				if key:sub(1, 5) == "gate_" then
					hostPrefix = "Lintel_"
					for _, opening in ipairs(S.Openings) do
						if "gate_" .. opening.id == key then
							hostKey = "wall_" .. opening.side
						end
					end
				end
				local host
				for _, part in ipairs(ring:GetChildren()) do
					if part:IsA("BasePart") and part.Name:sub(1, #hostPrefix) == hostPrefix
							and Tycoon.siegeKeyForPart(part) == hostKey then
						host = part
						break
					end
				end
				if host then
					local prompt = Instance.new("ProximityPrompt")
					prompt.Name = anchorName
					prompt.ActionText = "Repair"
					prompt.ObjectText = key:sub(1, 5) == "gate_" and "Gate" or "Wall"
					prompt.HoldDuration = H.RepairSeconds
					prompt.MaxActivationDistance = 16
					prompt.RequiresLineOfSight = false
					prompt.Parent = host
					prompt.Triggered:Connect(function(player)
						self:repairStructure(key, player)
					end)
				end
			elseif not broken and anchor then
				anchor:Destroy()
			end
		end
	end

	--- One hit on one key. Returns the damage dealt — 0 for a key already down,
	--- which is how a caller counts wasted swings.
	function Tycoon:damageStructure(key: string, amount: number, _attacker: Player?): number
		if not self.structureHealth or self.structureHealth[key] == nil then
			return 0
		end
		if amount <= 0 or self:structureBroken(key) then
			return 0
		end
		if _attacker then
			self.lastBreaker = self.lastBreaker or {}
			self.lastBreaker[key] = _attacker
		end
		self.structureHealth[key] = math.max(0, self.structureHealth[key] - amount)
		if self.structureHealth[key] <= 0 then
			self:withWallRing(function(ring)
				self:applySiegeState(ring)
			end)
		end
		self:syncSiege()
		return amount
	end

	-- Fired when someone repairs a plot that is not theirs (#123). Main.server
	-- points it at HelpService.credit; the arrow stays one-way, the observer
	-- shape everything else here uses.
	Tycoon.repairObserver = nil :: ((any, Player) -> ())?

	--- Anyone present, holding the prompt: the whole repair (#123 opened it past
	--- the owner — a repair only ever helps the plot). A helper earns credit
	--- through the observer; the one refusal is the breaker themselves, so
	--- break-and-repair cannot farm kindness. The rebuild path is the ring's own
	--- idempotent builders — rebuildWallRing re-emits the courses and
	--- hangGateLeaves the leaves, and applySiegeState (now healthy) leaves them
	--- standing.
	function Tycoon:repairStructure(key: string, player: Player): boolean
		if not self:structureBroken(key) then
			return false
		end
		local breaker = self.lastBreaker and self.lastBreaker[key]
		if self.lastBreaker then
			self.lastBreaker[key] = nil
		end
		if player ~= self.owner and self.owner and player ~= breaker
				and Tycoon.repairObserver then
			Tycoon.repairObserver(self, player)
		end
		self.structureHealth[key] = self:siegeMaxHealth(key)
		self:syncSiege()
		self:rebuildWallRing()
		local character = player.Character
		if character and character.PrimaryPart then
			Fx.burst(character:GetPivot().Position, Color3.fromRGB(180, 220, 140), 10, workspace)
		end
		return true
	end

	--- Ancestry by walking `.Parent`, which the spec harness's Instances carry;
	--- `IsDescendantOf` they do not, and this is the one place it would be asked.
	local function isUnder(part: Instance, root: Instance): boolean
		local node = part
		while node do
			if node == root then
				return true
			end
			node = node.Parent
		end
		return false
	end

	-- Whether two players are allies (#102). Main.server points this at the
	-- party predicate; a mixin cannot require a service.
	Tycoon.allyCheck = nil :: ((Player, Player) -> boolean)?

	local function isAlly(owner: Player?, attacker: Player): boolean
		return owner ~= nil and Tycoon.allyCheck ~= nil and Tycoon.allyCheck(owner, attacker)
	end

	--- The one door swing damage comes through. `parts` is everything one swing
	--- boxed; each siege key it touched takes ONE hit — `struck` is the dedup
	--- and the CALLER owns it, because a swing strikes twice (CombatService
	--- samples the arc a frame apart) and the second sample must not land a
	--- second hit. The plot's own owner is refused — no accidental
	--- self-demolition — and so is the owner's party (#102): a partymate's plot
	--- is your plot's trust boundary. No PvP-zone rule exists to consult (#89):
	--- a raider breaks a gate wherever the gate is.
	function Tycoon.siegeStrike(parts: { BasePart }, attacker: Player, damage: number, struck: { [any]: any }?)
		struck = struck or {}
		for _, part in ipairs(parts) do
			local key = Tycoon.siegeKeyForPart(part)
			if not key and isStorageBody(part) then
				key = "storage"
			end
			if key then
				for _, tycoon in ipairs(Tycoon.all()) do
					if tycoon.model and isUnder(part, tycoon.model) then
						if tycoon.owner ~= attacker and not isAlly(tycoon.owner, attacker)
								and not struck[tycoon] then
							struck[tycoon] = {}
						end
						if struck[tycoon] and not struck[tycoon][key] then
							struck[tycoon][key] = true
							if key == "storage" then
								tycoon:damageStorage(damage * H.PlayerDamageScale, attacker)
							else
								tycoon:damageStructure(key, damage * H.PlayerDamageScale, attacker)
							end
						end
						break
					end
				end
			end
		end
	end

	return Tycoon
end


__MODULES["Storage"] = function()
	--[[
		tycoon/Storage.lua — the storage unit's health, and the repair that needs
		someone standing at it.

		design:D-02, via #93 — the vault body is the storage unit: it has health, a
		raider hits it with a bat, and while it is broken the plot cannot bank
		overflow. Where it stands and what it looks like are #88 and #126; what a
		raid takes from it is #94; the cap it holds is #98. This file is the state
		machine those tickets call into.

		AUTHORITY IS THE TABLE, THE ATTRIBUTES ARE A MIRROR. self.storage holds
		health and brokenness; StorageHealth/StorageMaxHealth/StorageBroken on the
		vault base replicate so a client bar can draw with no remote, and nothing
		server-side may read them back.

		damageStorage IS THE SEAM. Raids (#94), mobs and bosses (#124) all land
		here, and damage already scales by storedOverflowFraction — which returns 0
		until #98 gives the unit a cap, so the raid arithmetic arrives in one place
		later with no caller changing.

		NO REMOTE, same argument as CollectOffline: the repair intent has no
		payload, so there is no number for a client to send and none for the server
		to disbelieve. The ProximityPrompt is only enabled while broken. Since #123
		anyone may repair — it only ever helps the plot — and a stranger's repair
		earns a kindness credit through Tycoon.repairObserver, with the breaker
		themselves the one exclusion.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Economy = Req("Economy")
	local Tycoon = Req("Class")

	local COLORS = Tycoon.COLORS
	local S = Config.Storage

	-- The charred coat a broken unit wears. A constant here rather than a lerp of
	-- the live colour, so repair can restore COLORS.vault exactly.
	local BROKEN_COLOR = Color3.fromRGB(38, 30, 34)

	--- Fresh tenancy, full unit. assign() and release() both call this; a rebirth
	--- keeps the owner and deliberately keeps the unit's dents with them.
	function Tycoon:resetStorage()
		self.storage = { health = S.MaxHealth, broken = false }
		local base = self.storageBase
		if base and base.Parent then
			base.Color = COLORS.vault
		end
		self:mirrorStorage()
	end

	--- Writes the replication mirror. One writer: every state change ends here.
	function Tycoon:mirrorStorage()
		local base = self.storageBase
		if base and base.Parent then
			base:SetAttribute("StorageHealth", self.storage.health)
			base:SetAttribute("StorageMaxHealth", S.MaxHealth)
			base:SetAttribute("StorageBroken", self.storage.broken)
			base:SetAttribute("StorageFill", self:storedOverflowFraction())
		end
		if self.storagePrompt and self.storagePrompt.Parent then
			self.storagePrompt.Enabled = self.storage.broken
		end
	end

	--- Hangs the repair prompt on the vault base. Called by buildCollector on the
	--- headline vault only — the plot has one storage unit, whatever it grows.
	function Tycoon:buildStorageUnit(base: BasePart)
		self.storageBase = base

		local prompt = Instance.new("ProximityPrompt")
		prompt.Name = "RepairStorage"
		prompt.ActionText = "Repair"
		prompt.ObjectText = "Storage Unit"
		prompt.HoldDuration = S.RepairHoldSeconds
		prompt.MaxActivationDistance = Config.Offline.Vault.PromptDistance
		prompt.RequiresLineOfSight = false
		prompt.Enabled = false          -- nothing to repair until something breaks
		prompt.Parent = base
		prompt.Triggered:Connect(function(player)
			self:repairStorage(player)
		end)
		self.storagePrompt = prompt

		self:mirrorStorage()
	end

	--- How full the unit is: the owner's banked Tung against the cap (#98).
	--- The damage scaling below and #94's loot arithmetic read the same number,
	--- which is the whole reason it is one function.
	function Tycoon:storedOverflowFraction(): number
		local owner = self.owner
		if not owner then
			return 0
		end
		local cap = Economy.storageCapFor(owner)
		if cap <= 0 then
			return 0
		end
		return math.clamp(Economy.get(owner) / cap, 0, 1)
	end

	--- The predicate #98's overflow banking consults: a broken unit banks nothing.
	function Tycoon:storageIntact(): boolean
		return self.storage.broken ~= true
	end

	-- The break observer: fires once per break, on the transition only, with the
	-- attacker who landed it. Main.server points this at RaidService (#94) —
	-- the service requires this world, so the arrow cannot point back.
	Tycoon.storageBreakObserver = nil :: ((any, Player) -> ())?

	--- One hit on the unit. Returns the damage actually dealt — a broken unit
	--- absorbs nothing more, so hitting it again is wasted swings, and the return
	--- value is how #94 will know the difference.
	function Tycoon:damageStorage(amount: number, attacker: Player?): number
		if amount <= 0 or self.storage.broken then
			return 0
		end
		local scaled = amount * (1 + S.DamagePerOverflowFraction * self:storedOverflowFraction())
		self.storage.health = math.max(0, self.storage.health - scaled)
		if self.storage.health <= 0 then
			self.storage.broken = true
			local base = self.storageBase
			if base and base.Parent then
				base.Color = BROKEN_COLOR
			end
			self.storageBreaker = attacker
			if attacker and Tycoon.storageBreakObserver then
				Tycoon.storageBreakObserver(self, attacker)
			end
		end
		self:mirrorStorage()
		return scaled
	end

	--- Anyone present, pressing the thing: the whole repair (#123 opened it past
	--- the owner). A helper earns credit through the repair observer; the breaker
	--- themselves is the one refusal, so break-and-repair cannot farm kindness.
	function Tycoon:repairStorage(player: Player): boolean
		if not self.storage.broken then
			return false
		end
		local breaker = self.storageBreaker
		self.storageBreaker = nil
		if player ~= self.owner and self.owner and player ~= breaker
				and Tycoon.repairObserver then
			Tycoon.repairObserver(self, player)
		end
		self.storage.health = S.MaxHealth
		self.storage.broken = false
		local base = self.storageBase
		if base and base.Parent then
			base.Color = COLORS.vault
		end
		self:mirrorStorage()
		return true
	end

	return Tycoon
end


__MODULES["Tycoon"] = function()
	--[[
		Tycoon.lua — the standardized tycoon.

		One instance per plot. Everything it builds comes from Config.Buttons, so
		adding content is a data edit, never a code edit. The contract for a new
		entry is just:

			kind = "Dropper"   -> needs slot, variant, dropValue, dropRate
			kind = "Upgrader"  -> needs slot, variant, multiplier
			kind = "Belt"      -> needs speedBonus
			kind = "Power"     -> needs factor (cumulative), variant, and NO slot
			kind = "Structure" -> needs structure ("walls" | "gates")
			kind = "Gear"      -> needs grants (a Config.Bats id)
			kind = "Armor"     -> needs grants (a Config.Armor id)
			kind = "Land"      -> needs side ("left" | "right") and width. One
			                      expansion strip of ground, outward from the centre.

		EIGHT KINDS, IN THREE PLACES. Add a case to tycoon/Installers.lua to invent
		one, add it to KNOWN_KINDS in tools/verify_config.lua, and add it to the list
		above. This list is the copy that fell behind: it said five while INSTALLERS
		and KNOWN_KINDS carried Power, Armor and Floor as well. Nothing checks it,
		which is why it is named here and in CLAUDE.md as the one to do by hand.

		THIS FILE IS THE AGGREGATOR AND NOTHING ELSE. Req searches one level of
		folder nesting (Req.lua:54-62), so Req("Tycoon") resolves here and this is
		the whole public surface: Class builds the bare table, each mixin below
		attaches its methods to that same table through Tycoon.__index, and
		`Tycoon.part` is re-exported for FloorService.

		THE REQUIRES BELOW ARE LOAD-BEARING, NOT DECORATION. Deleting one silently
		removes a dozen methods from the class, and the first symptom is a nil call
		inside Tycoon.new — pass 2 of the verifier cannot see it, because the name
		that went missing is a method on a table, not a local. The mixins require
		Class (and Parts), never each other and never this file: Req raises
		"circular dependency" at RUNTIME, so a cycle here fails the boot rather than
		the build.
	]]

	local Req = __Req
	local Tycoon = Req("Class")
	local Parts = Req("Parts")

	-- Required for their side effect: each one attaches its methods to the class
	-- table Class built. Alphabetical, because there is no load order to express —
	-- a mixin defines functions and runs no code at load.
	Req("Belt")
	Req("Buttons")
	Req("Drops")
	Req("Income")
	Req("Installers")
	Req("Land")
	Req("Ownership")
	Req("Props")
	Req("Purchase")
	Req("Siege")
	Req("Storage")
	Req("Vault")

	--- The plot's own part constructor, exposed so FloorService builds its deck out
	--- of the same defaults (anchored, smooth surfaces, collidable unless told
	--- otherwise) instead of a second near-identical local copy that drifts.
	Tycoon.part = Parts.newPart

	return Tycoon
end


__MODULES["Vault"] = function()
	--[[
		tycoon/Vault.lua — the collector at the end of a belt, the gauge on its side,
		and where a drop's ride ends.

		onCollect IS THE PAYER. design:D-02, via #180 — a tung carries its
		dropper's value, and entering the vault pays it through Config.dropPayout
		(every owned upgrader x the generator) and the live multiplier stack. It
		claims the drop with a Collected flag because Touched fires twice, and a
		double-firing sensor paying twice would mint money. A drop the sensor
		does not see is INCOME LOST — it stands at the run-off until the reaper
		takes it, unpaid — which is why buildCollector ASSERTS the vault shell
		stays downstream of the run-off and why the sensor owns the whole intake.

		setVaultGauge DECIDES NOTHING. All four of its values are worked out by
		VaultService, which is the module allowed to know what offline earnings are.
		Nothing in this folder may require SessionService: it derives income from a
		SAVED profile precisely so an absent player can be paid with no plot to ask,
		and it is required BY the service that draws this gauge.

		The gauge is bottom-anchored and floored at MIN_PART. Roblox silently keeps
		the old size rather than erroring on a part thinner than 0.05 on any axis, so
		an empty gauge that failed to resize would read as whatever it last held.
	]]

	local Req = __Req
	local Config = Req("Config")
	local Economy = Req("Economy")
	local Style = Req("Style")
	local Util = Req("Util")
	local Fx = Req("Fx")
	local TungModels = Req("TungModels")
	local Tycoon = Req("Class")
	local Parts = Req("Parts")

	local newPart = Parts.newPart
	local COLORS = Tycoon.COLORS
	local MIN_PART = Tycoon.MIN_PART

	local L = Config.Layout
	local OV = Config.Offline.Vault

	-- ── collector ────────────────────────────────────────────────────────────────

	--- One path's way INTO a collector: the run-off ramp, the collect sensor and
	--- the funnel mouth at the end of its last leg. Its own method (#162) because
	--- the ground floor is two mirrored paths feeding one vault — the shell is
	--- built once by buildCollector and each path brings its own intake.
	function Tycoon:buildCollectorIntake(pathIndex: number, folder: Instance,
		bodyDepth: number, bodyWidth: number)
		local path = self:beltPath(pathIndex)
		local _, beltEnd, exitDir = self:leg(self:legCount(pathIndex), pathIndex)
		local runOff = (path.collectorAt - beltEnd).Magnitude

		local function alongExit(distance, y, lateral)
			local point = beltEnd + exitDir * distance + Vector3.new(0, y + path.y, 0)
				+ Vector3.new(-exitDir.Z, 0, exitDir.X) * (lateral or 0)
			return self.cf * CFrame.lookAt(point, point + exitDir)
		end

		-- How far the vault's near face stands past the belt end. Everything
		-- below is sized off it, so the intake ATTACHES whatever the spacing:
		-- the fixed-length ramp it replaces stopped three studs short of the
		-- face, and a drop that bounced on the lip fell into the gap and sat at
		-- the vault's foot until the reaper took it (#162 tophat).
		local faceDist = runOff - bodyDepth / 2

		-- funnel mouth facing back down the belt
		local mouth = newPart(folder, "Mouth", Vector3.new(bodyWidth - 6, 6, 1.5),
			alongExit(faceDist - 0.5, L.BeltY + 3, 0),
			Color3.fromRGB(30, 24, 40), Enum.Material.Neon, false)
		mouth.Transparency = 0.5

		-- The run-off ramp spans the WHOLE gap: tucked 0.6 under the belt's end,
		-- kissing 0.4 into the vault's face, so there is no seam for a tumbling
		-- drop to fall through.
		--
		-- ITS TOP SITS 0.05 UNDER THE BELT SURFACE'S, and that is the launch fix
		-- (#162 tophat): the ramp ran 0.1 PROUD of the surface it receives from,
		-- and a lip standing against the travel is a ski jump — a shrug at the
		-- shipped 28 studs/s and a launch into orbit at power3's 74. A drop may
		-- always STEP DOWN onto the intake; it may never climb onto it.
		local rampRun = faceDist + 1.0
		local ramp = newPart(folder, "Ramp", Vector3.new(L.BeltWidth, 0.6, rampRun),
			alongExit((faceDist - 0.2) / 2, L.BeltY - 0.35, 0),
			COLORS.belt, Enum.Material.SmoothPlastic)
		ramp.CustomPhysicalProperties = PhysicalProperties.new(0.7, 0.05, 0.1, 1, 1)

		-- The most expensive one to miss: a drop the collector does not see is
		-- 100% of its value, not a fraction of it. The sensor owns the whole
		-- run-off — belt end to face, a stud proud of the surface either way —
		-- so a drop that bounces, drifts or settles anywhere on the intake still
		-- ENTERS the volume and collects. Twelve studs TALL, because the failure
		-- this family keeps re-finding is vertical: a drop popped upward by a
		-- bunched queue or a bounce arcs over a short volume and is never seen
		-- again.
		local sensor = newPart(folder, "Sensor",
			Vector3.new(L.BeltWidth + 3, 12, faceDist + 1.5),
			alongExit((faceDist - 0.3) / 2, L.BeltY + 4.5, 0),
			Color3.fromRGB(255, 255, 255), Enum.Material.Neon, false)
		sensor.Transparency = 1
		sensor.CanTouch = true

		sensor.Touched:Connect(function(hit)
			self:onCollect(hit)
		end)
	end

	--- Run-off ramp, collect sensor and the body that catches the drops, at the end
	--- of a path's last leg.
	---
	--- `headline` adds the vault dressing — gold trim, statue, income sign. Only
	--- the ground floor gets it: a second statue on every upper floor is noise, and
	--- the income readout on it would be wrong anyway (it reports the whole plot).
	function Tycoon:buildCollector(pathIndex: number?, parent: Instance?, headline: boolean?)
		pathIndex = pathIndex or 1
		local path = self:beltPath(pathIndex)

		local folder = parent
		if not folder then
			folder = Instance.new("Folder")
			folder.Name = "Collector"
			folder.Parent = self.model
			self.collectorFolder = folder
			self:registerFactoryFolder(folder)
		end

		-- The catcher sits past the end of the last leg. Its shell must stay
		-- entirely DOWNSTREAM of the sensor: a solid body overlapping the run-off
		-- walls the belt off and nothing can ever be collected.
		local _, beltEnd, exitDir = self:leg(self:legCount(pathIndex), pathIndex)
		local V = L.Vault
		local bodyDepth = headline and V.bodyDepth or V.plainDepth
		local bodyWidth = headline and V.bodyWidth or V.plainWidth
		local bodyHeight = headline and V.bodyHeight or V.plainHeight
		local centre = path.collectorAt
		local runOff = (centre - beltEnd).Magnitude
		assert(runOff > bodyDepth / 2 + 3,
			("Collector body overlaps the belt run-off on path %q; move its collectorAt further out"):format(tostring(path.id)))

		-- Path-local: `y` is measured from the floor this belt runs on, exactly as
		-- it is everywhere else on the path.
		local function alongExit(distance, y, lateral)
			local point = beltEnd + exitDir * distance + Vector3.new(0, y + path.y, 0)
				+ Vector3.new(-exitDir.Z, 0, exitDir.X) * (lateral or 0)
			return self.cf * CFrame.lookAt(point, point + exitDir)
		end

		local base = newPart(folder, "VaultBase", Vector3.new(bodyWidth, bodyHeight, bodyDepth),
			alongExit(runOff, bodyHeight / 2, 0), COLORS.vault, Enum.Material.WoodPlanks)
		newPart(folder, "VaultTrim", Vector3.new(bodyWidth + 1, 1.2, bodyDepth + 1),
			alongExit(runOff, bodyHeight + 0.4, 0), COLORS.gold, Enum.Material.Metal)

		self:buildCollectorIntake(pathIndex, folder, bodyDepth, bodyWidth)

		if not headline then
			return
		end

		-- sign
		local signAnchor = newPart(folder, "SignAnchor", Vector3.new(1, 1, 1), alongExit(runOff, V.signY, 0), COLORS.vault, nil, false)
		signAnchor.Transparency = 1

		local billboard = Style.billboard(signAnchor, {
			name = "Sign", width = V.signWidth, height = V.signHeight, distance = OV.Distance,
		})
		local label = Style.text(billboard, {
			name = "Rate", text = "SAHUR VAULT", color = COLORS.gold,
		})
		self.vaultLabel = label

		-- THE GAUGE, and it goes on a SIDE of the vault rather than on top of it.
		--
		-- The lid is spoken for three times over — trim at bodyHeight + 0.4, the
		-- 20x6 board spanning y 9..15, the statue above that — so a column on the
		-- roof would grow straight through two of them. The lateral faces are the
		-- only clear ones, and of the two only one faces the open floor: with the
		-- vault at back-centre (#162), that is the FRONT face, looking straight
		-- down the aisle at the gate.
		--
		-- WHICH SIGN THAT IS depends on the last leg's exit direction. alongExit
		-- puts lateral on (-exitDir.Z, 0, exitDir.X); this is built off the WEST
		-- path, which exits along +X, making that perpendicular +Z — so a
		-- POSITIVE lateral lands on the front face and a negative one in the gap
		-- behind the vault. Derived, not measured: UNVERIFIED IN STUDIO.
		local w = V.window
		local windowCF = alongExit(runOff, w.y, w.lateral)
		local window = newPart(folder, "FillWindow", Vector3.new(w.thickness, w.height, w.width),
			windowCF, COLORS.gold, Enum.Material.Glass, false)
		window.Transparency = 0.55
		-- CanQuery off as well as CanCollide: a pane in front of the vault body is
		-- exactly the sort of thing a raycast-driven prompt or a camera collision
		-- would otherwise catch on.
		window.CanQuery = false
		self.vaultWindow = window

		-- The gold inside the pane. Built at FULL height and centred, which is the
		-- pose setVaultGauge measures its offsets against — see vaultFillBase.
		local fill = newPart(folder, "FillBody",
			Vector3.new(w.thickness * 0.55, w.height, w.width - 0.8),
			windowCF, COLORS.gold, Enum.Material.Neon, false)
		fill.CanQuery = false
		self.vaultFill = fill
		self.vaultFillBase = windowCF

		-- The small print, bolted UNDER the pane on the same face. Its own tier:
		-- the headline is the plot's number and carries to the arena, the
		-- arithmetic behind it only has to resolve once you are standing here.
		local detailAnchor = newPart(folder, "DetailAnchor", Vector3.new(1, 1, 1),
			alongExit(runOff, V.detailSignY, V.detailLateral), COLORS.vault, nil, false)
		detailAnchor.Transparency = 1
		local detailBoard = Style.billboard(detailAnchor, {
			name = "Detail", width = V.detailWidth, height = V.detailHeight, distance = OV.NearDistance,
		})
		self.vaultDetailLabel = Style.text(detailBoard, {
			name = "Detail", text = "", color = COLORS.gold, weight = "body",
		})

		-- The claim. A ProximityPrompt rather than a remote, because the intent
		-- here has no payload at all: there is no amount for a client to send and
		-- therefore none for the server to have to disbelieve. VaultService hangs
		-- the handler on it — Tycoon does not know what offline earnings are.
		local prompt = Instance.new("ProximityPrompt")
		prompt.Name = "CollectOffline"
		prompt.ActionText = "Collect"
		prompt.ObjectText = "Sahur Vault"
		prompt.HoldDuration = OV.PromptHoldSeconds
		prompt.MaxActivationDistance = OV.PromptDistance
		prompt.RequiresLineOfSight = false
		prompt.Enabled = false          -- nothing banked until something is
		prompt.Parent = base
		self.vaultPrompt = prompt

		-- The body doubles as the storage unit (#93): health, brokenness and the
		-- repair prompt all hang on this same base. Storage.lua owns that state.
		self:buildStorageUnit(base)

		-- Facing the gate: the frame looks along the west path's +X exit, so a
		-- quarter turn the other way points the statue down the aisle at the
		-- gateway. UNVERIFIED IN STUDIO, same as the gauge face.
		local statue = TungModels.buildStatue("classic", V.statueScale)
		statue:PivotTo(alongExit(runOff, V.statueY, 0) * CFrame.Angles(0, -math.pi / 2, 0))
		statue.Parent = folder
		self.vaultStatue = statue
	end

	--- Writes the vault gauge. THE ONLY THING IN THIS FILE THAT DRAWS IT, and it
	--- decides nothing: every one of these four values is worked out by
	--- VaultService, which is the module allowed to know what offline earnings are.
	--- Tycoon must not require SessionService — SessionService derives income from
	--- a SAVED profile precisely so it never has to reach for a live plot — so the
	--- arrow points one way and this is the far end of it.
	---
	---   fraction  0..1 of the window, bottom-anchored
	---   headline  the 20x6 board, or nil to hand it back to updateSign
	---   detail    the small print under the pane
	---   waiting   true when there is a real grant to collect, which is also the
	---             only state the prompt is live in
	function Tycoon:setVaultGauge(fraction: number, headline: string?, detail: string?, waiting: boolean?)
		self.vaultHeadline = headline
		if self.vaultLabel and self.vaultLabel.Parent and headline then
			self.vaultLabel.Text = headline
		end
		if self.vaultDetailLabel and self.vaultDetailLabel.Parent then
			self.vaultDetailLabel.Text = detail or ""
		end

		local fill = self.vaultFill
		if fill and fill.Parent then
			local full = L.Vault.window.height
			-- MIN_PART, not zero: Roblox rejects a part thinner than 0.05 on any
			-- axis, and an empty gauge that failed to resize would keep whatever
			-- height it last had — an empty vault reading as a full one.
			local height = math.max(full * math.clamp(fraction, 0, 1), MIN_PART)
			fill.Size = Vector3.new(fill.Size.X, height, fill.Size.Z)
			-- Bottom-anchored. Resizing a part in Roblox grows it about its centre,
			-- so a gauge left at the window's centre would creep DOWN through the
			-- vault floor as it filled instead of rising up the pane.
			fill.CFrame = self.vaultFillBase * CFrame.new(0, (height - full) / 2, 0)
			fill.Color = waiting and COLORS.gold or COLORS.vaultPromise
			fill.Transparency = waiting and 0 or 0.4
		end

		if self.vaultPrompt and self.vaultPrompt.Parent then
			self.vaultPrompt.Enabled = waiting == true
		end
	end

	function Tycoon:onCollect(hit: BasePart)
		local model = hit.Parent
		if not model or not model:IsA("Model") then
			return
		end
		if model:GetAttribute("PlotIndex") ~= self.index then
			return
		end
		if model:GetAttribute("Collected") then
			return  -- touch fires twice; the first one claimed it
		end
		model:SetAttribute("Collected", true)

		-- recycleDrop below returns the budget slot; decrementing here as well
		-- would count one drop out twice and starve the spawners.
		local owner = self.owner
		if owner and owner.Parent then
			-- design:D-02, via #180 — THE PAYMENT. A collected tung pays its
			-- dropper's value through the plot multiplier and the live session
			-- stack, and this is the game's ONE live payer: a tung that never
			-- reaches this line is income that never arrives. The Collected flag
			-- above is what makes the double-firing Touched pay once.
			local dropValue = model:GetAttribute("DropValue")
			local paid = 0
			if type(dropValue) == "number" and dropValue > 0 then
				paid = Config.dropPayout(dropValue, function(id)
					return self.owned[id] == true
				end)
				Economy.add(owner, paid, true)
			end

			-- late game the vault eats ~10 drops/sec; throttle the confetti so a
			-- finished factory doesn't spam hundreds of billboards per minute.
			local now = os.clock()
			if now - (self.lastPayoutFx or 0) > 0.3 then
				self.lastPayoutFx = now
				Fx.floatingText(hit.Position + Vector3.new(0, 3, 0),
					"+" .. Util.abbreviate(paid > 0 and paid * Economy.multiplier(owner) or self:incomePerSecond()),
					COLORS.gold, self.model)
				Fx.tung(hit, 0.9 + math.random() * 0.35, 0.18)
			end
		end
		self:recycleDrop(model)
	end

	return Tycoon
end


-- ── entry point ───────────────────────────────────────────────


--[[
	Main.server.lua — Tung Tung Tycoon boot sequence.

	Order matters: data before economy (leaderstats read profiles), world
	before plots, plots before players are let in.
]]

local Req = __Req
local Config = Req("Config")
Req("Net")  -- creates the RemoteEvent folder before any client asks for it
local MapBuilder = Req("MapBuilder")
local DataService = Req("DataService")
local Analytics = Req("Analytics")
local Economy = Req("Economy")
local CombatService = Req("CombatService")
local MovementService = Req("MovementService")
local RaidService = Req("RaidService")
local HelpService = Req("HelpService")
local PartyService = Req("PartyService")
local RecallService = Req("RecallService")
local TowerService = Req("TowerService")
local DisclosureService = Req("DisclosureService")
local ShopService = Req("ShopService")
local ObjectiveService = Req("ObjectiveService")
local LeaderboardService = Req("LeaderboardService")
local PlotService = Req("PlotService")
local NPCService = Req("NPCService")
local AdminService = Req("AdminService")

-- SessionService (offline earnings, the session loops) and GateService (the
-- doors in the shell) have graduated and always run.
-- UpgradeService is still a prototype and is a no-op unless
-- Config.Prototypes.PlayerUpgrades is on, so it costs nothing in a shipping build.
local Tycoon = Req("Tycoon")
local UpgradeService = Req("UpgradeService")
local SessionService = Req("SessionService")
local VaultService = Req("VaultService")
local GateService = Req("GateService")

-- Shipped, and flagless: the friend bonus turns off by setting
-- Config.Social.BonusPerFriend to 0, on which start() declines to register its
-- multiplier hook. It connects its own PlayerAdded/PlayerRemoving.
local SocialService = Req("SocialService")

local Players = game:GetService("Players")

local START = os.clock()

Players.CharacterAutoLoads = true

-- 1. world
local world = MapBuilder.build()

-- 2. services
DataService.start()
Analytics.start()
Economy.start()
CombatService.start()
MovementService.start()

-- 3. plots
PlotService.build(world)
PlotService.start()

-- One optional service must not take claiming and the player wiring down
-- with it: everything below this line is gameplay on TOP of the plot loop,
-- so a throw is contained and shouted rather than fatal. The method-resolution
-- lint is the real fix for the class of bug that motivated this; the blast
-- door is for whatever a lint cannot see. Everything ABOVE (world, data,
-- economy, plots) stays unwrapped — if those fail the server is correctly dead.
local function boot(name: string, fn)
	local ok, err = pcall(fn)
	if not ok then
		warn(("[Tung] %s failed to start: %s"):format(name, tostring(err)))
	end
end

-- 4. raids
boot("NPCService", NPCService.start)

-- 4b. admin chat commands. Self-gating on Config.Admin and on WHO is asking, so
-- this is a no-op for an ordinary player on a live server. After NPCService,
-- because !wave and !clear drive its schedule.
boot("AdminService", AdminService.start)

-- 5. sessions and the one remaining prototype
boot("UpgradeService", UpgradeService.start)
boot("SessionService", SessionService.start)
-- after SessionService: it registers listeners on plots that are already built
-- and reads the projection SessionService owns
boot("VaultService", VaultService.start)
-- The gates in the shell's two openings. Anywhere after PlotService.build: it
-- walks Tycoon.all() on its own fixed beat and finds the leaves inside the walls
-- model, so the plots have to exist, but it registers no listener and reacts to
-- no purchase — a gate is a distance test, not an event.
boot("GateService", GateService.start)
-- The siege hook (#124): a swing that boxed wall or gate parts lands here.
-- Wired from this file rather than inside CombatService, because Tycoon
-- requires CombatService and the observer shape exists to keep that arrow
-- one-way.
CombatService.setStructureObserver(Tycoon.siegeStrike)
-- The storage cap's broken-state reader (#98): a smashed unit collapses the
-- cap to its floor, and Economy cannot require Tycoon to ask.
Economy.setStorageIntactHook(function(player)
	local tycoon = PlotService.plotOf(player)
	return tycoon == nil or tycoon:storageIntact()
end)
-- The raid loot loop (#94): a break with an attacker spills into their hands,
-- and RaidService.start hangs the death-drops and banking loops. Same
-- one-way-arrow argument as the two hooks above.
Tycoon.storageBreakObserver = function(tycoon, attacker)
	RaidService.onStorageBroken(tycoon, attacker, os.clock())
end
boot("RaidService", RaidService.start)
-- Helping pays (#123): the boost hook registers, and repairing someone
-- else's plot lands as a kindness credit.
Tycoon.repairObserver = function(tycoon, player)
	HelpService.credit(player, tycoon.owner, "repairs", os.clock())
end
boot("HelpService", HelpService.start)
-- The party (#102): the trust boundary reaches combat and the plot through
-- the same observer shape as everything above.
CombatService.setAllyCheck(PartyService.sameParty)
Tycoon.allyCheck = PartyService.sameParty
boot("PartyService", PartyService.start)
-- Recall (#103): after PlotService, whose teleportToPlot is the arrival.
boot("RecallService", RecallService.start)
-- The tower (#95): after NPCService (it spawns through the minting site) and
-- PartyService (a climb brings the presser's whole party).
boot("TowerService", TowerService.start)
-- Disclosure (#96): the beat that grows each player's interface, and the
-- gate NPCService reads before a plot's first siege.
boot("DisclosureService", DisclosureService.start)
-- The shop (#108): after PlotService, whose plotOf keeps the owned mirrors
-- in step.
boot("ShopService", ShopService.start)
-- Objectives (#97): reads persisted stats on a beat; no ordering needs.
boot("ObjectiveService", ObjectiveService.start)
-- The board and the frontier (#105): a world object on its own beat.
boot("LeaderboardService", LeaderboardService.start)
-- The guide (#100): its mouth is the hint machinery, one arrow, one line.
-- It answers ANY player who talks to it — a visitor gets the owner's guide's
-- flavour, which is a kindness surface, not a leak.
Tycoon.guideSpeaker = function(tycoon, player)
	local profile = DataService.get(player)
	local hint = profile and ObjectiveService.hintFor(profile)
	Economy.notify(player, { kind = "info", title = "Your Tung says",
		body = hint or "Tung tung. The middle pays best. Come back when something new unlocks." })
end
boot("SocialService", SocialService.start)

-- 6. players
local function onCharacterAdded(player: Player, character: Model)
	-- keep players from clipping into the belt machinery on spawn
	character:WaitForChild("HumanoidRootPart", 10)

	-- Respawn on your own plot rather than the arena. Roblox picks the spawn
	-- before we get here, so this is a reposition, not a SpawnLocation: a
	-- per-plot SpawnLocation would land in the random-spawn pool and start
	-- sending other players to your factory.
	task.defer(PlotService.teleportToPlot, player)

	CombatService.onCharacter(player, character)
	UpgradeService.onCharacter(player, character)
	Economy.push(player)
end

local function onPlayerAdded(player: Player)
	DataService.load(player)
	-- BETWEEN load AND SessionService.onPlayer, AND THAT IS NOT A PREFERENCE.
	-- SessionService.onPlayer overwrites profile.lastSeen with os.time() as its
	-- second act, and its per-second tick re-stamps it after that. The previous
	-- logout time is readable exactly once, here, and it is the only input the
	-- `returned` event has. Moving this line below SessionService.onPlayer does
	-- not break anything visibly — it makes every "how long before they came
	-- back" number zero.
	Analytics.onPlayer(player)
	Economy.setupLeaderstats(player)
	Economy.push(player)
	UpgradeService.onPlayer(player)
	SessionService.onPlayer(player)

	player.CharacterAdded:Connect(function(character)
		task.spawn(onCharacterAdded, player, character)
	end)
	if player.Character then
		task.spawn(onCharacterAdded, player, player.Character)
	end

	-- give them a factory right away if one is free
	task.delay(1.5, function()
		if player.Parent and not PlotService.plotOf(player) then
			PlotService.autoAssign(player)
		end
	end)

	Economy.notify(player, {
		kind = "welcome",
		title = "TUNG TUNG TYCOON",
		body = "Buy droppers. Upgrade the tung. Defend the Sahur raid.",
	})
end

Players.PlayerAdded:Connect(onPlayerAdded)
for _, player in ipairs(Players:GetPlayers()) do
	task.spawn(onPlayerAdded, player)
end

print(("[Tung] Tung Tung Tycoon booted in %.2fs — %d plots, %d buttons, %d bats.")
	:format(os.clock() - START, Config.World.PlotCount, #Config.Buttons, #Config.Bats))
